    if post_residual > 0 {
        let min_useful = if next_item_size > 0 { next_item_size.min(80) } else { 10 };
        if (post_residual as u32) < min_useful {
            // Dead space: gap cannot fit the next item (or any item at stream end).
            let severity = (min_useful - post_residual) as f64;
            score += 40.0 + severity * 8.0;
        }
