        }
        // early stream with few bins: fresh bin is fine
        if open_bins_count <= 4 && progress < 0.3 {
            score += 25.0;
        }
    }

    // Late in the stream, consolidate: prefer tightest fits even more.
    score -= progress * 0.3 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never host a future item
    // (sizes >= 1) are pure waste. Penalize tiny gaps aggressively.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    score -= (item_size as f64) * 0.55;

    // Lookahead (k=2): if the next item fits exactly into the post residual,
    // strongly reward; if it nearly fits, mild reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size > post_residual && next_item_size - post_residual <= 10 {
            score += 10.0; // next item won't fit here; slight penalty
        }
    }

    // Last-chance bin: if this is the only open bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: mildly penalize, unless current open bins are all crowded
    // (low mean residual) or the item would leave a huge usable gap anyway.
    if bin_residual == bin_capacity {
        score += 22.0;
        score -= open_bins_count as f64 * 1.5;
        if mean_residual < 15.0 {
            score -= 25.0;
        }
        if item_size > 70 {
            score -= 15.0; // big items are hard to place later; fresh bin is fine
        }
    }

    // Open-bins pressure: prefer bins that reduce fragmentation of crowded state.
    score += open_bins_count as f64 * 0.4;
    score -= mean_residual * 0.15;

    // Late-stream consolidation: as the stream progresses, avoid spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) exponentially.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later (items >= 1,
    // so anything < ~next plausible minimum is waste). Use lookahead coupling.
    if post_residual > 0 {
        let waste = post_residual as f64;
        let usable = if next_item_size > 0 { next_item_size as f64 } else { 1.0 };
        if waste < usable {
            score += 6.0 * (usable - waste);
        }
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
