            let gap = (post_residual - next_item_size) as f64;
            score -= 5.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Time horizon: late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Global state coupling: many open bins with high mean residual => prefer
    // filling existing bins rather than spreading.
    if open_bins_count > 0 {
        let spread = (mean_residual - bin_residual as f64).abs();
        score += 0.05 * spread;
        score -= 0.02 * (open_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity && bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // Default: new bin is worse than a decent existing fit.
        score += 20.0 - 25.0 * pressure;
        // Late stream: opening a fresh bin is even less attractive.
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
