    // Penalize new-bin candidate unless current bins would leave big dead space.
    if bin_residual == bin_capacity {
        // New bin: neutral baseline; add mild penalty so existing good fits win,
        // but subtract if all fitting bins would waste a lot.
        score += 3.0;
        if post_residual > 0 && (post_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    // Slight preference for bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual - item_size) as f64;
    score += 0.3 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // plausible future item (min size 1, but practically < ~10) are "dead".
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    } else if post_residual < 20 {
        score += 12.0; // near-dead gap
    }

    // Reward exact / tight fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Best-fit core: prefer bins whose residual is close to the item.
    score += (bin_residual as f64 - item_size as f64) * 0.15;

    // Open-bin pressure: discourage spreading across many bins, but ease off
    // late in the stream when consolidation matters less.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.5 - 0.3 * progress);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly, i.e. when
    // this bin's post_residual would leave a large dead gap relative to mean.
    if bin_residual == bin_capacity {
        let gap_penalty = (mean_residual - item_size as f64).max(0.0);
        score = bin_capacity as f64 * 0.45 + gap_penalty * 0.6;
        // Late in the stream, opening fresh bins is cheap relative to wasted space.
        score -= progress * 10.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this placement is ideal; if it nearly fits, slightly penalize.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.1;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a future item (size >= 1, but practically >= ~10) are toxic.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small gaps just above the minimum item size are nearly unusable too.
    if post_residual >= 10 && post_residual < 20 {
