    }

    // Reward tight fits: the smaller the post_residual relative to capacity,
    // the better the packing density.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bin pressure: penalize spreading across many bins unless the fit
    // is genuinely good; encourage closing out nearly-full bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64) * 1.5 * (1.0 - tightness);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits the resulting residual, reward this
    // placement; if post_residual blocks the next item, penalize slightly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // New-bin candidate handling: an empty bin is a safe but lazy choice.
    // Only prefer it when no open bin offers a decent fit (post_residual
    // would be large dead space in every open bin).
    if bin_residual == bin_capacity {
        // Baseline score for a fresh bin: modest, but not free.
        score = (bin_capacity - item_size) as f64 * 0.9;
        score += open_bins_count as f64 * -0.5; // mild encouragement to reuse bins
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a new bin
        }
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

