    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer perfect or near-perfect fits (dead space minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Non-linear penalty on small residuals (wasted space that's hard to reuse).
        let r = post_residual as f64;
        score += 60.0 / r; // small residuals get big penalty
        if r <= 10.0 {
            score += 40.0; // tiny slivers are nearly unusable (items >= 1 but rare)
        }
    }

    // 2-step lookahead: reward when the next item exactly fills the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // perfect chain placement
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how snugly it fits
            let slack_after_next = post_residual - next_item_size;
            score -= 120.0 - (slack_after_next as f64) * 2.0;
        } else {
            // next item would NOT fit here: mild penalty for fragmenting space
            score += 25.0;
        }
    }

    // Relative-to-mean coupling: bins with residual below mean are "tighter";
    // filling a tight bin is good (consolidation), leaving it open is bad.
    let tightness = mean_residual - (bin_residual as f64);
    score += tightness * 0.8;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity (poor fit anywhere else) or
    // late in the stream. Penalize the fresh bin otherwise.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = (item_size as f64) / (bin_capacity as f64);
        // new bin starts at post_residual = capacity - item; make it less
        // attractive unless item is big or few fitting bins exist
        score += 80.0 * (1.0 - large_item) + 40.0 * (1.0 - progress);
        if fitting_bins_count <= 1 {
            score -= 350.0; // fallback: opening a bin beats a forced bad fit
        }
    }

    // Mild preference for consolidating into fewer bins when many are open.
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any leftover gap that no item (min size 1)
    // could still use productively is heavily penalized. Gaps in the "dead zone"
    // (small but nonzero) are worse than a perfect fit or a fully used bin.
    let dead_threshold = 12.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward tight fits (waste-free placements).
    if post_residual == 0 {
        score -= 40.0;
    } else {
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= tightness * 15.0;
    }

    // Penalize creating gaps that cannot fit the lookahead item while the
    // current bin could otherwise have served it.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 6.0;
    }
    // Reward leaving exactly enough room for the next item (chain fit).
    if next_item_size > 0 && post_residual == next_item_size as u64 as u32 {
        score -= 12.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * 2.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing fits are poor (large post_residual or many open bins already
    // tight). An empty bin gives full flexibility for future large items.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by how well this item would
        // otherwise fit somewhere.
        score = (bin_capacity - item_size) as f64 * 0.5 + pressure * 1.5;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: new bin is fine
        }
        if next_item_size > bin_residual - item_size && next_item_size > 0 {
            score -= 10.0; // new bin leaves room for the next item
        }
    }

    // Slight preference for bins whose residual is close to the mean
    // (keeps residuals balanced, avoiding many tiny fragmented gaps).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
