        score -= 20.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin needlessly
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when existing bins
    // would leave very poor fits and many bins are already open.
    if bin_residual == bin_capacity {
