        // mean residual across open bins is small.
        let existing_poor = mean_residual < item_size as f64 * 1.2;
        if existing_poor && open_bins_count > 2 {
            score -= 18.0 + 10.0 * progress;
        } else {
            score += 30.0 + 20.0 * (1.0 - tight);
