    // Fractional capacity coupling: reward bins whose fill fraction crosses
    // integer-division thresholds (e.g. > 3/4 full).
    let fill_frac = (bin_capacity - post_residual) as f64 / cap;
    let quarter = (fill_frac * 4.0).floor();
    score -= quarter * 3.0;

    // Slight preference to consolidate when many bins are open
    score -= 0.5 * open_bins_count as f64 * (1.0 - fill_frac);

    // Small progress-adaptive tightness bonus
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (post_residual as f64 / cap) * 5.0;

    score
}

