    // Global state coupling: when mean residual across open bins is high,
    // prefer bins whose residual is far from the mean (balance exploitation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.15 * dev;

    // Mild pressure to close out nearly-full bins early.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Encourage using bins with large residuals when few bins are open.
    if open_bins_count <= 2 {
        score -= 0.1 * bin_residual as f64;
    }

    score
}

