        if pair_sum <= bin_residual {
            let pair_waste = bin_residual - pair_sum;
            if pair_waste <= 2 {
                score -= 250.0;
            }
            score -= (bin_capacity as f64 - pair_waste as f64) * 0.1;
        } else {
            // Next item cannot follow into this bin; penalize mildly
            score += 15.0;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.6;

    // Penalize large dead space unusable by typical items (min size 1..100 range)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny sliver waste
    }
    if post_residual >= 80 {
        score -= 30.0; // large residual stays flexible
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin
    // offers a good fit (post_residual small or exact chain).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 50.0;
        // Discourage new bin if item is small relative to capacity (fits well elsewhere)
        score += (item_size as f64 / bin_capacity as f64) * 40.0;
        // Encourage new bin when many bins are nearly full (consolidation pressure)
        score -= (mean_residual / bin_capacity as f64) * 30.0;
        // Late in the stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

