    // Penalize bins whose residual deviates far above the mean residual (fragmentation risk).
    score += ((post_residual as f64 - mean_residual).abs()) * 0.3;

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e., when this call is the empty-bin call and residual is full.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized early (stream is long, plenty of future items
        // could fill existing bins) but less so near the end of the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let horizon_factor = 1.0 - 0.5 * progress;
        score += 70.0 * horizon_factor;

        // If the next item is large, a fresh bin is more useful.
        if next_item_size >= item_size {
            score -= 35.0;
        }
        // If current item nearly fills a fresh bin, opening is fine.
        if item_size as f64 >= 0.9 * bin_capacity as f64 {
            score -= 60.0;
        }
    }

    // Mild time-horizon modulation: late in the stream, pack tighter (avoid new bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits, scaled by smooth polynomial in post_residual
    let mut score = post + 12.0 * norm_post * norm_post * cap;

    // Non-linear coupling: tight placements matter more later in the stream
    let tightness = 1.0 - norm_post;
    score -= 30.0 * progress * tightness * tightness * tightness;

    // Penalize bins whose residual deviates from mean residual (fragmentation)
    let dev = (post - mean_residual) / cap;
    score += 8.0 * dev * dev * cap;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * (1.0 - progress);
    }

    // Lookahead: reward leaving room for the next item (smooth interaction)
    let next = next_item_size as f64;
    if next > 0.0 {
        let gap = post - next;
        if gap >= 0.0 {
            score -= 10.0 * (gap / cap) * (1.0 - (gap / cap));
        } else {
            score += 6.0 * (-gap / cap);
        }
    }

    // Mild penalty for spreading across many open bins late in stream
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of common item sizes) are more valuable.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -60.0 // perfect fit is always best
    } else if pr % 10 == 0 {
        -12.0 // residue aligns with coarse item grid
    } else if pr % 5 == 0 {
        -5.0
    } else if pr < 10 {
        8.0 // tiny dead space, nearly unusable
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Reward leaving room for the lookahead item (exact or harmonic match).
    if next_item_size > 0 && next_item_size <= pr {
        let nx = next_item_size;
        let mut look = -18.0;
        if pr % nx == 0 { look -= 10.0; }           // future item divides leftover exactly
        if nx % 10 == 0 && pr % 10 == 0 { look -= 6.0; } // both on coarse grid
        if pr - nx < 10 { look += 10.0; }           // would leave fresh dead space
        score += look;
    } else if next_item_size > pr {
        // This bin cannot host the next item; mild penalty unless residual tiny.
        if pr >= 10 { score += 4.0; }
    }

    // Tightness coupling: prefer bins where the item fills a large fraction
    // of the residual (best-fit-like, non-linear).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill * fill;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin when decent fits exist,
    // but allow it when the item is huge and would strand open bins.
    if bin_residual == bin_capacity {
        let base = 35.0
            + 0.25 * open_bins_count as f64
            + 0.10 * mean_residual;
        // If item is large relative to capacity, a fresh bin is reasonable.
        let large = item_size as f64 / cap;
        score += base * (1.0 - 0.6 * large);
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild pressure to consolidate: many open bins with high mean residual
    // favor packing into existing space.
    score += 0.05 * open_bins_count as f64 - 0.05 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.02;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item fits but leaves more slack; penalize proportionally.
            score -= 60.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            // Next item will NOT fit in this bin's remainder: dead space risk.
            score += 40.0 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post residual to mean residual: leaving much less than average
    // residual means we consumed the bin efficiently.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Penalize opening a new bin when plenty of open bins exist that fit,
    // unless the fit is very tight (post_residual small already rewarded).
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 120.0 + 10.0 * open_bins_count as f64;
    }

    // Late in the stream, consolidate: prefer tightest fits even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 0.3 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward small post_residual non-linearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            let unusable = (next_item_size - post_residual) as f64;
            score += 6.0 * (unusable / bin_capacity as f64).sqrt();
        } else if post_residual >= next_item_size {
            // Reward leaving room for the known next item.
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        // Penalize new bin when existing bins are healthy; discount late in stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 - 18.0 * fragmentation - 8.0 * progress;
        // If no open bin really fits well, opening may be fine: soften when post_residual==0 impossible.
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Slight preference for bins with residual above the mean (balance residuals).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Mild pressure to consolidate when many bins are open.
    score += 0.02 * open_bins_count as f64;

    // Penalize very small post_residual slivers less than exact zero (perfect fit reward).
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let is_new_bin = (bin_residual == bin_capacity) as f64;

    // Base: quadratic waste term
    let mut score = pr + 0.9 * pr * pr / cap;

    // Smooth progress coupling: early on tolerate residual, later penalize it harder
    let progress_gain = progress * progress;
    score -= 0.8 * progress_gain * (cap - pr);

    // Cubic dead-space penalty: residuals that can't fit typical small items
    let dead = (norm_pr * (1.0 - norm_pr)).sqrt();
    score += 2.0 * (1.0 - dead) * pr * (0.5 + progress);

    // Tight fits reward: small post_residual relative to capacity
    score -= 3.0 * (1.0 - norm_pr).exp() * (1.0 - progress);

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64 <= pr) as f64;
        let slack = (pr - next_item_size as f64).abs() / cap;
        score -= 4.0 * fits_next * (1.0 - slack);
        score += 1.5 * (1.0 - fits_next) * (pr / cap);
    }

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // Mean residual deviation: prefer bins whose residual stays near mean (balance)
    let dev = (pr - mean_residual).abs() / cap;
    score += 1.2 * dev * (0.5 + progress);

    // New-bin candidate: penalize mildly early, more when open bins are few
    score += is_new_bin * (5.0 + 3.0 * (1.0 - progress) + open_bins_count as f64 * 0.3);

    // Prefer reusing bins over spreading when many bins open
    score += (1.0 - is_new_bin) * (-0.5) * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction band does the leftover fall in?
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Integer-division thresholds: post_residual in "harmonic" bands of capacity
    // Band 0: post == 0 (perfect fit) -> strongly reward
    // Band 1: post in (0, 20] -> small dead space, mild reward
    // Band 2: post in (20, 50] -> medium leftover
    // Band 3: post in (50, 100) -> large leftover, but useful if next item fits

    if post_residual == 0 {
        score -= 40.0;
    } else {
        // modulo arithmetic on post_residual: leftover close to common item sizes is valuable
        let pr = post_residual;
        let harmonic_bonus: f64 = match pr % 10 {
            0 => 6.0, // leftover divisible by 10 aligns with typical item sizes
            1..=3 => 1.0,
            4..=7 => -2.0,
            _ => 0.0,
        };
        score -= harmonic_bonus;

        // class the residual by integer division thresholds
        let class = pr / 25; // 0,1,2,3
        match class {
            0 => score -= 8.0,   // tiny dead space, good packing
            1 => score += 2.0,   // 25..49 leftover: awkward zone
            2 => score -= 1.0,   // 50..74: can host medium items
            _ => score += 3.0,   // 75+: mostly-empty bin being filled poorly
        }

        // Lookahead coupling: if next item fits exactly in post_residual, big reward
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 35.0;
            } else if next_item_size < post_residual {
                let npost = post_residual - next_item_size;
                // reward if chain continues with small remainder
                if npost <= 10 {
                    score -= 12.0;
                } else {
                    score -= (post_residual - next_item_size) as f64 * 0.05;
                }
            } else {
                // next item cannot fit here: leftover becomes dead space
                score += (post_residual - next_item_size).abs() as f64 * 0.02 + 4.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 15.0;
        // but if item is large relative to capacity and mean residual is small, new bin is fine
        let item_frac = item_size as f64 / cap;
        if item_frac > 0.7 {
            score -= 10.0;
        }
        if open_bins_count == 0 {
            score -= 60.0; // must open first bin
        }
        // late in stream, prefer consolidating rather than opening bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer bins with residual close to item size (tight fit)
    let tightness = (bin_residual - item_size) as f64;
    score += (tightness / cap) * 10.0;

    // Mild pressure to spread load when many bins are open with high mean residual
    score -= mean_residual * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps: post_residual in (0, 10] is dead space
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 8.0;
    }

    // Reward perfect or near-perfect fits
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Reward residual that can still fit the next item (lookahead)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open bins pressure: with many open bins, discourage spreading; prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (1.0 + progress) * 0.05;

    // New-bin candidate: empty bin should be chosen only when it beats tight fits
    if bin_residual == bin_capacity {
        score += 18.0 + mean_residual * 0.05;
    }

    // Prefer bins tighter than average (below-mean residual = better packed)
    score += (bin_residual as f64 - mean_residual) * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: penalize large post_residual relative to item size.
    score += 0.6 * (post_residual as f64 / item_size as f64);

    // 2-step lookahead: reward if next item fits perfectly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize proportional to wasted potential
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Compare against mean residual across open bins: prefer bins below mean residual (tighter).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when good existing fits exist, unless residual is very large.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless item is huge relative to capacity or no alternatives.
        let size_ratio = item_size as f64 / bin_capacity as f64;
        score += 10.0 - 8.0 * size_ratio;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative, must open new bin
        }
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
    }

    // Slight penalty for creating dead space below the minimum item size (unusable residual).
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: squared post-residual penalty for wasted space.
    score += 0.35 * (post_residual as f64) * (post_residual as f64) / cap;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Small dead-space threshold: residuals too small for typical items are wasted.
    let dead = if post_residual < 10 { 1.0 } else { 0.0 };
    score += dead * 12.0;

    // Lookahead: penalize if the next item fits better in the leftover space
    // we are consuming, i.e. next item would have fit in post_residual but
    // barely; conversely reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (n - post_residual as f64).abs() < 1.0 {
            score -= 15.0; // chaining exact fits
        } else if n <= post_residual as f64 {
            score += 0.15 * n; // mild cost of consuming space the next item needs
        } else {
            score -= 0.05 * (post_residual as f64); // leftover unusable anyway
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer fuller bins among many open bins.
    let fill = 1.0 - (bin_residual as f64) / cap;
    score -= 10.0 * fill * fill;

    // Global balance: penalize bins whose residual is far above mean residual
    // (they are under-filled); slight pull toward mean.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev;

    // Time horizon: early in the stream, be conservative (avoid opening too
    // many bins); late, allow spreading to reduce fragmentation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress;

    // New-bin candidate: default moderate score; opened only when open bins
    // score worse (poor fits, many open bins with large residuals).
    if bin_residual == bin_capacity {
        let base = 0.5 * item_size as f64 + 8.0;
        // Early stream: opening new bins is cheap-ish; late stream: expensive.
        score = base + 20.0 * (1.0 - progress) - 4.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let mut score = pr as f64;
    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 - progress) + norm_pr * norm_pr * progress;
    score += 40.0 * poly;
    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= 60.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;
    // Penalize dead space relative to mean residual of open bins
    score += 0.3 * (pr - mean_residual).max(0.0);
    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }
    // Lookahead: prefer leaving post_residual that fits the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 25.0 * (pr - nxt) / cap;
        } else {
            score += 15.0 * (nxt - pr) / cap;
        }
    }
    // New-bin candidate: mild penalty so we prefer existing bins unless very poor fit
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - norm_item) + 10.0 * (1.0 - progress);
    }
    // Mild scaling with open bins to encourage consolidation
    score += open_bins_count as f64 * 0.05 * norm_pr;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: partition post_residual into capacity-fraction classes.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;      // 25
    let fifth = bin_capacity / 5;        // 20
    let tenth = bin_capacity / 10;       // 10

    // Reward residuals that fall on "harmonic" grid values (highly reusable).
    let harmonic = if post_residual % quarter == 0 {
        12.0
    } else if post_residual % fifth == 0 {
        8.0
    } else if post_residual % tenth == 0 {
        5.0
    } else {
        0.0
    };
    score -= harmonic;

    // Penalize dead space: residuals too small to fit typical items.
    let min_item = 10.0_f64.min(c);
    if pr > 0.0 && pr < min_item {
        score += 40.0; // pure dead space
    } else if pr < 2.0 * min_item {
        score += 8.0;
    }

    // Lookahead coupling: harmonic class of next_item_size vs post_residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            // Perfect next-fit bonus: next item fills bin exactly.
            if (pr - nx) as u32 % tenth == 0 {
                score -= 10.0;
            } else {
                score -= 4.0;
            }
        } else {
            // Next item cannot use this bin's residual: penalize large leftovers.
            score += (pr - c * 0.1).max(0.0) * 0.3;
        }
        // Modulo affinity: residual and next item share a harmonic divisor.
        let g = gcd(post_residual, next_item_size);
        if g >= tenth {
            score -= 3.0;
        }
    } else {
        // Last item: prefer tightest closure.
        score += pr * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish, only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        score = c * 0.75 + (open_bins_count as f64) * 0.5 - mean_residual * 0.3;
        if fitting_bins_count == 1 {
            score += 30.0; // don't abandon the lone fitting bin
        }
    }

    // Mild stream-phase adaptation: late in stream, pack tighter.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= phase * 2.0;
    score += (mean_residual - pr).abs() * 0.05;

    score
}

fn gcd(a: u32, b: u32) -> u32 {
    if b == 0 { a } else { gcd(b, a % b) }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to the current residual.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // Lookahead coupling: penalize if post_residual can't fit the next item
    // but is large enough to be "wasted potential".
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Open-bin pressure: mildly discourage spreading across many bins,
    // but a brand-new empty bin is a fresh start, keep it competitive.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64;
    } else {
        score += 0.3 * open_bins_count as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mean-residual coupling: bins far below mean residual are less attractive.
    score += 0.15 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as u32 >= next_item_size {
            // Next item fits perfectly -> big reward
            score -= 60.0 * (1.0 - diff / (bin_capacity as f64)) * (1.0 + nxt / 100.0);
            // Bonus if next item fills bin exactly
            if post_residual == next_item_size {
                score -= 80.0;
            }
        } else {
            // Next item won't fit here: penalize leaving residue that's just slightly
            // too small for the next item (worst dead space)
            let gap = nxt - post_residual as f64;
            if gap <= 10.0 {
                score += 25.0 * (1.0 - gap / 10.0);
            }
        }
    } else {
        // Last item: strongly prefer tightest fit
        score -= 100.0;
    }

    // Prefer bins below mean residual (consolidating waste)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: this is the only bin that fits -> strong reward
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize leaving large unusable residue (post_residual < 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Early in stream: slightly favor filling existing bins over opening new ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when open bins have small residuals
        score += 15.0 * (1.0 - progress) + 0.3 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress within the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: reward near-perfect fills (post_residual close to 0)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Dead-space penalty: post_residual too small for the next item is wasted
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let waste = next_item_size as f64 - post_residual as f64;
        score += 3.0 + 0.35 * waste;
        // Extra penalty late in stream when closing out bins
        score += 4.0 * progress;
    }

    // Perfect-fit lookahead bonus: item + next item exactly fills the bin
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many open bins: prefer consolidating into existing bins, discourage opening more
    score += 0.8 * open_bins_count as f64;

    // New-bin candidate: only attractive when current bin fits are loose or absent
    if bin_residual == bin_capacity {
        let mean_fit_quality = if mean_residual > 0.0 {
            (item_size as f64 / mean_residual).min(2.0)
        } else {
            2.0
        };
        // Penalize new bins by default; reduce penalty when open bins fit poorly
        let mut new_bin_score = 55.0 + 5.0 * open_bins_count as f64;
        new_bin_score -= 18.0 * mean_fit_quality;
        // Late in the stream, prefer filling existing bins even more
        new_bin_score += 20.0 * progress;
        // If no other bin fits (fitting_bins_count == 0), new bin is necessary
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0;
        }
        score = new_bin_score;
    } else {
        // Prefer bins whose residual is closest to the item (best fit)
        let slack = (bin_residual - item_size) as f64;
        score += 0.25 * slack;
    }

    // Mild global balance: bins far below mean residual are less attractive
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Smooth polynomial core: reward tight fits (low post_residual)
    let mut score = pr as f64;

    // Non-linear coupling of post-residual with stream progress:
    // early on, tolerate slack; late, penalize dead space quadratically.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += 30.0 * x * x * (p2 + 0.5 * p3);
    score -= 20.0 * x * (1.0 - p2);

    // Fit scarcity: last fitting bin gets a bonus (smooth exponential)
    if fitting_bins_count <= 1 {
        score -= 25.0 * (1.0 - x) * (0.5 + progress);
    }

    // Lookahead coupling: if next item fits in post-residual, reward strongly
    let n = next_item_size as f64;
    if n > 0.0 && n <= pr as f64 {
        let fit_ratio = (n / cap).min(1.0);
        score -= 15.0 * (1.0 - fit_ratio) * (1.0 - progress);
    } else if n > pr as f64 && pr > 0 {
        score += 10.0 * x * x; // dead space next item can't use
    }

    // Mean residual context: prefer bins below mean residual (tighter)
    let dev = (mean_residual - bin_residual as f64) / cap;
    score += 8.0 * dev * dev * (1.0 - progress);

    // Mild penalty for too many open bins early
    score += (open_bins_count as f64).ln() * 2.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect class, reward heavily.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the leftover: leftover that can host another item
    // is far more valuable than dead space. Class by capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: leftovers below the smallest useful size (<= ~10)
    // are almost certainly waste.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 * (10.0 - pr) / 10.0;
    }

    // Lookahead compatibility: if next item fits exactly into post_residual,
    // strong reward (harmonic pair completion).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // next item fits: leftover keeps utility, scale by snugness
            let snug = (next_item_size as f64) / pr;
            score -= 80.0 * snug;
        } else {
            // next item cannot use this leftover: penalize proportionally
            score += 20.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current placement
    // would create large dead space or the bin is nearly full.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 60.0;
        // but if item is large relative to capacity, a new bin is natural
        let frac = (item_size as f64) / cap;
        if frac > 0.5 {
            score -= 70.0 * frac;
        }
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is closest to the item in harmonic terms:
    // integer-division class of residual vs item.
    let cls_fit = (bin_residual / item_size.max(1)) as f64;
    if cls_fit >= 1.0 {
        score -= 10.0 * (cls_fit.min(3.0) - 1.0);
    }

    // Slight preference for tighter bins overall (low residual relative to mean).
    if mean_residual > 0.0 {
        let rel = (bin_residual as f64) / mean_residual;
        if rel < 1.0 {
            score -= 15.0 * (1.0 - rel);
        }
    }

    // Modulo-style harmonic bonus: leftover divisible into common item classes
    // (multiples of 10) retains packing utility.
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Tight fit reward: cubic bonus for small leftover space.
    score -= 60.0 * (1.0 - pr / cap).powi(3);

    // Perfect or near-perfect fill is extremely attractive.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 12 {
        score -= 45.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 30.0;
            } else if gap <= 25 {
                score -= 12.0;
            }
        } else {
            // Penalize dead space the next item cannot use, scaled by how much is wasted.
            let dead = next_item_size as f64 - pr;
            score += dead.min(40.0) * 0.8;
            // Extra penalty if the dead space is small enough to be permanently stranded.
            if pr < 15.0 {
                score += 20.0;
            }
        }
        // Two-step lookahead: if the next item would leave a residual that can absorb
        // the *current* bin's stranded space, treat this bin as a good chain partner.
        if post_residual >= next_item_size && post_residual - next_item_size <= item_size as u32 {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    }

    // Consolidation pressure grows with the number of open bins.
    if open_bins_count > 2 {
        score -= 4.0 * (open_bins_count.min(20) as f64);
    }

    // Penalize residuals far above the mean (fragmentation risk), but forgive
    // bins that are nearly full — those are close to closure, not fragmented.
    let dev = (pr - mean_residual).abs();
    let forgiveness = 1.0 - (pr / cap).powi(2);
    score += dev * 0.3 * forgiveness.max(0.2);

    // New-bin candidate logic (empty bin call).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let horizon_factor = 1.0 - 0.5 * progress;
        score += 70.0 * horizon_factor;

        // If the best existing fit would strand a lot of space, a fresh bin gains value.
        let waste_here = pr; // empty-bin call: pr == capacity, so use item fit quality instead
        let _ = waste_here;
        if fitting_bins_count <= 1 {
            score -= 40.0;
        }
        // If the next item is large, a fresh bin is more useful.
        if next_item_size >= item_size {
            score -= 35.0;
        }
        // If current item nearly fills a fresh bin, opening is fine.
        if item_size as f64 >= 0.9 * cap {
            score -= 60.0;
        } else if item_size as f64 >= 0.6 * cap {
            score -= 20.0;
        }
    }

    // Mild time-horizon modulation: late in the stream, pack tighter.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - pr / cap);

    score
}

