            // Extra reward if the leftover after the next item would be tiny.
            let after2 = post_residual - next_item_size;
            score -= 8.0 * (1.0 - after2 as f64 / bin_capacity as f64);
        } else {
            // Post-residual can't host the next item: penalize proportionally.
            score += 6.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - pr / bin_capacity as f64);

    // Global fragmentation signal: if mean residual is high, opening new bins
    // is less costly, so existing bins with bad fits get penalized.
    if mean_residual > item_size as f64 + 15.0 {
        score += 3.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins for
    // better long-run packing; late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, and when current fits are poor.
        score -= 15.0 * (1.0 - progress);
        score -= 5.0 * (mean_residual / bin_capacity as f64);
        if post_residual == 0 {
            score -= 10.0; // perfect fit anywhere always wins
        }
        if fitting_bins_count <= 1 && bin_residual == bin_capacity {
            score -= 18.0; // no good existing option
        }
    } else {
        // Existing bin: more attractive late in the stream.
        score -= 10.0 * progress;
    }

    // Tight-fit reward: item nearly fills the bin.
    let tightness = item_size as f64 / bin_residual as f64;
    if tightness > 0.85 {
        score -= 10.0 * (tightness - 0.85);
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;
    score -= 70.0 * (1.0 - pr / cap).powi(3);
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 28.0;
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 45.0;
            } else if gap <= 6 {
                score -= 36.0;
            } else if gap <= 22 {
                score -= 14.0;
            } else {
                score += (gap as f64 - 22.0) * 0.28;
            }
        } else {
            score += (ni - pr).min(45.0) * 0.85;
        }
    }
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        if fill < 0.55 {
            score += 55.0 * (0.55 - fill);
        } else {
            score -= 10.0 * fill;
        }
        if fitting_bins_count > 1 {
            score += 8.0 * (fitting_bins_count.min(5) as f64);
        }
    }
    // tightness bonus: reward near-perfect fills
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 18.0;
    }
    // dead-space guard: residuals too small for typical items are wasted;
    // steer item into bins whose post-residual can still host mid-size items
    if post_residual > 0 && post_residual < 12 {
        score += 6.0;
    }
    // prefer bins whose residual is a good "landing pad" for the next item
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 4.0 * (1.0 - slack / cap).max(0.0);
    }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;
    score -= 68.0 * (1.0 - pr / cap).powi(3);
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 30.0;
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 40.0;
            } else if gap <= 20 {
                score -= 16.0;
            } else {
                score += (gap as f64 - 20.0) * 0.3;
            }
        } else {
            // lookahead: if next item also won't fit, dead space is compounding
            let waste = (ni - pr).min(45.0);
            let dead = if pr < ni && (pr + ni) > cap { 1.0 } else { 0.0 };
            score += waste * 0.9 + dead * 12.0;
        }
    }
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        if fill < 0.55 {
            score += 58.0 * (0.55 - fill);
        } else {
            score -= 12.0 * fill;
        }
        if fitting_bins_count > 1 {
            score += 9.0 * (fitting_bins_count.min(5) as f64);
        }
        // late in stream, prefer consolidating into existing bins
        if step_index * 4 > total_items * 3 {
            score += 6.0;
        }
    }
    if post_residual == 0 {
        score -= 44.0;
    } else if post_residual <= 3 {
        score -= 20.0;
    } else if post_residual <= 8 {
        score -= 6.0;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    let mut score = pr;

    // Smooth non-linear penalty on wasted space, growing with stream progress
    let norm_pr = pr / cap;
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) with a cubic bonus
    score -= 30.0 * (1.0 - norm_pr).powi(3);

    // Lookahead coupling: penalize leaving residual that neither fits nor matches next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs() / cap;
        score += 15.0 * gap * gap;
        // Reward residual that exactly accommodates the next item
        score -= 12.0 * (-20.0 * (pr - nx).abs() / cap).exp();
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Slight preference for bins deviating from mean residual (diversity of sizes)
    score += 3.0 * ((bin_residual as f64 - mean_residual) / cap).abs();

    // Mild penalty for many open bins, encouraging consolidation
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: keep it neutral-ish, only attractive when fits are bad
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - norm_pr) - 30.0 * (1.0 - item_size as f64 / cap).powi(2);
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // convex reward for high fill ratio (refined exponent)
    score -= 70.0 * (1.0 - pr / cap).powi(4);

    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 30.0;
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 40.0;
            } else if gap <= 20 {
                score -= 16.0;
            } else {
                score += (gap as f64 - 20.0) * 0.3;
            }
        } else {
            // dead-space penalty: leftover space that next item cannot use
            score += (ni - pr).min(50.0) * 0.9;
        }
    }

    // new-bin candidate handling
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        if fill < 0.58 {
            score += 60.0 * (0.58 - fill);
        } else {
            score -= 12.0 * fill;
        }
        // penalize opening a new bin when open bins can still fit
        if fitting_bins_count > 1 {
            score += 9.0 * (fitting_bins_count.min(6) as f64);
        }
        // late in the stream, prefer consolidating into open bins
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.7 {
            score += 6.0;
        }
    }

    // tightness bonus: reward near-perfect fills
    if post_residual == 0 {
        score -= 45.0;
    } else if post_residual <= 3 {
        score -= 20.0;
    } else if post_residual <= 7 {
        score -= 6.0;
    }

    // penalize residuals that are awkward relative to mean residual (dead space)
    if pr > 0.0 && mean_residual > 0.0 {
        let ratio = pr / mean_residual;
        if ratio > 2.0 {
            score += (ratio - 2.0).min(3.0) * 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    score -= 0.35 * (bin_capacity as f64 - post_residual as f64).max(0.0);

    // Harmonic class of post_residual: residual classes mod 10.
    // Residuals that are "harmonically useful" (>= 10, multiples of 5) are less penalized.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else if pr < 10 {
        // Dead space below the minimum item size: penalize hard.
        score += (10 - pr) as f64 * 4.0;
    } else {
        // Residual in [10, 100]: reward proportional to how well the NEXT item
        // could use it (lookahead harmonic matching).
        if next_item_size > 0 && next_item_size <= pr {
            score -= 25.0 + 0.3 * (pr - next_item_size) as f64;
        } else if next_item_size > 0 {
            // Next item cannot use this residual: mild penalty scaled by waste.
            score += 0.15 * (next_item_size - pr).min(50) as f64;
        }
        // Class bonus: residuals that are multiples of 5 or 10 are more reusable.
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
        // Integer-division thresholds: reward residuals in "usable bands".
        let band = pr / 20; // 0..5
        score -= band as f64 * 2.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New empty bin candidate: only attractive when current bin fit is bad
    // or no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // More attractive late in stream or when open bins are already crowded.
        score += 0.05 * open_bins_count as f64;
        if next_item_size > 0 {
            // A fresh bin guarantees room for the next item too.
            if next_item_size + item_size <= bin_capacity {
                score -= 18.0;
            }
        }
        // If the item would leave a bad residual in every existing bin,
        // opening fresh is competitive.
        if pr < 10 && pr > 0 {
            score -= 30.0;
        }
    }

    // Small coupling with mean residual: prefer bins below the mean
    // (consolidate fragmented space into larger leftovers).
    score += 0.10 * (mean_residual - bin_residual as f64);

    // Mild stream-phase modulation: tighten decisions early, loosen late.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * phase;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;
    score -= 65.0 * (1.0 - pr / cap).powi(3);
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 28.0;
            let gap = post_residual - next_item_size;
            if gap <= 6 {
                score -= 36.0;
            } else if gap <= 22 {
                score -= 14.0;
            } else {
                score += (gap as f64 - 22.0) * 0.25;
            }
            // extra reward when the leftover after next item also matches mean residual scale
            if (gap as f64 - mean_residual).abs() < 8.0 {
                score -= 6.0;
            }
        } else {
            score += (ni - pr).min(45.0) * 0.85;
        }
    }
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        if fill < 0.55 {
            score += 55.0 * (0.55 - fill);
        } else {
            score -= 10.0 * fill;
        }
        // penalize opening a new bin when many open bins can still fit
        if fitting_bins_count > 1 {
            score += 8.0 * (fitting_bins_count.min(5) as f64);
        }
        // late in the stream, avoid opening new bins unless the fill is exceptional
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress > 0.7 && fill < 0.75 {
            score += 30.0 * (0.75 - fill);
        }
    }
    // tightness bonus: reward near-perfect fills
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 18.0;
    } else if post_residual as f64 <= mean_residual * 0.5 {
        score -= 8.0;
    }
    // discourage leaving residuals that no plausible next item (<= 100) can use well
    if post_residual > 100 && pr / cap > 0.45 {
        score += 5.0;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can use
    // are heavily penalized. Items are >= 1, but "usable" gap threshold
    // grows with stream progression (late stream => waste is costlier).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let dead_threshold = 3.0 + 12.0 * progress;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 40.0 + dead_threshold - post_residual as f64;
    }
    // Zero waste is the ideal: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Penalize leaving a gap that exactly blocks the lookahead item
    // (gap < next item but > 0 => dead space for the next step).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0 + 0.25 * (next_item_size - post_residual) as f64;
    }
    // Reward if the next item fits exactly in the post residual.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance bonus: this is the only bin that can fit the item,
    // so avoid opening a new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins => prefer consolidating into
    // existing bins; few open bins => new bins are cheaper.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / bin_capacity as f64);
    score += 2.0 * pressure;

    // New-bin candidate: only attractive when open bins have poor
    // remaining space relative to the item, or fit is very loose.
    if bin_residual == bin_capacity {
        let mean_tightness = mean_residual / bin_capacity as f64;
        // Base cost of a fresh bin, discounted by how badly open bins fit.
        score = 55.0 + item_size as f64 * 0.3 - 45.0 * (1.0 - mean_tightness.min(1.0));
        if fitting_bins_count == 0 {
            score -= 70.0; // must open a bin anyway
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;
    score -= 65.0 * (1.0 - pr / cap).powi(3);
    // dead-space pressure: residual far above the stream's typical leftover is wasteful
    if mean_residual > 0.0 {
        let excess = pr - mean_residual;
        if excess > 0.0 {
            score += excess * 0.14;
        } else {
            score -= (-excess) * 0.06;
        }
    }
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 30.0;
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 42.0;
            } else if gap <= 20 {
                score -= 16.0;
            } else if gap <= 45 {
                score += (gap as f64 - 20.0) * 0.22;
            } else {
                score += (gap as f64 - 45.0) * 0.35 + 5.5;
            }
        } else {
            let miss = ni - pr;
            // small misses may still be tolerable if many bins remain open
            let relief = (fitting_bins_count.min(4) as f64) * 4.0;
            score += (miss.min(45.0) * 0.85 - relief).max(0.0);
        }
    }
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        if fill < 0.58 {
            score += 58.0 * (0.58 - fill);
        } else {
            score -= 12.0 * fill;
        }
        // penalize opening a new bin when open bins can still fit,
        // scaled by how much space those bins would waste
        if fitting_bins_count > 1 {
            score += 10.0 * (fitting_bins_count.min(5) as f64);
        }
        // late in the stream, avoid spawning bins for marginal gains
        if step_index * 4 > total_items * 3 && fill < 0.75 {
            score += 12.0 * (0.75 - fill);
        }
    }
    // tightness bonus: reward near-perfect fills
    if post_residual == 0 {
        score -= 44.0;
    } else if post_residual <= 3 {
        score -= 21.0;
    } else if post_residual <= 8 {
        score -= 8.0;
    }
    // lookahead: if next item exactly fills the post-residual of another
    // arrangement, prefer bins that leave a usable chunk vs fragmented slivers
    if post_residual > 8 && post_residual < next_item_size as u32 {
        score += (post_residual as f64) * 0.10;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Cubic fill-efficiency reward: the closer to full, the better.
    score -= 65.0 * (1.0 - pr / cap).powi(3);

    // Perfect fits are near-mandatory choices.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 120.0;
    } else if post_residual <= 6 {
        score -= 45.0;
    } else if post_residual <= 12 {
        score -= 15.0;
    }

    // 2-step lookahead with calibrated gap bands.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 28.0;
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 400.0; // sets up a perfect follow-up
            } else if gap <= 6 {
                score -= 36.0;
            } else if gap <= 22 {
                score -= 14.0;
            } else {
                score += (gap as f64 - 22.0) * 0.25;
            }
        } else {
            // Next item won't fit here; penalize dead-space risk, capped.
            score += (ni - pr).min(45.0) * 0.85;
        }
    }

    // Consuming more slack than the average residual is efficient.
    score -= 0.5 * (mean_residual - pr);

    // Last-chance bin: strongly prefer the only bin that fits over a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a bin unless the item would
    // fill it substantially; also penalize more when many bins already fit.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        if fill < 0.55 {
            score += 55.0 * (0.55 - fill);
        } else {
            score -= 10.0 * fill;
        }
        if fitting_bins_count > 1 {
            score += 8.0 * (fitting_bins_count.min(5) as f64);
        }
        if open_bins_count > 0 {
            score += 40.0 + 6.0 * open_bins_count.min(10) as f64;
        }
    }

    // Late-stream consolidation: tighten fits as progress advances.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 0.4 * pr;

    // Mid-stream: mildly favor bins whose residual matches typical upcoming items.
    if next_item_size > 0 && post_residual >= next_item_size {
        let ratio = next_item_size as f64 / (post_residual as f64).max(1.0);
        score -= 8.0 * ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: heavily reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: this bin becomes exactly full after next item
        } else if next_item_size <= post_residual {
            // partial chain: reward proportionally to how much of post_residual is consumed
            let fit_frac = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fit_frac;
        } else {
            // next item cannot follow here; penalize dead space that blocks the chain
            score += 15.0 * (next_item_size as f64 - post_residual as f64).min(30.0) / 30.0;
        }
    }

    // Penalize leaving residuals that are hard to fill (small awkward leftovers)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer bins tighter than the mean residual (best-fit style), scaled by mean
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Slight preference for filling existing bins as the stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
