            // reward leaving room for the next item proportionally to how snug it is
            let snug = next_item_size as f64 / post_residual as f64;
            score -= snug * 8.0;
        } else {
            // next item cannot use the leftover: mild penalty scaled by wasted fraction
            score += (next_item_size as f64 / bin_capacity as f64) * 4.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // would create bad residual states. Penalize fresh bins when good fits exist.
    if bin_residual == bin_capacity {
        // Base aversion to opening new bins, decaying as stream progresses
        // (early on, spreading items may be fine; late, consolidation matters).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * (1.0 - 0.5 * progress);

        // If many open bins already, opening more is costly.
        score += open_bins_count as f64 * 1.5;

        // If mean residual is large, there is slack available elsewhere — don't open.
        if mean_residual > item_size as f64 {
            score += (mean_residual - item_size as f64) * 0.5;
        }
    } else {
        // Reward using existing bins, more so when they are below mean residual
        // (i.e., we are consolidating the emptiest useful space).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Time horizon: late in the stream, avoid leaving many scattered partial bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 {
        score += post_residual as f64 * 0.3 * progress;
    }

    // Mild preference for bins whose residual is a "round" amount usable by
    // common item sizes (multiples of 10).
    if post_residual % 10 == 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
