    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Tightness ratio: the fuller the bin becomes, the better.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Last-chance bin: if this is the only bin that fits, avoid forcing a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into
    // existing bins; penalize opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (1.0 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins pressure.
        score += 25.0 + pressure;
        // But if the item is large and mean residual is small, new bin is fine.
        score -= (item_size as f64 / 100.0) * 20.0;
    } else {
        // Existing bin: slight reward that grows with pressure.
        score -= pressure * 0.3;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this placement; if it cannot fit, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 25.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Prefer bins whose residual is close to the item (snug fit).
    let snug = (bin_residual as f64 - item_size as f64).abs();
    score += snug * 0.2;

    // Deviation from mean residual: prefer bins tighter than average.
    score += (bin_residual as f64 - mean_residual).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Cubic tightness reward on fill ratio (borrowed idea, retuned).
    score -= 70.0 * (1.0 - pr / cap).powi(3);

    // Exact / near-exact fits.
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 120.0;
    } else if post_residual <= 8 {
        score -= 45.0;
    }

    // 2-step lookahead with gap-banded coupling.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post_residual >= next_item_size {
            if next_item_size == post_residual {
                score -= 420.0;
            } else {
                let gap = post_residual - next_item_size;
                if gap <= 6 {
                    score -= 55.0;
                } else if gap <= 22 {
                    score -= 18.0;
                } else {
                    score += (gap as f64 - 22.0) * 0.3;
                }
            }
        } else {
            score += (ni - pr).min(50.0) * 0.8;
        }
    }

    // Mean-residual coupling: consuming more slack than average is good.
    score -= 0.6 * (mean_residual - pr);

    // Only fitting bin: strongly prefer it over a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 160.0;
    }

    // New-bin candidate gating: allow it only for large items that leave
    // little waste; penalize more when many open bins already fit.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        if fill < 0.6 {
            score += 90.0 * (0.6 - fill) + 8.0 * open_bins_count as f64;
        } else {
            score -= 12.0 * fill;
        }
        if fitting_bins_count > 1 {
            score += 9.0 * (fitting_bins_count.min(6) as f64);
        }
    }

    // Late-stream consolidation pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 0.35 * pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
