pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit: small post residual relative to capacity
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 50.0;

    // Lookahead: reward if next item fits in post_residual (chaining)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0 + 0.5 * (next_item_size as f64);
        } else {
            // penalize dead space next item can't use
            score += 0.3 * (post_residual as f64 - (next_item_size as f64).min(post_residual as f64));
            if next_item_size as f64 > post_residual as f64 {
                score += 0.2 * (next_item_size as f64 - post_residual as f64);
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Many open bins: prefer filling existing ones over opening new
    if open_bins_count > 2 {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    // Global mean residual coupling: if this bin's residual is far below mean, it's tighter -> favor
    score += 0.4 * (mean_residual - bin_residual as f64);

    // Time horizon: later in stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize leaving residuals that are small but unusable (< smallest plausible item)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // New bin candidate: only attractive when no good existing option context
    if bin_residual == bin_capacity {
        score += 25.0 + 5.0 * (fitting_bins_count as f64);
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
