    score -= 65.0 * (1.0 - pr / cap).powi(3);

    // 2-step lookahead: exact setup for the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 6 {
                score -= 90.0;
            } else if gap <= 22 {
                score -= 60.0 * gap as f64 / cap;
            } else {
                score += (gap as f64 - 22.0) * 0.25;
            }
        } else {
            // Next item won't fit here: dead-space risk, capped penalty.
            score += (ni - pr).min(45.0) * 0.85;
        }
    }

    // Compare post residual to mean residual: efficient consumption reward.
    score -= 0.5 * (mean_residual - pr);

    // Last-chance bin: only fitting bin strongly preferred over new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate handling: bias by item fill fraction.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        if fill < 0.55 {
            score += 120.0 + 55.0 * (0.55 - fill) + 10.0 * open_bins_count as f64;
        } else {
            score += 120.0 + 10.0 * open_bins_count as f64 - 10.0 * fill;
        }
        if fitting_bins_count > 1 {
            score += 8.0 * fitting_bins_count.min(5) as f64;
        }
    }

    // Late-stream consolidation: prefer tightest fits more as progress grows.
