    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (low post residual)
    let mut score = pr;

    // Smooth non-linear coupling of post residual with stream progress:
    // early on, dead space matters less (bins may still be filled later);
    // late in the stream, wasted residual is heavily penalized.
    let progress_weight = 40.0 * progress * progress * (3.0 - 2.0 * progress); // smoothstep-like
    score += progress_weight * norm_pr * norm_pr * cap;

    // Penalize residuals that are too small to ever fit typical items,
    // but only smoothly via a quadratic dead-space term.
    let dead_threshold = 20.0;
    if pr < dead_threshold {
        let d = (dead_threshold - pr) / dead_threshold;
        score += 25.0 * d * d;
    }

    // Reward near-perfect fits with a smooth bonus (quadratic in 1 - norm_pr).
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead coupling: if next item fits exactly in post residual, reward smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = (pr - nxt).abs();
        if pr >= nxt {
            score -= 12.0 * (1.0 - fit_gap / cap);
        } else {
            score += 6.0 * (fit_gap / cap) * (fit_gap / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // mild competition normalization: more fitting bins -> slightly higher score for all,
        // preserving relative ordering by fit quality
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Mean residual coupling: bins far from the mean residual are slightly penalized,
    // encouraging homogenization of residual space for future packing.
    let mean_dev = (pr - mean_residual) / cap;
    score += 8.0 * mean_dev * mean_dev;

    // New-bin candidate handling: an empty bin has large post residual; make it
    // attractive only when the current bin fit is terrible (large norm_pr).
    if bin_residual == bin_capacity {
        score = pr + 10.0 - 20.0 * norm_pr * norm_pr + progress_weight * norm_pr;
        if next_item_size as f64 >= 0.9 * cap {
            score -= 15.0; // big next item: fresh bin is valuable
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
