        }
        // late in the stream, prefer closing out existing bins over opening new ones
        if step_index as f64 / total_items.max(1) as f64 > 0.75 {
            score += 12.0;
        }
    }
    // tightness bonus: reward near-perfect fills
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 18.0;
    }
    // steer toward bins whose residual is small relative to fleet average
    if mean_residual > 0.0 {
        let dev = (pr - mean_residual) / mean_residual;
