}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: which residue class does the leftover fall into? ---
    let pr = post_residual;
    // Perfect fits are ideal
    if pr == 0 {
        score -= 1000.0;
    }
    // "Dead zone": leftovers too small for the minimum item size (1) don't exist here,
    // but tiny leftovers relative to capacity are low-value; classify by eighths of capacity.
    let eighth = bin_capacity / 8;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    // Integer-division thresholds on post_residual: reward bins whose leftover
    // lands in "reusable" harmonic classes.
    let pr_class = pr / eighth; // 0..=8 harmonic class
    match pr_class {
        0 => score -= 40.0,               // leftover < 1/8 capacity: nearly full bin, great
        1 => score -= 20.0,               // small but plausibly fillable later
        2 => score -= 10.0,               // quarter-ish leftover, very reusable
        3 => score -= 5.0,
        4 => score += 0.0,                // half-full: neutral
        5 => score += 5.0,
        6 => score += 10.0,
        7 => score += 15.0,
        _ => {}
    }

    // Modulo coupling: leftover that is congruent to common item sizes is more reusable.
    // Check post_residual mod small harmonic moduli.
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0; // leftover is a multiple of 10 -> likely exact future fit
    }
    if pr % 5 == 0 && pr % 10 != 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 120.0;
        } else if next_item_size < pr {
            let nxt_left = pr - next_item_size;
            // harmonic class of the double-leftover
            if nxt_left / eighth == 0 {
                score -= 60.0; // two items would nearly exhaust this bin
            } else if nxt_left % 10 == 0 {
                score -= 25.0;
            } else {
                score -= 8.0;
            }
        } else {
            // next item cannot follow into this bin: penalize proportional to wasted potential
            score += 4.0 + (next_item_size as f64 - pr as f64).min(30.0) * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; modulated by stream progress and current fleet.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 - 30.0 + 25.0 * progress + (open_bins_count as f64).min(20.0) * 1.5;
        // If mean residual across open bins is large, opening new bins is wasteful.
        score += (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 40.0;
        // If next item is huge, a fresh bin has hedging value.
        if next_item_size >= half {
            score -= 20.0;
        }
    } else {
        // Prefer tighter existing bins: mild pull toward bins closer to full before placement.
        score += (bin_residual as f64 / bin_capacity as f64) * 5.0;
    }

    // Slight preference for consolidating when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
