    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score += (11 - post_residual) as f64 * 6.0;
    } else if post_residual <= 20 {
        score += 8.0;
    }

    // --- Reward tight fits (post_residual small relative to item) ---
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // --- Last-chance bin: strongly prefer using it over opening a new bin ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // --- Open-bin pressure: with many open bins, discourage opening new ones ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open-bin pressure,
        // but allow opening when existing residuals are large and fragmented.
        score += 20.0 + pressure;
        score -= (mean_residual - item_size as f64).max(0.0) * 0.2;
    } else {
        // Using an existing bin relieves pressure; reward more when many bins open.
        score -= pressure * 0.5;
    }

    // --- Lookahead: if the next item fits exactly in the post residual, big reward ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= 5.0;
        } else if post_residual > 0 && next_item_size > post_residual && next_item_size <= bin_capacity {
            // post residual too small for next item -> dead space likely
            score += (post_residual.min(20)) as f64 * 0.8;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Tightness bonus (borrowed strength from best heuristic)
    score -= 55.0 * (1.0 - norm_pr).powi(3);

    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 18.0;
    }

    // Lookahead: reward exact/near-exact fit of next item, penalize unusable gap
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 28.0;
            let gap = pr - ni;
            if gap <= 6.0 {
                score -= 36.0;
            } else if gap <= 22.0 {
                score -= 14.0;
            } else {
                score += (gap - 22.0) * 0.25;
            }
        } else {
            score += (ni - pr).min(45.0) * 0.85;
        }
    }

    // Dead-space penalty for residuals too small for typical items
    if pr < 20.0 {
        let d = (20.0 - pr) / 20.0;
        score += 12.0 * d * d;
    }

    // Mean residual homogenization
    let mean_dev = (pr - mean_residual) / cap;
    score += 6.0 * mean_dev * mean_dev;

    // Last-chance bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // New-bin candidate: open only for large items or when no decent fit exists
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        if fill < 0.55 {
            score += 55.0 * (0.55 - fill);
        } else {
            score -= 10.0 * fill;
        }
        if fitting_bins_count > 1 {
            score += 8.0 * (fitting_bins_count.min(5) as f64);
        }
        if next_item_size as f64 >= 0.9 * cap {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
