pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills (small post-residual dead space is exponentially penalized).
    let tiny_waste = (post_residual as f64 / bin_capacity as f64).powf(3.0);
    score -= 30.0 * tiny_waste;

    // Exact fit bonus: post_residual == 0 is the ideal outcome.
    if post_residual == 0 {
        score -= 50.0;
    }

    // --- Aggressive 2-step lookahead ---
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 == next {
            // Perfect chaining: next item exactly fills this bin.
            score -= 60.0;
        } else if (post_residual as f64) >= next {
            // Next item still fits here: mild reward proportional to closeness.
            let slack = post_residual as f64 - next;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize leftover that becomes dead space,
            // worse when the leftover is very small (unusable).
            let unusable = post_residual as f64 / next;
            score += 15.0 * (1.0 - unusable.min(1.0));
        }
        // Compare post_residual against the mean residual of open bins:
        // leaving a residual near the mean keeps flexibility for future items.
        let dev = (post_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is penalized, more so when many
    // bins are already open and the item fits poorly elsewhere.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut penalty = 8.0 + 10.0 * (open_bins_count as f64).ln();
        // Late in the stream, prefer consolidating into open bins.
        penalty += 10.0 * progress;
        // But if the item is large relative to a fresh bin, opening is safer.
        penalty -= (item_size as f64 / bin_capacity as f64) * 6.0;
        score += penalty;
    } else {
        // Mild preference for bins whose residual is closest to the item (tight fit).
        let tightness = 1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64;
        score -= 5.0 * tightness;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
