        if next_item_size <= post_residual {
            // Exact harmonic match: next item divides leftover nicely.
            let gap = post_residual - next_item_size;
            if gap <= bin_capacity / 8 {
                score -= 20.0;
            } else {
                score -= 8.0;
            }
        } else {
            // Next item won't fit here: leftover likely becomes dead space.
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Penalize the fresh bin progressively as the
    // stream advances and as open bins accumulate.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.05 * open_bins_count as f64
            + 20.0 * (step_index as f64 / total_items.max(1) as f64);
        // But if the mean residual across open bins is tiny (bins nearly full),
        // opening fresh capacity is reasonable.
        if mean_residual < 0.15 * c {
            score -= 30.0;
        }
    }

    // Mild global pressure: when many bins are open, tighten packing by
    // rewarding tighter fits relative to the mean residual.
    if pr < mean_residual {
        score -= 3.0;
    } else if pr > mean_residual * 1.5 {
        score += 3.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
