            }
        } else {
            // lookahead: how much of the item would spill relative to residual
            score += (ni - pr).min(45.0) * 0.85;
            // if bin is nearly full, mild extra penalty (dead space is small anyway)
            if pr < ni && pr <= 8.0 {
                score += 4.0;
            }
        }
    }

    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        if fill < 0.55 {
            score += 55.0 * (0.55 - fill);
        } else {
            score -= 10.0 * fill;
        }
        // penalize opening a new bin when many open bins can still fit
        if fitting_bins_count > 1 {
            score += 9.0 * (fitting_bins_count.min(5) as f64);
        }
        // discourage new bins late in the stream when open bins are roomy
        if mean_residual > 20.0 && open_bins_count > 2 {
            score += 6.0;
        }
    }

    // tightness bonus: reward near-perfect fills
    if post_residual == 0 {
        score -= 42.0;
    } else if post_residual <= 3 {
        score -= 18.0;
    } else if post_residual <= 7 {
        // small dead space still good, mild gradient
        score -= 8.0 * (7 - post_residual) as f64 / 4.0;
    }

    // reward bins whose residual stays usable for typical next items
    if post_residual >= 1 && post_residual <= 100 {
        let usable = (post_residual as f64 / 30.0).min(1.0);
        score -= 3.0 * usable;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
