    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 120.0; // tiny gap = wasted capacity forever
        } else if post_residual < 25 {
            score += 45.0; // only items >=10 can still use it, but awkwardly
        } else if post_residual < 40 {
            score += 12.0;
        }
    } else {
        score -= 60.0; // perfect fit: reward strongly
    }

    // Tightness reward: fraction of the residual consumed by this item.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 25.0 * (next_item_size as f64 / post_residual as f64);
        } else if post_residual > 0 && next_item_size > post_residual && post_residual < 10 {
            score += 40.0; // dead space that even the lookahead can't use
        }
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from existing open bins.
        score += 70.0 + 8.0 * open_bins_count as f64;
        // More attractive late in the stream when consolidation matters less.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 25.0 * progress;
        // If open bins have large mean residual, prefer them instead of a new bin.
        score += 0.35 * mean_residual;
        // If no open bin fits (this call is the only candidate), allow opening.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mild global pressure: prefer filling already-open bins as bin count grows.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
