pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward a perfect match between post_residual
    // and the next item size (bin becomes exactly full after two placements).
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            // Perfect 2-item fill: strongly favor this bin.
            score -= 40.0;
        } else {
            // Partial match: reward closeness, scaled by how tight the fit is.
            let tightness = 1.0 - gap / (post_residual as f64).max(1.0);
            score -= 25.0 * tightness * tightness;
        }
    } else if next_item_size > post_residual {
        // Next item cannot follow into this bin: penalize proportionally to
        // the leftover dead space created.
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward leaving post_residual small relative to the mean residual
    // (compact usage relative to the fleet average).
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when the current bin fit is poor (large post_residual
    // that the next item cannot use).
    if bin_residual == bin_capacity {
        // Mild preference for new bins early in the stream (diversification),
        // but generally worse than a good fit due to the base residual term.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
