    // tightness bonus: reward near-perfect fills
    if post_residual == 0 {
        score -= 41.0;
    } else if post_residual <= 3 {
        score -= 18.0;
    } else if post_residual <= 7 {
        score -= 7.0;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that becomes unusable for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Penalize leaving a gap just barely too small for the next item.
            let gap = next_item_size as f64 - post_residual as f64;
            if gap < 15.0 {
                score += 10.0 * (1.0 - gap / 15.0);
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful unless the item is huge
    // and no open bin is a decent fit, or open bins are mostly full.
    if bin_residual == bin_capacity {
        let avg_open_util = 1.0 - mean_residual / bin_capacity as f64;
        let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
        let big_item = item_size as f64 / bin_capacity as f64;
        // Cost of a fresh bin: base penalty, relieved by large items and high global pressure.
        score += 55.0 - 30.0 * big_item - 15.0 * avg_open_util;
        if fitting_bins_count > 0 && fit_ratio > 0.5 {
            score += 60.0; // never open a new bin when a tight fit exists
        }
        let _ = pressure;
    } else {
        // Slight preference for fuller bins to consolidate open bins.
        score -= 5.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    // Time-horizon modulation: early in the stream, be conservative (favor new bins
    // slightly to spread load); late in the stream, pack aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * fit_ratio;

    // Prefer bins whose residual deviates favorably from the mean (above-mean residual
    // bins absorb large items; below-mean bins should be left for small items).
    if item_size as f64 > mean_residual {
        score += 3.0 * (item_size as f64 - mean_residual) / bin_capacity as f64;
    }

    score
}

