    } else if post_residual <= 8 {
        score -= 7.0;
    }
    // combined lookahead: reward residuals that exactly host the next item,
    // and gently discourage leaving residuals that are just below it
    if next_item_size > 0 && bin_residual != bin_capacity {
        let ni = next_item_size as f64;
        let diff = (pr - ni).abs();
        if diff <= 2.0 {
