}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity-fraction band does the
    // leftover space fall into? Bands: (0,25] tiny, (25,50] half, (50,75], (75,100).
    let pr = post_residual;
    let band = (pr * 4) / bin_capacity.max(1); // 0..=4 integer division threshold
    let band_bonus: f64 = match band {
        0 => 6.0,                       // tiny dead space: worst outcome, penalize
        1 => -2.0,                      // quarter band: decent
        2 => -6.0,                      // half band: excellent, future items fit
        3 => -4.0,                      // three-quarter: roomy but wasteful
        _ => 0.0,
    };
    score += band_bonus;

    // Modulo-10 residue class: leftovers that are multiples of 10 are "harmonic"
    // since item sizes are typically multiples of 10; they pair cleanly.
    let m = pr % 10;
    if m == 0 {
        score -= 3.0;
    } else if m <= 4 {
        score += (5 - m) as f64 * 0.8;  // awkward slivers
    } else {
        score += (m - 5) as f64 * 0.4;
    }

    // Lookahead coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 10.0;              // perfect harmonic pairing
        } else if next_item_size <= pr {
            let pair_waste = pr - next_item_size;
            score -= 4.0 * (1.0 - pair_waste as f64 / bin_capacity as f64);
            if pair_waste % 10 == 0 {
                score -= 2.0;           // aligned pair
            }
        } else {
            // next item cannot use this leftover at all
            score += (next_item_size - pr).min(30) as f64 * 0.25;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: empty bin should only win when current bin
    // would leave a large, awkward remainder.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let awkward = (post_residual > 0 && post_residual < 20) ||
                      (next_item_size > 0 && next_item_size > post_residual && post_residual > 0);
        if awkward {
            score -= 5.0 + 5.0 * progress;
        } else {
            score += 12.0;              // keep using open bins by default
        }
    }

    // Slight nudge toward filling bins with large residual relative to mean.
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // Waste fraction term: penalize proportional dead space.
    score += 2.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

