    let mut score = pr;
    score -= 68.0 * (1.0 - pr / cap).powi(3);
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 30.0;
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 38.0;
            } else if gap <= 20 {
                score -= 15.0;
            } else {
                score += (gap as f64 - 20.0) * 0.28;
            }
            // extra reward when the follow-up item also fits after that
            if gap >= next_item_size as u32 * 2 {
                score -= 6.0;
            }
        } else {
            score += (ni - pr).min(48.0) * 0.88;
        }
    }
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        if fill < 0.55 {
            score += 58.0 * (0.55 - fill);
        } else {
            score -= 11.0 * fill;
        }
        // penalize opening a new bin when many open bins can still fit
        if fitting_bins_count > 1 {
            score += 9.0 * (fitting_bins_count.min(5) as f64);
        }
        // late in the stream, avoid spreading waste into fresh bins
        if step_index as f64 > 0.75 * total_items as f64 {
            score += 12.0;
        }
    }
    // tightness bonus: reward near-perfect fills
    if post_residual == 0 {
        score -= 42.0;
    } else if post_residual <= 3 {
        score -= 20.0;
    } else if post_residual <= 8 && (post_residual as f64) < mean_residual * 0.5 {
        score -= 8.0;
    }
    // mild penalty for leaving dead space far above the average residual
    if pr > mean_residual * 1.6 {
        score += (pr - mean_residual * 1.6) * 0.12;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post residual, mildly non-linear
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // early on, prefer filling bins (weight grows with progress^2)
    let progress_coupling = progress * progress * (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 20.0 * progress_coupling * pr;

    // Penalize dead space that cannot fit the next item (lookahead waste)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            let waste = (nxt - pr) / cap;
            score += 15.0 * waste * waste * cap * (0.5 + progress);
        } else {
            // reward residuals that exactly or nearly fit next item
            let fit_quality = 1.0 - ((pr - nxt) / cap);
            score -= 10.0 * fit_quality * fit_quality * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Prefer bins with residuals below mean (tighter bins first)
    let mean_term = (mean_residual - pr) / cap;
    score -= 5.0 * mean_term;

    // Smooth penalty for spreading across too many open bins late in stream
    let open_pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.1);
    score += 3.0 * open_pressure * norm_item * (0.5 + progress);

    // New-bin candidate: neutral-ish baseline with smooth progress-dependent reluctance
    if bin_residual == bin_capacity {
        score = cap * (0.8 + 0.4 * progress) - 10.0 * (1.0 - norm_item);
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
