    if post_residual == 0 {
        score -= 45.0;
    } else if post_residual <= 3 {
        score -= 20.0;
    } else if post_residual <= 8 {
        score -= 8.0;
    }
    // mild reward for leaving residuals that match common small items
    if post_residual > 0 && post_residual <= 25 && post_residual >= next_item_size.min(25) {
        score -= 4.0;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize into capacity fractions (1/8 bins)
    let quantum = bin_capacity / 8;
    let post_class = post_residual / quantum;
    let pre_class = bin_residual / quantum;

    // Reward placements that land post_residual exactly on a harmonic class boundary
    // (post_residual is a multiple of quantum => "clean" residual, reusable by coarse items)
    let boundary_dist = (post_residual as f64 - (post_class as f64 * quantum as f64)).abs();
    score -= 12.0 * (1.0 - boundary_dist / quantum as f64);

    // Penalize dead space: post_residual too small to fit the smallest plausible item (<= 10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Harmonic pairing: does post_residual exactly admit the next item (or a multiple/divisor class)?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0; // chain fit: next item fills this bin exactly
        } else if next_item_size <= post_residual {
            // next item fits; reward proportional to how tight the double-fit is
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
            // harmonic alignment: next_item_size divides post_residual evenly
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; penalize more if we wasted a lot of space
            score += 5.0 * ((next_item_size - post_residual) as f64 / cap_f);
        }
    }

    // Integer-division threshold on post_residual: bins with residual in the "awkward band"
    // (just above half-capacity fraction classes) are less valuable
    if post_class >= 4 && post_residual % quantum != 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless current bin fit is poor
    if bin_residual == bin_capacity {
        score += 45.0;
        // but if next item is huge and current placement would strand space, new bin is fine
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score -= 55.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * (1.0 - post_residual as f64 / cap_f);

    // Mean-residual coupling: if this bin's residual is far below mean, it's a good filler
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
