    let norm_item = item_size as f64 / cap;

    // Base: post residual with non-linear tightening of near-full bins
    let mut score = pr;
    score -= 65.0 * (1.0 - norm_pr).powi(3);

    // Progress coupling: prefer filling bins more as stream advances
    let progress_coupling = progress * progress * (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 15.0 * progress_coupling * pr;

    // Lookahead: gap-aware coupling with next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 28.0;
            let gap = post_residual - next_item_size;
            if gap <= 6 {
                score -= 36.0;
            } else if gap <= 22 {
                score -= 14.0;
            } else {
                score += (gap as f64 - 22.0) * 0.25;
            }
        } else {
            score += (ni - pr).min(45.0) * 0.85 * (0.6 + progress);
        }
    }

    // Perfect / near-perfect fill rewards
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 18.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 22.0 * (1.0 + progress);
    }

    // Prefer bins tighter than the mean
    let mean_term = (mean_residual - pr) / cap;
    score -= 4.0 * mean_term;

    // Mild pressure against spreading across many bins late in stream
    let open_pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.1);
    score += 3.0 * open_pressure * norm_item * (0.5 + progress);

    // New-bin candidate: reluctant when small items would leave big holes,
    // and when other open bins could also fit the item
    if bin_residual == bin_capacity {
        let fill = norm_item;
        if fill < 0.55 {
            score += 55.0 * (0.55 - fill);
        } else {
            score -= 10.0 * fill;
        }
        if fitting_bins_count > 1 {
            score += 8.0 * (fitting_bins_count.min(5) as f64);
        }
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than proportionally.
    // A gap is "unusable" if it is smaller than the minimum plausible item size (assume ~1..20)
    // and smaller than the next item that might use it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Dead space that the next item cannot use: penalize heavily.
            let dead = (next_item_size - post_residual) as f64;
            score += 2.5 * dead;
        } else {
            // Next item fits: reward leaving a tight-but-usable gap.
            score -= 1.5 * (post_residual as f64 - next_item_size as f64).min(20.0);
        }
    }

    // Non-linear penalty on tiny residual gaps (unusable crumbs).
    if post_residual > 0 && post_residual <= 10 {
        score += 8.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual <= 5 {
        score -= 5.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    // (penalize opening new bins / spreading residual).
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 1.2 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Penalize new-bin candidate unless current bins would leave big dead space.
    if bin_residual == bin_capacity {
        // New bin: neutral baseline; add mild penalty so existing good fits win,
        // but subtract if all fitting bins would waste a lot.
        score += 3.0;
        if post_residual > 0 && (post_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    // Slight preference for bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual - item_size) as f64;
    score += 0.3 * tightness;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
