    // tightness bonus: reward near-perfect fills
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 18.0;
    } else if post_residual <= 8 && next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
        score += 6.0; // residual too small for next item is nearly dead space
    }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
