pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item -> huge reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near match: next item fits with small slack
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + slack / 10.0);
    }

    // Next item does NOT fit the leftover: penalize proportionally to wasted lookahead
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.8;
    }

    // Reward tight fills (small post residual) especially when bin becomes near-full
    if post_residual < 10 {
        score -= 15.0;
    }
    if post_residual == 0 {
        score -= 20.0;
    }

    // Compare post residual against mean residual: leaving far more than average
    // residual wastes capacity elsewhere; leaving far less is good.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins fit badly.
    if bin_residual == bin_capacity {
        let mut bad_fit = true;
        if next_item_size > 0 && post_residual >= next_item_size {
            bad_fit = false;
        }
        if post_residual <= 10 {
            bad_fit = false;
        }
        if bad_fit {
            // base penalty, softened when many bins are open (consolidation pressure low)
            score += 45.0 - (open_bins_count.min(20) as f64);
        } else {
            score += 10.0;
        }
    }

    // Slight preference for using older/more-filled bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
