    // Open-bin pressure: mild preference to fill existing bins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 0.8 * pressure * (pr / cap);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate gating: only open a new bin for large items or when
    // existing fits are all poor.
    if bin_residual == bin_capacity {
