        // If current bins would leave big dead space, new bin becomes attractive.
        if post_residual > 0 && (post_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    // Tightness bonus: prefer bins whose residual is close to the item.
    let tightness = (bin_residual - item_size) as f64;
    score += 0.25 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
