    // Lookahead: penalize residuals that the next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Residual remains usable: mild reward scaled by usability.
            score -= 2.0 * (next_item_size as f64) / (post_residual as f64 + 1.0);
        } else {
            // Residual becomes dead for the next item: penalize proportionally.
            score += 4.0 * (post_residual as f64) / (next_item_size as f64 + 1.0);
        }
        // If next item exactly matches the post-residual, big reward.
        if post_residual == next_item_size && post_residual > 0 {
            score -= 12.0;
        }
    } else {
        // Last item: prefer zero waste anywhere.
        score -= 5.0 * (bin_residual as f64 - item_size as f64).recip().min(1.0);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Many open bins: prefer consolidation into existing bins.
    let crowding = open_bins_count as f64 / ((total_items as f64).max(1.0)).sqrt();
    score += 2.0 * crowding * (post_residual as f64 / bin_capacity as f64);

    // Global state coupling: if mean residual is high, tighten selection pressure.
    score += 0.5 * (mean_residual - post_residual as f64) * 0.1;

    // Time horizon: early in the stream, be pickier (keep bins flexible).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: empty bin should only win when fits are terrible.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more so when other bins fit the item.
        let mut new_bin_penalty = 30.0;
        if fitting_bins_count > 0 {
            new_bin_penalty += 20.0 * (fitting_bins_count as f64);
        }
        // Late in the stream, opening a fresh bin is more acceptable.
        new_bin_penalty *= (1.2 - progress);
        score += new_bin_penalty;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
