    // Mean residual context: prefer bins near mean residual (balance)
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate: make it attractive only when open bins are crowded
    if bin_residual == bin_capacity {
        score = 30.0 + 20.0 * prog_coupling - 5.0 * (mean_residual / cap);
    }

    score
}

