pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "slot band" it falls into.
    let band = post_residual / (bin_capacity / 4); // 0..=4 bands of 25
    match band {
        0 => score -= 30.0, // near-perfect fit, strongly reward
        1 => score -= 12.0, // good fit
        2 => score -= 4.0,  // moderate
        3 => score += 8.0,  // poor: leaves awkward 50-75 dead space
        _ => {}             // mostly empty bin usage
    }

    // Modulo-10 harmonic: dead space that is a multiple of 10 is reusable
    // by typical item sizes; non-multiples are more likely to be dead.
    let dead_mod = post_residual % 10;
    if dead_mod != 0 {
        score += dead_mod as f64 * 0.6;
    } else {
        score -= 3.0;
    }

    // Lookahead coupling: reward if next item exactly fills post_residual,
    // penalize if next item cannot use the residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size <= post_residual {
            let frac = post_residual as f64 / next_item_size as f64;
            if frac < 2.0 {
                score -= 10.0; // next item consumes most of residual
            } else {
                score += 5.0; // next item leaves a lot behind anyway
            }
        } else {
            score += 6.0; // residual unusable for next item
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin early in the stream
    // or when few bins are open; allow it late when residuals are fragmented.
    let is_new_bin = bin_residual == bin_capacity && post_residual > 0;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs() / bin_capacity as f64;
        score += 20.0 - 15.0 * progress - 10.0 * fragmentation;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Prefer tighter (smaller residual) bins overall, scaled by mean residual.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

