pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps that are too small to hold any plausible item are wasted.
    // Penalize post_residual in the "dead zone" (1..=9) heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Mid-range leftovers that few items can use are also bad.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }
    // Perfect or near-perfect fits are highly desirable.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward tightness relative to bin capacity (fractional fill quality).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Penalize leaving residual far below mean residual (wasting a roomy bin
    // when the item barely fits) only mildly; tight fits preferred instead.
    let fit_tightness = (bin_residual - item_size) as f64 / bin_residual.max(1) as f64;
    score += 10.0 * (1.0 - fit_tightness);

    // --- Open bins pressure ---
    // Encourage filling existing bins as the number of open bins grows.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score -= 6.0 * pressure;

    // --- Last-chance bin ---
    // If this is the only bin that can fit the item, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // --- Lookahead coupling (k=2) ---
    // If the next item fits exactly into the post residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 20.0;
        }
        // If post_residual cannot host the next item but is small, penalize.
        if next_item_size > post_residual && post_residual < 10 {
            score += 15.0;
        }
    }

    // --- New-bin candidate handling ---
    // An empty bin has bin_residual == bin_capacity. Its natural post_residual
    // is large, so add a mild opening cost that grows over the stream; this
    // makes opening a new bin only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 + 10.0 * progress;
        // But if no open bin fits and open bins are many, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Small nudge toward bins with residual close to the item (best-fit core).
    score += 0.15 * ((bin_residual as f64 - item_size as f64) - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
