    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Prefer bins with residuals below mean (tighter bins first)
    let mean_term = (mean_residual - pr) / cap;
    score -= 5.0 * mean_term;

