pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    if post_residual == 0 {
        // Perfect closure: overwhelmingly good
        return -1000.0;
    }

    // Base: post residual, mildly non-linear
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress
    let progress_coupling = progress * progress * (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 20.0 * progress_coupling * pr;

    // Lookahead: exact match with next item is a perfect two-step play
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr == nxt {
            score -= 900.0 - 30.0 * progress;
        } else if pr < nxt {
            let waste = (nxt - pr) / cap;
            score += 15.0 * waste * waste * cap * (0.5 + progress);
            // small dead sliver that can't fit next item: extra penalty
            if post_residual < 10 {
                score += 45.0 * (1.0 - progress);
            } else if post_residual < 20 {
                score += 10.0;
            }
        } else {
            // reward residuals that nearly fit next item, scaled by closeness
            let two_step_waste = pr - nxt;
            if two_step_waste <= 10.0 {
                score -= 80.0 + 1.5 * (10.0 - two_step_waste);
            } else {
                score -= 300.0 - 2.0 * two_step_waste;
            }
            let cushion = two_step_waste.min(15.0);
            score -= (2.0 + 2.0 * progress) * cushion;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    } else if fitting_bins_count == 2 && post_residual < bin_capacity / 3 {
        score -= 8.0;
    }

    // Prefer bins with residuals below mean (tighter bins first)
    let mean_term = (mean_residual - pr) / cap;
    score -= 5.0 * mean_term;

    // Fill ratio reward: denser placement first
    let fill = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 20.0 * fill;

    // Penalize spreading across too many open bins late in stream
    let open_pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.1);
    score += 3.0 * open_pressure * norm_item * (0.5 + progress);

    // Keep residuals "usable-shaped" for future mid-sized items
    if post_residual >= bin_capacity / 8 && post_residual <= bin_capacity / 2 {
        score -= 6.0;
    }

    // Sliver penalty when bins are plentiful
    if post_residual <= 5 && open_bins_count > 6 {
        score += 25.0 * (1.0 - progress);
    }

    // New-bin candidate gating
    if bin_residual == bin_capacity {
        let big_next = next_item_size as f64 / cap;
        score = cap * (0.8 + 0.4 * progress)
            + 180.0 - 60.0 * progress
            + 0.15 * open_bins_count as f64
            - 25.0 * big_next.max(0.0)
            - 10.0 * (1.0 - norm_item);
        // clean two-step play: fresh bin leaves exact residual for next item
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 30.0;
        }
        // discourage new bins when open bins are abundant and mostly empty
        if open_bins_count > 6 && mean_residual > 0.4 * cap {
            score += 20.0;
        }
        if open_bins_count <= 4 && progress < 0.3 {
            score += 25.0;
        }
        if mean_residual < 15.0 && progress > 0.5 {
            score -= 15.0;
        }
        let item_frac = norm_item;
        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3;
        }
    }

    score
}

