        }
        // NEW: scarcity-aware lookahead — when few bins can host the next item,
        // strongly prefer leaving a residual that keeps the next item placeable
        if next_item_size > 0 && post_residual >= next_item_size {
            let scarcity_bonus = match fitting_bins_count {
                1 => 30.0 ,
                2 => 15.0 ,
                3 => 6.0 ,
                _ => 0.0 ,
            } ;
