                }
                // NEW: reward residuals that could host next item plus a small remainder
                let after_next = post_residual - next_item_size;
                if after_next > 0 && after_next <= 6 && open_bins_count > 3 {
                    score -= 6.0 * (1.0 - after_next as f64 / 6.0);
                }
            } else {
                score += 2.0 * (next_item_size - post_residual) as f64;
                if post_residual < 25 {
