                // near-perfect sealed bins
                if post_residual < 3 {
                    score -= 400.0;
                }
                // NEW: residual just below next item is nearly dead — scale penalty by closeness
                let miss = (next_item_size - post_residual) as f64;
                if miss <= 5.0 {
                    score += 25.0 * (1.0 - miss / 5.0);
                }
            }
        }

