            score += 12.0;
        }
        // large items into fresh bins leave usable leftovers
        if item_frac > 0.6 && next_item_size > 0 && fresh_left >= next_item_size as f64 {
            score -= 8.0 * (1.0 - progress);
        }
    }

    score
}

