                }
                // residual hosting two next-items cleanly
                if next_item_size > 1 && post_residual >= 2 * next_item_size && post_residual % next_item_size == 0 {
                    score -= 15.0;
                }
                // two-item lookahead: leftover after next item stays usable
                let after_next = post_residual - next_item_size;
                if after_next <= 12 && mean_residual >= after_next as f64 {
                    score -= 22.0 - 0.8 * after_next as f64;
                }
                // leftover after next item still fits next_item again (multi-pack)
                if next_item_size > 1 && after_next >= next_item_size {
                    score -= 6.0 + 0.2 * (after_next / next_item_size) as f64;
                }
                // REFINED: graded reward for leftover after next item that remains
