    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post residual, mildly non-linear
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Progress coupling: prefer filling bins as stream advances
    let progress_coupling = progress * progress * (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 20.0 * progress_coupling * pr;

    // Lookahead: penalize dead space vs next item; reward near/exact fits
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            let waste = (nxt - pr) / cap;
            score += 15.0 * waste * waste * cap * (0.5 + progress);
            // near-miss residuals are stranded: strong penalty early
            let miss = (nxt - pr) as u32;
            if miss <= 3 {
                score += 8.0 * (4 - miss) as f64 * (1.0 - progress);
            }
            // tiny slivers are unusable
            if pr < 10.0 {
                score += 30.0 * (1.0 - progress);
            }
