            score += 35.0;
        }
        // prefer fresh bin when existing residuals can't host next item
        if next_item_size > 0 && fitting_bins_count <= 2 && mean_residual < next_item_size as f64 {
            score -= 18.0 * (1.0 - progress);
        }
        // discourage opening fresh bins when many usable bins exist
        if open_bins_count > 8 && mean_residual > next_item_size as f64 + 10.0 {
            score += 12.0;
        }
        // fresh leftover hosting next item plus mean slack
        if next_item_size > 0 && (fresh_left as u32) >= next_item_size
            && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress);
        }
        // large items leave big usable leftovers
        if norm_item > 0.6 && next_item_size > 0 && (fresh_left as u32) >= next_item_size {
            score -= 8.0 * (1.0 - progress);
        }
    }

    score
}

