        // (perfect two-step closure) — strong compaction reward
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress);
            }
        }
        // fresh bin leftover below mean residual is likely dead space —
        // discourage unless it exactly matches the next item
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0;
        }
        // NEW: fresh bin is strongly justified when no open bin can host the
        // next item but the fresh leftover can — avoids future forced new bins
        if next_item_size > 0 && fitting_bins_count <= 1 && fresh_left >= next_item_size {
            score -= 12.0 + 8.0 * (1.0 - progress);
        }
        // NEW: late stream — prefer closing bins tightly over opening fresh ones
        if progress > 0.8 && open_bins_count > 3 {
            score += 15.0 * (progress - 0.8) / 0.2;
        }
    }

    score
}

