        // penalize when the item is small and bins are still cheap to fill
        if item_frac < 0.2 && open_bins_count > 2 && progress < 0.6 {
            score += 15.0 * (0.6 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    if post_residual == 0 {
        score -= 1000.0;
    } else {
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 900.0 - 30.0 * progress;
            } else if next_item_size <= post_residual {
                let two_step_waste = (post_residual - next_item_size) as f64;
                if two_step_waste == 0.0 {
                    score -= 700.0;
                } else if two_step_waste >= 10.0 {
                    score -= 300.0 - 2.0 * two_step_waste;
                } else {
                    score -= 80.0 + 1.5 * (10.0 - two_step_waste);
                }
                // cushion: comfortable slack for the next item
                if post_residual >= next_item_size + 3 {
                    let cushion = (post_residual - next_item_size) as f64;
                    score -= (2.0 + 2.0 * progress) * cushion.min(15.0);
