                }
                // NEW: residual within 2 of a multiple of next_item — near-exact chain
                if next_item_size > 2 && post_residual > next_item_size {
                    let r = post_residual % next_item_size;
                    if r == 1 || r == next_item_size - 1 {
                        score -= 5.0;
                    }
                }
            } else {
                score += 2.0 * (next_item_size - post_residual) as f64;
                if post_residual < 25 {
