    let prn = pr / cap;
    let p1 = prog;
    let p2 = prog * prog;
    let p3 = p2 * prog;
    // Weight grows smoothly with progress: prefer tight fits early, penalize waste late.
    let w = 6.0 * p1 + 18.0 * p2 + 24.0 * p3;
    score += w * prn * prn * cap;

