pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo small moduli.
    // Residue 0 (perfect fill or multiple of a divisor) is highly desirable.
    let r8 = post_residual % 8;
    let r10 = post_residual % 10;
    let r16 = post_residual % 16;

    // Reward small residues (near-perfect packing classes).
    score -= match r8 {
        0 => 14.0,
        1 => 7.0,
        2 => 4.0,
        3 => 2.0,
        _ => 0.0,
    };
    score -= if r10 == 0 { 10.0 } else if r10 <= 2 { 4.0 } else { 0.0 };
    score -= if r16 == 0 { 6.0 } else { 0.0 };

    // Dead-space penalty: residuals below the smallest plausible item (<= 10)
    // are essentially unusable; penalize hard via integer-division threshold.
    let dead_units = post_residual / 10; // 0 => dead space class
    if dead_units == 0 {
        score += 30.0;
    } else if dead_units == 1 {
        score += 8.0;
    }

    // Coupling with next item: if next_item_size fits exactly into post_residual,
    // strongly reward; if it nearly fits, mild reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap % 10 == 0 {
                score -= 12.0;
            } else if gap <= 5 {
                score -= 6.0;
            }
        } else {
            // next item won't fit here; slightly penalize leaving a large odd residue
            if post_residual % 10 != 0 {
                score += 3.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
        if dead_units >= 3 {
            score += 10.0; // but poor fit overrides
        }
    }

    // New-bin candidate: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened later in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 - 8.0 * progress;
        // If mean residual is large, prefer using open bins
        if mean_residual > item_size as f64 + 15.0 {
            score += 12.0;
        }
    }

    // Mild preference to fill bins tighter than the mean residual.
    if (post_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

