            if next_item_size == post_residual {
                // chain closure: next item seals this bin exactly
                score -= 900.0 - 30.0 * progress;
            } else if next_item_size < post_residual {
                let after_next = post_residual - next_item_size;
                let slack = after_next as f64;
                if slack == 0.0 {
                    score -= 700.0;
                } else if slack >= 10.0 {
                    score -= 300.0 - 2.0 * slack;
                } else {
                    score -= 80.0 + 1.5 * (10.0 - slack);
                }
                // comfortable cushion for the next item
                if after_next >= 3 {
                    score -= (2.0 + 2.0 * progress) * slack.min(15.0);
                }
                // leftover after next item still hosts next_item again
                if next_item_size > 1 && after_next >= next_item_size {
                    score -= 6.0 + 0.2 * (after_next / next_item_size) as f64;
                    if after_next % next_item_size == 0 {
                        let chain_bonus = if open_bins_count > 6 { 16.0 } else { 12.0 };
                        score -= chain_bonus;
                    }
                }
                // leftover after next item is small and reusable
                if after_next <= 12 && mean_residual >= after_next as f64 {
                    score -= 22.0 - 0.8 * after_next as f64;
                }
                // headroom matches mean residual shape: good future home
                if (slack - mean_residual).abs() <= 3.0 {
                    score -= 7.0;
                }
                // residual hosts next item twice exactly
                if next_item_size > 0 && post_residual == 2 * next_item_size {
                    score -= 10.0;
                }
            } else {
                // next item does NOT fit in the leftover
                let miss = next_item_size - post_residual;
                score += 2.0 * miss as f64;
                if post_residual < 25 {
                    score += 15.0;
                }
                // near-sealed bins are excellent regardless
                if post_residual < 3 {
                    score -= 400.0;
                }
                // strand-space guard just under common small sizes
                if post_residual >= 8 && post_residual <= 16 {
                    score += 10.0 * (1.0 - progress);
                }
                // near-miss is forgivable when few alternatives exist
                if miss <= 6 && fitting_bins_count <= 2 {
                    score -= 5.0;
                }
                if miss <= 3 {
                    score += 8.0 * (4 - miss) as f64 * (1.0 - progress);
                }
            }
        }

        // small leftovers are likely dead space
        if post_residual < 10 {
            score += 45.0;
        } else if post_residual < 20 {
            score += 10.0;
        }

        // residual balance against mean
        score -= (mean_residual - post_residual as f64) * 0.6;

        // gap-based dead-space penalty with scarcity scaling
        let gap = (post_residual as f64 - item_size as f64).max(0.0);
        let gap_ratio = gap / (item_size as f64).max(1.0);
        if gap > 0.0 {
            let scarcity = if fitting_bins_count <= 2 { 0.6 } else if fitting_bins_count <= 4 { 0.3 } else { 0.2 };
            score += scarcity * gap + 18.0 * gap_ratio.min(2.0);
            if gap < mean_residual {
                let fillable = next_item_size > 0 && gap >= next_item_size as f64;
                let w = if fillable { 0.2 } else { 0.6 };
                score += w * (mean_residual - gap);
            }
        }

        // last-chance bonus for the only fitting bin
        if fitting_bins_count == 1 {
            score -= 12.0;
        }

        // reward high fill ratio
        let fill = item_size as f64 / (bin_residual as f64).max(1.0);
        score -= 20.0 * fill;

        // unusable residual relative to the next item
        if next_item_size > 0 && post_residual < next_item_size {
            let dead_frac = post_residual as f64 / bin_capacity as f64;
            let unusable_ratio = post_residual as f64 / (next_item_size as f64).max(1.0);
            score += 0.4 * post_residual as f64 + 30.0 * dead_frac + 12.0 * (1.0 - unusable_ratio);
            if next_item_size - post_residual <= 4 {
                score += 20.0 * (1.0 - progress);
            }
        }

        // anti-fragmentation guard
        if fitting_bins_count == 2 && post_residual < bin_capacity / 3 {
            score -= 8.0;
        }

        // tiny slivers when bins are plentiful
        if post_residual <= 5 && open_bins_count > 6 {
            score += 25.0 * (1.0 - progress);
        }

        // mid-sized future homes
        if post_residual >= bin_capacity / 8 && post_residual <= bin_capacity / 2 {
            score -= 6.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= bin_capacity / 2 {
            score -= 4.0 * (1.0 - progress);
        }
        // residuals that can absorb two more average items
        if post_residual as f64 >= 2.0 * mean_residual && post_residual > 20 {
            score -= 5.0;
        }
    }

    // ---- NEW-BIN CANDIDATE ----
    if bin_residual == bin_capacity {
        let fresh_left = bin_capacity - item_size;
        let item_frac = item_size as f64 / bin_capacity as f64;
        let big_next = next_item_size as f64 / bin_capacity as f64;
        score += 180.0 - 60.0 * progress + 0.15 * open_bins_count as f64 - 25.0 * big_next.max(0.0);

        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
        if open_bins_count <= 4 && progress < 0.3 {
            score += 25.0;
        }
        if mean_residual < 15.0 && progress > 0.5 {
            score -= 15.0;
        }
        // small items in a fresh bin waste capacity
        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3;
        }
        // fresh bin leftover exactly fits the next item
        if next_item_size > 0 && fresh_left == next_item_size {
            score -= 30.0;
        }
        // fresh bin leftover hosts next item with near-zero tail
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress);
            }
        }
        // fresh bin leftover can host next item twice exactly
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0;
        }
        // fresh bin justified when leftover hosts next item plus mean slack
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress);
        }
        // fresh-bin leftover sliver is wasteful
        if next_item_size > 0 && fresh_left < next_item_size && fresh_left < 8 {
            score += 35.0;
        }
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0;
        }
        // prefer fresh bin when existing residuals cannot host the next item
        if next_item_size > 0 && fitting_bins_count <= 2 && mean_residual < next_item_size as f64 {
            score -= 18.0 * (1.0 - progress);
        }
        // discourage fresh bins late when many half-empty bins exist
        if open_bins_count > 8 && mean_residual > next_item_size as f64 + 10.0 {
            score += 12.0;
        }
        // large items leave big usable leftovers in fresh bins
        if item_frac > 0.6 && next_item_size > 0 && fresh_left >= next_item_size {
            score -= 8.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize residual below the minimum item size band (1..=10 unusable).
    if post_residual < 10 {
        score += (10.0 - post_residual as f64) * 4.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 25.0;

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (empty-bin candidate has bin_residual == bin_capacity).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 8.0 + progress * 20.0;
    } else {
        score -= open_bins_count as f64 * 2.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 20.0;
        }
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        score += 10.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - post_residual as f64) * 0.3;

    score
}

