pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    if post_residual > 0 {
        if next_item_size > 0 {
            if next_item_size == post_residual {
                // perfect two-step chain: strong reward, slightly stronger early
                score -= 900.0 - 30.0 * progress;
            } else if post_residual >= next_item_size {
                let two_step_waste = (post_residual - next_item_size) as f64;
                if two_step_waste == 0.0 {
                    score -= 700.0;
                } else if two_step_waste >= 10.0 {
                    score -= 300.0 - 2.0 * two_step_waste;
                } else {
                    score -= 80.0 + 1.5 * (10.0 - two_step_waste);
                }
                // cushion: comfortable slack for the next item
                if post_residual >= next_item_size + 3 {
                    let cushion = (post_residual - next_item_size) as f64;
                    score -= (2.0 + 2.0 * progress) * cushion.min(15.0);
                }
                // multi-pack: leftover after next item still fits next_item again
                let after_next = post_residual - next_item_size;
                if next_item_size > 1 && after_next >= next_item_size {
                    score -= 6.0 + 0.2 * (after_next / next_item_size) as f64;
                    // chain home: leftover hosts next item an exact number of times
                    if after_next % next_item_size == 0 {
                        score -= 8.0 * (1.0 - progress);
                    }
                }
                // leftover after next item stays small and usable
                if after_next <= 12 && mean_residual >= after_next as f64 {
                    score -= 22.0 - 0.8 * after_next as f64;
                }
                // near-seal sliver after next item
                if after_next < next_item_size && after_next <= 3 {
                    score -= 14.0 * (1.0 - progress);
                }
                // near-seal: leftover just below next item but close
                if after_next < next_item_size && after_next >= 1 && (next_item_size - after_next) <= 5 {
                    score -= 6.0 * (1.0 - progress);
                }
                // leftover matches mean residual shape: reusable home
                if (after_next as f64 - mean_residual).abs() <= 4.0 {
                    score -= 6.0 * (1.0 - progress);
                }
                // three-way closure: residual hosts next item then seals exactly
                if post_residual == 2 * next_item_size {
                    score -= 10.0;
                }
                // headroom matches mean residual: compaction sweet spot
                if (two_step_waste - mean_residual).abs() <= 3.0 {
                    score -= 7.0;
                }
            } else {
                // next item will NOT fit: dead space risk, scaled by near-miss
                let miss = (next_item_size - post_residual) as f64;
                score += 40.0 * miss;
                if miss <= 3.0 {
                    score += 8.0 * (4.0 - miss) * (1.0 - progress);
                }
                if post_residual < 25 {
                    score += 15.0;
                }
                // near-perfect sealed bins
                if post_residual < 3 {
                    score -= 400.0;
                }
                // strand-space guard just under common small sizes
                if post_residual >= 8 && post_residual <= 16 {
                    score += 10.0 * (1.0 - progress);
                }
                // near-miss that seals the bin exactly on a later small item
                if miss <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
                // near-miss with only one other fitting bin: keep it alive anyway
                if miss <= 6.0 && fitting_bins_count <= 2 {
                    score -= 5.0;
                }
                // salvage late in the stream with few alternatives
                if miss <= 10.0 && fitting_bins_count <= 2 && progress > 0.7 {
                    score -= 10.0 * (1.0 - progress);
                }
            }
        }

        // Compare post residual to mean residual: consuming efficiently.
        score -= 0.6 * (mean_residual - post_residual as f64);

