    } else if post_residual <= 15 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: reward when the next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // perfect 2-step chain
        } else if next_item_size < post_residual {
            let slack_after_next = post_residual - next_item_size;
            if slack_after_next <= 5 {
