            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.3 * overshoot;
        }
    } else {
        // Last item: only the immediate fit matters.
        score -= 15.0;
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (tighter bins),
    // i.e. using up a tight bin is good; leaving a loose bin is fine.
    score += 0.4 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; prefer it only
    // when placing into an open bin would create large dead space late in the stream.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score += 40.0;
        // Late in the stream, opening fresh bins is more acceptable.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * progress;
        // If many bins are open and mean residual is small, opening a new bin
        // is relatively cheap; if few bins, discourage it.
        if open_bins_count <= 2 {
            score += 25.0;
        }
        // If next item is large, an empty bin preserves flexibility.
        if next_item_size >= 60 {
            score -= 20.0;
        }
    }

    // Mild penalty for wasting a very large bin residual on a tiny item.
    if item_size < 20 && bin_residual > 80 && bin_residual < bin_capacity {
        score += 15.0;
    }

    score
}

