        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        // NEW: fresh bin penalized when some open bin's post-fit residual still hosts next item
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size && post_residual <= bin_capacity / 2 {
            score += 8.0 * (1.0 - progress) ;
        }
        // NEW: fresh bin late in stream with large leftover relative to remaining demand is wasteful
        if progress > 0.6 && fresh_left as f64 > 2.0 * mean_residual {
            score += 10.0 * (progress - 0.6) / 0.4 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(3) * 12.0;

    // Penalize dead space that no plausible future item can use:
    // if post_residual is nonzero but smaller than the smallest plausible item,
    // it is likely wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty for stranding it
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer filling bins with already-low residual (consolidate fragmentation).
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= tightness * 6.0;

    // Global state: if many bins are open with large mean residual,
    // encourage using existing bins rather than opening new ones.
    if bin_residual < bin_capacity {
        let openness = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score -= openness * 1.5;
    } else {
        // New-bin candidate: penalize mildly unless current bins are very fragmented.
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 10.0 + fragmentation * 0.2;

        // Late in the stream, opening new bins is more acceptable since
        // fewer future items remain to fill them; relax the penalty.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 6.0;
    }

    // Mild time-dependent decay of lookahead weight: early stream, keep bins flexible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if next_item_size > 0 && progress < 0.5 {
        // early: prefer bins leaving room for medium items
        if post_residual >= 30 {
            score -= 4.0;
        }
    }

    // Penalize extremely large post_residual waste relative to mean residual
    if post_residual as f64 > mean_residual * 1.5 && bin_residual < bin_capacity {
        score += 4.0;
    }

    score
}

