pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let isz = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with cubic smoothing
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Stream-progress coupling: later in the stream, dead space matters more
    let late = progress * progress;
    score += 30.0 * late * norm_pr;

    // Reward bins whose residual is near a "useful" zone relative to lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score -= 8.0 * (-gap / 40.0) * (1.0 - late);
    } else {
        // last item: strongly prefer tight packing
        score -= 10.0 * (1.0 - norm_pr);
    }

    // Penalize creating residuals that waste capacity vs mean residual
    let mr = mean_residual / cap;
    score += 15.0 * (norm_pr - mr) * (norm_pr - mr);

    // Last-chance bin bonus: avoid opening new bins unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Slight penalty for many open bins (encourage consolidation)
    score += 0.3 * open_bins_count as f64 * norm_pr;

    // Mild reward for large item consumption of the bin
    score -= 0.05 * isz;

    score
}

