            if next_item_size == post_residual {
                score -= 900.0 - 30.0 * progress;
            } else if next_item_size <= post_residual {
                let two_step_waste = (post_residual - next_item_size) as f64;
                if two_step_waste == 0.0 {
                    score -= 700.0;
                } else if two_step_waste >= 10.0 {
                    score -= 300.0 - 2.0 * two_step_waste;
                } else {
                    score -= 80.0 + 1.5 * (10.0 - two_step_waste);
                }
                // cushion: comfortable slack for the next item
                if post_residual >= next_item_size + 3 {
                    let cushion = (post_residual - next_item_size) as f64;
                    score -= (2.0 + 2.0 * progress) * cushion.min(15.0);
                }
                // slack close to half the mean residual: well-shaped future home
                let slack = post_residual as f64 - next_item_size as f64;
                if slack <= mean_residual * 0.5 {
                    score -= 10.0 * (1.0 - slack / (mean_residual.max(1.0) * 0.5));
                }
                // two-item lookahead: leftover after next item stays usable
                let after_next = post_residual - next_item_size;
                if after_next <= 12 && mean_residual >= after_next as f64 {
                    score -= 22.0 - 0.8 * after_next as f64;
                }
                // leftover after next item still fits next_item again (multi-pack)
                if next_item_size > 1 && after_next >= next_item_size {
                    score -= 6.0 + 0.2 * (after_next / next_item_size) as f64;
                }
                // near-exact closure chains — deepen when bins are plentiful
                if next_item_size > 1 && after_next >= next_item_size && after_next % next_item_size == 0 {
                    let chain_bonus = if open_bins_count > 6 { 16.0 } else { 12.0 };
                    score -= chain_bonus;
                }
                // leftover after next item can host next item plus a small tail
                if next_item_size > 1 && after_next > next_item_size {
                    let tail = after_next - next_item_size;
                    if tail <= 4 {
                        score -= 9.0 - 1.5 * tail as f64;
                    }
                }
                // leftover after next item matches mean residual shape: reusable home
                if (after_next as f64 - mean_residual).abs() <= 4.0 {
                    score -= 6.0 * (1.0 - progress);
                }
                // near-seal sliver after next item
                if after_next < next_item_size && after_next <= 3 {
                    score -= 14.0 * (1.0 - progress);
                }
                // leftover just below next item is a near-seal: mild reward late
                if after_next < next_item_size && after_next >= 1 && (next_item_size - after_next) <= 5 {
                    score -= 6.0 * (1.0 - progress);
                }
            } else {
                score += 2.0 * (next_item_size - post_residual) as f64;
                if post_residual < 25 {
                    score += 15.0;
                }
                // near-perfect sealed bins
                if post_residual < 3 {
                    score -= 400.0;
                }
                // strand-space guard just under common small sizes
                if post_residual >= 8 && post_residual <= 16 {
                    score += 10.0 * (1.0 - progress);
                }
                // near-miss whose gap matches mean residual shape — dead space
                let miss = next_item_size - post_residual;
                if miss > 3 && miss as f64 <= mean_residual * 0.5 {
