pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: penalize leftover space (dead space minimization).
    let mut score = post_residual as f64;

    // ---- Harmonic class logic on post_residual (capacity fractions) ----
    // Classify post_residual into capacity-fraction classes.
    // Small leftovers (<= 10% of capacity) are nearly perfect fits -> strong reward.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    if post_residual == 0 {
        score -= 60.0; // perfect fit: bin closed, ideal
    } else if pr <= 0.10 * c {
        score -= 35.0; // near-perfect fit class
    } else if pr <= 0.25 * c {
        score -= 10.0; // decent fit class
    } else if pr <= 0.50 * c {
        score += 5.0; // mediocre class
    } else {
        score += 20.0; // half-empty bin left behind: bad
    }

    // ---- Modulo arithmetic: residue classes of post_residual mod 10 ----
    // Items are integers; leftovers that are tiny "granular" residues (1..=5)
    // are nearly useless dead space -> penalize; residues near class boundaries
    // that align with common item sizes (multiples of 10) are more reusable.
    let gran = post_residual % 10;
    if post_residual > 0 {
        match gran {
            0 => score -= 6.0,        // round residue: likely reusable
            1..=5 => score += 4.0,    // sliver residue: dead space
            6..=9 => score += 1.0,    // mildly awkward
            _ => {}
        }
    }

    // Integer-division threshold: post_residual / 10 gives a coarse "slot count".
    // Fewer usable 10-sized slots left => worse bin.
    let slots = (post_residual / 10) as f64;
    score += (3.0 - slots.min(3.0)) * 4.0;

    // ---- Lookahead coupling: does next_item_size fit in post_residual? ----
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // guaranteed perfect follow-up placement
        } else if next_item_size <= post_residual {
            // Reward more when the follow-up leaves little new dead space.
            let follow_post = post_residual - next_item_size;
            if follow_post <= 10 {
                score -= 20.0;
            } else {
                score -= 8.0;
            }
        } else {
            // Next item won't fit here; if the leftover is a "harmonic class"
            // that many item sizes hit, keep it usable; else penalize.
            if post_residual >= 10 {
                score += 6.0;
            } else {
                score += 14.0;
            }
