    } else {
        // Last item: closing bins cheaply is all that matters.
        score -= 15.0;
    }

    // ---- Last-chance bin logic ----
    // If this is the ONLY bin that fits the item, using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when existing bins fit poorly.
        // Base cost of a fresh bin ~ its full residual; discount slightly so a
