        score += 1.5 * (open_bins_count as f64).sqrt();
    }

    // ---- Mild global pressure: spread load when mean residual is high ----
    if bin_residual != bin_capacity {
        score -= 0.05 * (mean_residual - pr);
    }

    score
}

