        score -= 10.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item can't use the gap -> dead space likely
        score += 12.0;
    }

    // Open-bin pressure: when many bins are open, favor consolidation
    // (penalize new-bin candidate / spreading).
    if bin_residual == bin_capacity {
        score += 5.0 + 2.5 * open_bins_count as f64;
    } else {
        score -= 1.5 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (fill the emptier-feeling bins less, keep large residuals flexible)?
    // Prefer placing into bins with residual close to item (tight packing):
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Early stream: be slightly more willing to open bins for good structure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 6.0 * (1.0 - progress);
    }

    score
}

