        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let pr = post_residual as f64;
    let nx = next_item_size as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        let diff = (pr - nx).abs();
        if diff < 0.5 {
            // Perfect lookahead fit: place next item here with zero waste
            score -= 60.0;
        } else {
            // Penalize mismatch, stronger when post_residual is slightly too small
            // (dead space that the next item cannot use)
            if pr < nx {
                let dead = nx - pr;
                score += dead * 0.8;
                // Extra penalty if dead space is small but unusable (worst case)
                if dead <= 15.0 {
                    score += 25.0;
                }
            } else {
                // post_residual can still fit next item: mild reward scaled by tightness
                score -= (pr - nx).min(30.0) * 0.5;
            }
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are tight;
    // prefer filling tight bins to keep many large-residual bins flexible
    let rel = (pr - mean_residual) / (bin_capacity as f64);
    score += rel * 20.0;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Penalize leaving tiny unusable fragments (<10) unless it's a fresh bin
    if pr > 0.0 && pr < 10.0 && bin_residual < bin_capacity {
        score -= 15.0; // small fragment is near-waste anyway; slight reward to fill tight
    } else if pr == 0.0 {
        score -= 80.0; // perfect fill: always excellent
    }

    // New-bin candidate handling: opening a new bin is only attractive early in
    // the stream or when many bins are open (diversity) — otherwise discourage
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = open_bins_count as f64;
        // discourage new bins mid-stream with few bins; allow more when crowded
        score += 40.0 * progress - openness.min(20.0) * 1.5 + 20.0;
    }

    // Late-stream tightening: waste matters more as stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

