pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone = 12.0; // gaps below this are rarely fillable
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += 60.0 * (dead_zone - post_residual as f64) / dead_zone;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Prefer bins whose residual closely matches item size (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.35 * tightness;

    // Pressure from open bins: with many open bins, avoid wasting capacity;
    // with few open bins, prefer consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.8 * open_bins_count as f64 * (0.3 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post-residual, this is a great placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // New-bin candidate: only attractive when existing residuals are all poor fits.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline penalty; reduced when open bins are fragmented or mean residual is too small.
        let mut nb = 45.0;
        if open_bins_count == 0 {
            nb = -100.0; // must open a bin
        } else {
            if mean_residual < item_size as f64 * 1.2 {
                nb -= 30.0; // existing bins are tight
            }
            if fitting_bins_count == 0 {
                nb -= 50.0;
            }
            // Later in the stream, prefer filling existing bins rather than opening new ones.
            nb += 30.0 * progress;
        }
        score += nb;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    if post_residual == 0 {
        score -= 1000.0 ;
    } else {
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 900.0 - 30.0 * progress ;
            } else if next_item_size <= post_residual {
                let two_step_waste = (post_residual - next_item_size) as f64 ;
                if two_step_waste == 0.0 {
                    score -= 700.0 ;
                } else if two_step_waste >= 10.0 {
                    score -= 300.0 - 2.0 * two_step_waste ;
                } else {
                    score -= 80.0 + 1.5 * (10.0 - two_step_waste) ;
                }
                // cushion: comfortable slack for the next item
                if post_residual >= next_item_size + 3 {
                    let cushion = (post_residual - next_item_size) as f64 ;
                    score -= (2.0 + 2.0 * progress) * cushion . min (15.0) ;
                }
                // two-item lookahead: leftover after next item stays usable
                let after_next = post_residual - next_item_size ;
                if after_next <= 12 && mean_residual >= after_next as f64 {
                    score -= 22.0 - 0.8 * after_next as f64 ;
                }
                // leftover after next item still fits next_item again (multi-pack)
                if next_item_size > 1 && after_next >= next_item_size {
                    score -= 6.0 + 0.2 * (after_next / next_item_size) as f64 ;
                }
                // near-seal sliver after next item
                if after_next < next_item_size && after_next <= 3 {
                    score -= 14.0 * (1.0 - progress) ;
                }
                // leftover matches mean residual shape: reusable home
                if (after_next as f64 - mean_residual) . abs () <= 4.0 {
                    score -= 6.0 * (1.0 - progress) ;
                }
                // leftover can host next item a whole number of times: chain home
                if next_item_size > 1 && after_next >= next_item_size && after_next % next_item_size == 0 {
                    score -= 8.0 * (1.0 - progress) ;
                }
                // leftover just below next item is a near-seal: mild reward late
                if after_next < next_item_size && after_next >= 1 && (next_item_size - after_next) <= 5 {
                    score -= 6.0 * (1.0 - progress) ;
                }
                // NEW: leftover after next item can also host the mean-sized item — triple lookahead
                if after_next > 0 && mean_residual > 1.0 && after_next as f64 >= mean_residual {
                    score -= 5.0 * (1.0 - progress) * (1.0 - (after_next as f64 - mean_residual) / (mean_residual + 1.0)) . max (0.0) ;
                }
            } else {
                score += 2.0 * (next_item_size - post_residual) as f64 ;
                if post_residual < 25 {
                    score += 15.0 ;
                }
                // near-perfect sealed bins
                if post_residual < 3 {
                    score -= 400.0 ;
                }
                // strand-space guard just under common small sizes
                if post_residual >= 8 && post_residual <= 16 {
                    score += 10.0 * (1.0 - progress) ;
                }
                // near-miss whose gap matches mean residual shape — dead space
                let miss = next_item_size - post_residual ;
                if miss > 3 && miss as f64 <= mean_residual * 0.5 {
                    score += 4.0 * (1.0 - progress) ;
                }
                // near-miss with only one other fitting bin: keep it alive anyway
                if miss <= 6 && fitting_bins_count <= 2 {
                    score -= 5.0 ;
                }
                // salvage late in the stream with few alternatives
                if miss <= 10 && fitting_bins_count <= 2 && progress > 0.7 {
                    score -= 10.0 * (1.0 - progress) ;
                }
                // near-miss that seals the bin exactly on a later small item
                if miss <= 2 {
                    score -= 18.0 * (1.0 - progress) ;
                }
                // NEW: near-miss gap that a tiny future item (<= mean/2) could seal
                if miss > 2 && miss <= 6 && mean_residual > 0.0 && (miss as f64) <= mean_residual * 0.45 && open_bins_count > 4 {
                    score -= 7.0 * (1.0 - progress) ;
                }
            }
        }
        if post_residual < 10 {
            score += 45.0 ;
        } else if post_residual < 20 {
            score += 10.0 ;
        }
        score -= (mean_residual - post_residual as f64) * 0.6 ;
        // dead-gap penalty with scarcity scaling
        let gap = (post_residual as f64 - item_size as f64) . max (0.0) ;
        let gap_ratio = gap / (item_size as f64) . max (1.0) ;
        if gap > 0.0 {
            let scarcity = if fitting_bins_count <= 2 { 0.6 } else if fitting_bins_count <= 4 { 0.3 } else { 0.2 } ;
            score += scarcity * gap + 18.0 * gap_ratio . min (2.0) ;
            if gap < mean_residual {
                let fillable = next_item_size > 0 && gap >= next_item_size as f64 ;
                let w = if fillable { 0.2 } else { 0.6 } ;
                score += w * (mean_residual - gap) ;
            }
            if next_item_size > 0 && (gap as u32) == next_item_size {
                score -= 20.0 ;
            }
            // gap exactly two next-items: perfect double closure
            if next_item_size > 1 && (gap as u32) == 2 * next_item_size {
                score -= 12.0 ;
            }
            // NEW: gap divisible by next item — repeated chain closures
            if next_item_size > 1 && (gap as u32) >= 2 * next_item_size && (gap as u32) % next_item_size == 0 {
                score -= 5.0 * (1.0 - progress) ;
            }
        }
        if fitting_bins_count == 1 {
            score -= 12.0 ;
        }
        let fill = item_size as f64 / (bin_residual as f64) . max (1.0) ;
        score -= 20.0 * fill ;
        // dead space: unusable residual relative to next item
        if next_item_size > 0 && post_residual < next_item_size {
            let dead_frac = post_residual as f64 / bin_capacity as f64 ;
            let unusable_ratio = post_residual as f64 / (next_item_size as f64) . max (1.0) ;
            score += 0.4 * post_residual as f64 + 30.0 * dead_frac + 12.0 * (1.0 - unusable_ratio) ;
            if next_item_size - post_residual <= 4 {
                score += 20.0 * (1.0 - progress) ;
            }
        }
        // anti-fragmentation guard
        if fitting_bins_count == 2 && post_residual < bin_capacity / 3 {
            score -= 8.0 ;
        }
        // tiny unusable slivers when bins are plentiful
        if post_residual <= 5 && open_bins_count > 6 {
            score += 25.0 * (1.0 - progress) ;
        }
        // mid-sized future homes
        if post_residual >= bin_capacity / 8 && post_residual <= bin_capacity / 2 {
            score -= 6.0 ;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= bin_capacity / 2 {
            score -= 4.0 * (1.0 - progress) ;
        }
        // reward residuals that can absorb two more average items
        if post_residual as f64 >= 2.0 * mean_residual && post_residual > 20 {
            score -= 5.0 ;
        }
        // compaction sweet spot: headroom matches mean residual
        if next_item_size > 0 && post_residual > next_item_size {
            let headroom = post_residual - next_item_size ;
            if (headroom as f64 - mean_residual) . abs () <= 3.0 {
                score -= 7.0 ;
            }
        }
        // three-way closure: residual hosts next item then seals exactly
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0 ;
        }
        // self-renewing home shape with scarcity
        if next_item_size > 0 && post_residual > next_item_size {
            let headroom = (post_residual - next_item_size) as f64 ;
            if (headroom - mean_residual) . abs () <= 1.0 && fitting_bins_count <= 3 {
                score -= 5.0 * (1.0 - progress) ;
            }
        }
        // residual that fits next item plus a small item is doubly useful
        if next_item_size > 1 && post_residual > next_item_size + 1 && post_residual <= next_item_size + 10 {
            score -= 4.0 * (1.0 - progress) ;
        }
        // NEW: scarce-fit premium scales with how many bins could take this item
        if fitting_bins_count >= 4 && post_residual > 15 {
            score += 3.0 ;
        }
        // NEW: late-stream compaction — strongly prefer deepest fills near the end
        if progress > 0.75 && post_residual < 8 {
            score -= 15.0 * (progress - 0.75) * 4.0 ;
        }
    }
    // NEW-BIN CANDIDATE
    if bin_residual == bin_capacity {
        let big_next = next_item_size as f64 / bin_capacity as f64 ;
        score += 180.0 - 60.0 * progress + 0.15 * open_bins_count as f64 - 25.0 * big_next . max (0.0) ;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0 ;
        }
        if open_bins_count <= 4 && progress < 0.3 {
            score += 25.0 ;
        }
        if mean_residual < 15.0 && progress > 0.5 {
            score -= 15.0 ;
        }
        let item_frac = item_size as f64 / bin_capacity as f64 ;
        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3 ;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3 ;
        }
        let fresh_left = bin_capacity - item_size ;
        if next_item_size > 0 && fresh_left == next_item_size {
            score -= 30.0 ;
        }
        if open_bins_count > 6 && mean_residual > 0.4 * bin_capacity as f64 {
            score += 20.0 ;
        }
        // fresh-bin leftover sliver is wasteful
        if next_item_size > 0 && fresh_left < next_item_size && fresh_left < 8 {
            score += 35.0 ;
        }
        // prefer fresh bin when all existing residuals are too small for next item
        if next_item_size > 0 && fitting_bins_count <= 2 && mean_residual < next_item_size as f64 {
            score -= 18.0 * (1.0 - progress) ;
        }
        // discourage opening fresh bins late when many half-empty bins exist
        if open_bins_count > 8 && mean_residual > next_item_size as f64 + 10.0 {
            score += 12.0 ;
        }
        // large items into fresh bins leave big usable leftovers: mild reward
        if item_frac > 0.6 && next_item_size > 0 && fresh_left >= next_item_size {
            score -= 8.0 * (1.0 - progress) ;
        }
        // fresh bin justified when leftover can host next item plus mean slack
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress) ;
        }
        // near-zero tail after next item (perfect closure)
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size ;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress) ;
            }
        }
        // fresh bin leftover below mean residual is likely dead space
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        // chain home: leftover hosts next item twice exactly
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        // near-exact fill wastes nothing and preserves all open residuals
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        // fresh bin leftover matching mean residual — reusable home shape
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        // fresh bin leftover can host next item multiple times: strong chain home
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        // fresh bin leftover that hosts next item plus mean-shaped slack
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        // avoid opening fresh bins when a fitting open bin nearly seals with this item
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        // NEW: never open a fresh bin for a tiny item when open bins are abundant and roomy
        if item_frac < 0.2 && open_bins_count > 5 && mean_residual > 30.0 {
            score += 18.0 ;
        }
        // NEW: late-stream fresh bins are almost always wasteful if any bin fits
        if progress > 0.85 && fitting_bins_count >= 1 {
            score += 20.0 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a mild non-linear penalty
    // for mid-range waste that is too small to host typical future items.
    if post_residual > 0 {
        score += 0.35 * ((post_residual as f64).powf(1.25) / bin_capacity as f64) * 10.0;
    }

    // Aggressive 2-step lookahead: reward exact/near-exact match of next item
    // into the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if nxt <= post {
            let gap = post - nxt;
            // Perfect chain (post_residual == next_item_size) is gold.
            if gap == 0.0 {
                score -= 60.0;
            } else {
                // Reward closeness of the follow-up fit.
                let fit_quality = 1.0 - (gap / post).sqrt();
                score -= 40.0 * fit_quality;
            }
        } else {
            // Next item cannot follow in this bin: penalize proportionally to overflow.
            let overflow = (nxt - post) / bin_capacity as f64;
            score += 15.0 * overflow.min(1.0);
        }

        // Two-step chaining: can next item's residue host nothing useful?
        // If post_residual is a dead zone (small, unfillable), penalize.
        if post > 0 && post < 10 {
            score += 25.0;
        }
    }

    // Relative to mean residual: bins with residual far below mean are "tighter"
    // and should be preferred for filling (keeps many medium-residual bins alive).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin gets a neutral-ish base but should
    // only win when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Early in the stream, opening bins is cheap; later, discourage it.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * progress;
        // If many bins are already open, avoid adding more unless necessary.
        score += 2.0 * open_bins_count as f64;
    }

    // Slight preference to keep bin count manageable: spreading items thin is bad.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    if post_residual > 0 {
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 900.0 - 30.0 * progress;
            } else if post_residual >= next_item_size {
                let two_step_waste = (post_residual - next_item_size) as f64;
                if two_step_waste >= 10.0 {
                    score -= 300.0 - 2.0 * two_step_waste;
                } else {
                    score -= 80.0 + 1.5 * (10.0 - two_step_waste);
                }
                let cushion = (post_residual - next_item_size) as f64;
                if post_residual >= next_item_size + 3 {
                    score -= (2.0 + 2.0 * progress) * cushion.min(15.0);
