        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0;
        }
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0;
        }
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress);
        }
        if next_item_size > 0 && (fresh_left as f64 - mean_residual).abs() <= 2.0 {
            score -= 8.0;
        }
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual).abs() <= 3.0 {
            score -= 9.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0;
        }
        // COMBINED FEATURE: two-step lookahead on fresh bin — fresh leftover must
        // host next item AND leave mean-shaped slack; otherwise penalize more when
        // open bins are plentiful, since fragmenting a fresh bin is costly.
        if next_item_size > 0 && fresh_left >= next_item_size {
            let tail2 = fresh_left - next_item_size;
            if (tail2 as f64) >= 2.0 * mean_residual {
                score -= 7.0 * (1.0 - progress);
            } else if (tail2 as f64) < mean_residual * 0.5 && open_bins_count > 5 {
                score += 9.0 * (1.0 - progress);
            }
        }
        // COMBINED FEATURE: strong compaction bias — when an open bin's post-fit
        // residual matches the next item exactly, make new bins far less attractive.
        if next_item_size > 0 && post_residual == next_item_size {
            score += 120.0;
        }
        // COMBINED FEATURE: fine-grained residual fitting — prefer open bins whose
        // post residual stays a small multiple of mean residual (reusable home),
        // scaled by scarcity of fitting bins.
        if post_residual > 0 && mean_residual > 1.0 {
            let ratio = post_residual as f64 / mean_residual;
            if ratio >= 0.9 && ratio <= 1.4 {
                score -= 10.0 * (1.0 - progress).min(0.6);
            } else if ratio > 3.0 {
                score += 6.0 * (ratio - 3.0).min(3.0);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * tightness * tightness;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 250.0;
        } else if next_item_size <= post_residual {
            // mild reward if next item still fits after this placement
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // penalize creating dead space that next item cannot use
            let waste = (next_item_size - post_residual).min(item_size) as f64;
            score += 0.35 * waste;
        }
    }

    // Last-chance bin: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: prefer it only when all open bins would leave bad residue,
    // or when open bins are mostly full (mean residual low).
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        score += 90.0;
        // cheaper to open a new bin late in the stream? no — cost amortizes over remaining items
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
        // if mean residual across open bins is small, opening a new bin is reasonable
        score -= 0.5 * mean_residual;
        // avoid opening many bins when a single fitting bin exists
        if fitting_bins_count == 1 {
            score += 200.0;
        }
    }

    // Penalize very small unusable residues (dead space) non-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }

    // Slight preference for fuller bins as stream progresses (compaction pressure).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Mild load balancing: avoid dumping into the fullest bin when many bins are open.
    if open_bins_count > 4 && bin_residual != bin_capacity {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev.abs();
    }

    score
}

