        if next_item_size > 0 && fitting_bins_count >= 3 && mean_residual >= next_item_size as f64 + 5.0 {
            score += 10.0 * (1.0 - progress) ;
        }
        // NEW: fresh bin with triple chain leftover is a strong home
        if next_item_size > 1 && fresh_left >= 3 * next_item_size {
            score -= 5.0 * (1.0 - progress) ;
        }
    }
    score
}

