pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" the leftover space is.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class A: post_residual divisible by common small sizes -> highly reusable.
    if post_residual > 0 {
        let mut bonus = 0.0;
        for d in [10u32, 20, 25, 50] {
            if post_residual % d == 0 {
                bonus += 6.0;
            }
        }
        score -= bonus;
        // Exact-fill class is best.
        if post_residual == 0 {
            score -= 40.0;
        }
    } else {
        score -= 60.0; // perfect fit: strongest reward
    }

    // Dead-space penalty: residuals that cannot hold the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match via integer division threshold
            let k = post_residual / next_item_size;
            score -= 12.0 * k as f64;
        } else {
            // next item won't fit here; penalize wasting capacity
            score += 8.0 * (next_item_size - post_residual) as f64 / cap;
        }
    } else {
        // Last item: prefer tightest packing, ignore future concerns
        score -= 20.0;
    }

    // Capacity-fraction classes: reward bins whose residual lands on clean fractions.
    let frac = post / cap;
    if (frac * 4.0).round() / 4.0 == frac && post > 0.0 {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish baseline, penalized when many bins already fit.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * fitting_bins_count as f64;
        // Opening fresh is attractive late in stream with fragmented bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        if fitting_bins_count > 0 && mean_residual < 0.35 * cap {
            score -= 10.0 * progress;
        }
    }

    // Tie-break: prefer bins with residual far from mean (keep uniform bins clean)
    score += 0.1 * (post - mean_residual).abs();

    score
}

