        let big_next = next_item_size as f64 / bin_capacity as f64 ;
        score += 180.0 - 60.0 * progress + 0.15 * open_bins_count as f64 - 25.0 * big_next . max (0.0) ;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0 ;
        }
        if open_bins_count <= 4 && progress < 0.3 {
            score += 25.0 ;
        }
        if mean_residual < 15.0 && progress > 0.5 {
            score -= 15.0 ;
        }
        let item_frac = item_size as f64 / bin_capacity as f64 ;
        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3 ;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3 ;
        }
        let fresh_left = bin_capacity - item_size ;
        if next_item_size > 0 && fresh_left == next_item_size {
            score -= 30.0 ;
        }
        if open_bins_count > 6 && mean_residual > 0.4 * bin_capacity as f64 {
            score += 20.0 ;
        }
        // fresh-bin leftover sliver is wasteful
        if next_item_size > 0 && fresh_left < next_item_size && fresh_left < 8 {
            score += 35.0 ;
        }
        // prefer fresh bin when all existing residuals are too small for next item
        if next_item_size > 0 && fitting_bins_count <= 2 && mean_residual < next_item_size as f64 {
            score -= 18.0 * (1.0 - progress) ;
        }
        // discourage opening fresh bins late when many half-empty bins exist
        if open_bins_count > 8 && mean_residual > next_item_size as f64 + 10.0 {
            score += 12.0 ;
        }
        // large items into fresh bins leave big usable leftovers: mild reward
        if item_frac > 0.6 && next_item_size > 0 && fresh_left >= next_item_size {
            score -= 8.0 * (1.0 - progress) ;
        }
        // fresh bin justified when leftover can host next item plus mean slack
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress) ;
        }
        // near-zero tail after next item (perfect closure)
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size ;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress) ;
            }
        }
        // fresh bin leftover below mean residual is likely dead space
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        // chain home: leftover hosts next item twice exactly
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        // near-exact fill wastes nothing and preserves all open residuals
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        // fresh bin leftover matching mean residual — reusable home shape
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        // fresh bin leftover can host next item multiple times: strong chain home
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        // fresh bin leftover that hosts next item plus mean-shaped slack
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        // avoid opening fresh bins when a fitting open bin nearly seals with this item
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        // fresh bin justified only if its leftover is at least as usable as the
        // mean open residual; otherwise opening wastes the existing slack pool
        if next_item_size > 0 && fresh_left < next_item_size {
            score += 18.0 * (1.0 - progress) ;
        }
        // late-stream fresh bins are costly unless this item nearly seals them
        if progress > 0.8 && fresh_left > bin_capacity / 4 {
            score += 10.0 * (progress - 0.8) * 100.0 ;
        }
        // NEW: fresh bin is strongly preferred when no open bin fits the next item
        // at all and the fresh leftover can host it
        if next_item_size > 0 && fitting_bins_count == 0 && fresh_left >= next_item_size {
            score -= 22.0 * (1.0 - progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for typical future items
    // are wasted space. Penalize gaps in (0, 10] heavily, and gaps below 20
    // moderately (item sizes 1..100 unknown, so small gaps are risky).
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 15.0;
    }

    // Reward very tight fits (best-fit core signal).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Open-bin pressure: with many bins open, prefer reusing existing bins
    // rather than spreading items; add a mild penalty scaled by bin count.
    score += (open_bins_count as f64).sqrt() * 2.0;

    // Lookahead: if the next item fits exactly into the post_residual,
    // strongly favor this placement (perfect chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 45.0;
        } else {
            score -= 10.0;
        }
    }
    // If next item cannot fit in the leftover gap and the gap is small,
    // the gap is dead space for the near future.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: an empty bin has full residual. Make it
    // attractive only when no open bin offers a decent fit; otherwise keep
    // it slightly worse than a good existing fit.
    if bin_residual == bin_capacity {
        // Baseline: new bin is like a fresh residual of capacity.
        score = bin_capacity as f64 * 0.9 - (open_bins_count as f64).sqrt() * 3.0;
        // If many bins fit the item, discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 20.0 + 5.0 * fitting_bins_count as f64;
        }
        // If this is the last chance (only one fitting bin), opening a new
        // bin is less harmful, but still prefer reuse.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
        // Late in the stream, slightly discourage accumulating open bins.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 10.0;
        }
    }

    score
}

