                // near-seal sliver after next item
                if after_next < next_item_size && after_next <= 3 {
                    score -= 14.0 * (1.0 - progress) ;
                }
                // leftover matches mean residual shape: reusable home
                if (after_next as f64 - mean_residual) . abs () <= 4.0 {
                    score -= 6.0 * (1.0 - progress) ;
                }
                // leftover can host next item a whole number of times: chain home
                if next_item_size > 1 && after_next >= next_item_size && after_next % next_item_size == 0 {
                    score -= 8.0 * (1.0 - progress) ;
                }
                // leftover just below next item is a near-seal: mild reward late
                if after_next < next_item_size && after_next >= 1 && (next_item_size - after_next) <= 5 {
                    score -= 6.0 * (1.0 - progress) ;
                }
                // NEW: leftover after next item that still exceeds mean residual —
                // a long-lived home, worth more when bins are scarce
                if after_next as f64 > mean_residual + 2.0 && fitting_bins_count <= 3 {
                    score -= 4.0 * (1.0 - progress) ;
                }
            } else {
                score += 2.0 * (next_item_size - post_residual) as f64 ;
                if post_residual < 25 {
                    score += 15.0 ;
                }
                // near-perfect sealed bins
                if post_residual < 3 {
                    score -= 400.0 ;
                }
                // strand-space guard just under common small sizes
                if post_residual >= 8 && post_residual <= 16 {
                    score += 10.0 * (1.0 - progress) ;
                }
                // near-miss whose gap matches mean residual shape — dead space
                let miss = next_item_size - post_residual ;
                if miss > 3 && miss as f64 <= mean_residual * 0.5 {
                    score += 4.0 * (1.0 - progress) ;
                }
                // near-miss with only one other fitting bin: keep it alive anyway
                if miss <= 6 && fitting_bins_count <= 2 {
                    score -= 5.0 ;
                }
                // salvage late in the stream with few alternatives
                if miss <= 10 && fitting_bins_count <= 2 && progress > 0.7 {
                    score -= 10.0 * (1.0 - progress) ;
                }
                // near-miss that seals the bin exactly on a later small item
                if miss <= 2 {
                    score -= 18.0 * (1.0 - progress) ;
                }
                // NEW: near-miss gap scales with how close the gap is to mean
                // residual — gaps near mean are more likely filled later
                if miss > 2 {
                    let gap_to_mean = (miss as f64 - mean_residual) . abs () ;
                    if gap_to_mean <= 5.0 {
                        score -= 3.0 * (1.0 - gap_to_mean / 5.0) * (1.0 - progress) ;
                    }
                }
            }
        }
        if post_residual < 10 {
            score += 45.0 ;
        } else if post_residual < 20 {
            score += 10.0 ;
        }
        score -= (mean_residual - post_residual as f64) * 0.6 ;
        // dead-gap penalty with scarcity scaling
        let gap = (post_residual as f64 - item_size as f64) . max (0.0) ;
        let gap_ratio = gap / (item_size as f64) . max (1.0) ;
        if gap > 0.0 {
            let scarcity = if fitting_bins_count <= 2 { 0.6 } else if fitting_bins_count <= 4 { 0.3 } else { 0.2 } ;
            score += scarcity * gap + 18.0 * gap_ratio . min (2.0) ;
            if gap < mean_residual {
                let fillable = next_item_size > 0 && gap >= next_item_size as f64 ;
                let w = if fillable { 0.2 } else { 0.6 } ;
                score += w * (mean_residual - gap) ;
            }
            if next_item_size > 0 && (gap as u32) == next_item_size {
                score -= 20.0 ;
            }
            // gap exactly two next-items: perfect double closure
            if next_item_size > 1 && (gap as u32) == 2 * next_item_size {
                score -= 12.0 ;
            }
            // NEW: gap that hosts next item plus one more mean-sized item is a
            // strong two-step home; tighten the coupling with open bin count
            if next_item_size > 1 && gap >= (next_item_size as f64) + mean_residual
                && open_bins_count > 5 {
                score -= 3.0 * (1.0 - progress) ;
            }
        }
        if fitting_bins_count == 1 {
            score -= 12.0 ;
        }
        let fill = item_size as f64 / (bin_residual as f64) . max (1.0) ;
        score -= 20.0 * fill ;
        // dead space: unusable residual relative to next item
        if next_item_size > 0 && post_residual < next_item_size {
            let dead_frac = post_residual as f64 / bin_capacity as f64 ;
            let unusable_ratio = post_residual as f64 / (next_item_size as f64) . max (1.0) ;
            score += 0.4 * post_residual as f64 + 30.0 * dead_frac + 12.0 * (1.0 - unusable_ratio) ;
            if next_item_size - post_residual <= 4 {
                score += 20.0 * (1.0 - progress) ;
            }
        }
        // anti-fragmentation guard
        if fitting_bins_count == 2 && post_residual < bin_capacity / 3 {
            score -= 8.0 ;
        }
        // tiny unusable slivers when bins are plentiful
        if post_residual <= 5 && open_bins_count > 6 {
            score += 25.0 * (1.0 - progress) ;
        }
        // mid-sized future homes
        if post_residual >= bin_capacity / 8 && post_residual <= bin_capacity / 2 {
            score -= 6.0 ;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= bin_capacity / 2 {
            score -= 4.0 * (1.0 - progress) ;
        }
        // reward residuals that can absorb two more average items
        if post_residual as f64 >= 2.0 * mean_residual && post_residual > 20 {
            score -= 5.0 ;
        }
        // compaction sweet spot: headroom matches mean residual
        if next_item_size > 0 && post_residual > next_item_size {
            let headroom = post_residual - next_item_size ;
            if (headroom as f64 - mean_residual) . abs () <= 3.0 {
                score -= 7.0 ;
            }
        }
        // three-way closure: residual hosts next item then seals exactly
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0 ;
        }
        // self-renewing home shape with scarcity
        if next_item_size > 0 && post_residual > next_item_size {
            let headroom = (post_residual - next_item_size) as f64 ;
            if (headroom - mean_residual) . abs () <= 1.0 && fitting_bins_count <= 3 {
                score -= 5.0 * (1.0 - progress) ;
            }
        }
        // residual that fits next item plus a small item is doubly useful
        if next_item_size > 1 && post_residual > next_item_size + 1 && post_residual <= next_item_size + 10 {
            score -= 4.0 * (1.0 - progress) ;
        }
        // NEW: residual utilization ratio — bins whose remaining fraction is
        // large relative to capacity are better long-term homes late in stream
        let res_frac = post_residual as f64 / bin_capacity as f64 ;
        if res_frac > 0.4 && progress > 0.5 {
            score -= 6.0 * (res_frac - 0.4) ;
        }
    }
    // NEW-BIN CANDIDATE
    if bin_residual == bin_capacity {
        let big_next = next_item_size as f64 / bin_capacity as f64 ;
        score += 180.0 - 60.0 * progress + 0.15 * open_bins_count as f64 - 25.0 * big_next . max (0.0) ;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0 ;
        }
        if open_bins_count <= 4 && progress < 0.3 {
            score += 25.0 ;
        }
        if mean_residual < 15.0 && progress > 0.5 {
            score -= 15.0 ;
        }
        let item_frac = item_size as f64 / bin_capacity as f64 ;
        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3 ;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3 ;
        }
        let fresh_left = bin_capacity - item_size ;
        if next_item_size > 0 && fresh_left == next_item_size {
            score -= 30.0 ;
        }
        if open_bins_count > 6 && mean_residual > 0.4 * bin_capacity as f64 {
            score += 20.0 ;
        }
        // fresh-bin leftover sliver is wasteful
        if next_item_size > 0 && fresh_left < next_item_size && fresh_left < 8 {
            score += 35.0 ;
        }
        // prefer fresh bin when all existing residuals are too small for next item
        if next_item_size > 0 && fitting_bins_count <= 2 && mean_residual < next_item_size as f64 {
            score -= 18.0 * (1.0 - progress) ;
        }
        // discourage opening fresh bins late when many half-empty bins exist
        if open_bins_count > 8 && mean_residual > next_item_size as f64 + 10.0 {
            score += 12.0 ;
        }
        // large items into fresh bins leave big usable leftovers: mild reward
        if item_frac > 0.6 && next_item_size > 0 && fresh_left >= next_item_size {
            score -= 8.0 * (1.0 - progress) ;
        }
        // fresh bin justified when leftover can host next item plus mean slack
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress) ;
        }
        // near-zero tail after next item (perfect closure)
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size ;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress) ;
            }
        }
        // fresh bin leftover below mean residual is likely dead space
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        // chain home: leftover hosts next item twice exactly
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        // near-exact fill wastes nothing and preserves all open residuals
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        // fresh bin leftover matching mean residual — reusable home shape
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        // fresh bin leftover can host next item multiple times: strong chain home
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        // fresh bin leftover that hosts next item plus mean-shaped slack
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        // avoid opening fresh bins when a fitting open bin nearly seals with this item
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        // NEW: fresh bin penalty scales with total residual spread across open
        // bins — if open bins hold plenty of slack, opening fresh is costlier
        let spread = mean_residual * open_bins_count as f64 ;
        if spread > 1.5 * item_size as f64 && progress > 0.4 {
            score += 10.0 * (1.0 - progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is always ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            score -= 150.0 - 0.5 * ((post_residual - next_item_size as u32) as f64);
        }
        // Penalize post_residual just below next item (dead space for lookahead)
        if post_residual > 0 && post_residual < next_item_size {
            score += 60.0;
        }
    }

    // Compare post_residual against mean residual across open bins:
    // prefer bins whose leftover stays close to (but below) the mean
    let pr = post_residual as f64;
    let dev = pr - mean_residual;
    score += 0.3 * dev.abs();
    if pr > mean_residual {
        score += 0.4 * dev;
    }

    // Tight fit reward: small post_residual relative to capacity
    score += 0.5 * (pr / bin_capacity as f64) * (pr / bin_capacity as f64) * 100.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Penalize opening a brand-new bin when open bins fit decently
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // new bin attractive only if no open bin gives a tight fit
        if post_residual >= 0 {
            score += 30.0 + mean_residual * 0.5;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 120.0; // an open bin likely serves the next item too
            }
        }
    }

    // Slight preference to spread load early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize large dead space quadratically: residuals that can't fit typical
    // future items (10..80 range) are wasted.
    if post_residual < 10 {
        score -= 15.0; // near-perfect fit bonus
    } else if post_residual < 40 {
        score -= 5.0;
    } else {
        score += 0.15 * (post_residual as f64 - 40.0);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if this placement leaves a residual the next item wastes, penalize.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            score -= 4.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 0.1 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Global state coupling: when many bins are open with high mean residual,
    // encourage consolidating into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation_pressure = mean_residual / bin_capacity as f64;
    score -= 8.0 * consolidation_pressure * (1.0 + 0.5 * progress);

    // Penalize opening a new bin (empty candidate) more when many bins already
    // exist, unless the fit into existing bins is truly bad.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * open_bins_count as f64;
        // But allow new bin early in the stream when structure is unclear.
        if progress < 0.1 {
            score -= 6.0;
        }
    }

    // Mild time-horizon adaptation: late in the stream, squeeze harder.
    score -= 5.0 * progress * tightness;

    // Small tie-breaker against fragmented bins: prefer bins with more residual
    // used so far (i.e., smaller bin_residual) among equally tight fits.
    score += 0.02 * bin_residual as f64;

    score
}

