pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear reward for tight fits: quadratic suppression of post_residual
    let tightness = 1.0 - post / cap;
    score -= 8.0 * tightness * tightness * (1.0 + progress);

    // Penalize dead space that is too small for typical future items
    let dead = post / cap;
    if post > 0.0 {
        score += 6.0 * dead * (1.0 - dead) * (1.0 - progress);
    }

    // Discourage opening a new bin when a fitting bin exists
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 12.0 + 10.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Coupling with mean residual: prefer bins below mean residual (denser bins)
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    // Lookahead: reward leaving space compatible with next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx {
