        let item_frac = item_size as f64 / bin_capacity as f64 ;
        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3 ;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3 ;
        }
        let fresh_left = bin_capacity - item_size ;
        if next_item_size > 0 && fresh_left == next_item_size {
            score -= 30.0 ;
        }
        if open_bins_count > 6 && mean_residual > 0.4 * bin_capacity as f64 {
            score += 20.0 ;
        }
        // fresh-bin leftover sliver is wasteful
        if next_item_size > 0 && fresh_left < next_item_size && fresh_left < 8 {
            score += 35.0 ;
        }
        // prefer fresh bin when all existing residuals are too small for next item
        if next_item_size > 0 && fitting_bins_count <= 2 && mean_residual < next_item_size as f64 {
            score -= 18.0 * (1.0 - progress) ;
        }
        // large items into fresh bins leave big usable leftovers: mild reward
        if item_frac > 0.6 && next_item_size > 0 && fresh_left >= next_item_size {
            score -= 8.0 * (1.0 - progress) ;
        }
        // fresh bin justified when leftover can host next item plus mean slack
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress) ;
        }
        // near-zero tail after next item (perfect closure)
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size ;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress) ;
            }
        }
        // fresh bin leftover below mean residual is likely dead space
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        // chain home: leftover hosts next item twice exactly
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        // near-exact fill wastes nothing and preserves all open residuals
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        // fresh bin leftover matching mean residual — reusable home shape
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        // fresh bin leftover can host next item multiple times: strong chain home
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        // fresh bin leftover that hosts next item plus mean-shaped slack
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        // avoid opening fresh bins when a fitting open bin nearly seals with this item
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        // discourage fresh bins late when many half-empty bins exist
        if open_bins_count > 8 && next_item_size > 0 && mean_residual > next_item_size as f64 + 10.0 {
            score += 12.0 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus as post_residual approaches zero.
    let tight = 1.0 - (post_residual as f64 / cap);
    score -= 60.0 * tight * tight;

    // Harmonic class of post_residual: residuals that can still host
    // "round" future items (multiples of 10 / half-capacity chunks) are valuable.
    let pr = post_residual;
    if pr == 0 {
        score -= 200.0; // perfect fill
    } else {
        // Penalize awkward residuals: small but nonzero (dead space).
        if pr < 10 {
            score += 45.0; // dead space under minimum item size
        }
        // Reward residuals that are exact multiples of 10 (harmonic class mod 10 == 0)
        if pr % 10 == 0 {
            score -= 12.0;
        } else if pr % 5 == 0 {
            score -= 4.0;
        } else {
            score += 8.0; // non-harmonic leftover
        }
        // Residuals able to host the lookahead item get a strong reward.
        if next_item_size > 0 && pr >= next_item_size {
            score -= 25.0;
            // Extra reward if the lookahead would then fit in a harmonic class.
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 {
                score -= 10.0;
            }
        } else if next_item_size > 0 {
            // Post-residual cannot host the next item: mild penalty,
            // but small residuals are cheap to waste.
            score += (next_item_size as f64 - pr as f64) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate logic: only attractive when no open bin fits well
    // or the stream is early and spreading load is useful.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening a bin costs; penalize unless many bins already open
        // (parallel packing) or current fit would be bad.
        let poor_fit = (bin_residual - item_size) as f64 > 0.7 * cap;
        score += 40.0; // base cost of a fresh bin
        if open_bins_count == 0 {
            score -= 200.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if poor_fit && fitting_bins_count > 0 {
            // Opening a new bin is better than dumping into a mostly-full bin
            // only if that bin is the last fitting one.
            if fitting_bins_count == 1 {
                score -= 60.0;
            }
        }
        // Late in the stream, prefer closing out existing bins.
        score += 30.0 * progress;
        // Mean residual high => open bins have room, discourage new bins.
        score += 0.4 * (mean_residual - 30.0).max(0.0);
    }

    // Mild penalty for using very empty bins when many bins are open,
    // to consolidate load into partially filled bins.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 10.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
