            score -= 9.0 * (1.0 - progress) ;
        }
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        // new: discourage fresh bins when an open bin would be sealed exactly by this item
        if post_residual == 0 {
            score += 60.0 ;
        }
        // new: fresh-bin leftover that is a strand just below next item — dead space risk
        if next_item_size > 0 && fresh_left < next_item_size && (next_item_size - fresh_left) <= 6 {
            score += 8.0 * (1.0 - progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never host the smallest
    // plausible item (1..=10) are pure waste; punish them super-linearly.
    if post_residual <= 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    } else if post_residual <= 25 {
        // Small-ish gaps are risky too (most items are >= 10, so gaps < 20
        // only fit a narrow slice of the distribution).
        score += 8.0 + (25 - post_residual) as f64 * 0.8;
    }

    // Reward tight fits: fraction of the bin consumed by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 30.0;

    // Perfect fit is the ideal outcome.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer
    // filling existing bins; few open bins -> opening new bins is cheap.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 4.0;
    score += pressure * (1.0 - fill);

    // Lookahead: if the next item fits the post-residual, this placement
    // sets up a chain; reward it. If it nearly fits but not quite, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual + 10 {
            score += 6.0;
        }
    }

    // New-bin candidate: an empty bin should only win when no open bin
    // offers a decent fit. Make it moderately attractive by default
    // (fresh residual = 100) but let tight fits / last-chance bonuses
    // of open bins beat it.
    if bin_residual == bin_capacity {
        score += 15.0 + pressure;
    }

    // Mean-residual coupling: if open bins are on average quite full,
    // conserving their residual matters more; penalize wasting it here.
    let mean_frac = mean_residual / bin_capacity as f64;
    score += mean_frac * (post_residual as f64) * 0.3;

    // Mild stream-progression term: late in the stream, prefer consolidating
    // into existing bins to avoid trailing half-empty bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 5.0 * (1.0 - fill);

    score
}

