        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        // NEW: fresh bin unattractive when many open bins already have large residuals
        if open_bins_count > 5 {
            let big_open = (mean_residual / bin_capacity as f64) . min (1.0) ;
            score += 30.0 * big_open * (1.0 - progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual)
    score -= (bin_capacity as f64 / (post_residual as f64 + 1.0)) * 0.5;

    // 2-step lookahead: reward if next item fits the post residual exactly-ish
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item cannot fit here; penalize proportionally to wasted lookahead potential
        score += 5.0 + (next_item_size as f64 - post_residual as f64) * 0.1;
    }

    // Relative to mean residual: prefer bins with residual below mean (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strong reward to use it, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when decent fits exist, unless lookahead wants it
    if bin_residual == bin_capacity {
        let base = 25.0;
        let relief = if next_item_size > 0 && post_residual >= next_item_size { 10.0 } else { 0.0 };
        score += base - relief;
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * (bin_residual as f64 / bin_capacity as f64);

    score
}

