pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic penalty on leftover space.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Many fitting bins: mild penalty to encourage spreading choices carefully.
    if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0);
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward if next item fills residual exactly or near-exactly.
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 8.0;
            }
        } else {
            // Post-residual too small for next item: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Global state: many open bins with large mean residual -> prefer filling existing bins.
    if open_bins_count > 4 && mean_residual > item_size as f64 * 1.5 {
        score -= 10.0;
    }

    // Time horizon: early in stream, opening new bins is cheaper; late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early, penalized later.
        score += progress * 20.0;
        // But if no open bin fits well, new bin is fine.
        if post_residual > 40 {
            score -= 5.0;
        }
    } else {
        // Existing bin: slight late-stream bonus for consolidation.
        score -= progress * 5.0;
    }

    // Penalize creating residuals that are awkward (just above common item sizes).
    for awkward in [11u32, 21, 31, 41, 51, 61, 71] {
        if post_residual >= awkward && post_residual <= awkward + 3 {
            score += 6.0;
        }
    }

    score
}

