}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let prog = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = it / c;
    let pr_norm = pr / c;

    let mut score = pr;

    // non-linear waste penalty: quadratic in normalized post-residual
    score += 40.0 * pr_norm * pr_norm * c;

    // fill reward: cubic in fit ratio
    score -= 30.0 * fit_ratio * fit_ratio * fit_ratio * c;

    // smooth stream-progress coupling: as stream progresses, prefer tighter fits
    let coupling = prog * prog * (1.0 - prog);
    score -= 25.0 * coupling * it;
    score += 20.0 * prog * pr_norm * c;

    // dead-space avoidance relative to mean residual
    let dev = (pr - mean_residual) / c;
    score += 15.0 * dev * dev * c;

    // lookahead: reward residual that can still host next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / c;
            score -= 18.0 * (1.0 - slack * slack);
        } else {
            let miss = (nx - pr) / c;
            score += 12.0 * miss * miss * c;
        }
    }

    // last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // new-bin candidate: penalize mildly so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 10.0 + 25.0 * fit_ratio;
    }

    // mild open-bin pressure to consolidate
    score += (open_bins_count as f64).ln() * (1.0 + fit_ratio);

    score
}

