        if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
            score += 14.0 * (1.0 - progress) ;
        }
        // NEW: late-stream fresh bins should be strongly justified by item size
        if progress > 0.75 && item_frac < 0.25 {
            score += 10.0 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well the leftover aligns with common item sizes.
    // Residuals that are multiples of small "harmonic" denominators are more reusable.
    let pr = post_residual;
    if pr > 0 {
        let mut bonus = 0.0;
        if pr % 10 == 0 { bonus += 8.0; }
        if pr % 20 == 0 { bonus += 6.0; }
        if pr % 25 == 0 { bonus += 5.0; }
        if pr % 50 == 0 { bonus += 4.0; }
        if pr % 5 == 0 { bonus += 2.0; }
        // Small residuals are near-dead space: penalize sharply via integer division thresholds.
        if pr < 10 { score += 30.0; }
        else if pr < 20 { score += 10.0; }
        // Perfect fit is ideal.
        if pr == 0 { bonus += 40.0; }
        score -= bonus;
    } else {
        score -= 60.0; // exact fill, best outcome
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0;
        } else if next_item_size < pr {
            // Harmonic compatibility: next item leaves a "nice" residual too.
            let next_post = pr - next_item_size;
            if next_post % 10 == 0 { score -= 8.0; }
            if next_post < 10 { score += 6.0; }
        } else {
            // Next item cannot use this bin's leftover; slight penalty for tight fits that strand us.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer reusing an open bin unless the new bin
    // offers clearly better long-term flexibility.
    if bin_residual == bin_capacity {
        // A fresh bin has full residual: make it competitive but not dominant.
        score -= 15.0;
        // Late in the stream, opening fresh bins is cheaper (fewer future items to place).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
        // Many open bins with high mean residual: reuse instead of opening.
        if mean_residual > 40.0 && open_bins_count > 2 {
            score += 20.0;
        }
    } else {
        // Slight preference for bins with residual close to item usage (tight packing).
        let tight = (bin_residual as f64 - item_size as f64).abs();
        score += tight * 0.05;
    }

    // Mean-residual harmonic alignment: bins whose residual matches the fleet mean
    // keep balance; outliers are slightly discouraged.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.02;

    // Modulo threshold on item_size: large items (>= half capacity) should go in
    // bins that will be nearly emptied.
    if item_size >= bin_capacity / 2 && post_residual <= 20 {
        score -= 12.0;
    }

    score
}

