        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        // fresh bin leftover matching mean residual — reusable home shape
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        // fresh bin leftover can host next item multiple times: strong chain home
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        // fresh bin leftover that hosts next item plus mean-shaped slack
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        // avoid opening fresh bins when a fitting open bin nearly seals with this item
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        // NEW: fresh-bin leftover that hosts next item twice with tiny tail — triple chain
        if next_item_size > 1 && fresh_left >= 2 * next_item_size + 1 && fresh_left <= 2 * next_item_size + 5 {
            score -= 8.0 * (1.0 - progress) ;
        }
        // NEW: fresh bin dead-space ratio — leftover just below next item wastes proportionally
        if next_item_size > 0 && fresh_left < next_item_size {
            let waste_frac = fresh_left as f64 / (next_item_size as f64).max(1.0) ;
            score += 8.0 * (1.0 - waste_frac) ;
        }
        // NEW: late stream with many open bins — fresh bins fragment; tighten
        if progress > 0.6 && open_bins_count > 5 {
            score += 10.0 * (progress - 0.6) / 0.4 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..)
    // are pure waste; penalize small unusable gaps quadratically.
    if post_residual > 0 && post_residual < item_size {
        score += 40.0 + (post_residual as f64) * 0.5;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits relative to bin residual (small waste fraction).
    if bin_residual > 0 {
        score -= (item_size as f64 / bin_residual as f64) * 25.0;
    }

    // Lookahead: bonus if next item fits the post residual exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + (post_residual as f64 - next_item_size as f64).min(20.0) * 0.3;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few bins, opening a new bin is cheap.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a "ragged" bin; filling it is good.
    score -= (mean_residual - bin_residual as f64).max(0.0) * 0.4;

    // New-bin candidate handling: opening a new bin gets a mild baseline
    // penalty that grows with stream progression (late stream: consolidate).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + progress * 30.0;
    }

    score
}

