        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0 ;
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let headroom = (post_residual - next_item_size) as f64 ;
            if (headroom - mean_residual) . abs () <= 1.0 && fitting_bins_count <= 3 {
                score -= 5.0 * (1.0 - progress) ;
            }
        }
        if next_item_size > 1 && post_residual > next_item_size + 1 && post_residual <= next_item_size + 10 {
            score -= 4.0 * (1.0 - progress) ;
        }
        // new: tiny post-residual slivers late are near-sealed, mild extra reward
        if post_residual <= 4 && progress > 0.6 {
            score -= 8.0 * (1.0 - progress) ;
