        if next_item_size > 0 && fitting_bins_count >= 3 && fresh_left < next_item_size + 8 {
            score += 10.0 * (1.0 - progress) ;
        }
        // new: fresh bin with leftover >= mean residual keeps a reusable home
        if fresh_left as f64 >= mean_residual * 1.5 && next_item_size > 0 && fresh_left >= next_item_size {
            score -= 5.0 * (1.0 - progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling)
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // dead space for the lookahead item
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else {
            // post_residual can host the next item: reward
            score -= 0.3 * next_item_size as f64;
        }
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize leaving residuals that are hard to fill later (small odd gaps)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // When many bins are open, prefer consolidation into fuller bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_pressure = (open_bins_count as f64).ln() + 1.0;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64) * (1.0 + progress);

    // Prefer bins whose residual is close to the mean residual (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 30.0;
        // If the item fits poorly in any existing bin, opening is more attractive
        if fitting_bins_count == 0 || (bin_residual - item_size) < 15 {
            score -= 45.0;
        }
        // Late in the stream, avoid opening unnecessary bins
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
