        if post_residual > 0 && fresh_left > post_residual + 10 && fitting_bins_count <= 3 {
            score -= 9.0 * (1.0 - progress) ;
        } else if post_residual > 0 && fresh_left <= post_residual + 4 && open_bins_count > 5 {
            score += 10.0 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: prefer tight fits (small post_residual), with non-linear squashing
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Smooth stream-progress coupling: later in stream, penalize large residuals more strongly
    score += 6.0 * progress * norm_post * norm_post;

    // If next item fits exactly into the post residual, reward this bin (smooth interaction)
    let next_fits = if next_item_size > 0 { (bin_residual as f64 - post - next_item_size as f64).abs() } else { cap };
    score -= 4.0 * (1.0 - next_fits / cap) * (1.0 - norm_post);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Penalize wasting space when many bins are open and mean residual is low (fragmentation)
    score += 0.5 * (open_bins_count as f64).ln1p() * (norm_post - mean_residual / cap).abs();

    // New-bin candidate: penalize so we only open when all fits are poor
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress;
    }

    score
}

