pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into small
    // "dead classes" are penalized; large residuals are fine (still usable).
    let dead_zone = 1u32..=10;
    if dead_zone.contains(&post_residual) {
        score += 25.0 * (11 - post_residual) as f64; // tiny unusable slivers are worst
    }

    // Modulo-class reward: residual that can host common future item sizes
    // (multiples/divisors of capacity) is more valuable.
    let usable = |r: u32| -> f64 {
        let mut v = 0.0;
        for k in [10u32, 20, 25, 50] {
            if r >= k {
                v += (r / k) as f64 * 2.0;
            }
        }
        v
    };
    score -= usable(post_residual);

    // Integer-division threshold: reward near-perfect packing classes.
    if bin_residual % 25 == 0 && post_residual % 25 == 0 {
        score -= 6.0;
    }
    if post_residual % 10 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let after = post_residual - next_item_size;
            score -= 12.0;
            if dead_zone.contains(&after) {
                score += 15.0; // but don't create a sliver for the next item
            }
        } else {
            score += 4.0; // this bin likely dies after placement
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no good open fit exists.
    if bin_residual == bin_capacity {
        score += 55.0;
        score -= 0.15 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Progress-based tie-break: late in stream, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64);

    score
}

