        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 + 5.0 {
            score += 10.0 * (1.0 - progress) ;
        }
        // NEW: opening fresh bins early for small items fragments the stream
        if item_size <= 20 && open_bins_count >= 3 && progress < 0.5 {
            score += 8.0 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: small gaps that likely cannot host future items
    // (items are 1..=100, but small gaps waste capacity). Penalize gaps
    // below a threshold more aggressively, with a cliff shape.
    let gap = post_residual as f64;
    if gap > 0.0 && gap <= 15.0 {
        // Unusable sliver: heavy penalty proportional to wasted capacity.
        score += 60.0 * (1.0 - gap / 15.0);
    } else if gap <= 25.0 {
        // Moderately risky gap.
        score += 12.0 * (25.0 - gap) / 10.0;
    }

    // If the next item fits exactly in the post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post-residual cannot host the lookahead item: penalize if gap is small.
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    // over opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // for the new-bin candidate (residual == capacity), add pressure.
    if bin_residual == bin_capacity {
        score += 15.0 + 5.0 * open_bins_count as f64;
        // If an existing bin fits well (post_residual small), make new bin worse.
        if post_residual as f64 <= mean_residual {
            score += 20.0;
        }
    } else {
        // Slight preference for bins with below-average residual (tighter bins)
        // to keep wide-open bins available for large items.
        if (bin_residual as f64) > mean_residual {
            score += 5.0;
        } else {
            score -= 3.0;
        }
    }

    // Early in the stream, be a bit more willing to open bins (exploration);
    // late in the stream, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

