pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fits).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - post_residual as f64).abs() < 0.5 {
            // Perfect chaining: next item fills this bin exactly.
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Next item fits here too; reward proportional to how well it chains.
            let chain_waste = (post_residual as f64 - nxt).abs();
            score -= 10.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize dead space that blocks lookahead.
            score += 4.0 * ((post_residual as f64 - nxt) / bin_capacity as f64);
        }
    }

    // Compare post_residual against mean residual: leaving residuals near the mean
    // keeps flexibility; extreme small residuals are dead space.
    let pr = post_residual as f64;
    if pr < mean_residual * 0.5 && pr > 0.0 {
        score += 3.0 * (mean_residual * 0.5 - pr);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score -= 0.5 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless current fits are bad.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if the item is large and would leave a tiny residual elsewhere,
        // a fresh bin may be fine; soften penalty for large items.
        score -= item_size as f64 * 0.05;
    }

    // Mild penalty for very tight fits that strand unusable slivers (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

