        // Next item won't fit here; penalize more if the leftover dead space is awkward.
        score += 8.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
    }

    // Global state: many open bins with high mean residual -> prefer consolidating.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = open_bins_count as f64 / (total_items.max(1) as f64);
    score -= 10.0 * crowding * (mean_residual / bin_capacity as f64);
