pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: exact-fit classes are rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit, ideal
    } else {
        // Class the residual by integer division into harmonic buckets.
        let class = pr / 10; // 0..=10
        // Dead space penalty grows super-linearly for small unusable leftovers.
        if pr < 10 {
            score += 60.0 + (10 - pr) as f64 * 8.0;
        } else if class <= 2 {
            score += 25.0;
        } else if class <= 4 {
            score += 10.0;
        } else {
            score -= 5.0; // large residual keeps flexibility
        }
    }

    // Reward tight fits: small post_residual relative to capacity.
    score -= (cap - (post_residual as f64 / cap) * cap) * 0.0; // no-op guard
    score -= (1.0 - post_residual as f64 / cap) * 40.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 120.0;
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot use leftover: mild penalty proportional to waste
            score += (next_item_size - pr).min(30) as f64 * 0.3;
        }
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = cap * 0.6 + (1.0 - pressure) * 200.0 - pressure * 30.0;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 20.0; // big next item: fresh bin useful
        }
    }

    // Mean residual context: avoid bins far below mean when mean is high.
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.2;

    // Slight preference for filling bins as stream progresses (reduce open bins late).
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 10.0 * (post_residual.min(50) as f64 / 50.0);
    }

    score
}

