        }

        // fill ratio reward
        let fill = item_size as f64 / bin_residual.max(1) as f64;
        score -= 20.0 * fill;

        // unusable residual relative to next item
        if next_item_size > 0 && post_residual < next_item_size {
            let unusable_ratio = post_residual as f64 / (next_item_size as f64).max(1.0);
            score += 0.4 * post_residual as f64 + 30.0 * (post_residual as f64 / bin_capacity as f64)
                + 12.0 * (1.0 - unusable_ratio);
        }

        // Last-chance bin: only bin that fits — prefer over new bin.
        if fitting_bins_count == 1 && bin_residual >= item_size {
            score -= 150.0;
        }

        // anti-fragmentation guard
        if fitting_bins_count == 2 && post_residual < bin_capacity / 3 {
            score -= 8.0;
        }

        // tiny unusable slivers when bins are plentiful
        if post_residual <= 5 && open_bins_count > 6 {
            score += 25.0 * (1.0 - progress);
        }

        // residual that can absorb two more average items
        if post_residual as f64 >= 2.0 * mean_residual && post_residual > 20 {
            score -= 5.0;
        }
    }

    // NEW-BIN CANDIDATE
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let fresh_left = bin_capacity - item_size;
        score += 180.0 - 60.0 * progress + 0.15 * open_bins_count as f64;

        // small items into a fresh bin waste space; large items pack well
        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3;
        }

        if next_item_size > 0 {
            if fresh_left == next_item_size {
                score -= 30.0;
            }
            if fresh_left == 2 * next_item_size {
                score -= 12.0;
            }
            // fresh leftover below next item and small: dead sliver
            if fresh_left < next_item_size && fresh_left < 8 {
                score += 35.0;
            }
            // fresh leftover can host next item plus mean-shaped slack
            if fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual).abs() <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
            // prefer fresh bin when existing residuals too small for next item
            if fitting_bins_count <= 2 && mean_residual < next_item_size as f64 {
                score -= 18.0 * (1.0 - progress);
            }
            // discourage fresh bins when many half-empty bins exist
            if open_bins_count > 8 && mean_residual > next_item_size as f64 + 10.0 {
                score += 12.0;
            }
        }
        // near-exact fill
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress);
        }
        // avoid opening fresh bins when an open bin nearly seals with this item
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0;
        }
        // early stream with few bins: fresh bin is fine
        if open_bins_count <= 4 && progress < 0.3 {
            score += 25.0;
        }
    }

    // Late in the stream, consolidate: prefer tightest fits even more.
    score -= progress * 0.3 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host the
    // smallest plausible item (<= 10) are pure waste; penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        // Small gaps that only fit tiny items are semi-dead space.
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 60.0;
    }

    // Prefer tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Lookahead: if the next item fits exactly into the post_residual,
    // this placement chains perfectly; reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Next item won't fit here; the residual becomes dead space
            // unless it is large enough for future items.
            if post_residual < 20 {
                score += 15.0;
            }
        }
    }

    // Open-bin pressure: with many open bins, favor consolidating into
    // existing bins rather than spreading; penalize lightly per open bin.
    score += (open_bins_count as f64) * 0.8;

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make empty bins attractive only when the item is
    // large (poor fit elsewhere) — otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        } else {
            score += 30.0;
        }
    }

    // Mean-residual coupling: if the stream's average residual is low
    // (bins are well packed), reward tight placements even more.
    if mean_residual < 25.0 && post_residual < 25 {
        score -= 8.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
