            let tail = fresh_left - next_item_size ;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress) ;
            }
        }
        // fresh bin leftover below mean residual is likely dead space
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        // chain home: leftover hosts next item twice exactly
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        // near-exact fill wastes nothing and preserves all open residuals
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        // fresh bin leftover matching mean residual — reusable home shape
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        // fresh bin leftover can host next item multiple times: strong chain home
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        // fresh bin leftover that hosts next item plus mean-shaped slack
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        // avoid opening fresh bins when a fitting open bin nearly seals with this item
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        // NEW: fresh bin is better when its leftover preserves a mid-band home while all open residuals are tiny
        if next_item_size > 0 && fresh_left >= bin_capacity / 8 && fresh_left <= bin_capacity / 2 && mean_residual < 6.0 {
            score -= 7.0 * (1.0 - progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with extra emphasis.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness;

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // strongly reward this placement (perfect chain).
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how well it fills remainder
            let fill = nr / (post_residual as f64);
            score -= 12.0 * fill;
            // penalize leaving a remainder the next item can't fill well
            score += 0.15 * (post_residual as f64 - nr);
        } else {
            // next item does NOT fit: penalize creating dead space it can't use
            let waste = nr - post_residual as f64;
            score += 0.20 * waste.min(30.0);
        }
    }

    // Compare against mean residual: placing into a below-average-residual bin
    // (larger residual than mean) keeps small holes concentrated.
    let resid = bin_residual as f64;
    if resid > mean_residual {
        score -= 0.10 * (resid - mean_residual).min(40.0);
    } else {
        score += 0.10 * (mean_residual - resid).min(40.0);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // many candidates: mild penalty to encourage discrimination
        score += 0.5 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate handling: only open a new bin when no open bin offers
    // a decent fit (post_residual would be small) or stream is early.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins more as stream progresses (reuse pressure),
        // unless the current item is large and would leave big waste elsewhere.
        let large_item_bonus = if item_size > bin_capacity / 2 { 10.0 } else { 0.0 };
        score += 20.0 + 15.0 * progress - large_item_bonus;
        // If the next item is small, a fresh bin is more attractive.
        if next_item_size > 0 && next_item_size < 20 {
            score -= 10.0;
        }
    }

    // Slight preference for bins with large residuals early on (first-fit flavor).
    if open_bins_count > 0 {
        score -= 0.02 * (resid as f64) / (open_bins_count as f64);
    }

    score
}

