pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more aggressively at small post-residuals.
    if post_residual > 0 {
        score -= (cap / post_residual as f64).sqrt() * 4.0;
    } else {
        score -= 25.0; // perfect fit bonus
    }

    // Penalize dead space that cannot fit the smallest plausible item.
    if post_residual < item_size && post_residual > 0 {
        score += 12.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let lookahead_fit = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 10.0 * (1.0 - lookahead_fit);
    } else if next_item_size > 0 && (post_residual as u32) < next_item_size {
        // Next item won't fit here; mild penalty proportional to wasted opportunity.
        score += 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Time horizon: early in the stream, prefer keeping residuals balanced; later, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (mean_residual - post_residual as f64) * 0.5;

    // Global pressure: many open bins relative to capacity -> prefer filling existing bins.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.0;
    }

    // Prefer bins whose residual deviates from the mean (consolidate outliers).
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    // New-bin candidate: penalize opening a new bin unless current fit is very poor.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.3 * mean_residual;
    }

    score
}

