        if next_item_size > 0 && fresh_left < next_item_size {
            score += 18.0 * (1.0 - progress) ;
        }
        // late-stream fresh bins are costly unless this item nearly seals them
        if progress > 0.8 && fresh_left > bin_capacity / 4 {
            score += 10.0 * (progress - 0.8) * 100.0 ;
        }
        // fresh bin lookahead: leftover hosts next item and tail matches mean shape
        if next_item_size > 1 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size ;
            if tail >= next_item_size && ((tail as f64) - mean_residual) . abs () <= 5.0 {
                score -= 7.0 * (1.0 - progress) ;
            }
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the leftover space: how "reusable" is the residual?
    // Residuals that are multiples of common item sizes (or large enough for
    // typical items) are valuable; tiny residuals (< 10) are dead space.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr < 10 {
        score += 25.0; // unusable dead space
    } else {
        // mod-based reusability bonus: residual divisible by small item sizes
        if pr % 10 == 0 { score -= 12.0; }
        if pr % 20 == 0 { score -= 8.0; }
        if pr % 25 == 0 { score -= 6.0; }
        // capacity-fraction thresholds: residual still >= half capacity is flexible
        if (pr as f64) >= 0.5 * cap { score -= 10.0; }
        else if (pr as f64) >= 0.25 * cap { score -= 4.0; }
        else { score += 6.0; }
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if (next_item_size as u64) <= pr as u64 {
            score -= 15.0;
            // harmonic pairing: next item exactly divides the residual
            if pr % next_item_size == 0 {
                score -= 12.0;
            }
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }
    // Many competing bins: mild penalty to spread usage toward tighter fits
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: penalize opening a fresh bin unless the item
    // is large or the current stream is early (plenty of future items to fill it).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let base = 45.0
            - 25.0 * (1.0 - progress)      // early stream: new bins are cheaper
            - 0.35 * (item_size as f64);   // large items justify fresh bins
        let _ = mean_residual;
        let _ = open_bins_count;
        score = base + (post_residual as f64) * 0.5;
    } else {
        // prefer bins whose residual is below the mean (tightening bins)
        score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);
    }

    score
}

