    } else if next_item_size > 0 && (next_item_size as u64) > (post_residual as u64) && (next_item_size as u64) <= (bin_residual as u64) {
        // next item won't fit here after placement but fits now: mild penalty
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += pressure * 2.0;

    // New-bin candidate: penalize mildly, but allow it when open bins have poor fits.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > mean_residual;
