pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportionally how well item fills the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio * fill_ratio * (bin_residual as f64 / bin_capacity as f64);

    // Penalize dead space: small post_residual is good, but if post_residual
    // is nonzero yet too small for the smallest plausible item, it's waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty if we leave large gap
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Time horizon: later in the stream, consolidation matters more; reward
    // using existing bins, penalize opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty grows with progress and open bins.
        score += 20.0 + 30.0 * progress + 0.5 * open_bins_count as f64;
    } else {
        score -= 5.0 * progress;
    }

    // Global state: if mean residual is high, spreading items is fine;
    // if mean residual is low, prefer bins that keep residuals balanced.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild penalty for leaving exactly-half-like awkward gaps mid-stream.
    if post_residual == bin_capacity / 2 && progress < 0.9 {
        score += 2.0;
    }

    score
}

