        // mean open residual; otherwise opening wastes the existing slack pool
        if next_item_size > 0 && fresh_left < next_item_size {
            score += 18.0 * (1.0 - progress) ;
        }
        // late-stream fresh bins are costly unless this item nearly seals them
        if progress > 0.8 && fresh_left > bin_capacity / 4 {
            score += 10.0 * (progress - 0.8) * 100.0 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / c;

    // Base: waste potential, penalized non-linearly (quadratic dead space)
    let mut score = norm_pr * norm_pr * 60.0 + pr * 0.35;

    // Smooth stream-progress coupling: early on prefer tight fills less aggressively,
    // late in the stream be very frugal with residuals
    let progress_coupling = 1.0 + 1.6 * progress * progress;
    score *= progress_coupling;

    // Reward large item consumption relative to bin (smooth saturation)
    let fill = it / c;
    score -= 25.0 * fill * (1.0 - 0.5 * fill);

    // Mean residual interaction: if open bins are loose on average, tolerate residual here
    let mr_norm = mean_residual / c;
    score -= 12.0 * norm_pr * mr_norm;

    // Lookahead: if next item fits the post-residual, reward strongly (smooth kernel)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_margin = (pr - nx) / c;
        if fit_margin >= 0.0 {
            score -= 30.0 * (1.0 - fit_margin) * (1.0 - 0.5 * progress);
        } else {
            // smooth penalty for near-miss residuals
            score += 8.0 * (-fit_margin) * (1.0 - fit_margin.max(-1.0));
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 45.0 * (1.0 - 0.3 * progress);
    }

    // Many open bins: mild penalty to consolidate into fewer bins
    score += 1.5 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score = 100.0 + 40.0 * (1.0 - progress) - 20.0 * mr_norm;
    }

    score
}

