pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: smaller post_residual is better, superlinear.
    score -= 40.0 / (1.0 + post_residual as f64);

    // Dead-space penalty: residuals too small for the smallest plausible item (<= 8)
    // are wasted; penalize that band strongly.
    if post_residual > 0 && post_residual <= 8 {
        score += 25.0;
    }

    // Harmonic residue classes of post_residual modulo capacity fractions:
    // classify leftover space into usable "harmonic classes".
    let quarter = bin_capacity / 4; // 25
    let fifth = bin_capacity / 5;   // 20
    let r_q = (post_residual % quarter) as f64;
    let r_f = (post_residual % fifth) as f64;
    // Aligning post_residual near a class boundary means it pairs well with
    // common item sizes (multiples of 10/20/25): reward near-zero residues.
    if r_q < 5.0 || r_q > (quarter as f64) - 5.0 {
        score -= 6.0;
    }
    if r_f < 4.0 || r_f > (fifth as f64) - 4.0 {
        score -= 4.0;
    }

    // Lookahead coupling: if the next item fits the post_residual exactly or well,
    // strongly favor this bin (chaining placements).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 / (1.0 + slack);
            // next item leaves another tiny dead space? discourage
            if post_residual - next_item_size <= 4 && post_residual - next_item_size > 0 {
                score += 8.0;
            }
        } else {
            // next item cannot follow in this bin: slight penalty proportional to gap
            score += ((next_item_size - post_residual) as f64) * 0.05;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has large post_residual;
    // penalize it mildly so it's chosen only when open bins give bad fits,
    // but relax that penalty late in the stream or when many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 - 10.0 * progress - 0.5 * (open_bins_count.min(20) as f64);
    }

    // Prefer bins with residual below the mean (consolidating fuller bins first),
    // keeping many large-residual bins open for future large items.
    score += ((mean_residual - bin_residual as f64).max(-30.0).min(30.0)) * 0.3;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

