        // self-renewing home shape with scarcity
        if next_item_size > 0 && post_residual > next_item_size {
            let headroom = (post_residual - next_item_size) as f64 ;
            if (headroom - mean_residual) . abs () <= 1.0 && fitting_bins_count <= 3 {
