        if next_item_size > 1 && post_residual > next_item_size + 1 && post_residual <= next_item_size + 10 {
            score -= 4.0 * (1.0 - progress) ;
        }
        // NEW: prefer bins whose post_residual is closest to (but >=) next item — minimal leftover
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count > 1 {
            let excess = (post_residual - next_item_size) as f64 ;
            score -= 3.0 * (1.0 - excess / (bin_capacity as f64 * 0.5)) . max (0.0) ;
