    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Lookahead: reward placements that leave room for the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0; // leaves exact room for next item
        } else if post_residual >= next_item_size {
            // good: next item still fits; mildly reward small slack after next item
            let after_next = post_residual - next_item_size;
            score -= 4.0 * (1.0 - after_next as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here after placement: mild penalty
            score += 6.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer filling existing bins.
    if open_bins_count > 0 {
        let mean_res_ratio = mean_residual / bin_capacity as f64;
        if mean_res_ratio > 0.5 {
            score -= 5.0 * mean_res_ratio; // plenty of slack overall, consolidate
        }
    }

    // Time horizon: early in the stream, be more willing to open new bins (score new bins slightly better);
    // late in the stream, squeeze everything into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decreasing as stream progresses (fewer future items to fill it).
        score += 18.0 * (1.0 - 0.6 * progress);
        // If current item nearly fills a fresh bin, opening is attractive.
        if item_size as f64 / bin_capacity as f64 > 0.8 {
            score -= 10.0;
        }
        // If no open bin fits well (this is the only fitting candidate), new bin is fine.
        if fitting_bins_count == 0 {
            score -= 8.0;
        }
    }

    // Penalize leaving residuals that are awkward (just above common item sizes creates poor fits later).
    let awkward = |r: u32| -> f64 {
        let rf = r as f64;
        // residual slightly larger than a plausible item size is bad (hard to fill exactly)
        let frac = (rf / 10.0).fract();
        if r > 0 && frac < 0.15 && rf > 10.0 { 3.0 * (0.15 - frac) } else { 0.0 }
    };
    score += awkward(post_residual);

    // Mild penalty proportional to number of open bins to discourage proliferation late.
    score += 0.3 * open_bins_count as f64 * progress;

    score
}

