        // mean open residual; otherwise opening wastes the existing slack pool
        if next_item_size > 0 && fresh_left < next_item_size {
            score += 18.0 * (1.0 - progress) ;
        }
        // late-stream fresh bins are costly unless this item nearly seals them
        if progress > 0.8 && fresh_left > bin_capacity / 4 {
            score += 10.0 * (progress - 0.8) * 100.0 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual scaled by progress (waste matters more later)
    let mut score = pr * (0.5 + progress);

    // Smooth non-linear coupling: quadratic + cubic of normalized post-residual
    let q = norm_pr * norm_pr;
    let c = q * norm_pr;
    score += 30.0 * q * (0.5 + progress);
    score -= 20.0 * c * (1.0 - progress);

    // Dead-space penalty: residual too small for any item (1..100)
    let dead = ((1.0 - norm_pr) * (1.0 - norm_pr)).max(0.0);
    score += 25.0 * dead * (1.0 - progress);

    // Reward tight fits (small post residual) especially when few fitting bins
    let tight = 1.0 - norm_pr;
    let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
    score -= 15.0 * tight * tight * scarcity;

    // Lookahead coupling: favor post-residual close to next item size
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx) / cap;
        score -= 12.0 * (-8.0 * diff * diff).exp() * (1.0 - progress);
    }

    // Penalty for spreading across many open bins late in stream
    score += 2.0 * open_bins_count as f64 * progress * norm_pr;

    // Mean-residual alignment: prefer bins near mean residual
    let md = (pr - mean_residual) / cap;
    score += 5.0 * md * md;

    score
}

