pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common item
    // classes (10, 20, 25, 50) are more reusable, so reward them.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    if post_residual > 0 {
        // Modulo-class rewards: perfectly divisible residuals are "harmonic".
        if post_residual % 50 == 0 { score -= 8.0; }
        else if post_residual % 25 == 0 { score -= 5.0; }
        else if post_residual % 20 == 0 { score -= 4.0; }
        else if post_residual % 10 == 0 { score -= 2.5; }
        else { score += 2.0; } // non-harmonic dead space penalty

        // Integer-division threshold: small unusable slivers are dead space.
        if post_residual < 10 { score += 15.0; }
        else if post_residual < 20 { score += 6.0; }
    } else {
        // Perfect fill is ideal.
        score -= 25.0;
    }

    // Lookahead coupling: does the residual form a harmonic pair with next item?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0; // exact match next step
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack % 10 == 0 { score -= 4.0; }
            score += slack as f64 * 0.15;
        } else {
            // next item cannot use this bin's leftover; penalize by fraction
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Fraction-of-capacity class of the item placement.
    let fill_frac = (item_size as f64) / cap;
    if fill_frac > 0.8 { score -= 6.0; }
    else if fill_frac > 0.5 { score -= 2.0; }
    else { score += 1.5; }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless it is genuinely
    // better (few open bins early, or current fit is terrible).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (post_residual as f64) < 10.0;
        if open_bins_count > 0 && !poor_fit {
            score += 14.0 + 10.0 * (1.0 - progress);
        }
        if mean_residual > 40.0 && open_bins_count > 2 {
            score += 6.0; // plenty of slack elsewhere; avoid spreading
        }
    }

    // Mild tie-break toward consolidating into fuller bins.
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

