pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual
    // exactly (or nearly) matches the next item size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain fit
        } else if post_residual > next_item_size {
            let gap = post - next;
            score -= 25.0 / (1.0 + gap / 20.0); // next item still fits here
        } else {
            // next item won't fit in leftover: penalize proportionally
            score += (next - post) * 0.5;
        }
        // coupling with mean residual: prefer bins whose leftover stays
        // near the fleet mean so residual space stays usable
        score += 0.3 * ((post - mean_residual).abs());
    }

    // Dead-space penalty: leftover too small to ever matter
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize opening a new bin when open bins could fit, unless
    // the item fits poorly everywhere (tight fit is good though)
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus pressure with bin count
        score += 20.0 + 2.0 * open_bins_count as f64;
        // if next item is large, a fresh bin is more attractive
        if next_item_size >= 50 {
            score -= 15.0;
        }
    } else {
        // reward tight fits in existing bins
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
        // late in stream, consolidate more aggressively
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

