pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect/near-perfect fit reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Tightness reward: quadratic in post-residual relative to capacity.
        let tight = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
        score -= 40.0 * tight * tight;
    }

    // Penalize dead space that is too small for any future item (min item = 1).
    if post_residual > 0 && post_residual < 2 {
        score += 500.0;
    }

    // Lookahead coupling: reward residuals that pair with the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            // reward leaving room for next item, scaled by how snugly next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 / (1.0 + slack / 10.0);
        } else {
            // next item won't fit here; mild penalty scaled by wasted potential
            score += 10.0 * (next_item_size as f64 - post_residual as f64) / 20.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: only attractive when open bins are badly fragmented
    // or the item is large and fits nowhere snugly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // fragmentation measure: mean residual relative to capacity
        let frag = mean_residual / bin_capacity as f64;
        // prefer new bin when mean residual is low (bins nearly full) or many bins open
        let new_bin_bonus = 120.0 * frag + 8.0 * (open_bins_count as f64).sqrt() + 50.0 * progress;
        score += new_bin_bonus;
        // discourage opening new bins for small items
        score += (bin_capacity - item_size) as f64 * 0.5;
    } else {
        // Mild reward for filling existing bins rather than spreading.
        score -= 5.0 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        // Penalize placing into bins whose residual deviates wildly from mean (keeps spread even)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.3 * dev;
    }

    // Time horizon: early in stream, be conservative (keep bins flexible);
    // late in stream, prefer aggressive packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 30.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

