pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear polynomial coupling to progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Smooth non-linear penalty for awkward residuals (mid-range dead space)
    let dead = norm_pr * (1.0 - norm_pr); // peaks at norm_pr = 0.5
    score += 30.0 * dead * (0.5 + progress);

    // Reward tight fits (small post residual) more strongly later in the stream
    score -= 10.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Coupling with mean residual: prefer bins whose residual deviates favorably from mean
    score += 0.3 * (pr as f64 - mean_residual).abs() * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: if next item fits exactly in post residual, reward
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score += 0.2 * gap;
        if post_residual as i64 == next_item_size as i64 {
            score -= 20.0;
        }
    }

    // Mild penalty for spreading across too many open bins late in stream
    score += 0.05 * open_bins_count as f64 * progress;

    // New-bin candidate: make empty bin attractive only when residuals are poor
    if bin_residual == bin_capacity {
        let avg_bad = mean_residual / cap;
        score = cap * (0.6 + 0.4 * progress) - 20.0 * avg_bad * avg_bad;
    }

    score
}

