    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact fills are perfect.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Small dead space is dangerous if nothing else can use it: penalize
    // residues that fall in "unusable" harmonic classes (prime-ish gaps).
    let pr = post_residual;
    let class = pr / 10; // harmonic class bucket of 10
    match class {
        0 => score -= 40.0,          // residue 1..9: nearly full, great
        1 => score -= 25.0,          // 10..19: still very usable
        2 => score -= 15.0,          // 20..29
        3 => score += 5.0,           // 30..39: mediocre
        4 => score += 10.0,          // 40..49: half-empty, wasteful
        _ => score += 15.0,          // >50 left: bin barely used
    }

