    // are more likely to be filled by future items -> reward them.
    if pr % 10 == 0 { score -= 8.0; }
    if pr % 25 == 0 { score -= 6.0; }
    if pr % 20 == 0 { score -= 5.0; }
    if pr % 30 == 0 { score -= 4.0; }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 120.0;
        } else if next_item_size <= pr {
            // next item fits: leftover after that pair matters
            let after_next = pr - next_item_size;
            score -= 20.0 - (after_next as f64) * 0.3;
        } else {
