            score += (next_item_size - pr).min(40) as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Prefer tight bins relative to the mean residual of open bins.
    score -= (mean_residual - post_residual as f64) * 0.25;

    // Early in the stream, be more willing to open bins (spread items);
    // late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: accept early or when item is large and mean
        // residual is fragmented; otherwise push toward existing bins.
        let large_item_bonus = if item_size > bin_capacity / 2 { 15.0 } else { 0.0 };
        score += 25.0 + (1.0 - progress) * 10.0 - large_item_bonus
