    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: discourage spreading into already-fragmented bins
    if open_bins_count > 2 {
        score += (open_bins_count as f64).ln() * 3.0 * (post / cap);
