pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = post / cap;

    // Base: quadratic waste penalty on post-residual
    let mut score = post + 0.9 * post * fit_ratio;

    // Smooth cubic coupling with stream progress: waste matters more later
    score += 0.35 * post * fit_ratio * fit_ratio * (0.5 + progress);

    // Tight-fit reward (smooth, non-piecewise): gaussian-like bump near zero residual
    let tightness = (-fit_ratio * fit_ratio * 18.0).exp();
    score -= 12.0 * tightness * (0.6 + 0.8 * progress);

    // Last-chance bonus when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Penalize bins far from mean residual (fragmentation avoidance), smoothly
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Lookahead: reward leaving space for the next item, smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = post - nx;
        if gap >= 0.0 {
            score -= 5.0 * (-gap * gap / 400.0).exp();
        } else {
            score += 3.0 * (-gap / cap);
        }
    }

    // New-bin candidate: penalize opening a fresh bin unless item is large
    let is_new = (bin_residual as f64 - cap).abs() < 1e-6 && open_bins_count > 0;
    if is_new {
        let fill = item_size as f64 / cap;
        score += 25.0 - 18.0 * fill * fill - 10.0 * progress;
    }

    score
}

