pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of common item sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        let mut class_bonus = 0.0;
        for m in [10u32, 20, 25, 30, 40, 50, 60, 70, 80, 100].iter() {
            if pr % m == 0 {
                class_bonus += 6.0;
            }
        }
        // Perfect fill: dead space zero is ideal
        if pr == 0 {
            score -= 40.0;
        }
        // Small dead space (< 10) is unusable for any item: heavy penalty
        if pr < 10 {
            score += 25.0;
        }
        score -= class_bonus;
    }

    // Fraction-of-capacity coupling: penalize residuals in awkward bands
    let frac = post_residual as f64 / cap;
    if frac > 0.0 && frac < 0.10 {
        score += 15.0; // dead zone
    } else if frac >= 0.10 && frac <= 0.35 {
        score -= 5.0; // still very usable
    }

    // Lookahead harmony: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            // harmonic division: post_residual / next_item_size integer
            if pr % next_item_size == 0 {
                score -= 12.0;
            }
            score -= 4.0;
        } else {
            // next item won't fit here: mild penalty proportional to overshoot class
            score += ((next_item_size - pr) % 20) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: prefer existing bins unless current bin is
    // nearly full and mean residual across fleet is high.
    if bin_residual == bin_capacity {
        // brand-new bin: baseline penalty so it's chosen only when open bins are bad
        score += 12.0;
        if (post_residual as f64) < mean_residual * 0.5 && open_bins_count > 0 {
            score -= 8.0;
        }
    } else if (bin_residual as f64) < mean_residual {
        score -= 3.0; // tighter than average bin: good target
    }

    // Late in stream: consolidate, avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;

    score
}

