}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 40.0;

    // Aggressive 2-step lookahead: perfect match with next item is ideal
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Reward exact match strongly
        if diff == 0.0 {
            score -= 60.0;
        } else {
            score += diff * 0.8;
        }
        // Penalize dead space that cannot fit the next item
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 1.2;
        }
    } else {
        // Last item: minimize waste
        score -= 10.0;
    }

    // New-bin candidate handling: only open a new bin when no good fit exists
    if bin_residual == bin_capacity {
        // Prefer new bin if current bin would leave large unusable gap
        let would_waste = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score += 25.0 - would_waste * 30.0;
        // Discourage new bins when many bins already fit the item
        if fitting_bins_count > 1 {
            score += 30.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Slight preference for bins tighter than the mean residual (compactness)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Late-stream consolidation: as stream progresses, avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

