    score += 0.08 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in stream, slightly favor reusing bins; late, favor tight fits more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: default neutral-ish score; open a new bin only when
    // no open bin offers a good fit (post_residual small) or it's the last chance.
    if bin_residual == bin_capacity {
        let base = 55.0 + 25.0 * progress;
