        }
        // post_residual as a fraction of bin capacity — penalize mid-range waste
        let post_frac = post_residual as f64 / bin_capacity as f64 ;
        if post_frac > 0.5 && post_frac < 0.9 && next_item_size > 0 && post_residual > next_item_size {
            score -= 8.0 * (post_frac - 0.5) ;
        }
        // NEW: scarce-fitting bonus scales with how few bins fit the item
        if fitting_bins_count <= 2 && post_residual >= next_item_size {
            score -= 3.0 * (1.0 - progress) ;
        }
    }
