        if post_residual == 0 {
            score += 60.0 ;
        }
        // NEW: fresh bin late with many open bins is costly unless item is large
        if progress > 0.75 && open_bins_count > 5 && item_frac < 0.5 {
            score += 15.0 * (progress - 0.75) / 0.25 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: penalize leftover space, but with diminishing (quadratic) dead-space cost.
    let norm_post = post / cap;
    let mut score = norm_post + 0.6 * norm_post * norm_post;

    // Smooth non-linear coupling of leftover with stream progress:
    // early on, tolerate leftovers (bins can still be filled later);
    // late, dead space is costly.
    let progress_w = 0.5 + 1.5 * progress * progress;
    score *= progress_w;

    // Tight fit reward: smooth bell around post_residual == 0..small.
    let tightness = (1.0 - norm_post).max(0.0);
    score -= 1.2 * tightness * tightness * tightness;

    // Lookahead: if next item fits the post-residual, reward strongly (smooth sigmoid-like gate).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = if post >= nxt { 1.0 } else { 0.0 };
        let closeness = 1.0 - ((post - nxt).abs() / cap).min(1.0);
        score -= 0.9 * fits_next * closeness * closeness;
    }

    // Last-chance bonus: sole fitting bin — avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 0.8 + 0.5 * progress;
    }

    // Reward bins with residuals below the mean (consolidating emptier space usage),
    // smooth quadratic coupling.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.35 * dev * dev * dev.signum();

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item fits poorly everywhere; make the empty bin mildly unattractive
    // unless the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let size_ratio = item / cap;
        score += 1.0 - 1.4 * size_ratio * size_ratio;
        // Late in the stream, new bins are fine (fewer future items to fill them).
        score -= 0.7 * progress;
    }

    // Mild preference for using fewer bins when many are open.
    score += 0.002 * open_bins_count as f64 * norm_post;

    score
}

