pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host
    // even the smallest plausible future item are pure waste.
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 25.0 + 2.0 * (dead_threshold - post_residual as f64);
    }

    // Reward tight fits strongly.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // Penalize leaving a gap the next item just barely misses.
    if next_item_size > post_residual && post_residual > 0 && next_item_size <= bin_residual {
        score += 5.0;
    }

    // Open-bin pressure: discourage proliferation of bins, but allow opening
    // a fresh bin when existing bins would be badly fragmented.
    score += 1.5 * open_bins_count as f64;

    // New-bin candidate (empty bin): make it attractive only when fits are poor.
    if bin_residual == bin_capacity {
        let waste_if_forced = (bin_capacity - item_size) as f64;
        let poor_fit = (post_residual as f64 - mean_residual).abs();
        // Default: opening a new bin is moderately expensive.
        score = 0.4 * waste_if_forced + 2.0 * open_bins_count as f64;
        // If this is the only fitting bin, keep it open rather than open new.
        if fitting_bins_count == 1 {
            score += 15.0;
        }
        // If mean residual across open bins is large, prefer reusing them.
        score += 0.5 * mean_residual;
        let _ = poor_fit;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Mild phase pressure: early in the stream, be frugal with bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * (1.0 - progress);

    score
}

