pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward a perfect chain fit.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // exact two-item closure
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportional to how snugly the next item fits
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize leftover dead space
            let dead = post_residual as f64 / bin_capacity as f64;
            score += 20.0 * dead;
        }
    } else {
        // last item: just close bins tightly
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Base fit tightness: prefer bins where the item fills most of the residual
    let fill = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill;

    // Penalize residuals far below the mean (fragmented bins)
    score += 0.15 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let good_lookahead = next_item_size > 0 && post_residual >= next_item_size;
        if fitting_bins_count > 0 && (fill > 0.7 || good_lookahead) {
            score += 60.0; // keep using open bins when fit is decent
        } else {
            score -= 5.0; // allow opening a bin on poor fits
        }
    }

    // Mild pressure to consolidate as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

