    // Early stream: prefer tight fills (minimize post_residual strongly, quartic).
    // Late stream: smoother preference, penalize large residuals more.
    let x = pr / cap; // normalized post residual
    let t = progress;
    let coupling = 1.0 + 3.0 * t * t + 2.0 * t * t * t;
    score += coupling * (x * x * x * x) * cap * 0.5;

