            score -= 3.0 * (1.0 + pr / nx) * 0.1;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Mild penalty when many bins are open and residual is large (fragmentation).
    let frag = (open_bins_count as f64).ln() + 1.0;
    score += frag * x * x * 1.5;

    // Bias toward bins below mean residual (consolidate fuller bins).
    score += 0.3 * (mean_residual - pr) / cap;

    // New-bin candidate: only attractive if no good fit exists elsewhere;
    // base penalty that shrinks as stream progresses.
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - t) + 2.0;
    }

    score
}

