        score += 180.0 - 60.0 * progress + 0.15 * open_bins_count as f64 - 25.0 * big_next . max (0.0) ;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0 ;
        }
        if open_bins_count <= 4 && progress < 0.3 {
            score += 25.0 ;
        }
        if mean_residual < 15.0 && progress > 0.5 {
            score -= 15.0 ;
        }
        let item_frac = item_size as f64 / bin_capacity as f64 ;
        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3 ;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3 ;
        }
        let fresh_left = bin_capacity - item_size ;
        if next_item_size > 0 && fresh_left == next_item_size {
            score -= 30.0 ;
        }
        if open_bins_count > 6 && mean_residual > 0.4 * bin_capacity as f64 {
            score += 20.0 ;
        }
        // fresh-bin leftover sliver is wasteful
        if next_item_size > 0 && fresh_left < next_item_size && fresh_left < 8 {
            score += 35.0 ;
        }
        // prefer fresh bin when all existing residuals are too small for next item
        if next_item_size > 0 && fitting_bins_count <= 2 && mean_residual < next_item_size as f64 {
            score -= 18.0 * (1.0 - progress) ;
        }
        // discourage opening fresh bins late when many half-empty bins exist
        if open_bins_count > 8 && mean_residual > next_item_size as f64 + 10.0 {
            score += 12.0 ;
        }
        // large items into fresh bins leave big usable leftovers: mild reward
        if item_frac > 0.6 && next_item_size > 0 && fresh_left >= next_item_size {
            score -= 8.0 * (1.0 - progress) ;
        }
        // fresh bin justified when leftover can host next item plus mean slack
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress) ;
        }
        // near-zero tail after next item (perfect closure)
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size ;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress) ;
            }
        }
        // fresh bin leftover below mean residual is likely dead space
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        // chain home: leftover hosts next item twice exactly
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        // near-exact fill wastes nothing and preserves all open residuals
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        // fresh bin leftover matching mean residual — reusable home shape
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        // chain home: leftover hosts next item multiple times exactly
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        // fresh bin leftover that hosts next item plus mean-shaped slack
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        // avoid opening fresh bins when a fitting open bin nearly seals with this item
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        // NEW: fresh bin more attractive when open-bin residuals are uniformly small
        if mean_residual < 0.15 * bin_capacity as f64 && open_bins_count > 3 {
            score -= 6.0 * (1.0 - progress) ;
        }
        // NEW: late stream — fresh bins only for large items that would strand elsewhere
        if progress > 0.85 && item_frac < 0.5 {
            score += 10.0 * (progress - 0.85) / 0.15 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space quality via integer division thresholds
    let pr = post_residual;
    let class = match pr {
        0 => 0.0,                 // perfect fit
        1..=5 => 0.0,             // near-perfect
        6..=15 => 4.0,            // small dead zone
        16..=30 => 10.0,          // medium dead zone
        31..=50 => 18.0,
        _ => 26.0,                // large waste
    };
    score += class;

    // Modulo-10 harmonic banding: residuals that are multiples of 10 pair well
    // with typical item granularities
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    } else if pr % 5 == 0 {
        score -= 2.0;
    }

    // Lookahead coupling: reward residuals that can host the next item too
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 8.0;
        } else {
            // penalty proportional to how much we block the next item
            let gap = (next_item_size - pr) as f64;
            score += gap * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly
    if bin_residual == bin_capacity {
        let avg_fit_quality = mean_residual / cap;
        let pressure = open_bins_count as f64;
        // penalize opening new bins early / when existing bins are roomy
        score += 30.0 + pressure * 2.0 - avg_fit_quality * 10.0;
        // but if current item is large and would leave tiny residual elsewhere,
        // a fresh bin is fine
        if item_size as f64 / cap > 0.7 {
            score -= 12.0;
        }
    }

    // Tight-fit bonus: item fills most of the bin
    let fill = item_size as f64 / bin_residual as f64;
    if fill > 0.9 {
        score -= 10.0;
    } else if fill > 0.7 {
        score -= 4.0;
    }

    // Stream progression: later in stream, be greedier about exact packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    // penalize residuals below the minimum item size (unusable)
    if pr > 0 && pr < 10 {
        score += 20.0;
    }

    score
}

