        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        // fresh-bin dead-space ratio — leftover that nothing can use
        if next_item_size > 0 && fresh_left < next_item_size {
            let fresh_dead = fresh_left as f64 / bin_capacity as f64 ;
            score += 40.0 * fresh_dead * (1.0 - progress) ;
        }
        // NEW: fresh bin whose leftover seals exactly with a mean-sized item
        if fresh_left > 0 && (fresh_left as f64 - mean_residual) . abs () <= 1.0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        // NEW: discourage fresh bins late when an open bin can still host next item
        if next_item_size > 0 && open_bins_count > 4 && mean_residual >= next_item_size as f64 && progress > 0.4 {
            score += 6.0 * progress ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    }

    // Lookahead: bonus if next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item cannot use this bin's leftover: penalize large leftovers
            score += 0.15 * (post_residual as f64 - mean_residual).abs();
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a new bin is expensive when few bins open,
    // but reasonable when open bins are mostly full (low mean residual).
    if bin_residual == bin_capacity {
        let pressure = mean_residual / (bin_capacity as f64);
        score = 70.0 + 60.0 * pressure + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 80.0; // no alternative
        }
    }

    // Time horizon: early in the stream, prefer consolidating into fewer bins;
    // late in the stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * tightness;
    score += (1.0 - progress) * 0.05 * open_bins_count as f64;

    // Mild preference for bins whose residual is below mean (fill the emptier ones less).
    score += 0.1 * ((bin_residual as f64) - mean_residual).max(0.0);

    score
}

