        }
        // avoid opening fresh bins when a fitting open bin nearly seals with this item
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        // NEW: late-stream compaction — avoid fresh bins when any open bin fits next item
        if next_item_size > 0 && progress > 0.6 && mean_residual >= next_item_size as f64 {
            score += 10.0 * progress ;
        }
        // NEW: penalize fresh bins whose leftover is a small odd sliver relative to mean
        if next_item_size > 0 && fresh_left >= next_item_size && fresh_left < next_item_size + 6 && (fresh_left - next_item_size) as f64 > mean_residual {
            score += 6.0 * (1.0 - progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let r = bin_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: penalize remaining space, with non-linear (quadratic/cubic) shaping
    let mut score = x * (1.0 + 2.0 * x * x);

    // Tight fits are strongly rewarded: cubic coupling of fill ratio
    let fill = item / cap;
    score -= 3.0 * fill * fill * fill;

    // Smooth interaction: post residual penalty softened when fill is high
    score += 2.0 * x * (1.0 - fill) * (1.0 - fill);

    // Stream progress: later in the stream, prefer tighter packing (weight residuals more)
    let prog_w = progress * progress;
    score += prog_w * 2.5 * x;
    score -= prog_w * 1.5 * fill;

    // Mean residual coupling: if open bins are loose on average, reward using this one well
    let mr = mean_residual / cap;
    score -= 0.8 * mr * fill * (1.0 - x);

    // Lookahead: if next item fits the post residual, reward leaving exactly that room
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt).abs();
        let nd = diff / cap;
        score -= 2.0 * (1.0 - nd * nd) * (1.0 - x) * (1.0 - progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && r >= item {
        score -= 4.0 * (1.0 - x);
    }

    // Penalty when many bins are open and this one would be left very loose
    let ob = open_bins_count as f64;
    score += 0.3 * (ob / (ob + 5.0)) * x * x;

    // New-bin candidate shaping: empty bin gets a moderate baseline so it wins only when fits are poor
    if (r - cap).abs() < 0.5 {
        score += 1.2 + 2.0 * progress;
    }

    score
}

