pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit any
    // future item (min item size ~1..10) are "wasted". Penalize small but
    // nonzero post_residual quadratically; large residuals are cheap space.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0 * (10.0 - post_residual as f64).powi(2);
        } else if post_residual < 20 {
            score += 12.0 * (20.0 - post_residual as f64);
        }
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Coupling with mean residual: prefer bins whose residual is far below
    // the mean (i.e., tight bins), penalize using bins with lots of slack.
    score += 0.6 * (mean_residual - bin_residual as f64).max(0.0);

    // Open-bin pressure: when many bins are open, discourage opening new
    // bins; when few bins are open, consolidation pressure is lower.
    let pressure = (open_bins_count as f64).sqrt() * 2.0;

    // New-bin candidate handling: bin_residual == bin_capacity means a
    // brand-new empty bin. Make it attractive only if no existing bin fits
    // well (post_residual would be large or fitting_bins_count == 0-ish).
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin, modulated by open-bin pressure and
        // how "desperate" the current situation is.
        score = 55.0 + pressure;
        if next_item_size > 0 && next_item_size as f64 >= bin_capacity as f64 * 0.5 {
            // Next item is large; a fresh bin is more useful.
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 50.0; // no existing bin fits: new bin is necessary
        }
    } else {
        // Last-chance bonus: if this is the ONLY bin that fits the item,
        // strongly favor using it instead of opening a new bin.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }

        // Lookahead: reward placing item so that next_item_size still fits
        // in the same bin; penalize if it leaves a gap just barely too small.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 8.0;
            } else if post_residual > 0 && next_item_size - post_residual <= 3 {
                score += 15.0; // teasing gap: dead space for the known next item
