pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that can never be used by typical future items:
    // small residuals (< ~10) are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when existing bins fit decently.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // New bins are more acceptable early (planning ahead) and when
        // mean residual of open bins is low (bins are full-ish).
        let mean_res_penalty = (mean_residual / bin_capacity as f64).max(0.0);
        score += 30.0 * (1.0 - mean_res_penalty) + 10.0 * progress;
        // If the next item is large and this bin would be nearly full after
        // placement, opening a fresh bin is actually attractive.
        if next_item_size > 0 {
            let next_fits_here = (next_item_size as f64) <= post_residual as f64;
            if next_fits_here {
                score -= 15.0;
            } else {
                score += 6.0;
            }
        }
        // Fewer open bins => opening new ones is cheaper.
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    } else {
        // Reward placing into bins whose residual is close to the item size
        // (best-fit style) even beyond the raw post_residual.
        let fit_gap = (bin_residual as f64 - item_size as f64);
        score -= 4.0 * (-fit_gap / 20.0).exp();

        // Lookahead: if the next item fits exactly in the post residual,
        // this is a perfect chain — reward it.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > 0 && next_item_size > post_residual {
            // Next item won't fit here; slight penalty for leaving awkward gap.
            score += 3.0;
        }
    }

    // Global pressure: many open bins with high mean residual → prefer
    // consolidating into existing bins (penalize waste relative to mean).
    if !is_new_bin {
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * deviation;
    }

    // Mild time-dependent conservatism: late in the stream, avoid loose fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

