    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += poly * 30.0;

    // Penalize wasted space more strongly later in the stream
    score -= (1.0 - progress) * (1.0 - progress) * 8.0;

    // Reward tight fits (small post_residual) with smooth falloff
    let tightness = (item_size as f64 / bin_capacity as f64).powi(3);
    score -= tightness * 15.0;

