    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Discard preference for opening a new bin unless residual is unusable
    let is_new = bin_residual == bin_capacity;
    if is_new {
        score += 5.0 + 10.0 * (1.0 - progress);
