        // fresh bin leftover below mean residual is likely dead space
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        // chain home: leftover hosts next item twice exactly
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        // near-exact fill wastes nothing and preserves all open residuals
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        // fresh bin leftover matching mean residual — reusable home shape
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        // chain home: leftover hosts next item multiple times exactly
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        // fresh bin leftover that hosts next item plus mean-shaped slack
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        // avoid opening fresh bins when a fitting open bin nearly seals with this item
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        // GEN82: resist fresh bins late when open bins still have room for the
        // next item — preserve existing homes to cut dead space
        if progress > 0.6 && next_item_size > 0 && fitting_bins_count > 0
            && mean_residual >= next_item_size as f64 {
            score += 10.0 * (progress - 0.6) * 2.5 ;
        }
        // GEN82: fresh bin attractive when leftover is a clean multiple of the
        // mean residual (predictable future homes)
        if mean_residual >= 5.0 && fresh_left as f64 >= mean_residual
            && ((fresh_left as f64 / mean_residual) - (fresh_left as f64 / mean_residual) . round ()) . abs () < 0.05 {
            score -= 7.0 * (1.0 - progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: perfect fill is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: small unusable remainders (1..=9) are wasted capacity.
    if post_residual >= 1 && post_residual <= 9 {
        score += 25.0;
    }

    // Harmonic classes of post_residual via modulo arithmetic.
    // Class 0 (multiples of 10): highly reusable by typical item sizes.
    let pr = post_residual;
    if pr > 0 && pr % 10 == 0 {
        score -= 12.0;
    }
    // Class mod 5: half-reusable class gets a mild bonus.
    if pr > 0 && pr % 5 == 0 {
        score -= 4.0;
    }
    // Integer-division thresholds: residual bands.
    let band = pr / 20; // 0..5
    score -= band as f64 * 3.0;

    // Lookahead coupling: if next item exactly fits post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            // next fits: bonus scaled by how snugly
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item cannot use this residual: penalize small leftovers more
            let waste = (post_residual as f64) / (next_item_size as f64);
            score += 8.0 * waste.min(1.5);
        }
        // Harmonic pair: post_residual + next_item_size hits a multiple of capacity fraction
        let sum = post_residual + next_item_size;
        if sum % 50 == 0 {
            score -= 6.0;
        }
    }

    // New-bin candidate handling: only prefer a fresh bin when no good open option exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 45.0;
        // As stream progresses, be slightly more willing to open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        // If many bins already fit, discourage opening a new one.
        score += 6.0 * fitting_bins_count as f64;
        // If this is a last-chance bin situation, opening new bin is attractive.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // Large items leave large residuals in fresh bins; small penalty adjust.
        score += (item_size as f64) * 0.05;
    }

    // Last-chance bonus for an existing bin: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Prefer filling bins that are already relatively empty among open bins.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Mild load-balancing pressure on number of open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

