    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item fits: mild reward proportional to tightness.
            score -= 50.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit: penalize leaving medium dead space,
            // scaled by how far the next item overshoots.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.5 * overshoot;
        }
    }

    // Compare post_residual against mean residual: leaving more than average
    // free space is wasteful; leaving less is good packing.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: keep it neutral-ish; only attractive when no open bin
    // fits well (handled by rewards above for good fits).
    if bin_residual == bin_capacity {
        score += 150.0;
    }

    // Late in the stream, prefer closing bins tightly (less fragmentation).
    let progress = step_index as f64 / total_items as f64;
    score += 0.2 * progress * post_residual as f64;

    score
}

