pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary: reward tight fits (small post_residual) with a non-linear squash.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving residuals that are awkwardly small but unusable:
    // dead space = post_residual too small to ever hold the smallest plausible item.
    if post_residual < 10 {
        score += 40.0; // near-perfect fit is great, but total overflow risk handled elsewhere
    } else if post_residual <= item_size {
        score -= 8.0; // residual still usable by similar-sized future items
    }

    // Lookahead coupling: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here after placement; mild penalty scaled by how close it was
            score += 6.0 * (1.0 - (next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: this is the only open bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global fragmentation pressure: when mean residual across open bins is low,
    // conserve space more aggressively (waste is costlier late).
    let frag = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score += 12.0 * frag * fit_ratio * (post_residual as f64);

    // Time horizon: later in the stream, prefer consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    // Many open bins: discourage spreading; reward packing into already-crowded set.
    score += 0.5 * open_bins_count as f64 * fit_ratio;

    // New-bin candidate handling: an empty bin has no placement waste, but opening
    // it should only win when existing fits are poor. Give it a moderate baseline.
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * (1.0 - progress);
        // If next item is large and current item is small, a fresh bin is attractive.
        if next_item_size >= 70 && item_size <= 30 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
