            }
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let x = pr / cap;
    let p = progress;
    // Early stream: prefer filling bins tightly (low post_residual); later: tolerate slack.
    let coupling = 12.0 * x * x * (1.0 - p) - 8.0 * x * p * p + 4.0 * x * x * x * p;
    score += coupling;

    // Penalize near-full waste that leaves unusable slivers, scaled by progress.
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * (0.5 + p);
    }

    // Last-chance bonus: only bin that fits -> reward strongly, more so early.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - p);
    }

    // Prefer bins with residual below mean (denser bins), smooth term.
    score += 0.3 * (mean_residual - pr);

    // Lookahead: favor leaving room for the next item, smoothly damped.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = if pr >= nx { 1.0 } else { 0.0 };
        score -= fit_next * 6.0 * (1.0 - p) * (pr - nx) / cap;
    }

    // Mild penalty on opening new bins when many bins are open and item fits.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 5.0 + 3.0 * p;
    }

    score
}

