            if (headroom as f64 - mean_residual) . abs () <= 1.0 && fitting_bins_count <= 3 {
                score -= 5.0 * (1.0 - progress) ;
            }
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0 ;
        }
        if next_item_size > 1 && post_residual > next_item_size + 1 && post_residual <= next_item_size + 10 {
            score -= 4.0 * (1.0 - progress) ;
        }
        // post_residual fraction of capacity — penalize mid-range waste
        let post_frac = post_residual as f64 / bin_capacity as f64 ;
        if post_frac > 0.5 && post_frac < 0.9 && next_item_size > 0 && post_residual > next_item_size {
            score -= 8.0 * (post_frac - 0.5) ;
        }
        // NEW: prefer bins whose post_residual stays above mean residual (reusable)
        if next_item_size > 0 && post_residual as f64 >= mean_residual + 2.0 && post_residual <= bin_capacity / 2 {
            score -= 3.0 * (1.0 - progress) ;
        }
    }
    // NEW-BIN CANDIDATE
    if bin_residual == bin_capacity {
        let big_next = next_item_size as f64 / bin_capacity as f64 ;
        score += 180.0 - 60.0 * progress + 0.15 * open_bins_count as f64 - 25.0 * big_next . max (0.0) ;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0 ;
        }
        if open_bins_count <= 4 && progress < 0.3 {
            score += 25.0 ;
        }
        if mean_residual < 15.0 && progress > 0.5 {
            score -= 15.0 ;
        }
        let item_frac = item_size as f64 / bin_capacity as f64 ;
        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3 ;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3 ;
        }
        let fresh_left = bin_capacity - item_size ;
        if next_item_size > 0 && fresh_left == next_item_size {
            score -= 30.0 ;
        }
        if open_bins_count > 6 && mean_residual > 0.4 * bin_capacity as f64 {
            score += 20.0 ;
        }
        if next_item_size > 0 && fresh_left < next_item_size && fresh_left < 8 {
            score += 35.0 ;
        }
        if next_item_size > 0 && fitting_bins_count <= 2 && mean_residual < next_item_size as f64 {
            score -= 18.0 * (1.0 - progress) ;
        }
        if open_bins_count > 8 && mean_residual > next_item_size as f64 + 10.0 {
            score += 12.0 ;
        }
        if item_frac > 0.6 && next_item_size > 0 && fresh_left >= next_item_size {
            score -= 8.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size ;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress) ;
            }
        }
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        // fresh-bin dead-space ratio — leftover that nothing can use
        if next_item_size > 0 && fresh_left < next_item_size {
            let fresh_dead = fresh_left as f64 / bin_capacity as f64 ;
            score += 40.0 * fresh_dead * (1.0 - progress) ;
        }
        // NEW: stronger guard against opening fresh bins when a good open home exists
        if next_item_size > 0 && post_residual >= next_item_size && post_residual as f64 >= mean_residual {
            score += 10.0 * (1.0 - progress) ;
        }
        // NEW: fresh bin attractive only if leftover is near-perfect closure
        if next_item_size > 0 && fresh_left > next_item_size + 6 && (fresh_left as f64) < mean_residual {
            score += 8.0 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is always best.
    if post_residual == 0 {
        return -1000.0;
    }

    // Harmonic class of the leftover: capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // in (0,1)

    // Reward leftovers that match common harmonic slots (1/2, 1/3, 1/4, 3/4, 2/3).
    let harmonic_targets = [0.25f64, 1.0 / 3.0, 0.5, 2.0 / 3.0, 0.75];
    let mut h_bonus = 0.0;
    for (i, &t) in harmonic_targets.iter().enumerate() {
        let d = (frac - t).abs();
        if d < 0.02 {
            h_bonus += 12.0 - (i as f64) * 1.5;
        }
    }
    score -= h_bonus;

    // Modulo arithmetic on post_residual: multiples of 10 and 5 are "clean" slots.
    let pr_u = post_residual;
    if pr_u % 10 == 0 {
        score -= 4.0;
    } else if pr_u % 5 == 0 {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // Lookahead coupling: does the leftover accommodate the next item?
    if next_item_size > 0 {
        if next_item_size <= pr_u {
            // Next item fits exactly or nearly: strong reward.
            let slack = (pr_u - next_item_size) as f64;
            if slack == 0.0 {
                score -= 30.0;
            } else if slack <= 10 {
                score -= 15.0;
            } else {
                score -= 5.0;
            }
        } else {
            // Leftover too small for next item: penalize proportionally to waste.
            score += (next_item_size - pr_u) as f64 * 0.3;
        }
    }

    // Integer division threshold classes on post_residual.
    let class = pr_u / 10; // 0..10 harmonic class
    match class {
        0 => score += 10.0,          // tiny dead space, nearly full bin: good
        1 | 2 => score -= 3.0,       // 10-29: usable small slot
        3 | 4 => score -= 6.0,       // 30-49: mid slot
        5 | 6 => score -= 4.0,       // 50-69
        _ => score += 1.0,           // large leftover: keep for bigger items
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.1;
        // But if item is huge and nothing fits well elsewhere, new bin is fine.
        if item_size >= bin_capacity * 3 / 4 {
            score -= 20.0;
        }
    }

    // Slight preference to fill older bins when many are open (load balancing).
    score += (open_bins_count as f64) * 0.05;

    // Progress-aware tightening: later in the stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * (0.05 + 0.1 * progress) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    if post_residual > 0 {
        if next_item_size > 0 {
            if next_item_size == post_residual {
                // perfect two-step chain: strong reward, slightly stronger early
                score -= 900.0 - 30.0 * progress;
            } else if post_residual >= next_item_size {
                let two_step_waste = (post_residual - next_item_size) as f64;
                if two_step_waste == 0.0 {
                    score -= 700.0;
                } else if two_step_waste >= 10.0 {
                    score -= 300.0 - 2.0 * two_step_waste;
                } else {
                    score -= 80.0 + 1.5 * (10.0 - two_step_waste);
                }
                // cushion: comfortable slack for the next item
                if post_residual >= next_item_size + 3 {
                    let cushion = (post_residual - next_item_size) as f64;
                    score -= (2.0 + 2.0 * progress) * cushion.min(15.0);
                }
                // multi-pack: leftover after next item still fits next_item again
                let after_next = post_residual - next_item_size;
                if next_item_size > 1 && after_next >= next_item_size {
                    score -= 6.0 + 0.2 * (after_next / next_item_size) as f64;
                    if after_next % next_item_size == 0 {
                        score -= 8.0 * (1.0 - progress);
                    }
                }
                // leftover after next item stays small and usable
                if after_next <= 12 && mean_residual >= after_next as f64 {
                    score -= 22.0 - 0.8 * after_next as f64;
                }
                // near-seal sliver after next item
                if after_next < next_item_size && after_next <= 3 {
                    score -= 14.0 * (1.0 - progress);
                }
                // leftover matches mean residual shape: reusable home
                if (after_next as f64 - mean_residual).abs() <= 4.0 {
                    score -= 6.0 * (1.0 - progress);
                }
            } else {
                // next item will NOT fit: dead space risk, scaled by near-miss
                let miss = (next_item_size - post_residual) as f64;
                score += 40.0 * miss;
                if miss <= 3.0 {
                    score += 8.0 * (4.0 - miss) * (1.0 - progress);
                }
                // near-miss with only one other fitting bin: keep it alive
                if miss <= 6.0 && fitting_bins_count <= 2 {
                    score -= 5.0;
                }
                // near-miss that seals the bin exactly on a later small item
                if miss <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
                if post_residual < 25 {
                    score += 15.0;
                }
                // strand-space guard just under common small sizes
                if post_residual >= 8 && post_residual <= 16 {
                    score += 10.0 * (1.0 - progress);
                }
                // near-miss whose gap matches mean residual shape — dead space
                if miss > 3.0 && miss <= mean_residual * 0.5 {
                    score += 4.0 * (1.0 - progress);
                }
            }
        }

        // Compare post residual to mean residual: consuming efficiently.
        score -= 0.6 * (mean_residual - post_residual as f64);

        // dead-gap penalty with scarcity scaling
        let gap = (post_residual as f64 - item_size as f64).max(0.0);
        let gap_ratio = gap / (item_size as f64).max(1.0);
        if gap > 0.0 {
            let scarcity = if fitting_bins_count <= 2 { 0.6 } else if fitting_bins_count <= 4 { 0.3 } else { 0.2 };
            score += scarcity * gap + 18.0 * gap_ratio.min(2.0);
            if gap < mean_residual {
                let fillable = next_item_size > 0 && gap >= next_item_size as f64;
                let w = if fillable { 0.2 } else { 0.6 };
                score += w * (mean_residual - gap);
            }
            if next_item_size > 0 && (gap as u32) == next_item_size {
                score -= 20.0;
            }
            if next_item_size > 1 && (gap as u32) == 2 * next_item_size {
                score -= 12.0;
            }
        }

        // fill ratio reward
        let fill = item_size as f64 / (bin_residual as f64).max(1.0);
        score -= 20.0 * fill;

        // dead space: unusable residual relative to next item
        if next_item_size > 0 && post_residual < next_item_size {
            let dead_frac = post_residual as f64 / bin_capacity as f64;
            let unusable_ratio = post_residual as f64 / (next_item_size as f64).max(1.0);
            score += 0.4 * post_residual as f64 + 30.0 * dead_frac + 12.0 * (1.0 - unusable_ratio);
            if next_item_size - post_residual <= 4 {
                score += 20.0 * (1.0 - progress);
            }
        }

        // anti-fragmentation guard: prefer the tighter of two candidates
        if fitting_bins_count == 2 && post_residual < bin_capacity / 3 {
            score -= 8.0;
        }

        // tiny unusable slivers when bins are plentiful
        if post_residual <= 5 && open_bins_count > 6 {
            score += 25.0 * (1.0 - progress);
        }

        // mid-sized future homes
        if post_residual >= bin_capacity / 8 && post_residual <= bin_capacity / 2 {
            score -= 6.0;
        }

        // residual that can absorb two more average items
        if post_residual as f64 >= 2.0 * mean_residual && post_residual > 20 {
            score -= 5.0;
        }

        // compaction sweet spot: headroom matches mean residual
        if next_item_size > 0 && post_residual > next_item_size {
            let headroom = post_residual - next_item_size;
            if (headroom as f64 - mean_residual).abs() <= 3.0 {
                score -= 7.0;
            }
            if (headroom as f64 - mean_residual).abs() <= 1.0 && fitting_bins_count <= 3 {
                score -= 5.0 * (1.0 - progress);
            }
        }

        // three-way closure: residual hosts next item then seals exactly
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0;
        }

        // residual that fits next item plus a small item is doubly useful
        if next_item_size > 1 && post_residual > next_item_size + 1 && post_residual <= next_item_size + 10 {
            score -= 4.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: only bin that fits, strongly prefer over new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // NEW-BIN CANDIDATE
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let big_next = next_item_size as f64 / bin_capacity as f64;
        score += 180.0 - 60.0 * progress + 0.15 * open_bins_count as f64 - 25.0 * big_next.max(0.0);
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
        if open_bins_count <= 4 && progress < 0.3 {
            score += 25.0;
        }
        if mean_residual < 15.0 && progress > 0.5 {
            score -= 15.0;
        }
        let item_frac = item_size as f64 / bin_capacity as f64;
        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3;
        }
        // fresh bin whose leftover exactly fits the next item
        let fresh_left = bin_capacity - item_size;
        if next_item_size > 0 && fresh_left == next_item_size {
            score -= 30.0;
        }
        // fresh-bin leftover sliver is wasteful
        if next_item_size > 0 && fresh_left < next_item_size && fresh_left < 8 {
            score += 35.0;
        }
        // prefer fresh bin when all existing residuals are too small for next item
        if next_item_size > 0 && fitting_bins_count <= 2 && mean_residual < next_item_size as f64 {
            score -= 18.0 * (1.0 - progress);
        }
        // fresh bin justified when leftover can host next item plus mean slack
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress);
        }
        // discourage opening fresh bins late when many half-empty bins exist
        if open_bins_count > 8 && mean_residual > next_item_size as f64 + 10.0 {
            score += 12.0;
        }
        // large items into fresh bins leave big usable leftovers: mild reward
        if item_frac > 0.6 && next_item_size > 0 && fresh_left >= next_item_size {
            score -= 8.0 * (1.0 - progress);
        }
        // near-zero tail after next item (perfect closure)
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress);
            }
        }
        // fresh bin leftover below mean residual is likely dead space
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0;
        }
        // chain home: leftover hosts next item twice exactly
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0;
        }
        // near-exact fill wastes nothing and preserves all open residuals
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress);
        }
        // fresh bin leftover matching mean residual — reusable home shape
        if next_item_size > 0 && (fresh_left as f64 - mean_residual).abs() <= 2.0 {
            score -= 8.0;
        }
        // chain home: leftover hosts next item multiple times exactly
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress);
        }
        // fresh bin leftover that hosts next item plus mean-shaped slack
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual).abs() <= 3.0 {
            score -= 9.0 * (1.0 - progress);
        }
        // avoid opening fresh bins when a fitting open bin nearly seals with this item
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0;
        }
    }

    score
}

