        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    }

    // Reward filling bins tightly relative to capacity
    let fill = (item_size as f64) / (bin_capacity as f64);
    score -= 30.0 * fill;

    // Open-bin pressure: discourage spreading across many bins
    score += 4.0 * (open_bins_count as f64).sqrt();

    // Dead-space relative to mean residual of open bins
    score += 0.3 * ((post_residual as f64) - mean_residual).abs();

    // Lookahead: favor bins whose leftover can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else if post_residual > 0 {
            score += 15.0; // leftover unusable for next item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: neutral-ish baseline, cheaper when few bins open
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * (open_bins_count as f64);
    }

    // Stream progression: tighten packing as stream advances
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    score -= 10.0 * progress * fill;

    score
}

