        }
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        // fresh-bin dead-space ratio — leftover that nothing can use
        if next_item_size > 0 && fresh_left < next_item_size {
            let fresh_dead = fresh_left as f64 / bin_capacity as f64 ;
            score += 40.0 * fresh_dead * (1.0 - progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual_frac = post / cap;
    let mut score = post;

    // Non-linear waste penalty: small post-residuals are valuable, huge ones wasteful.
    score += 40.0 * residual_frac * residual_frac * (1.0 + progress);

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: reward if next item fits the post-residual smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (post_residual >= next_item_size) as f64;
        let snug = (nxt / cap - residual_frac).abs();
        score -= 25.0 * fits_next * (1.0 - snug);
        score += 10.0 * (1.0 - fits_next) * residual_frac;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 40.0 * (1.0 - residual_frac);
    }

    // New-bin candidate: open a fresh bin when current fits are poor/tight,
    // or when many bins are open and mean residual is high (fragmentation).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap - residual_frac).abs();
        score = cap - 15.0
            - 20.0 * (fitting_bins_count as f64).ln().max(0.0)
            - 15.0 * fragmentation
            - 20.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Mild penalty for spreading across many open bins late in the stream.
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

