pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host even the
    // smallest possible item (size 1) are pure waste; residuals below a "useful"
    // threshold are heavily penalized with a quadratic term.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * (dead_threshold - post_residual as f64) * 3.0;
    } else {
        score -= 30.0; // bonus for keeping the bin reusable
    }

    // Penalize unusable dead space relative to the lookahead item: if the next
    // item cannot fit into the post_residual, this gap is likely wasted.
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += waste * 1.5;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0; // reward leaving room for the lookahead item
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading items thin.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += pressure * 2.0;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate: make an empty bin moderately attractive only when
    // no open bin offers a tight fit; otherwise discourage spreading.
    if bin_residual == bin_capacity {
        let tightness = (post_residual as f64) + item_size as f64;
        score += 25.0 + tightness * 0.1;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, new bin is fine
        }
    }

    // Tight-fit reward: post_residual close to zero (but nonzero) is ideal.
    if post_residual > 0 && post_residual <= 5 {
        score -= 20.0;
    }

    // Mild coupling with mean residual: prefer bins whose residual is below
    // average (they are more filled), keeping the bin pool balanced.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    score
}

