    let mut score = post_residual as f64;

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // reward closeness of next item to post_residual (tight chaining)
            let gap = post_residual as f64 - next_item_size as f64;
            score -= 120.0 - 0.8 * gap;
        } else {
            // penalty if next item cannot fit in the leftover
            let miss = next_item_size as f64 - post_residual as f64;
            score += 0.9 * miss;
        }
        // bonus if next item fits exactly
        if next_item_size == post_residual {
            score -= 200.0;
        }
    }

    // Compare post_residual against mean residual across open bins
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin, less so late in stream or when many bins open
    if bin_residual == bin_capacity {
        score += 90.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
    }

    // Mild preference for keeping residuals small relative to typical item sizes
    score += 0.15 * post_residual as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

