pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic in post-residual, modulated by stream progress.
    let mut score = pr * (1.0 + 0.5 * norm_pr * progress);

    // Smooth non-linear coupling: penalize residual that is "awkward" (mid-range dead space)
    // using a smooth bump centered around half-capacity, scaled by progress.
    let bump = norm_pr * (1.0 - norm_pr) * 4.0; // peaks at 0.5, smooth, zero at edges
    score += 12.0 * bump * (0.5 + progress);

    // Reward tight fits: subtract when post_residual is small relative to item size.
    let tightness = 1.0 - pr / (item_size as f64 + pr + 1.0);
    score -= 8.0 * tightness * tightness;

    // Lookahead: reward leaving room for the next item (smooth kernel).
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let diff = (pr - ns) / cap;
        score -= 6.0 * (-diff * diff * 8.0).exp();
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild pressure toward consolidation when many bins are open.
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // Prefer bins with residual above the mean (keeps small bins for small items).
    score += 0.3 * (pr - mean_residual);

    score
}

