pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in [1..9] is nearly unusable
    // (items >= 10), so penalize small nonzero residuals heavily; zero is perfect.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fit reward
    } else {
        let class = pr % 10; // harmonic decile class
        if pr < 10 {
            score += 25.0; // unusable dead space
        } else if class == 0 {
            score -= 8.0; // residual is a multiple of 10: reusable by any item
        } else if class <= 5 {
            score += 3.0; // partially awkward class
        }
        // Integer-division threshold: can residual host the lookahead item?
        if next_item_size > 0 && pr >= next_item_size {
            score -= 6.0 + (next_item_size as f64) * 0.05;
        } else if next_item_size > 0 {
            score += 5.0;
        }
    }

    // Capacity-fraction coupling: reward filling a bin past 50%, extra past 75%.
    let fill = 1.0 - (post_residual as f64) / cap;
    if fill >= 0.75 { score -= 10.0; }
    else if fill >= 0.5 { score -= 5.0; }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: make it unattractive unless all else is bad.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64;
    }

    // Mild pressure to consolidate when many bins are open.
    score += mean_residual * 0.05;

    // Late-stream tightening: prefer tight fits as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (bin_residual as f64 - item_size as f64) * 0.02 * progress;

    score
}

