        if next_item_size > 0 && fresh_left < next_item_size && progress > 0.6 {
            score += 20.0 ;
        }
        // NEW: fresh bin is attractive when leftover exceeds next item by a reusable margin
        if next_item_size > 0 && fresh_left >= next_item_size + 15 && open_bins_count <= 5 {
            score -= 6.0 * (1.0 - progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..100
    // interface, but typical small items ~10) are nearly worthless.
    let dead_threshold: f64 = 10.0;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        score += 60.0 * (dead_threshold - pr) / dead_threshold;
    } else if pr == 0.0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to what the bin had.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Open-bin pressure: discourage spreading across too many bins,
    // but only mildly so a new empty bin remains viable for good fits.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Post-residual too small for next item: penalize unusable gap.
            score += 8.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably
    // (tighter than average gets a small reward).
    score += 0.15 * (mean_residual - post_residual as f64);

    // Early in the stream, be slightly more willing to open fresh bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * (1.0 - progress);

    score
}

