        // near-exact fill wastes nothing and preserves all open residuals
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        // fresh bin leftover matching mean residual — reusable home shape
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        // chain home: leftover hosts next item multiple times exactly
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        // fresh bin leftover that hosts next item plus mean-shaped slack
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        // avoid opening fresh bins when a fitting open bin nearly seals with this item
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        // NEW: fresh-bin leftover that hosts next item twice-plus-mean is a rich home
        if next_item_size > 1 && fresh_left as f64 >= 2.0 * next_item_size as f64 + mean_residual {
            score -= 7.0 * (1.0 - progress) ;
        }
        // NEW: penalize fresh bins whose leftover is a dead sliver relative to mean
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < 0.4 * mean_residual {
            score += 12.0 * (1.0 - progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 6.0 * fill_frac * fill_frac;

    // Penalize leaving dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 4.0; // near-perfect closure
    } else if post_residual >= 10 && post_residual < 50 {
        // dead-space zone: worse the more unusable relative to mean residual
        score += 0.35 * (50.0 - post_residual as f64).max(0.0);
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this bin's remainder: slight penalty
            score += 1.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Global state: with many open bins, consolidate (favor bins below mean residual).
    if open_bins_count > 1 {
        let dev = mean_residual - bin_residual as f64;
        score -= 0.25 * dev;
        // mild consolidation pressure scaled by stream progress
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 2.0 * progress * (1.0 - fill_frac);
    }

    // New-bin candidate handling: opening a new bin is costly unless current fit is bad
    // or the lookahead suggests a dedicated bin is useful.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > 0.6 * bin_capacity as f64 && next_item_size > post_residual as u32;
        let mut penalty = 8.0;
        if bad_fit { penalty -= 6.0; }
        if fitting_bins_count == 0 { penalty -= 8.0; }
        if next_item_size > 0 && next_item_size >= item_size && next_item_size <= bin_capacity {
            penalty -= 1.0;
        }
        score += penalty;
    }

    // Mild noise-free exploration term tied to step parity of residual classes.
    let band = (bin_residual / 20) as f64;
    score += 0.15 * band * (1.0 - fill_frac);

    score
}

