    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mild pressure to balance residuals across many open bins.
    score += 0.05 * (mean_residual - post_residual as f64).abs() * (open_bins_count as f64).ln().max(1.0);

    // Smooth non-linear stream-progress coupling: waste tolerance shrinks over time.
    score *= 1.0 + 0.5 * progress * pr;

    score
}

