        // should not burn reusable space on poor fits
        if post_residual as f64 > 1.5 * mean_residual && progress < 0.4 && fitting_bins_count <= 3 {
            score -= 4.0 ;
        }
    }
    // NEW-BIN CANDIDATE
    if bin_residual == bin_capacity {
        let big_next = next_item_size as f64 / bin_capacity as f64 ;
        score += 180.0 - 60.0 * progress + 0.15 * open_bins_count as f64 - 25.0 * big_next . max (0.0) ;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0 ;
        }
        if open_bins_count <= 4 && progress < 0.3 {
            score += 25.0 ;
        }
        if mean_residual < 15.0 && progress > 0.5 {
            score -= 15.0 ;
        }
        let item_frac = item_size as f64 / bin_capacity as f64 ;
        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3 ;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3 ;
        }
        let fresh_left = bin_capacity - item_size ;
        if next_item_size > 0 && fresh_left == next_item_size {
            score -= 30.0 ;
        }
        if open_bins_count > 6 && mean_residual > 0.4 * bin_capacity as f64 {
            score += 20.0 ;
        }
        // fresh-bin leftover sliver is wasteful
        if next_item_size > 0 && fresh_left < next_item_size && fresh_left < 8 {
            score += 35.0 ;
        }
        // prefer fresh bin when all existing residuals are too small for next item
        if next_item_size > 0 && fitting_bins_count <= 2 && mean_residual < next_item_size as f64 {
            score -= 18.0 * (1.0 - progress) ;
        }
        // discourage opening fresh bins late when many half-empty bins exist
        if open_bins_count > 8 && mean_residual > next_item_size as f64 + 10.0 {
            score += 12.0 ;
        }
        // large items into fresh bins leave big usable leftovers: mild reward
        if item_frac > 0.6 && next_item_size > 0 && fresh_left >= next_item_size {
            score -= 8.0 * (1.0 - progress) ;
        }
        // fresh bin justified when leftover can host next item plus mean slack
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress) ;
        }
        // near-zero tail after next item (perfect closure)
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size ;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress) ;
            }
        }
        // fresh bin leftover below mean residual is likely dead space
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        // chain home: leftover hosts next item twice exactly
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        // near-exact fill wastes nothing and preserves all open residuals
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        // fresh bin leftover matching mean residual — reusable home shape
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        // chain home: leftover hosts next item multiple times exactly
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        // fresh bin leftover that hosts next item plus mean-shaped slack
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        // avoid opening fresh bins when a fitting open bin nearly seals with this item
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        // NEW: opening a fresh bin is more attractive when the current item is
        // large and the fresh leftover would be a mean-shaped reusable home
        if next_item_size > 0 && item_frac > 0.5 && (fresh_left as f64 - mean_residual) . abs () <= 4.0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        // NEW: penalize fresh bins late in the stream when fitting bins exist
        if progress > 0.75 && fitting_bins_count >= 1 {
            score += 10.0 * (progress - 0.75) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual in (0,10] is nearly dead space.
    let dead = if post_residual == 0 {
        -50.0 // perfect fit: huge reward
    } else if post_residual <= 5 {
        30.0
    } else if post_residual <= 10 {
        18.0
    } else if post_residual <= 20 {
        8.0
    } else if post_residual <= 30 {
        0.0
    } else {
        -3.0
    };
    score += dead;

    // Integer-division class: residual divisible into chunks of common small items
    let class = post_residual / 10;
    score -= (class as f64) * 1.5;

    // Lookahead: reward if next item fits the post residual exactly or well
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 25.0;
        } else if gap <= 10 {
            score -= 10.0;
        } else {
            score -= 3.0;
        }
    } else if next_item_size > post_residual {
        // next item cannot use leftover; penalize small leftovers more
        if post_residual < 20 {
            score += 12.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer fuller bins when many bins are open
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 10.0;

    // Mild pressure toward consolidation when open bin count is high
    score += (open_bins_count as f64) * 0.3;

    // Progress-based: later in the stream, be more conservative with dead space
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += dead * progress * 0.5;

    // New-bin candidate: only attractive when current fit is bad
    if bin_residual == bin_capacity {
        let bad_fit = if post_residual > 0 && post_residual <= 10 { 1.0 } else { 0.0 };
        score = 45.0 + bad_fit * 0.0 - (fitting_bins_count as f64) * 0.0;
