        if fitting_bins_count >= 1 && (bin_capacity - item_size) >= 0 {
            // prefer existing bins unless their post residual is tiny (dead space)
            score += 5.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 2.0;
        }
    }

    score
}

