        if progress > 0.75 && item_frac < 0.5 {
            score += 10.0 * (progress - 0.75) / 0.25 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: small post_residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 50.0 * tightness * tightness;

    // 2-step lookahead: reward if next item exactly fits post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it fills remainder
            let fill_after_next = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 150.0 * (1.0 - fill_after_next);
        } else {
            // next item cannot use the remainder: penalize dead space
            score += 30.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual against mean residual across open bins
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        score += 120.0;
        if fitting_bins_count > 0 {
            let best_possible = mean_residual.min(bin_capacity as f64);
            if best_possible >= item_size as f64 + 5.0 {
                score += 150.0;
