        // Early in stream, slightly prefer consolidating into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 50.0 * (1.0 - progress);
    }

    // Mild preference to fill already-open bins to reduce bin count
    score += 0.3 * open_bins_count as f64;

    score
}

