pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness: super-linear reward for small leftover space.
    score += (post_residual as f64 / cap).powi(3) * 30.0;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead: chainability — leftover space that exactly hosts the next item is gold.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / cap);
    } else if next_item_size > 0 {
        // Dead space the next item cannot use: penalize proportionally to how stranded it is.
        let dead = post_residual as f64;
        if dead > 0.0 {
            score += 2.0 * (dead / cap) * (dead / next_item_size as f64).min(3.0);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, scaled by stream progress.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 + 10.0 * progress;
    }

    // Crowding: when many bins are open, consolidate into existing ones.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Relative waste vs. fleet mean residual.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // New empty-bin candidate: baseline handicap so it only wins when fits are truly bad.
    if bin_residual == bin_capacity {
        score += 45.0 + 0.1 * (item_size as f64);
        // Late in the stream, opening fresh bins is slightly more acceptable.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
    }

    score
}

