        if progress > 0.85 && mean_residual >= 8.0 {
            score += 20.0 * (progress - 0.85) / 0.15 ;
        }
        // fresh bin that leaves a leftover matching the mean residual shape is a good home
        if next_item_size > 0 && fresh_left as f64 >= mean_residual + next_item_size as f64 {
            score -= 5.0 * (1.0 - progress) ;
        }
    }
    score
}

