pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = (1.0 - progress) * norm_pr * norm_pr + progress * (1.0 - norm_pr) * (1.0 - norm_pr);
    score += 12.0 * poly;

    // Reward tight fits, stronger as stream progresses
    let fit = 1.0 - norm_pr;
    score -= 18.0 * fit * fit * (0.5 + 0.5 * progress);

    // Penalize waste relative to mean residual of open bins
    score += 0.15 * (pr - mean_residual).abs();

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // Slight penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: make it moderately attractive only when fit is poor
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
