pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 buckets; small residuals are dead space.
    let class = post_residual % 10;
    if class != 0 {
        score += (10 - class) as f64 * 0.8; // penalize non-aligned leftover
    }
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    }

    // Integer division thresholds: residual divided into quarters of capacity
    let quarter = bin_capacity / 4;
    if post_residual < quarter {
        score -= 10.0; // tight fit is good
    } else if post_residual < 2 * quarter {
        score += 2.0;
    } else {
        score += 8.0; // leaving a big chunk means poor packing
    }

    // Lookahead coupling: can next item exactly fill post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain fill
        } else if next_item_size <= post_residual {
            score -= 12.0;
            // modulo harmony between next item and residual
            if post_residual % next_item_size == 0 {
                score -= 6.0;
            }
        } else {
            // next item can't use this residual anyway
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: mildly discourage opening new bins unless residual is wasted
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = mean_residual - item_size as f64;
        score = cap * 0.9 + waste * 0.3 + progress * 5.0
            - if next_item_size > 0 && post_residual >= next_item_size { 15.0 } else { 0.0 };
    }

    // Many open bins: prefer consolidating into existing ones
    score += open_bins_count as f64 * 0.05;

    score
}

