pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly accommodates the next item (chain packing).
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += lookahead_gap * 0.9;

        // Exact 2-step chain: this bin becomes perfectly reusable
        if post_residual == next_item_size {
            score -= 400.0;
        }

        // Pair efficiency: item + next item fill the bin nearly exactly
        let pair_sum = item_size as u32 + next_item_size;
        if pair_sum <= bin_residual {
            let pair_waste = bin_residual - pair_sum;
            if pair_waste <= 2 {
                score -= 250.0;
            }
            score -= (bin_capacity as f64 - pair_waste as f64) * 0.1;
        } else {
            // Next item cannot follow into this bin; penalize mildly
            score += 15.0;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.6;

    // Penalize large dead space unusable by typical items (min size 1..100 range)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny sliver waste
    }
    if post_residual >= 80 {
        score -= 30.0; // large residual stays flexible
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin
    // offers a good fit (post_residual small or exact chain).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 50.0;
        // Discourage new bin if item is small relative to capacity (fits well elsewhere)
        score += (item_size as f64 / bin_capacity as f64) * 40.0;
