            let headroom = post_residual - next_item_size ;
            if (headroom as f64 - mean_residual) . abs () <= 3.0 {
                score -= 7.0 ;
            }
            // self-renewing home shape with scarcity
            if (headroom as f64 - mean_residual) . abs () <= 1.0 && fitting_bins_count <= 3 {
                score -= 5.0 * (1.0 - progress) ;
            }
        }
        // three-way closure: residual hosts next item then seals exactly
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0 ;
        }
        // residual that fits next item plus a small item is doubly useful
        if next_item_size > 1 && post_residual > next_item_size + 1 && post_residual <= next_item_size + 10 {
            score -= 4.0 * (1.0 - progress) ;
        }
        // exact-fit scarcity bonus: sealing a scarce bin is doubly valuable
        if post_residual == 0 && fitting_bins_count <= 2 {
            score -= 60.0 * (1.0 - progress) ;
        }
    }
    // NEW-BIN CANDIDATE
    if bin_residual == bin_capacity {
        let big_next = next_item_size as f64 / bin_capacity as f64 ;
        score += 180.0 - 60.0 * progress + 0.15 * open_bins_count as f64 - 25.0 * big_next . max (0.0) ;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0 ;
        }
        if open_bins_count <= 4 && progress < 0.3 {
            score += 25.0 ;
        }
        if mean_residual < 15.0 && progress > 0.5 {
            score -= 15.0 ;
        }
        let item_frac = item_size as f64 / bin_capacity as f64 ;
        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3 ;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3 ;
        }
        let fresh_left = bin_capacity - item_size ;
        if next_item_size > 0 && fresh_left == next_item_size {
            score -= 30.0 ;
        }
        if open_bins_count > 6 && mean_residual > 0.4 * bin_capacity as f64 {
            score += 20.0 ;
        }
        // fresh-bin leftover sliver is wasteful
        if next_item_size > 0 && fresh_left < next_item_size && fresh_left < 8 {
            score += 35.0 ;
        }
        // prefer fresh bin when all existing residuals are too small for next item
        if next_item_size > 0 && fitting_bins_count <= 2 && mean_residual < next_item_size as f64 {
            score -= 18.0 * (1.0 - progress) ;
        }
        // discourage opening fresh bins late when many half-empty bins exist
        if open_bins_count > 8 && mean_residual > next_item_size as f64 + 10.0 {
            score += 12.0 ;
        }
        // large items into fresh bins leave big usable leftovers: mild reward
        if item_frac > 0.6 && next_item_size > 0 && fresh_left >= next_item_size {
            score -= 8.0 * (1.0 - progress) ;
        }
        // fresh bin justified when leftover can host next item plus mean slack
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress) ;
        }
        // near-zero tail after next item (perfect closure)
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size ;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress) ;
            }
        }
        // fresh bin leftover below mean residual is likely dead space
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        // chain home: leftover hosts next item twice exactly
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        // near-exact fill wastes nothing and preserves all open residuals
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        // fresh bin leftover matching mean residual — reusable home shape
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        // chain home: leftover hosts next item multiple times exactly
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        // fresh bin leftover that hosts next item plus mean-shaped slack
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        // avoid opening fresh bins when a fitting open bin nearly seals with this item
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        // fresh bin is bad when item would leave a strand just under next item size
        if next_item_size > 0 && fresh_left >= next_item_size - 6 && fresh_left < next_item_size {
            score += 18.0 * (1.0 - progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 3.0 * fit_ratio * fit_ratio;

    // Strongly reward near-perfect fills.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize dead space that no future item (min size 1) can use efficiently.
    if post_residual > 50 {
        score += 8.0;
    } else if post_residual > 30 {
        score += 3.0;
    }

    // Lookahead (k=2): reward leaving exactly enough room for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // Room for next item: mild reward, scaled by tightness for it.
            let next_tight = next_item_size as f64 / post_residual as f64;
            score -= 6.0 * next_tight;
        } else {
            // Next item won't fit here; slight penalty scaled by how much it misses.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.05 * miss;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // More competing bins -> allow more selectivity: penalize loose fits harder.
    if fitting_bins_count > 1 {
        score += 0.5 * (fitting_bins_count as f64 - 1.0) * (1.0 - fit_ratio);
    }

    // Global state: many open bins with high mean residual -> prefer consolidation
    // into bins below mean residual (tighter bins), to empty them out.
    if open_bins_count > 1 && mean_residual > 0.0 {
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        } else {
            score += 1.5;
        }
    }

    // Time horizon: early in stream, be conservative (keep bins flexible);
    // late in stream, prioritize closing bins out aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * fit_ratio;
    score += 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no open bin fits well
    // (large post_residual waste avoided) or stream is early and flexibility pays.
    if bin_residual == bin_capacity {
        let escape = 10.0 + 0.6 * (open_bins_count as f64);
        // Penalize opening a new bin; the penalty shrinks when item is large
        // (little value lost by starting fresh with a big item).
        score += escape - 0.15 * item_size as f64;
        // Late in the stream, avoid opening bins unless nearly necessary.
        score += 10.0 * progress;
    }

    score
}

