pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let isz = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - pr / cap;

    // Base: prefer small post residual, with a non-linear polynomial coupling
    let mut score = pr
        + 12.0 * (pr / cap) * (pr / cap) * cap
        - 30.0 * fill * fill * fill * isz;

    // Smooth stream-progress coupling: later in stream, penalize waste more
    score += 25.0 * progress * pr * (1.0 - fill);

    // Reward tight fits relative to bin residual (smooth ratio term)
    let fit_ratio = if bin_residual > 0 { isz / br } else { 1.0 };
    score -= 20.0 * fit_ratio * fit_ratio * fit_ratio;

    // Lookahead coupling: penalize if post residual can't host next item (smooth)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = ((pr - nx).abs()) / cap;
        score += 15.0 * (1.0 - gap * gap) * (pr / cap);
    }

    // Last-chance bin: strong smooth reward
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 + fill);
    }

    // Many open bins: mild penalty to avoid sprawl
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Mean residual coupling: prefer bins deviating from mean smoothly
    score += 5.0 * ((pr - mean_residual) / cap) * ((pr - mean_residual) / cap) * cap;

    // New-bin candidate: keep neutral baseline so it only wins when fits are poor
    if bin_residual == bin_capacity {
        score = pr + 8.0 + 10.0 * progress;
    }

    score
}

