            score += 15.0 ;
        }
        // fresh-bin dead-space ratio — leftover that nothing can use
        if next_item_size > 0 && fresh_left < next_item_size {
            let fresh_dead = fresh_left as f64 / bin_capacity as f64 ;
            score += 40.0 * fresh_dead * (1.0 - progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod capacity quantized into bands.
    // Residuals in [0,10) are near-perfect fits; reward strongly.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr <= 20 {
        score -= 8.0;
    } else if pr <= 35 {
        score += 6.0;
    } else if pr <= 50 {
        score += 14.0;
    } else {
        score += 25.0; // large dead space
    }

    // Integer-division threshold: post_residual / item_size ratio —
    // small ratio means bin was nearly filled relative to the item.
    let ratio = post_residual as f64 / (item_size.max(1) as f64);
    score += ratio * 12.0;

    // Coupling with lookahead: does leftover residual match next item's class?
    if next_item_size > 0 {
        let gap = (pr as i64 - next_item_size as i64).abs() as f64;
        // residual exactly accommodating next item is excellent
        if pr >= next_item_size && gap <= 10.0 {
            score -= 18.0;
        } else if gap <= 5.0 {
            score -= 10.0;
        } else {
            score += gap * 0.25;
        }
        // modular harmony: (pr mod 10) close to (next_item_size mod 10)
        let pm = (pr % 10) as i64;
        let nm = (next_item_size % 10) as i64;
        let md = (pm - nm).abs() as f64;
        score -= (10.0 - md) * 0.4;
    } else {
        // last item: fill as much as possible
        score += pr as f64 * 0.1;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize spreading across many open bins when mean residual is already high
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64).abs() * 0.15;
    }

    // New-bin candidate: bin_residual == bin_capacity (post_residual == bin_capacity).
    // Prefer opening a new bin only when all fits would leave big dead space,
    // i.e. when best-fit pressure is low. Give it a mid-range baseline.
    if bin_residual == bin_capacity {
        score = 55.0
            + (open_bins_count as f64) * 1.5
            - if next_item_size > 0 && next_item_size >= pr { 0.0 } else { 5.0 };
        // early in stream, opening bins is cheap
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
    }

    score
}

