        if next_item_size > 0 && fresh_left < next_item_size {
            let fresh_dead = fresh_left as f64 / bin_capacity as f64 ;
            score += 40.0 * fresh_dead * (1.0 - progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item
    // (<= ~10) are pure waste; penalize them super-linearly.
    if post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    } else if post_residual < 20 {
        score += 8.0 * (20 - post_residual) as f64;
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit: strong reward
    } else {
        // Prefer filling large residual bins: low residual before placement is fine,
        // but leaving a big gap is bad -> quadratic penalty on large post_residual.
        score += 0.02 * (post_residual as f64).powi(2);
    }

    // Reward tight fits relative to residual (waste fraction).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * waste_frac;

    // Open-bin pressure: discourage spreading items when many bins are open,
    // unless the fit is excellent.
    score += 0.35 * open_bins_count as f64 * (1.0 - waste_frac);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward this placement (chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // next item cannot use this gap -> gap likely dead space
            score += 6.0;
        }
    }

    // New-bin candidate: opening a new bin is only attractive when no open bin
    // offers a decent fit. Base cost grows with open bins and stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 + 0.5 * open_bins_count as f64 + 10.0 * progress;
        // If many open bins fit the item, opening a new bin is clearly worse.
        if fitting_bins_count > 1 {
            score += 25.0 * (fitting_bins_count as f64 - 1.0);
        }
        // If mean residual across open bins is large, prefer reusing bins.
        if mean_residual > item_size as f64 {
            score += 0.3 * (mean_residual - item_size as f64);
        }
    }

    // Mild tie-break toward bins whose residual is close to mean residual
    // (keeps bin states balanced).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

