pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let post_post = post_residual - next_item_size;
            // Reward leaving a residual that still accommodates the next item well.
            score -= 25.0 * (1.0 - post_post as f64 / bin_capacity as f64);
        } else {
            // Penalize creating dead space that the next item cannot use.
            let dead = post_residual as f64 / next_item_size as f64;
            score += 15.0 * dead.min(1.0);
        }
    }

    // Compare against mean residual: prefer bins with residual close to item (good fill).
    let diff = (bin_residual as f64 - item_size as f64) - mean_residual;
    score += 0.3 * diff;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64 / (total_items.max(1) as f64);
        let poor_fit = if fitting_bins_count == 0 { 0.0 } else {
            let best_gap = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
            best_gap / bin_capacity as f64
        };
        // Penalize opening new bins generally, less when fits are poor.
        score += 55.0 * (1.0 - 0.5 * poor_fit) + 10.0 * open_pressure;
    }

    // Slight preference for fuller bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress) * (item_size as f64 / bin_capacity as f64);

    score
}

