pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early stream -> be greedy about tight fits; late stream -> consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Dead-space penalty: residuals too small for the smallest item are pure waste.
    if post_residual < 1 {
        score += 1000.0;
    }
    // Small-but-usable residuals are valuable; reward near-perfect packing.
    if post_residual > 0 && post_residual <= 5 {
        score -= 8.0 + 4.0 * progress;
    }

    // Lookahead coupling: reward if the next item can also fit in the leftover space.
    if next_item_size > 0 && next_item_size <= post_residual {
        let lookahead_tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 6.0 * lookahead_tightness;
    } else if next_item_size > post_residual {
        // leftover won't host next item: mild penalty proportional to wasted opportunity
        score += 1.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate detection: only open a new bin when the item is large
    // relative to capacity (poor fit candidates everywhere) or many bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let item_ratio = item_size as f64 / bin_capacity as f64;
        let mut new_bin_penalty = 10.0;
        // Large items are fine to start a fresh bin with.
        new_bin_penalty -= 14.0 * item_ratio;
        // Many open bins with slack -> prefer filling them instead.
        new_bin_penalty += (open_bins_count as f64).sqrt() * (mean_residual / bin_capacity as f64).max(0.0) * 4.0;
        // Late in the stream, avoid spawning bins for small leftovers.
        new_bin_penalty += 6.0 * progress * (1.0 - item_ratio);
        score += new_bin_penalty.max(0.5);
    } else {
        // Existing bin: reward bins whose residual is close to item_size (snug fit).
        let snug = 1.0 - ((bin_residual - item_size) as f64 / bin_capacity as f64);
        score -= 5.0 * snug.max(0.0);
        // Prefer bins below mean residual (consolidate emptier space? no — fill fuller bins first).
        if (bin_residual as f64) < mean_residual {
            score += 2.0;
        } else {
            score -= 1.0;
        }
    }

    // Global pressure: when many bins are open, discourage spreading items out.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual (tight fit), non-linearly
    let mut score = norm_pr * norm_pr * 40.0 + norm_pr * 10.0;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap; later, tight packing matters more.
    let coupling = 1.0 + 3.0 * progress * progress + 2.0 * progress;
    score *= coupling;

    // Reward bins whose leftover can plausibly host the lookahead item (smooth kernel)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = pr - nx;
        let k = (-diff * diff / (2.0 * 25.0 * 25.0)).exp();
        score -= 8.0 * k;
    }

    // Last-chance bonus: strongly favor the only fitting bin (smooth, not piecewise)
    let last_chance = 1.0 / (fitting_bins_count as f64);
    score -= 6.0 * last_chance * last_chance;

    // Mild penalty for proliferation of open bins, scaled by progress
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // Deviation from mean residual: prefer bins near the mean (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Perfect-fit reward (smooth exponential kernel on normalized residual)
    score -= 12.0 * (-norm_pr * norm_pr / 0.005).exp();

    score
}

