                }
                // cushion: comfortable slack for the next item
                if post_residual >= next_item_size + 3 {
                    let cushion = (post_residual - next_item_size) as f64 ;
                    score -= (2.0 + 2.0 * progress) * cushion . min (15.0) ;
                }
                let after_next = post_residual - next_item_size ;
                // leftover after next item stays usable
                if after_next <= 12 && mean_residual >= after_next as f64 {
                    score -= 22.0 - 0.8 * after_next as f64 ;
                }
                // leftover can host next item again (chain home)
                if next_item_size > 1 && after_next >= next_item_size {
                    score -= 6.0 + 0.2 * (after_next / next_item_size) as f64 ;
                    if after_next % next_item_size == 0 {
                        score -= 8.0 * (1.0 - progress) ;
                    }
                }
                // near-seal sliver after next item
                if after_next < next_item_size && after_next <= 3 {
                    score -= 14.0 * (1.0 - progress) ;
                }
                // leftover matches mean residual shape: reusable home
                if (after_next as f64 - mean_residual) . abs () <= 4.0 {
                    score -= 6.0 * (1.0 - progress) ;
                }
            } else {
                let miss = next_item_size - post_residual ;
                score += 2.0 * miss as f64 ;
                if post_residual < 25 {
                    score += 15.0 ;
                }
                // near-perfect sealed bins
                if post_residual < 3 {
                    score -= 400.0 ;
                }
                // near-miss with only one other fitting bin: keep it alive
                if miss <= 6 && fitting_bins_count <= 2 {
                    score -= 5.0 ;
                }
                // salvage late in the stream with few alternatives
                if miss <= 10 && fitting_bins_count <= 2 && progress > 0.7 {
                    score -= 10.0 * (1.0 - progress) ;
                }
                // near-miss that seals the bin exactly on a later small item
                if miss <= 2 {
                    score -= 18.0 * (1.0 - progress) ;
                }
                // strand-space guard just under common small sizes
                if post_residual >= 8 && post_residual <= 16 {
                    score += 10.0 * (1.0 - progress) ;
                }
                // near-miss whose gap matches mean residual shape — dead space
                if miss > 3 && miss as f64 <= mean_residual * 0.5 {
                    score += 4.0 * (1.0 - progress) ;
                }
