            }
        }
        // three-way closure: residual hosts next item then seals exactly
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0 ;
        }
        // residual that fits next item plus a small item is doubly useful
        if next_item_size > 1 && post_residual > next_item_size + 1 && post_residual <= next_item_size + 10 {
            score -= 4.0 * (1.0 - progress) ;
        }
    }
    // NEW-BIN CANDIDATE
    if bin_residual == bin_capacity {
        let big_next = next_item_size as f64 / bin_capacity as f64 ;
        score += 180.0 - 60.0 * progress + 0.15 * open_bins_count as f64 - 25.0 * big_next . max (0.0) ;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0 ;
        }
        if open_bins_count <= 4 && progress < 0.3 {
            score += 25.0 ;
        }
        if mean_residual < 15.0 && progress > 0.5 {
            score -= 15.0 ;
        }
        let item_frac = item_size as f64 / bin_capacity as f64 ;
        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3 ;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3 ;
        }
        let fresh_left = bin_capacity - item_size ;
        if next_item_size > 0 && fresh_left == next_item_size {
            score -= 30.0 ;
        }
        if open_bins_count > 6 && mean_residual > 0.4 * bin_capacity as f64 {
            score += 20.0 ;
        }
        // fresh-bin leftover sliver is wasteful
        if next_item_size > 0 && fresh_left < next_item_size && fresh_left < 8 {
            score += 35.0 ;
        }
        // prefer fresh bin when all existing residuals are too small for next item
        if next_item_size > 0 && fitting_bins_count <= 2 && mean_residual < next_item_size as f64 {
            score -= 18.0 * (1.0 - progress) ;
        }
        // discourage opening fresh bins late when many half-empty bins exist
        if open_bins_count > 8 && mean_residual > next_item_size as f64 + 10.0 {
            score += 12.0 ;
        }
        // large items into fresh bins leave big usable leftovers: mild reward
        if item_frac > 0.6 && next_item_size > 0 && fresh_left >= next_item_size {
            score -= 8.0 * (1.0 - progress) ;
        }
        // fresh bin justified when leftover can host next item plus mean slack
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress) ;
        }
        // near-zero tail after next item (perfect closure)
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size ;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress) ;
            }
        }
        // fresh bin leftover below mean residual is likely dead space
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        // chain home: leftover hosts next item twice exactly
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        // near-exact fill wastes nothing and preserves all open residuals
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        // fresh bin leftover matching mean residual — reusable home shape
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        // chain home: leftover hosts next item multiple times exactly
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        // fresh bin leftover that hosts next item plus mean-shaped slack
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        // avoid opening fresh bins when a fitting open bin nearly seals with this item
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "slot band" of the capacity we land in.
    let band = post_residual / 10; // 0..=10 harmonic classes
    // Dead-space penalty grows super-linearly for awkward leftover classes
    // (residuals like 1..9 are nearly unusable for items >= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward landing exactly on a harmonic boundary (perfect fill classes).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual % 10 == 0 {
        score -= 12.0;
    }

    // Coupling with next item: if the next item fits exactly in post_residual,
    // this is a perfect pairing — heavily reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits, but leaves a residue: grade by leftover class.
        let next_left = post_residual - next_item_size;
        score -= 15.0 - (next_left as f64) * 0.5;
        if next_left < 10 {
            score += 10.0; // creates dead space after next item
        }
    } else if next_item_size > 0 {
        // Next item won't fit here regardless; slight penalty for tight bins
        // that become useless after this placement.
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless it creates terrible dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if post_residual < 10 {
            score -= 5.0; // still worth it to avoid a fresh bin
        }
    }

    // New-bin candidate handling: neutral-ish baseline, but attractive when
    // the item is large relative to capacity (big items deserve fresh bins)
    // or when open bins are all crowded.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        if large_item {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0; // fresh bin can host the next item too
        }
        if mean_residual < 15.0 && open_bins_count > 0 && !large_item {
            score += 10.0; // bins are roomy; prefer them
        }
    }

    // Stream progression: late in the stream, waste less; consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64) * 0.3 * progress;

    // Mild penalty when many bins are open but this one is far above mean residual
    // (prefer bins closer to the mean to keep residual distribution tight).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // Harmonic modulo bonus: post_residual sharing a class with next_item_size
    // hints at future fit compatibility.
    if next_item_size > 0 && (post_residual % 20) >= (next_item_size % 20) {
        score -= 3.0;
    }

    score
}

