    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Dead space: gaps too small to hold even the smallest item (1..10)
        if gap < 10.0 {
            score += 60.0 * (10.0 - gap) / 10.0;
        } else if gap < 20.0 {
            // Gaps that only fit tiny items are semi-dead
            score += 25.0 * (20.0 - gap) / 10.0;
        }
    } else {
        // Perfect fit: strong reward
        score -= 40.0;
    }

    // Penalize wasted capacity relative to bin: large post_residual means poor fill
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Open bins pressure: discourage spreading across many bins when few items remain
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 3.0 * pressure * (1.0 - progress);

    // Lookahead: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 35.0;
        } else if (post_residual as i64 - next_item_size as i64).abs() <= 2 {
            score -= 15.0;
        } else if next_item_size as u32 > post_residual {
            // Next item won't fit here anyway; slight penalty for stranding space
            score += 5.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it moderately unattractive unless current fits are bad
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * open_bins_count as f64;
    }

    score
}

