pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward if the next item exactly fills the post-residual (perfect 2-step match)
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 1000.0;
    }
    // Partial reward if next item fits into post-residual, scaled by tightness of fit
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 50.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Penalize post-residual too small for the next item (wasted potential)
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // Penalize creating dead space below the minimum item size (unusable gap)
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 500.0;
    }

    // Compare post-residual against mean residual: leaving less than average is good (tight packing)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: if this is the only fitting bin, prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Slight preference for filling already-open bins as the stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * progress * post_residual as f64;

    // Penalize opening a new bin mildly unless post-residual is very tight
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
