        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.3 {
            score += 18.0 * (1.0 - progress) ;
        }
        // fresh bin strongly justified when zero fitting bins exist for the next item
        if next_item_size > 0 && fitting_bins_count == 0 && fresh_left >= next_item_size {
            score -= 22.0 * (1.0 - progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual too small for any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: reward if the next item fits exactly into the post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0; // perfect chaining
        } else if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 6.0; // next item won't use this leftover
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        let waste = (bin_residual - item_size) as f64;
        if waste <= 20.0 {
            score -= 35.0;
        } else {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // current item would leave a large awkward gap in an existing bin, or when
    // few bins are open early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let gap_penalty = post_residual as f64; // item fills fresh bin perfectly? small residual good
        score = 60.0 + gap_penalty * 0.5 - 20.0 * (1.0 - progress);
        // If item is large, filling a fresh bin is natural.
        score -= (item_size as f64 / bin_capacity as f64) * 25.0;
        // Discard lookahead chaining advantage for fresh bins.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Mild penalty for spreading across too many bins relative to mean residual.
    score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - fit_ratio);

    score
}

