    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling: post_residual weighted by polynomial in progress
    let pr = post_residual as f64;
    let poly = 1.0 + 0.5 * progress - 0.75 * progress * progress + 0.25 * progress * progress * progress;
    score += 0.3 * pr * poly;

