    let fit_ratio = item_size as f64 / bin_capacity as f64;
    let tightness = (1.0 - fit_ratio).exp();
    score -= (1.0 - tightness) * (1.0 + 2.0 * progress);

    // Reward using bins that are the last chance to fit this item
    if fitting_bins_count == 1 {
        score -= 4.0;
    } else if fitting_bins_count > 1 {
        score += 0.1 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize deviating from mean residual (smooth quadratic coupling)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / (bin_capacity as f64);

    // Lookahead: reward leaving space for the next item smoothly
