pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A residual gap is "dead" if it is smaller than the smallest plausible item (1),
    // but practically gaps below ~10 are hard to fill; scale penalty quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual as i32) as f64 * 12.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Exact-fit lookahead: if next item exactly fills the post residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use the leftover: mild penalty proportional to gap.
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

