    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // penalize leftover after next item
            let after_next = post_residual - next_item_size;
            score += after_next as f64 * 0.6;
        } else {
            // next item won't fit here; penalize unusable dead space
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    } else {
        // last item: prefer tightest fit
        score -= 20.0;
    }

    // Penalize dead space relative to mean residual
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.25;

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: costly unless current bin leaves very awkward residue
    if bin_residual == bin_capacity {
        score += 35.0;
        // opening a new bin is attractive if next item fits perfectly in fresh bin
        if next_item_size > 0 && next_item_size == bin_capacity {
            score -= 60.0;
        }
    }

    // Prefer filling bins as stream progresses (fewer open bins better)
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
