pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * tightness * tightness;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 12.0; // small dead space is acceptable
    }

    // Penalize dead space that no realistic item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // unusable sliver (items >= 10... but sizes 1..100 allowed)
        if post_residual < 3 {
            score += 15.0;
        }
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            let chain_tight = (post_residual - next_item_size) as f64;
            score -= 5.0 * (1.0 - chain_tight / bin_capacity as f64);
        } else {
            score += 6.0; // this placement strands the lookahead item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // pairing potential in a fresh bin
            score -= 15.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer bins with below-average residual (consolidate fullness).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Mildly prefer bins that are already heavily loaded.
    let load = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 6.0 * load;

    // Many open bins: encourage filling existing ones rather than spreading.
    score += 0.3 * open_bins_count as f64 * tightness;

    score
}

