        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size ;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress) ;
            }
        }
        // fresh bin leftover below mean residual is likely dead space
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        // chain home: leftover hosts next item twice exactly
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        // near-exact fill wastes nothing and preserves all open residuals
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        // fresh bin leftover matching mean residual — reusable home shape
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        // chain home: leftover hosts next item multiple times exactly
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        // fresh bin leftover that hosts next item plus mean-shaped slack
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        // avoid opening fresh bins when a fitting open bin nearly seals with this item
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        // NEW: fresh bin unjustified when the item would leave a leftover larger than mean
        // residual by a wide margin AND open bins already have mean-shaped homes
        if next_item_size > 0 && fresh_left as f64 > mean_residual + 25.0 && open_bins_count > 3 {
            score += 10.0 * (1.0 - progress) ;
        }
        // NEW: fresh bin is excellent when leftover exactly seals with next item plus a tiny item
        if next_item_size > 0 && fresh_left > next_item_size && fresh_left - next_item_size <= 2 {
            score -= 12.0 * (1.0 - progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: quarter-fractions of capacity define "usable" residual bands.
    let q = cap_f / 4.0;
    let post_f = post_residual as f64;
    let class = (post_f / q).floor() as u32; // 0..4

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space in the lowest band (0..25) unless it can host the next item.
        let next_fits = next_item_size > 0 && next_item_size <= post_residual;
        match class {
            0 => {
                if next_fits { score -= 30.0; } else { score += 60.0; }
            }
            1 => { score -= 10.0; }
            2 => { score -= 20.0; }
            3 => { score -= 5.0; }
            _ => { score -= 15.0; } // class 4: nearly empty bin residual
        }
    }

    // Harmonic residue of post_residual mod (capacity/8): reward residuals that
    // align with common item-size classes (multiples of small steps).
    let step = (bin_capacity / 8).max(1);
    let harm = post_residual % step;
    score += (harm as f64) * 0.5;

    // Lookahead coupling: if the next item exactly fills this bin's post-residual,
    // strongly prefer this bin (sets up a perfect fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slight penalty proportional to wasted potential.
        score += (next_item_size - post_residual) as f64 * 0.25;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Early stream: keep bins openable, prefer tight packing later.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    // Mild preference toward bins below mean residual (consolidate slack).
    score += (mean_residual - bin_residual as f64) * 0.1;

    // New-bin candidate: only attractive when current bin leaves awkward tiny slack.
    if bin_residual == bin_capacity {
        if post_residual == 0 { score += 0.0; }
        // base new-bin score equals post_residual (full capacity), adjusted:
        score += 20.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
