        if next_item_size > 0 && fresh_left >= next_item_size && fresh_left - next_item_size == 0 {
            score -= 10.0 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward when the NEXT item exactly fits the post residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 3.0 * gap;

        // Perfect chaining bonus: post_residual == next_item_size.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Next item overflows but nearly fits: mild penalty for wasting the chain.
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize leaving dead space below the minimum item size (unusable sliver).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Prefer filling nearly-full bins (best-fit reinforcement).
    score += 0.3 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: discourage opening a new bin unless the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        // Base penalty; relaxed if many bins are open and fit is poor elsewhere.
        score += 20.0 - 0.05 * open_bins_count as f64;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 5.0; // room to chain two items in a fresh bin
        }
    }

    // Late-stream urgency: consolidate as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

