}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;

    // Base: penalize wasted space, but with non-linear (quadratic) growth
    let mut score = pr * (1.0 + 0.6 * pr / cap);

    // Smooth coupling: as stream progresses, tolerate larger residuals less
    score *= 1.0 + 0.5 * progress * (pr / cap);

    // Reward tight fits via a smooth bump around small post_residual
    score -= 8.0 * (-((pr / cap - 0.05) * (pr / cap - 0.05)) / 0.02).exp();

    // Lookahead: reward residual that can still host the next item (smooth)
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        score -= 4.0 * (1.0 - (gap / cap).powi(2)) * (1.0 - fit_norm) * (1.0 - next_norm);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // Mild penalty when many bins are open and this one is far from mean residual
    score += 0.05 * (open_bins_count as f64) * ((pr - mean_residual) / cap).abs();

    // Slight preference for larger items filling bins early vs late
    score += 3.0 * fit_norm * (1.0 - 2.0 * progress) * (pr / cap);

    score
}

