        if next_item_size > 0 && fresh_left < next_item_size && fitting_bins_count > 1 {
            score += 12.0 * (1.0 - progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps superlinearly.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 40.0; // tiny gap = wasted capacity
    } else if pr == 0.0 {
        score -= 60.0; // perfect fit is always excellent
    }

    // Reward tight fits proportionally to fill ratio.
    let fill = item_size as f64 / bin_residual as f64;
    score -= fill * 25.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading (favor new bin less, consolidation more).
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable only if it will be well-filled now and by the next item.
        score += 30.0 + pressure * 6.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0; // new bin can also host the lookahead item
        }
    } else {
        // Existing bin: bonus if it can also take the next item (keeps bins dense).
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
