pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        // Perfect or near-perfect match for the next item is highly desirable.
        let gap = (post - nxt).abs();
        if nxt <= post {
            // Next item fits here afterwards: reward tight chain.
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 40.0; // exact 2-item fill
            }
        } else {
            // Next item won't fit after this placement; penalize leaving stranded space.
            score += 0.6 * gap;
        }
    } else {
        // Last item: prefer tightest fit as usual (post_residual baseline already does).
        score += 0.1 * (post_residual as f64);
    }

    // Relative-to-mean coupling: bins with residual near mean are "typical"; prefer
    // placing into bins that are above-average full (small residual) only if the fit is tight.
    let res = bin_residual as f64;
    let deviation = res - mean_residual;
    if deviation < 0.0 {
        // Fuller-than-average bin: reward using it up (reduce fragmentation).
        score -= 0.35 * (-deviation) * (item_size as f64 / res.max(1.0));
    } else {
        // Emptier-than-average bin: slight penalty to avoid spreading load.
        score += 0.15 * deviation;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; penalize it moderately so
    // reasonable existing fits win, but keep it competitive against very poor fits.
    if bin_residual == bin_capacity {
        score += 55.0;
    }

    // Mild preference to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    // Slight time-decay: early in stream, be a bit more willing to open bins (exploration);
    // late in stream, squeeze harder into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

