    let cap = bin_capacity as f64;
    let mut score = pr;

    // Smooth non-linear coupling: dead-space penalty grows quadratically as
    // post_residual shrinks (unusable slivers), scaled by stream progress.
    let dead = 1.0 - pr / cap;
    score -= 12.0 * dead * dead * (0.5 + 0.5 * progress);

    // Reward near-perfect fits more strongly later in the stream.
    if post_residual < item_size {
        score -= 8.0 * (1.0 + progress);
    }

    // Last-chance bin: strongly favor to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
