    // are heavily penalized. Assume future items >= 10; treat gaps < 10 as dead.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        score += 200.0; // nearly unusable sliver
    } else if post_residual <= 20 {
        score += 60.0; // risky small gap
    } else if post_residual <= 35 {
        score += 15.0; // mildly awkward gap
    } else {
        // Larger usable residuals are mildly rewarded
        score -= (post_residual as f64 - 35.0) * 0.3;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 150.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading to new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (2.0 + 4.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open and
        // any open bin could actually fit the item.
        if fitting_bins_count > 0 {
            score += 120.0 + pressure;
        } else {
            score += 30.0; // no alternative; new bin is fine
        }
        // Lookahead: if next item is large, a fresh bin is more attractive.
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 40.0;
        }
    } else {
        // Placing into an existing bin reduces open-bin pressure slightly.
        score -= pressure * 0.05;
