    // Prefer bins with residual close to the mean (balanced packing),
    // penalize outliers that create fragmented space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.4;

    // Lookahead coupling: if the next item fits in the post-residual,
    // reward this placement (keeps chains going).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0; // post-residual likely wasted w.r.t. next item
    }

    score
}

