pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less wasted space relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Perfect fit bonus: post_residual near zero is highly desirable.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 40.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0; // perfect chaining fit
        } else if next_item_size <= post_residual {
            // Reward proportional to how much of post_residual the next item consumes.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= fill * 60.0;
            // Extra bonus if next item fills post_residual almost exactly.
            if post_residual - next_item_size < 10 {
                score -= 25.0;
            }
        } else {
            // Next item cannot use this bin's leftover: penalize large dead space.
            let waste = next_item_size - post_residual;
            score += waste as f64 * 0.8;
        }
    }

    // Penalize bins whose post_residual deviates badly from mean residual
    // (keeps residual distribution homogeneous so future items fit somewhere).
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += dev * 0.15;
    } else {
        score += dev * 0.05; // small reward for staying below mean
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are terrible.
    if bin_residual == bin_capacity {
        score += 70.0;
        // If lookahead item is huge relative to item, a fresh bin may be worth it.
        if next_item_size > item_size && next_item_size > 0 {
            score -= 20.0;
        }
        // Early in the stream, having fresh bins is cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
    }

    // Mild preference to fill older/more crowded bins first.
    score += open_bins_count as f64 * 0.05;

    score
}

