        if progress > 0.6 && mean_residual > 0.25 * bin_capacity as f64 {
            score += 18.0 * (1.0 - progress) ;
        }
        // NEW: fresh bin early with a big item leaves a large, likely reusable leftover
        if progress < 0.25 && item_frac > 0.5 && next_item_size > 0 && fresh_left >= next_item_size {
            score -= 6.0 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize when post_residual is small relative to item size.
    if item_size > 0 {
        score -= (item_size as f64 / bin_capacity as f64) * 20.0;
    }

    // Strong reward for exact fit.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize dead space that is too small for the smallest plausible item.
        if post_residual < 10 {
            score += 15.0;
        }
        // Reward residuals that could still fit a future item (lookahead-aware).
        if (next_item_size as u32) > 0 && (next_item_size as u32) <= post_residual {
            score -= 12.0;
        } else if next_item_size as u32 > post_residual {
            score += 6.0;
        }
    }

    // Last-chance bonus: only bin that fits, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
        // But if the fit leaves tiny dead space, soften the bonus.
        if post_residual > 0 && post_residual < 5 {
            score += 20.0;
        }
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist.
    if bin_residual == bin_capacity {
        score += 30.0;
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
        // Late in the stream, opening new bins is cheaper than bad fits; reduce penalty.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 15.0;
    }

    // Prefer bins with residual close to item (best-fit flavor) modulated by global mean.
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.1;

    // Slight preference for bins below mean residual (concentrate filling).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Mild pressure to use many open bins when few exist relative to stream length.
    let expected_bins = (total_items as f64) * (item_size as f64 / bin_capacity as f64);
    if (open_bins_count as f64) < expected_bins * 0.8 {
        score += 2.0;
    }

    score
}

