pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let item = item_size as f64;

    // Base: prefer small post-residual, with a convex penalty for large waste
    let mut score = pr_norm * pr_norm * 100.0 + pr_norm * 10.0;

    // Smooth polynomial coupling of post-residual with stream progress:
    // late in the stream, tighter fits matter more
    let coupling = (pr_norm - 0.5) * (pr_norm - 0.5) * (1.0 + 3.0 * progress);
    score += coupling * 40.0;

    // Penalize opening a new bin more as the stream progresses
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * progress;
    }

    // Reward last-chance bins (avoid opening a bin for a poor fit)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    } else {
        // slight preference for bins that are more filled
        score -= (1.0 - bin_residual as f64 / cap) * 5.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - ((pr - nxt) / cap).abs());
        } else {
            score += 8.0;
        }
    }

    // Mild penalty for too many open bins relative to mean residual
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - mean_residual / cap).max(0.0);

    // Small tie-breaker: prefer placing larger items into emptier bins
    score -= item / cap * 0.5;

    score
}

