    let mut score = post_residual as f64;

    // Harmonic class of the post residual: small post_residual = tight fit.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward tight fits strongly (dead-space penalty is superlinear).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 300.0;
    } else {
        // Quadratic dead-space penalty scaled by capacity fraction.
        score += (post / cap) * (post / cap) * 50.0;
    }

    // Harmonic classes: classify post_residual into residue classes mod 10.
    // Residuals that are "useful" for typical item sizes (multiples of 10 class)
    // get a bonus; awkward classes get penalized.
    let class = (post_residual % 10) as f64;
    if class == 0 {
        score -= 40.0; // perfectly aligned residual class
    } else if class >= 7.0 {
        score += 15.0; // nearly aligned but wasteful sliver
    } else if class <= 3.0 {
        score += 8.0; // tiny sliver, mostly dead space
    }

    // Integer-division threshold: post_residual bucket by 20.
    let bucket = post_residual / 20; // 0..=5
    score += bucket as f64 * 12.0;

    // Lookahead coupling: if next item fits in post_residual, reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 60.0;
            // Extra harmonic bonus when next item exactly fills residual class.
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 25.0;
            }
        } else {
            // Next item won't fit here; penalize proportionally to how close it was.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate handling: only open a new bin when current bin's
    // post fit is bad and mean residual is high.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bin early or when open bins are nearly full on average.
        if post_residual > 50 && mean_residual < 30.0 {
            score -= 150.0 * (1.0 - progress);
