    // minimum plausible future item become "dead space" — penalize them hard.
    if post_residual > 0 {
        // dead-space zone: cannot fit even a small item (assume min ~10,
        // but with unknown distribution use a soft threshold around 12)
        if post_residual < 12 {
            score += 40.0 * (1.0 - post_residual as f64 / 12.0);
        }
        // medium unusable gap: 12..=25 also risky
        else if post_residual < 25 {
            score += 12.0 * (1.0 - (post_residual as f64 - 12.0) / 13.0);
        }
    }

    // Reward tight fits (small post_residual) — subtract a bit for good fits.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are poor fits or too many bins are open.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin
        score += 20.0;
        // but if current item is large and open bins are crowded, a new bin
        // becomes attractive
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size > 60 {
            score -= 15.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            score -= 10.0;
        }
        // early stream: prefer filling existing bins
        score += 10.0 * (1.0 - progress);
        // if next item is large, keep fresh capacity
        if next_item_size > 0 && next_item_size > post_residual + 20 && next_item_size >= 50 {
            score -= 8.0;
        }
    } else {
        // Existing bin: if the next item would fit exactly in the post_residual,
        // this is a great chain — reward it.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
        // If placing here leaves a gap the next item cannot use, penalize.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 5.0;
        }
    }

    // Slight preference for bins with below-average residual (consolidate
    // emptiness into few bins).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

