    let mut score = post_residual as f64;

    // Reward near-exact fits: small post_residual strongly preferred.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into post_residual,
    // this bin chains perfectly — big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but leaves a third-generation residual.
            let third = post_residual - next_item_size;
            score -= 40.0 - (third as f64).min(40.0);
        } else {
            // Next item cannot use the leftover: dead-space penalty scaled by gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    }

    // Coupling with mean residual: prefer bins whose residual is far from the mean
    // (drain outlier bins), but avoid draining bins that would become dead space.
    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += dev * 0.15; // below-mean residual (tighter bin) favored
    } else {
        score += dev * 0.05;
    }

    // Last-chance bin: if this is the only bin that fits, strongly avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 35.0;
    }

    // New-bin candidate (empty bin): penalize so we only open when fits are poor.
    if bin_residual == bin_capacity {
        score += 45.0 + 0.3 * (post_residual as f64);
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * (1.0 - progress);
    }

    // Slight preference to fill bins that are already mostly full.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Penalize leaving residuals in the "awkward zone" (21..40) that few items fill.
    if post_residual >= 21 && post_residual <= 40 {
        score += 12.0;
    }

    score
}

