    let mut score = post_residual as f64;
    let t = step_index as f64 / (total_items.max(1) as f64);
    let is_new_bin = bin_residual == bin_capacity;

    // General tight-fit reward: larger items consume more of the bin's value.
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 60.0;
    }

    if is_new_bin {
        // New-bin candidate: penalize by default, scaled by wasted space potential.
        score += 25.0 + (bin_capacity - item_size) as f64 * 0.3;

        // If the next item would NOT fit in the leftover, a fresh bin is more attractive.
        if next_item_size > 0 {
            if (next_item_size as f64) > post_residual as f64 {
                score -= 12.0;
            } else {
                score += 20.0;
            }
        }
        // More open bins already -> less need for another one.
        score += (open_bins_count as f64).ln().max(0.0) * 5.0;
    } else {
        // Existing bin: reward if the next item pairs well with the post residual.
        if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            score -= (post_residual as f64 - next_item_size as f64) * 0.5;
        }
        // Prefer bins whose residual deviates favorably from the global mean
        // (clean up small residuals early, keep large residuals for big items).
        score += (mean_residual - post_residual as f64) * 0.2;
    }

    // Slight late-stream tightening: as the stream progresses, waste matters more.
    score += t * (post_residual as f64) * 0.1;

    score
}

