        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;

    // Base: prefer small post residual, with non-linear shaping
    let mut score = pr + 40.0 * prn * prn;

    // Stream progress coupling: tighten dead-space penalty as stream progresses
    let progress_coupling = 30.0 * prn * prn * prn * (0.5 + progress);
    score += progress_coupling;

    // Reward tight fits (post_residual near zero) increasingly over time
    let tight_bonus = (1.0 - prn) * (1.0 - prn) * 12.0 * (1.0 + progress);
    score -= tight_bonus;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Penalize bins whose residual is far below the mean (fragmented bins)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Lookahead: reward bins that can also fit the next item
    if next_item_size > 0 {
        let fits_next = (pr >= next_item_size as f64) as i32 as f64;
        let slack = (pr - next_item_size as f64) / cap;
        score -= fits_next * (8.0 + 6.0 * (1.0 - slack.abs()));
        // Penalize leaving just-barely-room that wastes space for the next item
        if pr < next_item_size as f64 && pr > 0.0 {
            score += 6.0 * (1.0 - pr / next_item_size.max(1) as f64);
        }
    }

    // Mild penalty for spreading across many bins early on
    score += (open_bins_count as f64).ln() * 2.0 * (1.0 - progress);

    // New-bin candidate: neutral baseline with slight preference when current fits are poor
    if bin_residual == bin_capacity {
        score = cap - item_size as f64 + 5.0;
    }

    score
}

