pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual (dead-space quality) ---
    // Residuals divisible by 20 are "harmonic" and easy to fill later.
    let harmonic_bonus = if post_residual == 0 {
        -40.0 // perfect fit: strongly reward
    } else if post_residual % 20 == 0 {
        -8.0
    } else if post_residual % 10 == 0 {
        -4.0
    } else if post_residual % 5 == 0 {
        -1.5
    } else {
        2.0 // awkward residual: penalize
    };
    score += harmonic_bonus;

    // Small dead space is worse than it looks: quadratic penalty below threshold.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 1.8;
    }

    // --- Lookahead coupling: does post_residual fit the next item? ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item can still land here: reward proportionally.
            score -= 6.0 + (next_item_size as f64 / 20.0);
            // Extra reward if post_residual is exactly a harmonic multiple of next size.
            if post_residual % next_item_size.max(1) == 0 {
                score -= 3.0;
            }
        } else {
            // Next item won't fit here: penalize if this was the only fitting bin.
            if fitting_bins_count <= 1 {
                score += 12.0;
            } else {
                score += 3.0;
            }
        }
    }

    // --- Last-chance logic: strongly prefer using the only fitting bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when open bins are crowded
        // or the item is huge relative to typical residuals.
        let crowded = mean_residual < item_size as f64 * 0.9;
        let pressure = open_bins_count as f64 / (step_index.max(1) as f64 + 1.0);
        if crowded || item_size >= 70 {
            score -= 5.0 + pressure;
        } else {
            score += 10.0 + (item_size as f64 / 10.0);
        }
    }

    // --- Progress-phase modulation: later in stream, waste matters more ---
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64 / 10.0);

    // Mild penalty for leaving residual far from mean (fragmentation).
    let diff = (post_residual as f64 - mean_residual).abs();
    score += diff * 0.05;

    score
}

