        if next_item_size > 0 && fresh_left < next_item_size {
            score += 0.3 * fresh_left as f64 * (1.0 - progress) ;
        }
        // NEW: fresh bin unattractive when an open bin already has headroom >= next item
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && open_bins_count > 3 {
            score += 8.0 * (1.0 - progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=15) are nearly unusable dead space.
    if post_residual > 0 && post_residual <= 15 {
        score += 120.0 * (1.0 - post_residual as f64 / 15.0);
    } else if post_residual == 0 {
        // Perfect fit is strongly rewarded.
        score -= 200.0;
    }

    // Reward leaving room that can still serve the next item (lookahead k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap too small for the next item: mild extra penalty.
        score += 10.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize bins whose residual is far below the mean (fragmented bins).
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    // New empty bin candidate: only attractive when it enables a good chain for upcoming items
    // or no existing bin fits well. Default: make it unattractive unless item is large.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 60.0 - 80.0 * large_item;
