pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer perfect or near-perfect fits (dead space minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Non-linear penalty on small residuals (wasted space that's hard to reuse).
        let r = post_residual as f64;
        score += 60.0 / r; // small residuals get big penalty
        if r <= 10.0 {
            score += 40.0; // tiny slivers are nearly unusable (items >= 1 but rare)
        }
    }

    // 2-step lookahead: reward when the next item exactly fills the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // perfect chain placement
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how snugly it fits
            let slack_after_next = post_residual - next_item_size;
            score -= 120.0 - (slack_after_next as f64) * 2.0;
        } else {
            // next item would NOT fit here: mild penalty for fragmenting space
            score += 25.0;
        }
    }

    // Relative-to-mean coupling: bins with residual below mean are "tighter";
    // filling a tight bin is good (consolidation), leaving it open is bad.
    let tightness = mean_residual - (bin_residual as f64);
    score += tightness * 0.8;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity (poor fit anywhere else) or
    // late in the stream. Penalize the fresh bin otherwise.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = (item_size as f64) / (bin_capacity as f64);
        // new bin starts at post_residual = capacity - item; make it less
        // attractive unless item is big or few fitting bins exist
        score += 80.0 * (1.0 - large_item) + 40.0 * (1.0 - progress);
        if fitting_bins_count <= 1 {
            score -= 350.0; // fallback: opening a bin beats a forced bad fit
        }
    }

    // Mild preference for consolidating into fewer bins when many are open.
    score += (open_bins_count as f64) * 0.5;

    score
}

