            if next_item_size > 0 && (gap as u32) == next_item_size {
                score -= 20.0 ;
            }
            if next_item_size > 1 && (gap as u32) == 2 * next_item_size {
                score -= 12.0 ;
            }
            // NEW: gap that is an exact multiple of next item seals cleanly later
            if next_item_size > 1 && (gap as u32) % next_item_size == 0 && (gap as u32) / next_item_size >= 2 {
