        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        // avoid opening fresh bins when a fitting open bin nearly seals with this item
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        // NEW: fresh bin attractive when its leftover exactly fits next item plus
        // a small remainder that matches the mean residual shape
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size ;
            if tail as f64 >= mean_residual - 2.0 && tail as f64 <= mean_residual + 2.0 && open_bins_count > 3 {
                score -= 7.0 * (1.0 - progress) ;
            }
        }
        // NEW: penalize fresh bins late in the stream when several open bins
        // already have residuals larger than the next item
        if progress > 0.6 && next_item_size > 0 && fitting_bins_count >= 3 && mean_residual > next_item_size as f64 {
            score += 10.0 * (progress - 0.6) / 0.4 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 40.0;

    // Penalize dead space: post_residual too small for the smallest plausible item (1..100 range, min 1).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Time horizon: early in the stream, be conservative with open bins (allow fragmentation later);
    // late in the stream, pack tightly and avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 15.0;

    // New-bin candidate handling: penalize opening a new bin, more so late in the stream
    // or when many bins are open, unless the item is huge and nothing fits well.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let pressure = (open_bins_count as f64).ln().max(0.0);
        score += 20.0 + progress * 25.0 + pressure * 3.0;
        // If item nearly fills a bin and mean residual is low, opening fresh is fine.
        if item_frac > 0.7 && mean_residual < item_size as f64 {
            score -= 35.0;
        }
    }

    // Global state: when mean residual across open bins is low, prefer bins with residual
    // close to the mean (balanced packing); when high, prefer filling the fullest bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    if mean_residual < 30.0 {
        score += dev * 0.5;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.15;

    // Prefer bins with residual just above the item (exactness bonus).
    let exact = (bin_residual as f64 - item_size as f64).abs();
    score += exact * 0.1;

    score
}

