}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: post residual, normalized
    let mut score = pr / cap;

    // Smooth non-linear waste penalty: dead space grows quadratically as residual shrinks
    let prn = pr / cap;
    score += 0.6 * prn * prn;

    // Coupling of post-residual with stream progress: late in the stream, be greedier (tight fits matter)
    let tight = 1.0 - prn;
    score -= 0.9 * tight * tight * (0.5 + progress);

    // Polynomial interaction: item size vs residual curvature
    let itn = it / cap;
    score += 0.4 * itn * itn * prn - 0.5 * itn * prn * prn;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 0.8;
    }

    // Lookahead: if next item fits in post residual, reward this placement
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 0.3 * (nx / cap);
            // extra reward for chaining near-perfect pairs
            let combined = (it + nx) / cap;
            score -= 0.4 * (1.0 - (combined - 1.0) * (combined - 1.0));
        } else {
            score += 0.15 * (nx / cap);
        }
    }

    // New-bin candidate handling: empty bin gets a moderate prior so we only open
    // when open bins have poor fits
    if bin_residual == bin_capacity {
        score += 0.55 + 0.25 * progress + 0.1 * (open_bins_count as f64).sqrt();
    }

    // Mean residual context: penalize placing into bins far from the mean (fragmentation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.2 * dev * dev;

    score
}

