            score -= 12.0 ;
        }
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        // NEW: fresh bin penalized when a fitting open bin already hosts next item
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count > 0 {
            score += 8.0 * (1.0 - progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting gap: bins whose post_residual falls on
    // "usable" class boundaries are preferred, since future items (1..100)
    // frequently match small modular classes.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else if pr <= 5 {
        // Tiny dead space is nearly worthless.
        score += 15.0;
    } else if pr % 10 == 0 {
        // Round-decade gap: highly reusable.
        score -= 12.0;
    } else if pr % 5 == 0 {
        score -= 6.0;
    } else if pr <= 10 {
        // Gap in (5,10]: only fits tiny items, mostly dead.
        score += 8.0;
    }

    // Integer-division thresholds: how many "typical" items (size ~20) still fit.
    let slots = pr / 20;
    score -= slots as f64 * 4.0;

    // Lookahead coupling: if the next item fits exactly into the post-residual
    // class, reward strongly; if the next item cannot fit at all, penalize.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = pr - next_item_size;
            if slack == 0 {
                score -= 25.0;
            } else if slack % 10 == 0 {
                score -= 10.0;
            } else if slack <= 5 {
                score += 5.0;
            }
        } else {
            // Next item won't fit here regardless; keep gap flexible.
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current gap is
    // truly unusable (very small or item is huge relative to residual).
    if bin_residual == bin_capacity {
        let waste = bin_residual - item_size;
        let bad_fit = (bin_residual - item_size) < 15 && bin_residual < bin_capacity;
        let _ = bad_fit;
        let usable_gap = bin_residual.saturating_sub(item_size);
        if usable_gap >= 20 {
            // Opening new bin wastes the residual of old bins; discourage mildly.
            score += 10.0 + mean_residual * 0.15;
        } else {
            // Old gaps are tiny; new bin is fine.
            score -= 5.0;
        }
        let _ = waste;
    }

    // Prefer tighter bins overall: closeness of residual to item size.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.05;

    // Late in the stream, consolidate: favor bins that close out fully.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if pr as f64 <= item_size as f64 * 0.5 {
        score -= 6.0 * progress;
    }

    // Slight preference for bins below mean residual (filling emptier bins
    // keeps tight bins available for tight items).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

