    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when current bins are very full on average
    // or this bin would leave severe dead space.
    if bin_residual == bin_capacity {
        let mean_fullness = 1.0 - mean_residual / (bin_capacity as f64);
