                let fillable = next_item_size > 0 && gap >= next_item_size as f64 ;
                let w = if fillable { 0.2 } else { 0.6 } ;
                score += w * (mean_residual - gap) ;
            }
            if next_item_size > 0 && (gap as u32) == next_item_size {
                score -= 20.0 ;
            }
            if next_item_size > 1 && (gap as u32) == 2 * next_item_size {
                score -= 12.0 ;
            }
        }
        if fitting_bins_count == 1 {
            score -= 12.0 ;
        }
        let fill = item_size as f64 / (bin_residual as f64) . max (1.0) ;
        score -= 20.0 * fill ;
        // dead space: unusable residual relative to next item
        if next_item_size > 0 && post_residual < next_item_size {
            let dead_frac = post_residual as f64 / bin_capacity as f64 ;
            let unusable_ratio = post_residual as f64 / (next_item_size as f64) . max (1.0) ;
            score += 0.4 * post_residual as f64 + 30.0 * dead_frac + 12.0 * (1.0 - unusable_ratio) ;
            if next_item_size - post_residual <= 4 {
                score += 20.0 * (1.0 - progress) ;
            }
        }
        // anti-fragmentation guard
        if fitting_bins_count == 2 && post_residual < bin_capacity / 3 {
            score -= 8.0 ;
        }
        // tiny unusable slivers when bins are plentiful
        if post_residual <= 5 && open_bins_count > 6 {
            score += 25.0 * (1.0 - progress) ;
        }
        // mid-sized future homes
        if post_residual >= bin_capacity / 8 && post_residual <= bin_capacity / 2 {
            score -= 6.0 ;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= bin_capacity / 2 {
            score -= 4.0 * (1.0 - progress) ;
        }
        // reward residuals that can absorb two more average items
        if post_residual as f64 >= 2.0 * mean_residual && post_residual > 20 {
            score -= 5.0 ;
        }
        // compaction sweet spot: headroom matches mean residual
        if next_item_size > 0 && post_residual > next_item_size {
            let headroom = post_residual - next_item_size ;
            if (headroom as f64 - mean_residual) . abs () <= 3.0 {
                score -= 7.0 ;
            }
            if (headroom as f64 - mean_residual) . abs () <= 1.0 && fitting_bins_count <= 3 {
                score -= 5.0 * (1.0 - progress) ;
            }
        }
        // three-way closure: residual hosts next item then seals exactly
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0 ;
        }
        // residual that fits next item plus a small item is doubly useful
        if next_item_size > 1 && post_residual > next_item_size + 1 && post_residual <= next_item_size + 10 {
            score -= 4.0 * (1.0 - progress) ;
        }
        // NEW: residual that fits next item plus one more mean-sized item
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 + mean_residual {
            score -= 5.0 * (1.0 - progress) ;
        }
    }
    // NEW-BIN CANDIDATE
    if bin_residual == bin_capacity {
        let big_next = next_item_size as f64 / bin_capacity as f64 ;
        score += 180.0 - 60.0 * progress + 0.15 * open_bins_count as f64 - 25.0 * big_next . max (0.0) ;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0 ;
        }
        if open_bins_count <= 4 && progress < 0.3 {
            score += 25.0 ;
        }
        if mean_residual < 15.0 && progress > 0.5 {
            score -= 15.0 ;
        }
        let item_frac = item_size as f64 / bin_capacity as f64 ;
        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3 ;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3 ;
        }
        let fresh_left = bin_capacity - item_size ;
        if next_item_size > 0 && fresh_left == next_item_size {
            score -= 30.0 ;
        }
        if open_bins_count > 6 && mean_residual > 0.4 * bin_capacity as f64 {
            score += 20.0 ;
        }
        // fresh-bin leftover sliver is wasteful
        if next_item_size > 0 && fresh_left < next_item_size && fresh_left < 8 {
            score += 35.0 ;
        }
        // prefer fresh bin when all existing residuals are too small for next item
        if next_item_size > 0 && fitting_bins_count <= 2 && mean_residual < next_item_size as f64 {
            score -= 18.0 * (1.0 - progress) ;
        }
        // discourage opening fresh bins late when many half-empty bins exist
        if open_bins_count > 8 && mean_residual > next_item_size as f64 + 10.0 {
            score += 12.0 ;
        }
        // large items into fresh bins leave big usable leftovers: mild reward
        if item_frac > 0.6 && next_item_size > 0 && fresh_left >= next_item_size {
            score -= 8.0 * (1.0 - progress) ;
        }
        // fresh bin justified when leftover can host next item plus mean slack
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress) ;
        }
        // near-zero tail after next item (perfect closure)
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size ;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress) ;
            }
        }
        // fresh bin leftover below mean residual is likely dead space
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        // chain home: leftover hosts next item twice exactly
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        // near-exact fill wastes nothing and preserves all open residuals
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        // fresh bin leftover matching mean residual — reusable home shape
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        // chain home: leftover hosts next item multiple times exactly
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        // fresh bin leftover that hosts next item plus mean-shaped slack
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        // avoid opening fresh bins when a fitting open bin nearly seals with this item
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        // NEW: avoid fresh bin when an open bin's leftover after this item still
        // hosts the next item — preserves compaction
        if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
            score += 8.0 * (1.0 - progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    if post_residual == 0 {
        score -= 1000.0;
    } else {
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 900.0 - 30.0 * progress;
            } else if post_residual >= next_item_size {
                let after_next = post_residual - next_item_size;
                if after_next == 0 {
                    score -= 700.0;
                } else if after_next <= 12 {
                    score -= 80.0 + 1.5 * (12 - after_next) as f64;
                } else {
                    score -= 300.0 - 2.0 * after_next as f64;
                }
                // chain home
                if next_item_size > 1 && after_next >= next_item_size {
                    score -= 6.0 + 0.2 * (after_next / next_item_size) as f64;
                    if after_next % next_item_size == 0 {
                        score -= 8.0 * (1.0 - progress);
                    }
                }
                // headroom matches mean residual: reusable home shape
                if ((after_next as f64) - mean_residual).abs() <= 4.0 {
                    score -= 6.0 * (1.0 - progress);
                }
                // near-seal sliver after next item
                if after_next < next_item_size && after_next <= 3 {
                    score -= 14.0 * (1.0 - progress);
                }
                // leftover just below next item: near-seal
                if after_next < next_item_size && after_next >= 1 && (next_item_size - after_next) <= 5 {
                    score -= 6.0 * (1.0 - progress);
                }
                // comfortable slack cushion
                if after_next >= 3 {
                    score -= (2.0 + 2.0 * progress) * (after_next as f64).min(15.0);
                }
                // leftover after next item stays usable
                if after_next <= 12 && mean_residual >= after_next as f64 {
                    score -= 22.0 - 0.8 * after_next as f64;
                }
                // three-way closure: hosts next item then seals exactly
                if post_residual == 2 * next_item_size {
                    score -= 10.0;
                }
            } else {
                let miss = next_item_size - post_residual;
                score += 2.0 * miss as f64;
                if post_residual < 25 {
                    score += 15.0;
                }
                // near-perfect sealed bins: strong reward
                if post_residual < 3 {
                    score -= 400.0;
                }
                if miss <= 6 && fitting_bins_count <= 2 {
                    score -= 5.0;
                }
                if miss <= 10 && fitting_bins_count <= 2 && progress > 0.7 {
                    score -= 10.0 * (1.0 - progress);
                }
                if miss <= 2 {
                    score -= 18.0 * (1.0 - progress);
                }
                // strand-space guard just under common small sizes
                if post_residual >= 8 && post_residual <= 16 {
                    score += 10.0 * (1.0 - progress);
                }
                // near-miss whose gap matches mean residual shape — dead space
                if miss > 3 && miss as f64 <= mean_residual * 0.5 {
                    score += 4.0 * (1.0 - progress);
                }
            }
        }

        score -= 0.6 * (mean_residual - post_residual as f64);
        if post_residual < 10 {
            score += 45.0;
        } else if post_residual < 20 {
            score += 10.0;
        }

        // dead-gap penalty with scarcity scaling
        let gap = (post_residual as f64 - item_size as f64).max(0.0);
        let gap_ratio = gap / (item_size as f64).max(1.0);
        if gap > 0.0 {
            let scarcity = if fitting_bins_count <= 2 { 0.6 } else if fitting_bins_count <= 4 { 0.3 } else { 0.2 };
            score += scarcity * gap + 18.0 * gap_ratio.min(2.0);
            if gap < mean_residual {
                let fillable = next_item_size > 0 && gap >= next_item_size as f64;
                let w = if fillable { 0.2 } else { 0.6 };
                score += w * (mean_residual - gap);
            }
            if next_item_size > 0 && (gap as u32) == next_item_size {
                score -= 20.0;
            }
            if next_item_size > 1 && (gap as u32) == 2 * next_item_size {
                score -= 12.0;
            }
        }

        // last-chance bin
        if fitting_bins_count == 1 && bin_residual >= item_size {
            score -= 12.0;
        }

        let fill = item_size as f64 / bin_residual.max(1) as f64;
        score -= 20.0 * fill;

        // unusable residual relative to next item
        if next_item_size > 0 && post_residual < next_item_size {
            let unusable_ratio = post_residual as f64 / (next_item_size as f64).max(1.0);
            score += 0.4 * post_residual as f64 + 30.0 * (post_residual as f64 / bin_capacity as f64)
                + 12.0 * (1.0 - unusable_ratio);
            if next_item_size - post_residual <= 4 {
                score += 20.0 * (1.0 - progress);
            }
        }

        // anti-fragmentation guard
        if fitting_bins_count == 2 && post_residual < bin_capacity / 3 {
            score -= 8.0;
        }

        // tiny unusable slivers when bins are plentiful
        if post_residual <= 5 && open_bins_count > 6 {
            score += 25.0 * (1.0 - progress);
        }

        // residual that can absorb two more average items
        if post_residual as f64 >= 2.0 * mean_residual && post_residual > 20 {
            score -= 5.0;
        }

        // mid-sized future homes
        if post_residual >= bin_capacity / 8 && post_residual <= bin_capacity / 2 {
            score -= 6.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= bin_capacity / 2 {
            score -= 4.0 * (1.0 - progress);
        }

        // compaction sweet spot: headroom matches mean residual
        if next_item_size > 0 && post_residual > next_item_size {
            let headroom = post_residual - next_item_size;
            if (headroom as f64 - mean_residual).abs() <= 3.0 {
                score -= 7.0;
            }
            if (headroom as f64 - mean_residual).abs() <= 1.0 && fitting_bins_count <= 3 {
                score -= 5.0 * (1.0 - progress);
            }
        }
        // residual that fits next item plus a small item is doubly useful
        if next_item_size > 1 && post_residual > next_item_size + 1 && post_residual <= next_item_size + 10 {
            score -= 4.0 * (1.0 - progress);
        }
    }

    // NEW-BIN CANDIDATE
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let fresh_left = bin_capacity - item_size;
        let big_next = next_item_size as f64 / bin_capacity as f64;
        score += 180.0 - 60.0 * progress + 0.15 * open_bins_count as f64 - 25.0 * big_next.max(0.0);

        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3;
        }

        if next_item_size > 0 {
            if fresh_left == next_item_size {
                score -= 30.0;
            }
            if fresh_left == 2 * next_item_size {
                score -= 12.0;
            }
            if next_item_size >= bin_capacity / 2 {
                score -= 10.0;
            }
            if fresh_left < next_item_size && fresh_left < 8 {
                score += 35.0;
            }
            if fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual).abs() <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
            if fitting_bins_count <= 2 && mean_residual < next_item_size as f64 {
                score -= 18.0 * (1.0 - progress);
            }
            if open_bins_count > 8 && mean_residual > next_item_size as f64 + 10.0 {
                score += 12.0;
            }
            // near-zero tail after next item (perfect closure)
            if fresh_left > next_item_size {
                let tail = fresh_left - next_item_size;
                if tail <= 3 {
                    score -= 14.0 * (1.0 - progress);
                }
            }
            // fresh leftover below mean residual is likely dead space
            if fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
                score += 10.0;
            }
            // large items into fresh bins leave big usable leftovers
            if item_frac > 0.6 && fresh_left >= next_item_size {
                score -= 8.0 * (1.0 - progress);
            }
            // fresh bin justified when leftover can host next item plus mean slack
            if fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
                score -= 10.0 * (1.0 - progress);
            }
            // chain home: leftover hosts next item multiple times exactly
            if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
                score -= 6.0 * (1.0 - progress);
            }
        }
        // near-exact fill
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress);
        }
        // avoid opening fresh bins when an open bin nearly seals with this item
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0;
        }
        // early stream with few bins: fresh bin is fine
        if open_bins_count <= 4 && progress < 0.3 {
            score += 25.0;
        }
        // late stream, tight mean residuals: prefer consolidation over fresh bins
        if mean_residual < 15.0 && progress > 0.5 {
            score -= 15.0;
        }
        // fresh leftover matching mean residual — reusable home shape
        if next_item_size > 0 && (fresh_left as f64 - mean_residual).abs() <= 2.0 {
            score -= 8.0;
        }
        // discourage opening fresh bins late when many half-empty bins exist
        if open_bins_count > 6 && mean_residual > 0.4 * bin_capacity as f64 {
            score += 20.0;
        }
    }

    // Late in the stream, consolidate: prefer tightest fits even more.
    score -= progress * 0.3 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class penalty: residuals that are dead space (small, hard to fill)
    let pr = post_residual;
    if pr > 0 {
        // classify residual into harmonic classes of capacity
        let class = bin_capacity / pr.max(1); // integer division: how many copies of residual fit in a bin
        if class == 1 {
            // residual > cap/2 : large leftover, still usable -> mild penalty
            score += 2.0;
        } else if class >= 2 && class <= 3 {
            // residual in (cap/4, cap/2] : sweet spot, reward
            score -= 6.0;
        } else if class >= 4 && class <= 6 {
            // moderate residual, moderately usable
            score += 1.0;
        } else {
            // tiny residual (class >= 7): near-dead space, strong penalty
            score += 10.0 + (7 - class.min(7)) as f64 * 0.0;
        }
        // modulo structure: residuals that divide capacity evenly are reusable by same-size items
        if bin_capacity % pr == 0 {
            score -= 3.0;
        }
        // penalize residuals that cannot fit the smallest plausible item
        if pr < 10 {
            score += 15.0;
        }
    } else {
        // perfect fit: maximal reward
        score -= 25.0;
    }

    // Lookahead: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits: reward, scaled by tightness of that fit
            let tight = (pr - next_item_size) as f64 / cap;
            score -= 8.0 * (1.0 - tight);
        } else {
            // next item won't fit here: penalize more if this was the only fitting bin
            if fitting_bins_count == 1 {
                score += 12.0;
            } else {
                score += 3.0;
            }
        }
        // harmonic coupling: next item pairs perfectly if post_residual is multiple-friendly
        if pr > 0 && next_item_size % pr.max(1) == 0 && pr >= next_item_size {
            score -= 4.0;
        }
    }

    // New-bin candidate handling: empty bin has residual == capacity
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when current bin would leave bad residue
        // and there are already many open bins (consolidation pressure)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 5.0 + 0.5 * open_bins_count as f64 * (1.0 - progress);
        // discourage opening new bins when a decent fit exists elsewhere
        if pr <= bin_capacity / 4 && pr >= 5 {
            score += 20.0;
        }
        // if only this bin fits, strongly prefer using it over a new bin
        if fitting_bins_count == 1 {
            score += 30.0;
        }
        // late in stream, prefer filling existing bins
        score += 10.0 * progress;
        return score;
    }

    // tightness reward: prefer bins where item fills most of the residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 5.0 * fill_ratio;

    // mean residual context: if this bin's residual is far below mean, it's an outlier worth filling
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    // last-chance bonus: if this is the only bin that fits, prefer it to avoid a new bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    score
}

