        }
        // NEW: residual can host next item plus one mean-sized item — strong compaction home
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 + mean_residual && post_residual <= next_item_size + 30 {
            score -= 6.0 * (1.0 - progress) ;
        }
    }
    // NEW-BIN CANDIDATE
    if bin_residual == bin_capacity {
        let big_next = next_item_size as f64 / bin_capacity as f64 ;
        score += 180.0 - 60.0 * progress + 0.15 * open_bins_count as f64 - 25.0 * big_next . max (0.0) ;
