        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        // NEW: fresh bin only worth it if leftover exceeds best reusable shape by clear margin
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left as f64) < mean_residual + next_item_size as f64 && open_bins_count > 5 {
            score += 8.0 * (1.0 - progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to hold
    // even the smallest plausible item are pure waste -> heavy penalty.
    let dead_threshold = 10u32; // smallest useful gap
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 + (dead_threshold - post_residual) as f64 * 4.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin exactly.
        score -= 45.0;
    } else {
        // Usable gap: mild reward proportional to tightness of fit.
        let tightness = post_residual as f64 / bin_capacity as f64;
        score -= 20.0 * (1.0 - tightness);
    }

    // Penalize leaving a gap that cannot fit the lookahead item but could
    // have fit it if we packed differently (lookahead awareness).
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            score += 8.0; // gap unusable for next item
        } else {
            score -= 6.0; // gap can host the next item: good chaining
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // yet another bin; encourage filling existing ones.
    let open_pressure = open_bins_count as f64 / 20.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when existing bins are crowded
        // or the fit in any open bin would be terrible.
        score += 15.0 + 30.0 * open_pressure;
        if post_residual as f64 > mean_residual {
            score += 10.0;
        }
    } else {
        score -= 5.0 * open_pressure;
    }

    // Mean-residual coupling: bins far below mean residual are less
    // attractive targets (their space is more flexible); prefer bins whose
    // residual is close to the item (small leftover relative to mean).
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    // Late-stream urgency: near the end, close bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

