pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // 2-step lookahead: reward if next item fits into post_residual exactly/loosely.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_fit = next_item_size as f64 / post_residual as f64;
            // Perfect chain (post_residual == next_item_size) is ideal.
            score -= 25.0 * next_fit;
        } else {
            // Next item cannot fit here: penalize wasted residual relative to mean.
            score += 8.0;
        }
    } else {
        // Last item: just minimize post residual.
        score -= 10.0;
    }

    // Penalize dead space relative to mean residual across open bins.
    let residual_f = post_residual as f64;
    if residual_f > mean_residual {
        score += 0.5 * (residual_f - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - residual_f);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless current bin fit is poor.
    if bin_residual == bin_capacity {
        // Opening a new bin is costly; add a fixed penalty so only bad fits
        // in existing bins make the new bin win.
        score += 15.0;
        // Early in stream, new bins are fine; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If next item is large, a fresh bin gives room.
        if next_item_size > item_size && next_item_size > 0 {
            score -= 12.0;
        }
    }

    // Slight preference for filling bins with less remaining spread among many bins.
    score += 0.05 * open_bins_count as f64 * (residual_f / bin_capacity as f64);

    score
}

