        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        // chain home: leftover hosts next item twice exactly
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        // near-exact fill wastes nothing and preserves all open residuals
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        // fresh bin leftover matching mean residual — reusable home shape
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        // chain home: leftover hosts next item multiple times exactly
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        // fresh bin leftover that hosts next item plus mean-shaped slack
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        // avoid opening fresh bins when a fitting open bin nearly seals with this item
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        // two-item lookahead: fresh bin can host this item plus the next two
        // average items — strong compaction signal
        if next_item_size > 0 && fresh_left as f64 >= item_size as f64 + 2.0 * mean_residual {
            score -= 14.0 * (1.0 - progress) ;
        }
        // fresh bin whose leftover is exactly the next item plus a sliver of mean slack
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= 0.25 * mean_residual {
            score -= 6.0 * (1.0 - progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity split into 8 bands.
    let band = post_residual / (bin_capacity / 8).max(1);
    let band_f = band as f64;

    // Reward small post_residual (tight fits), especially in low bands.
    score -= (8.0 - band_f) * 2.0;

    // Exact-fit class: post_residual in {0, 10, 20} is prime reusable space.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual % 10 == 0 && post_residual <= 30 {
        score -= 15.0;
    }

    // Dead-space penalty: leftover too small for the smallest plausible item (1..100 range).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 - slack * 0.15;
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to how close we were.
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.1;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer tighter fits: normalize by competition.
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // Prefer bins whose residual is below the mean residual (concentrate waste),
    // spreading open bins' fullness.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Early in the stream, be more willing to open new bins for large items
    // to preserve flexibility; late in the stream, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if item_size > bin_capacity / 2 {
        score -= progress * 10.0;
    }

    // Modulo coupling: item size classes vs post residual class alignment.
    let item_class = item_size % 4;
    let post_class = post_residual % 4;
    if item_class == post_class {
        score -= 3.0;
    }

    // Mild penalty for opening a brand-new bin when other bins could fit.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 12.0 + mean_residual * 0.1;
    }

    score
}

