            score += 35.0;
        } else if post_residual < 30 {
            score += 15.0;
        } else {
            // larger gaps remain usable for typical items: reward them
            score -= (post_residual as f64 - 30.0) * 0.8;
        }
    } else {
        score -= 40.0; // perfect fit
    }

    // Open-bins pressure: many open bins -> prefer consolidating into existing ones.
    let pressure = (open_bins_count as f64).ln() * 6.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when existing bins are crowded or fit is poor.
        let crowd = (mean_residual / bin_capacity as f64).powi(2);
        score += 45.0 - pressure - crowd * 30.0;
    } else {
        score -= pressure * 0.5;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: favor bins whose post_residual accommodates the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Late in the stream: prefer tight packing over opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

