pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item still fits in the bin after this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    }
    // Penalize dead space that cannot fit the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }
    // Penalize small unusable slivers of dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 20.0;

    // Last-chance bin bonus: if this is the only bin that fits, use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Prefer bins with residuals below the mean residual (better consolidation).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Penalize opening a new bin unless it's genuinely useful.
    if bin_residual == bin_capacity {
        // New bin: penalize unless the current bin situation is poor
        // (few fitting bins or large item relative to open residuals).
        score += 45.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        if next_item_size > 0 && item_size as f64 >= mean_residual {
            score -= 20.0;
        }
    }

    // Early in the stream, be slightly more willing to keep bins tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    score
