pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    if post_residual == 0 {
        // Perfect seal: extremely attractive.
        score -= 1000.0;
        return score;
    }

    // Tightness reward.
    let tightness = 1.0 - pr / cap;
    score -= 12.0 * tightness * tightness;

    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Exact two-item closure.
            score -= 900.0 - 30.0 * progress;
        } else if next_item_size <= post_residual {
            let after_next = post_residual - next_item_size;
            let slack = after_next as f64;
            if after_next == 0 {
                score -= 700.0;
            } else if slack >= 10.0 {
                score -= 300.0 - 2.0 * slack;
            } else {
                score -= 80.0 + 1.5 * (10.0 - slack);
            }
            // Comfortable cushion for the next item.
            if after_next >= 3 {
                score -= (2.0 + 2.0 * progress) * slack.min(15.0);
            }
            // Leftover stays reusable (matches mean residual shape).
            if after_next <= 12 && mean_residual >= slack {
                score -= 22.0 - 0.8 * slack;
            }
            // Chain home: leftover hosts next item again.
            if next_item_size > 1 && after_next >= next_item_size {
                score -= 6.0 + 0.2 * (after_next / next_item_size) as f64;
                if after_next % next_item_size == 0 {
                    score -= 8.0 * (1.0 - progress);
                }
            }
            // Near-seal sliver after next item.
            if after_next < next_item_size && after_next <= 3 {
                score -= 14.0 * (1.0 - progress);
            }
            if after_next < next_item_size && (next_item_size - after_next) <= 5 {
                score -= 6.0 * (1.0 - progress);
            }
            // Headroom matches mean residual: reusable home.
            if (slack - mean_residual).abs() <= 4.0 {
                score -= 6.0 * (1.0 - progress);
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 2.0 * miss;
            if post_residual < 25 {
                score += 15.0;
            }
            // Near-perfect sealed bins.
            if post_residual < 3 {
                score -= 400.0;
            }
            if miss <= 6.0 && fitting_bins_count <= 2 {
                score -= 5.0;
            }
            if miss <= 10.0 && fitting_bins_count <= 2 && progress > 0.7 {
                score -= 10.0 * (1.0 - progress);
            }
            if miss <= 2.0 {
                score -= 18.0 * (1.0 - progress);
            }
            // Strand-space guard just under common small sizes.
            if post_residual >= 8 && post_residual <= 16 {
                score += 10.0 * (1.0 - progress);
            }
            if miss > 3.0 && miss <= mean_residual * 0.5 {
                score += 4.0 * (1.0 - progress);
            }
        }
    }

    // Dead-gap penalty with scarcity scaling.
    let gap = pr - item_size as f64;
    if gap > 0.0 {
        let gap_ratio = gap / (item_size as f64).max(1.0);
        let scarcity = if fitting_bins_count <= 2 { 0.6 } else if fitting_bins_count <= 4 { 0.3 } else { 0.2 };
        score += scarcity * gap + 18.0 * gap_ratio.min(2.0);
        if gap < mean_residual {
            let fillable = next_item_size > 0 && gap >= next_item_size as f64;
            let w = if fillable { 0.2 } else { 0.6 };
            score += w * (mean_residual - gap);
        }
        if next_item_size > 0 && gap as u32 == next_item_size {
            score -= 20.0;
        }
        if next_item_size > 1 && gap as u32 == 2 * next_item_size {
            score -= 12.0;
        }
    }

    // Waste too small to be useful later.
    if next_item_size > 0 && pr < next_item_size as f64 {
        let dead_frac = pr / cap;
        let unusable_ratio = pr / (next_item_size as f64).max(1.0);
        score += 0.4 * pr + 30.0 * dead_frac + 12.0 * (1.0 - unusable_ratio);
        if next_item_size - post_residual <= 4 {
            score += 20.0 * (1.0 - progress);
        }
    }

    if post_residual < 10 {
        score += 45.0;
    } else if post_residual < 20 {
        score += 10.0;
    }
    score -= (mean_residual - pr) * 0.6;

    if fitting_bins_count == 1 {
        score -= 12.0;
    }
    let fill = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 20.0 * fill;

    // Anti-fragmentation guard.
    if fitting_bins_count == 2 && post_residual < bin_capacity / 3 {
        score -= 8.0;
    }
    // Tiny unusable slivers when bins are plentiful.
    if post_residual <= 5 && open_bins_count > 6 {
        score += 25.0 * (1.0 - progress);
    }
    // Mid-sized future homes.
    if post_residual >= bin_capacity / 8 && post_residual <= bin_capacity / 2 {
        score -= 6.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size && post_residual <= bin_capacity / 2 {
        score -= 4.0 * (1.0 - progress);
    }
    // Residual can absorb two more average items.
    if pr >= 2.0 * mean_residual && post_residual > 20 {
        score -= 5.0;
    }
    // Compaction sweet spot.
    if next_item_size > 0 && post_residual > next_item_size {
        let headroom = (post_residual - next_item_size) as f64;
        if (headroom - mean_residual).abs() <= 3.0 {
            score -= 7.0;
        }
        if (headroom - mean_residual).abs() <= 1.0 && fitting_bins_count <= 3 {
            score -= 5.0 * (1.0 - progress);
        }
    }
    // Three-way closure.
    if next_item_size > 0 && post_residual == 2 * next_item_size {
        score -= 10.0;
    }
    if next_item_size > 1 && post_residual > next_item_size + 1 && post_residual <= next_item_size + 10 {
        score -= 4.0 * (1.0 - progress);
    }

    // Late-stream consolidation.
    score -= 6.0 * progress * tightness;
    if open_bins_count > 0 {
        let spread = (mean_residual - pr).abs();
        score += 0.05 * spread;
        score -= 0.02 * (open_bins_count as f64) * (bin_residual as f64 / cap);
    }

    // NEW-BIN CANDIDATE.
    if bin_residual == bin_capacity {
        let fresh_left = (bin_capacity - item_size) as f64;
        let item_frac = item_size as f64 / cap;
        let big_next = next_item_size as f64 / cap;
        score += 180.0 - 60.0 * progress + 0.15 * open_bins_count as f64 - 25.0 * big_next;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
        if open_bins_count <= 4 && progress < 0.3 {
            score += 25.0;
        }
        if mean_residual < 15.0 && progress > 0.5 {
            score -= 15.0;
        }
        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3;
        }
        if next_item_size > 0 && fresh_left == next_item_size as f64 {
            score -= 30.0;
        }
        if open_bins_count > 6 && mean_residual > 0.4 * cap {
            score += 20.0;
        }
        // Fresh-bin leftover sliver is wasteful.
        if next_item_size > 0 && fresh_left < next_item_size as f64 && fresh_left < 8.0 {
            score += 35.0;
        }
        // Prefer fresh bin when existing residuals can't host next item.
        if next_item_size > 0 && fitting_bins_count <= 2 && mean_residual < next_item_size as f64 {
            score -= 18.0 * (1.0 - progress);
        }
        if open_bins_count > 8 && mean_residual > next_item_size as f64 + 10.0 {
            score += 12.0;
        }
        if item_frac > 0.6 && next_item_size > 0 && fresh_left >= next_item_size as f64 {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_left >= next_item_size as f64
            && (fresh_left - next_item_size as f64) <= mean_residual {
            score -= 10.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_left > next_item_size as f64 {
            let tail = fresh_left - next_item_size as f64;
            if tail <= 3.0 {
                score -= 14.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_left < next_item_size as f64 && fresh_left < mean_residual * 0.6 {
            score += 10.0;
        }
        if next_item_size > 1 && fresh_left == 2.0 * next_item_size as f64 {
            score -= 12.0;
        }
        if fresh_left <= 2.0 {
            score -= 25.0 * (1.0 - progress);
        }
        if next_item_size > 0 && (fresh_left - mean_residual).abs() <= 2.0 {
            score -= 8.0;
        }
        if next_item_size > 1 && fresh_left >= 2.0 * next_item_size as f64
            && (fresh_left as u32) % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_left > next_item_size as f64
            && ((fresh_left - next_item_size as f64) - mean_residual).abs() <= 3.0 {
            score -= 9.0 * (1.0 - progress);
        }
        // Avoid fresh bin when an open bin nearly seals with this item.
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0;
        }
    }

    score
}

