    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize dead space: small post-residuals that are too small to be useful
    // (nothing else can ever fit in a hole < 1). Weight holes that can't fit
    // the lookahead item, since they likely become waste.
    if next_item_size > 0 && post_residual > 0 {
        let hole_useless = (post_residual as u64) < (next_item_size as u64);
        if hole_useless {
            score += 25.0 + post_residual as f64 * 0.5;
        } else {
            // Residual exactly matching next item is golden
            if post_residual == next_item_size {
                score -= 400.0;
            } else {
                score -= 40.0; // hole can still be filled
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate (empty bin): penalize mildly so we prefer reusing open
    // bins when fits are decent, but keep it competitive when fits are bad.
    if bin_residual == bin_capacity {
        score += 60.0;
        // Opening a new bin is attractive late in the stream when many bins
        // are already open with fragmented residuals.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 120.0 * progress;
        // If mean residual across open bins is small (fragmented), new bin helps.
        if mean_residual < item_size as f64 {
            score -= 80.0;
        }
    }

    // Reward filling bins with large residuals (consolidate space).
    score -= bin_residual as f64 * 0.15;

    // Slight preference for bins whose residual is close to item size
    let tightness = (bin_residual - item_size) as f64;
    score += tightness * 0.3;

    // Time horizon: as stream progresses, be greedier about reusing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 50.0 * progress * (1.0 - tightness / bin_capacity as f64);

    score
}

