    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - progress) + x * (0.5 + 0.5 * progress);
    let mut score = post * (1.0 + 0.8 * poly);

    // Penalize dead space more as stream progresses
    score += 12.0 * progress * x * x * cap;

    // Reward tight fits
    score -= 8.0 * (1.0 - x);

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead: prefer bins leaving room for next item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = (x - nx).abs();
        score += 4.0 * gap * gap * (1.0 - progress);
    }

    // Mild penalty for opening new bins relative to open-bin pressure
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * (open_bins_count as f64).ln().max(0.0);
    }

