        if next_item_size > 0 && fresh_left < next_item_size && fresh_left < 8 {
            score += 35.0 ;
        }
        // prefer fresh bin when all existing residuals are too small for next item
        if next_item_size > 0 && fitting_bins_count <= 2 && mean_residual < next_item_size as f64 {
            score -= 18.0 * (1.0 - progress) ;
        }
        // discourage opening fresh bins late when many half-empty bins exist
        if open_bins_count > 8 && mean_residual > next_item_size as f64 + 10.0 {
            score += 12.0 ;
        }
        // large items into fresh bins leave big usable leftovers: mild reward
        if item_frac > 0.6 && next_item_size > 0 && fresh_left >= next_item_size {
            score -= 8.0 * (1.0 - progress) ;
        }
        // fresh bin justified when leftover can host next item plus mean slack
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress) ;
        }
        // near-zero tail after next item (perfect closure)
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size ;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress) ;
            }
        }
        // fresh bin leftover below mean residual is likely dead space
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        // chain home: leftover hosts next item twice exactly
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        // near-exact fill wastes nothing and preserves all open residuals
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        // fresh bin leftover matching mean residual — reusable home shape
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        // chain home: leftover hosts next item multiple times exactly
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        // fresh bin leftover that hosts next item plus mean-shaped slack
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        // avoid opening fresh bins when a fitting open bin nearly seals with this item
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        // fresh-bin leftover that cannot host next item but is large: dead space guard
        if next_item_size > 0 && fresh_left < next_item_size && fresh_left >= 8 {
            score += 0.3 * fresh_left as f64 * (1.0 - progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity fractions (1/4, 1/2, 3/4)
    let q = bin_capacity / 4;
    let frac_class = post_residual / q; // 0..4
    match frac_class {
        0 => score -= 30.0,                       // near-perfect fill
        1 => score += 5.0,                        // awkward small dead space
        2 => score += 0.0,                        // half-full: flexible
        3 => score -= 10.0,                       // roomy bin, good target
        _ => score -= 15.0,                       // empty/new bin bonus
    }

    // Modulo arithmetic on post_residual: values that pair with common sizes (10..80)
    let m = post_residual % 10;
    if m == 0 {
        score -= 8.0; // divisible by 10: likely exact pairing with future item
    } else {
        score += m as f64 * 1.5; // ragged residual penalized
    }

    // Lookahead harmonic class of next_item_size
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits here too: strong reward, scaled by leftover
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 + slack * 0.3;
            // exact chain fill
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            // next item won't fit here; penalize more if this bin becomes a dead-end
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.4;
        }
        // modulo coupling: next_item_size and post_residual share harmonic residue
        if post_residual % 10 == next_item_size % 10 && post_residual >= next_item_size {
            score -= 6.0;
        }
    } else {
        // last item: minimize waste aggressively
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: only attractive late in stream or when bin is empty & residual waste high
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress; // early: keep bins open; late: fresh bin ok
        if mean_residual < item_size as f64 {
            score -= 10.0; // no open bin realistically useful
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure)
    score -= (bin_capacity - bin_residual) as f64 * 0.15;
    if open_bins_count > 4 {
        score += 0.5 * (open_bins_count as f64 - 4.0);
    }

    // Tight-fit reward: item consumes most of the bin
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.8 {
        score -= 12.0 * (fill - 0.8) * 5.0;
    }

    score
}

