    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100 range)
    // are pure waste -> heavy penalty scaled by how "dead" the gap is.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0 * (10.0 - post_residual as f64);
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Reward leaving a gap that the lookahead item can exactly use (k=2 lookahead).
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 120.0;
        } else if gap > 0 && gap < 10 {
            score += 100.0; // would create dead space for next item
        } else if gap > 0 {
            score -= 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // Open-bin pressure: discourage proliferating bins when mean residual is large.
    score += open_bins_count as f64 * (mean_residual / bin_capacity as f64) * 8.0;

    // New-bin candidate: neutral-ish baseline; only attractive when existing
    // fits are poor. Penalize slightly so tight fits into open bins win,
    // but keep it competitive when dead space would be created.
    if bin_residual == bin_capacity {
        score += 40.0;
        if item_size >= 60 {
            score -= 30.0; // large items start fresh bins happily
        }
    }

    // Tight-fit gradient: prefer smaller post_residual nonlinearly.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64) * 0.5;

    score
}

