pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: perfect match with next item is ideal.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // next item exactly fills this bin
        } else if post_residual >= next_item_size {
            // next item fits; reward tightness of the two-step chain
            score -= 25.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
        } else {
            // dead space that next item cannot use
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize large unusable residuals generally (dead space below min item size)
    if post_residual < 10 {
        score += 40.0; // tiny unusable sliver
    }

    // Prefer tight fits relative to current residual
    score += 0.15 * (bin_residual - item_size) as f64;

    // Last-chance bonus: only bin that fits -> avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when residuals of open bins are poor
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - item_size as f64).max(0.0);
        score += 15.0 - mean_gap * 0.5; // penalize new bin unless open bins are tight
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Mild pressure to consolidate as stream progresses
    score += 5.0 * (step_index as f64 / total_items.max(1) as f64);

    score
}

