    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, especially exact fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Penalize large dead space relative to capacity.
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * dead_frac * dead_frac;

    // Lookahead: if next item fits the post-residual, this placement is valuable.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
        } else {
            // Wasted space if next item can't use the leftover.
            score += 6.0 * (next_item_size as f64 - post_residual as f64).min(50.0) / 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many fitting bins: mild penalty to prefer the tightest one (handled via base score),
    // but discourage spreading across too many open bins.
    if open_bins_count > 4 {
        score += 0.4 * open_bins_count as f64;
    }

    // Prefer bins whose residual deviates below the mean (consolidating emptier bins).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Time horizon: early in the stream, be pickier about residual quality;
    // late in the stream, just fill anything.
    let t = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * (1.0 - t);

    // New-bin candidate: make it moderately attractive only when nothing fits well.
    if bin_residual == bin_capacity {
        let bad_fit = fitting_bins_count == 0
            || (post_residual as f64) > 0.5 * bin_capacity as f64;
        if bad_fit {
            score -= 45.0;
        } else {
            score += 55.0;
        }
    }

    score
}

