pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post_residual, with non-linear sharpening
    let mut score = pr * (1.0 + 0.8 * pr_norm * pr_norm);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals (keep bins flexible);
    // late, aggressively minimize dead space.
    let progress_coupling = pr_norm * pr_norm * (1.0 - progress) * (1.0 - progress);
    score += 40.0 * progress_coupling;

    // Penalty for residuals that no plausible next item can use, weighted smoothly by progress
    if next_item_size > 0 {
        let waste = (pr - next_item_size as f64).max(0.0);
        score += 0.5 * waste * (0.3 + progress);
    }

    // Reward tight fits (post_residual near zero) with smooth term
    score -= 15.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Mild penalty when bin residual deviates from mean residual (keeps bin diversity)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Slight preference for filling bins when many bins are open
    score += 0.3 * (open_bins_count as f64) * pr_norm * pr_norm;

    score
}

