pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into
    // "reusable" classes (likely to fit future items), penalize dead space.
    let cap = bin_capacity as f64;

    // Class A: post_residual divisible by common item granularity (10, 20, 25)
    if post_residual % 10 == 0 {
        score -= 8.0;
        if post_residual % 20 == 0 { score -= 4.0; }
        if post_residual % 25 == 0 { score -= 3.0; }
    } else {
        // Non-round residual: penalize by distance to nearest multiple of 10
        let d = (post_residual % 10).min(10 - post_residual % 10) as f64;
        score += d * 0.8;
    }

    // Integer-division thresholds: post_residual in [1,10] is near-dead space
    let dead = post_residual / 10; // 0 => dead zone
    if dead == 0 && post_residual > 0 {
        score += 15.0;
    } else if dead == 1 {
        score += 4.0;
    }

    // Reward perfect fits
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack % 10 == 0 { score -= 5.0; }
            score += (slack as f64).sqrt() * 0.5;
        } else {
            // next item cannot use this bin's remainder; mild penalty if residual small
            score += 2.0;
        }
    }

    // Last-chance bin: strong preference to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: make empty bins attractive only when
    // open bins would leave bad residuals, else discourage proliferation.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let mean_fit = if mean_residual >= item_size as f64 { 1.0 } else { 0.0 };
        // base cost of a new bin, discounted when no bin fits or residuals are fragmented
        let mut new_bin_cost = 30.0;
        if pressure > 0.0 { new_bin_cost -= 20.0; }
        if mean_residual < 15.0 { new_bin_cost -= 8.0; }
        if mean_fit > 0.0 && post_residual % 10 == 0 { new_bin_cost += 10.0; }
        // scale with stream progression: later items, more willing to open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_cost -= progress * 5.0;
        score += new_bin_cost;
    }

    // Mild preference for tighter bins among open bins (best-fit flavor)
    score += (bin_residual as f64) * 0.05;

    // Penalize bins far from mean residual (fragmentation control)
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += diff * 0.03;

    // Small penalty for many open bins (encourage consolidation)
    score += open_bins_count as f64 * 0.02;

    score
}

