        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard dead-space zones: residuals 1..=10 are almost unusable (min item 1, but tiny gaps waste capacity).
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0;
    }
    // Residuals 11..=20 are risky if the next item is larger than the gap.
    if post_residual > 10 && post_residual < 21 {
        score += 15.0;
    }

    // Perfect or near-perfect fits get strong rewards.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // If the next item exactly fits the post residual, strongly favor this bin.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        // Next item fits in the gap: mild reward proportional to how much of the gap it uses.
        let usage = next_item_size as f64 / post_residual as f64;
        score -= 20.0 * usage;
    } else if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        // Next item cannot use the gap: penalize proportionally to gap size.
        score += 0.3 * post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity && post_residual <= 30 {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_penalty = 12.0 + 0.15 * open_bins_count as f64 + 10.0 * progress;
    if bin_residual == bin_capacity {
        // Candidate for a brand-new bin: base cost plus pressure.
        score += new_bin_penalty;
        // Opening a new bin is only attractive if no existing bin gives a tight fit.
        if fitting_bins_count > 0 {
            let best_possible_waste = if post_residual >= 0 { post_residual as f64 } else { 0.0 };
            let _ = best_possible_waste;
            score += 25.0;
        }
    } else {
        // Existing bin: small reward for keeping the number of open bins stable.
        score -= 0.05 * open_bins_count as f64;
        // Prefer bins whose residual is already below the mean (consolidating tightness).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 1.0;
        }
    }

    // Mild global tightness bonus: tighter overall fit relative to mean residual is better.
    score -= (bin_capacity as f64 - mean_residual).signum() * 0.5;

    score
}

