pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 * (1.0 - slack / bin_capacity as f64);
            // chain fit: next item leaves residual that is small
            let chain = post_residual - next_item_size;
            if chain <= 10 {
                score -= 150.0;
            }
        } else {
            // next item cannot follow into this bin: penalize dead space
            score += 80.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Relative to mean residual: prefer bins below mean residual (tighter bins first)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize opening new bin when a decent fit exists elsewhere
    if bin_residual == bin_capacity {
        score += 120.0;
        if next_item_size > 0 && item_size == next_item_size {
            score -= 60.0;
        }
    }

    // Slight preference for bins with low absolute residual (fill fuller bins)
    score += 0.1 * post_residual as f64;

    // Progress term: near the end, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

