pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic penalty on wasted space.
    score += 0.9 * (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item can fit into post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.05 * next_item_size as f64;
        } else {
            // Dead space relative to the upcoming item.
            score += 0.3 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let pressure = fitting_bins_count as f64;
        // Penalize new bins when fitting bins exist, more so early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 12.0 + 8.0 * pressure - 6.0 * progress;
        // If item leaves a large hole in a fresh bin, mild penalty.
        score += 0.1 * post_residual as f64;
    }

    // Global state coupling: penalize bins whose residual deviates from the mean
    // (prefer balanced residual distribution to keep options open).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Slightly prefer fuller bins overall.
    score -= 0.05 * (item_size as f64);

    score
}

