pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo 10 quantizes dead space quality.
    let pr = post_residual;
    let residue_class = pr % 10;
    // Dead space that is not reusable by common small items (1..=10) is penalized.
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 2.0; // tiny slivers are nearly useless
    }
    // Reward post_residuals that are "harmonic" multiples of 10 (nice packing targets).
    if residue_class == 0 && pr > 0 {
        score -= 6.0;
    } else if residue_class <= 2 {
        score += residue_class as f64;
    }

    // Integer-division threshold: if post_residual can exactly host next item, big reward.
    if next_item_size > 0 {
        if pr >= next_item_size {
            // next item fits here: strong bonus, scaled by tightness of the chain
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 - slack * 0.15;
            // harmonic chain: post_residual / next_item_size leaves a good remainder
            if (pr % next_item_size.max(1)) == 0 {
                score -= 5.0;
            }
        } else {
            // next item won't fit: penalize unless this bin was a last chance
            score += 4.0;
            if pr < 10 {
                score += 3.0; // bin becomes dead after this placement
            }
        }
    }

    // Last-chance bin (only fitting bin): reward strongly to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: make it moderately unattractive unless current bin is hopeless.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Early in the stream, opening bins is cheaper (more future items to pair).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * (1.0 - progress);
        // If item is huge (>= 70), pairing it with future small items in a fresh bin is fine.
        if item_size >= 70 {
            score -= 10.0;
        }
    }

    // Prefer filling bins far below the mean residual (tightest bin first).
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;

    // Capacity fraction coupling: reward placements leaving residual near capacity fractions
    // that are classic harmonic anchors (25, 50, 75).
    for anchor in [25u32, 50u32, 75u32] {
        if pr == anchor {
            score -= 4.0;
        }
    }

    // Mild penalty for very large waste relative to capacity.
    score += (pr as f64 / bin_capacity as f64) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
