    // Reward tight fits (small post_residual) exponentially.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Exact seal: nearly always the best move.
    if post_residual == 0 {
        score -= 900.0;
    }

    // Penalize dead space too small to be useful later.
    if post_residual > 0 {
        let waste = post_residual as f64;
        let usable = if next_item_size > 0 { next_item_size as f64 } else { 1.0 };
        if waste < usable {
            score += 6.0 * (usable - waste);
            // near-seal sliver: good late, bad early
            if waste <= 3.0 {
