    // Time horizon: late in the stream, prefer consolidating.
    score -= 6.0 * progress * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Global state coupling: prefer filling existing bins.
    if open_bins_count > 0 {
        let spread = (mean_residual - bin_residual as f64).abs();
        score += 0.05 * spread;
        score -= 0.02 * (open_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64);
    }

    // Fill ratio reward: bigger relative bite into the bin.
    let fill = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 20.0 * fill;

    // Small unusable residuals are costly.
    if post_residual < 10 {
        score += 45.0 * (1.0 - progress);
    } else if post_residual < 20 {
        score += 10.0;
    }

    // NEW-BIN CANDIDATE: default unattractive; open only when justified.
    if bin_residual == bin_capacity {
        let fresh_left = bin_capacity - item_size;
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 20.0 - 25.0 * pressure;
        score += 10.0 * progress;
        // fresh-bin leftover sliver is wasteful
        if next_item_size > 0 && fresh_left < next_item_size && fresh_left < 8 {
