    // Base: prefer tight fits, penalize dead space relative to capacity.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio;

    // Aggressive 2-step lookahead: reward when post_residual matches next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect chain: next item exactly fills remaining space.
            score -= 45.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow here; penalize proportionally to overshoot.
            let miss = (next_item_size - post_residual) as f64;
            score += 25.0 * (miss / bin_capacity as f64);
        }
    } else {
        // Last item: just minimize residual.
        score += 0.0;
    }

    // Coupling with mean residual: bins far below mean are "rich" — favor filling them.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it unattractive unless current bin fits are terrible.
    if bin_residual == bin_capacity {
        score += 40.0 + 0.3 * open_bins_count as f64;
