        if next_item_size > 60 {
            score -= 25.0;
        }
    }

    // Late-stream urgency: consolidate more aggressively as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * fit_ratio;

    score
}

