        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        // chain home: leftover hosts next item twice exactly
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        // near-exact fill wastes nothing and preserves all open residuals
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        // fresh bin leftover matching mean residual — reusable home shape
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        // chain home: leftover hosts next item multiple times exactly
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        // fresh bin leftover that hosts next item plus mean-shaped slack
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        // avoid opening fresh bins when a fitting open bin nearly seals with this item
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        // NEW: fresh bin penalized when an open bin's post_residual is an exact chain home
        if next_item_size > 0 && post_residual >= next_item_size && post_residual % next_item_size.max(1) == 0 {
            score += 10.0 ;
        }
        // NEW: fresh bin better when item is large and no open bin can host next item after this fit
        if next_item_size > 0 && item_frac > 0.5 && fitting_bins_count <= 3 && post_residual < next_item_size {
            score -= 12.0 * (1.0 - progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to item size)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 30.0;

    // Penalize dead space: post residuals too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: reward if next item fits exactly or well into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= next_fit * 20.0;
        } else {
            // next item cannot use this bin's leftover: mild penalty for large leftover
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Time horizon: early in stream, be more selective (penalize loose fits);
    // late in stream, prioritize closing bins out
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64) * 0.1;
    score -= progress * 10.0;

    // Global state: many open bins with high mean residual -> prefer filling existing bins
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 55.0;
        // but if current bin fit is terrible, new bin becomes competitive
        if fit_ratio < 0.5 {
            score -= 45.0;
        }
        if post_residual >= 90 {
            score -= 20.0; // fresh bin keeps flexibility
        }
    }

    // Penalize very large post_residual when item is small (wasteful placement)
    if (post_residual as f64) > 0.7 * bin_capacity as f64 && item_size < 30 {
        score += 15.0;
    }

    score
}

