pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10 define
    // "usable" classes. Small post_residuals in low-residue classes are
    // dead space; penalize them, reward post_residuals landing in
    // highly reusable classes (multiples of 10, especially 10..30).
    let r = post_residual % 10;
    let class = post_residual / 10;

    // Penalize awkward residues: 1..9 residuals are harder to fill later.
    if r != 0 {
        score += (10 - r) as f64 * 0.6;
    } else {
        score -= 3.0; // clean multiple of 10 is a good landing spot
    }

    // Reward mid-range classes (10..=30 post residual) which pair well
    // with typical item sizes (10..80).
    match class {
        0 => score += 8.0,          // nearly full: excellent
        1 | 2 | 3 => score -= 4.0,  // sweet spot for future small items
        4 | 5 => score += 0.0,
        6 | 7 => score += 2.0,
        _ => score += 5.0,          // large leftover: wasteful placement
    }

    // Lookahead coupling: if the next item fits exactly into post_residual
    // (same harmonic class), strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
            let gap = post_residual - next_item_size;
            if gap % 10 == 0 { score -= 4.0; }
        } else {
            // next item cannot follow here; slight penalty, stronger
            // if post_residual is a tiny dead zone
            if post_residual < 10 { score += 6.0; }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 12.0;
        if post_residual <= 10 { score -= 8.0; }
    }

    // New-bin candidate: empty bin has huge post_residual. Make it
    // attractive only when the current bin would leave bad dead space
    // or when mean residual is already tight.
    if bin_residual == bin_capacity {
        // neutral baseline for a fresh bin
        score -= 2.0;
        if post_residual < item_size + 10 && item_size > 50 {
            score -= 6.0; // large items start fresh bins happily
        }
    } else if post_residual as f64 > mean_residual + 20.0 {
        // placing here leaves more slack than average: mild penalty
        score += 4.0;
    }

    // Late in the stream, prefer tightening bins (less waste to carry).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64) * 0.05;
    score -= progress * (open_bins_count as f64) * 0.15;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
