    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    let dead_zone: f64 = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 8.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Reward fits that leave room for the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap that neither closes the bin nor fits the next item: extra penalty.
        score += 6.0;
    }

    // Last-chance pressure: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_penalty = open_bins_count as f64 * (2.0 + 4.0 * progress);
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: only attractive when current bin would waste a lot.
        score += 30.0 + new_bin_penalty;
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 10.0;
        }
    } else {
        // Mild reward for filling bins tighter than the current average residual.
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

