pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward near-zero post residual.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // 2-step lookahead: reward when next item fits exactly into post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual > next_item_size {
            // Next item fits: small leftover after that is good.
            let two_step_leftover = post_residual - next_item_size;
            score -= 40.0 - (two_step_leftover as f64) * 0.4;
        } else {
            // Next item cannot follow: penalize proportional to gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.6;
        }
    }

    // Penalize dead space relative to mean residual of open bins.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += (pr - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - pr) * 0.15;
    }

    // Last-chance bin: avoid wasting the only fitting bin on a bad fit,
    // but reward using it on a good fit.
    if fitting_bins_count == 1 {
        if post_residual <= 20 {
            score -= 30.0;
        } else {
            score += 25.0;
        }
    }

    // Late in stream: prefer tightening existing bins, discourage opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 10.0;

    // New-bin candidate: only attractive when item is huge and no good fit exists.
    if bin_residual == bin_capacity {
        if item_size >= 80 {
            score -= 15.0;
        } else {
            score += 45.0;
        }
    }

    score
}

