pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post_residual (tight fit), non-linearly
    let mut score = pr * (1.0 + 0.8 * pr / cap) - 0.5 * (pr / cap) * (1.0 - pr / cap) * cap;

    // Polynomial coupling with stream progress: early on, tolerate loose fits;
    // late in the stream, demand tighter packing (penalize residual more).
    let tightness = 1.0 + 2.5 * progress * progress + 1.5 * progress;
    score *= tightness;

    // Penalize dead space relative to mean residual of open bins (smooth interaction)
    score += 0.6 * (pr - mean_residual) * (1.0 + progress);

    // Reward using bins that are hard to fill otherwise
    if fitting_bins_count <= 1 {
        score -= 12.0 * (1.0 - progress);
    }

    // Lookahead: bonus if next item fits in post_residual (smooth quadratic reward)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = pr - nxt;
        if fit_gap >= 0.0 {
            score -= 4.0 * (1.0 - (fit_gap / cap).powf(2.0));
        } else {
            score += 2.0 * (-fit_gap / cap);
        }
    }

    // Slight preference for keeping fewer open bins early, more consolidation late
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: only attractive when the item is large and fits nowhere well
    if bin_residual == bin_capacity {
        let large = item_size as f64 / cap;
        score += 6.0 + 20.0 * (1.0 - large) - 10.0 * progress;
    }

    score
}

