        }
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size ;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress) ;
            }
        }
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible item (1..100 unknown distribution) are wasted space.
    // Penalize "unusable" gaps heavily: a post_residual below ~10 can likely
    // never be filled, while gaps of 10..=25 are risky.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // almost certainly dead space
        } else if post_residual <= 25 {
            score += 25.0; // risky small gap
        } else if post_residual <= 40 {
            score += 8.0; // moderately usable
        }
    }

    // Reward near-perfect fits (post_residual close to 0 handled above; here
    // reward exact tight packing).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits into this bin's post_residual,
    // reward the placement strongly (keeps chains tight).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + (next_item_size as f64) * 0.2;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // post_residual blocks the next item: penalize proportionally.
        score += 12.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (avoid bin proliferation).
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: make opening a new bin mildly expensive so it only
    // wins when fits into open bins are truly bad (large dead space).
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.3;
    } else {
        // Slight preference for bins whose residual deviates from the mean
        // in the "tighter" direction (consolidate slack).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Stream progression: early on, be a bit more willing to open bins;
    // later, pack tightly (amplify dead-space pressure over time).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
