pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: neutral baseline, adjusted by context.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when current item fits poorly everywhere
        // or the lookahead item is large and would waste space elsewhere.
        let tight_fit_penalty = if next_item_size > 0 && next_item_size > post_residual { -18.0 } else { 0.0 };
        let scarcity_bonus = if fitting_bins_count <= 1 { -12.0 } else { 0.0 };
        let early_bonus = if (step_index as f64 / total_items.max(1) as f64) < 0.35 { -4.0 } else { 0.0 };
        return 100.0 + tight_fit_penalty + scarcity_bonus + early_bonus;
    }

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward when post_residual can host next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0; // perfect chain
        } else if post_residual >= next_item_size {
            // reward proportional to how snugly the next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / 60.0).max(0.0);
        } else {
            // dead space relative to lookahead item: penalize
            let gap = (next_item_size - post_residual) as f64;
            score += 0.6 * gap.min(60.0);
        }
    }

    // Penalize post_residual in the "unusable zone" (small but nonzero leftovers
    // that few future items can fill, given min item size ~10).
    if post_residual > 0 && post_residual < 12 {
        score += 14.0;
    }

    // Compare against mean residual across open bins: prefer bins whose post
    // residual is below the mean (tighter packing), reward deviation.
    score += 0.35 * (mean_residual - post_residual as f64).max(-40.0);

    // Last-chance bin before opening a new bin: strong reward.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Slight preference for consolidating into fewer bins when many are open.
    score += 0.25 * open_bins_count as f64;

    // Reward larger items placed into larger residual bins (avoid wasting big space on small items).
    score -= 0.15 * item_size as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

