    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that cannot fit a plausible future item.
    if post_residual > 0 {
        if (post_residual as f64) < 10.0 {
            score += 6.0; // tiny unusable sliver
        } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
            score += 3.0; // lookahead item won't fit here after placement
        } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 4.0; // lookahead chains nicely into this bin
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let best_open_residual = mean_residual; // proxy for fit quality of open bins
        let open_fit_quality = if bin_residual as f64 - best_open_residual > 0.0 {
            (bin_residual as f64 - best_open_residual) / bin_capacity as f64
        } else {
            0.0
        };
        // Opening a new bin is penalized early, tolerated late or when open bins are fragmented.
        score += 15.0 - 8.0 * progress - 10.0 * open_fit_quality + 0.15 * open_bins_count as f64;
