    // Mild preference for filling bins with larger residuals (consolidate space).
    score -= 0.02 * bin_residual as f64;

    // Slight time-adaptive pressure: as stream ends, waste matters more.
    let horizon = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * horizon * (post_residual as f64 / bin_capacity as f64);

    score
}

