    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;
    let is_new = (bin_residual as f64 - cap).abs() < 0.5;

    // Base: quadratic penalty on wasted space, modulated by stream progress
    let mut score = prn * prn * (1.0 + progress);

    // Non-linear coupling: small post-residuals become more valuable as stream advances
    score -= (1.0 - prn) * (1.0 - prn) * 0.5 * (1.0 + progress);

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && !is_new {
        score -= 10.0 + 5.0 * progress;
    }

    // Penalize new bins when good fits exist, more so early in the stream
    if is_new {
        score += 3.0 + 4.0 * (1.0 - progress) + 0.02 * open_bins_count as f64;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 1.5 + (next_item_size as f64 / cap);
    } else if next_item_size > 0 && pr > 0 {
        score += 0.5 * (1.0 - (pr / next_item_size.max(1) as f64).min(1.0));
