    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues that are "dead space"
    // (small, hard-to-fill leftovers) get penalized via capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit reward: post_residual exactly divides capacity into harmonic classes
    if post_residual == 0 {
        score -= 1000.0;
    } else if bin_capacity % post_residual == 0 {
        // residual that tiles the bin (50, 25, 20, 10, ...) is reusable
        score -= 30.0 * (cap / post).min(4.0);
    }

    // Dead-space penalty: residual below typical small item sizes is nearly unusable
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Integer-division threshold classes on post_residual
    let post_class = post_residual / 10; // 0..10 harmonic decile
    score -= 3.0 * post_class as f64;

    // Lookahead coupling: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item can follow: reward proportional to how well it packs
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 + 20.0 * (1.0 - slack / cap);
            if (post_residual % next_item_size) == 0 {
                score -= 20.0; // exact tiling with next item
            }
        } else {
            // next item won't fit here: mild penalty scaled by mismatch
            score += 8.0 + 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when no open bin has decent fit;
    // opening a bin wastes the mean residual of open bins.
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual.max(0.0);
        score += 40.0 + 0.5 * avg_waste;
        // early in the stream, opening bins is cheaper (more future items to fill them)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress);
        // large items justify fresh bins
        if item_size > bin_capacity / 2 {
            score -= 25.0;
        }
        // if next item is huge, a fresh bin is flexible
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Prefer tighter bins generally: closeness of fit reward
    score -= 10.0 * (1.0 - (item_size as f64 / bin_residual as f64).min(1.0));

    // Congestion: many open bins -> consolidate, penalize spreading
    score += 0.5 * open_bins_count as f64 * (mean_residual / cap).max(0.0);

    // Modulo harmonic nudge: residuals in friendly residue classes mod 10
    if post_residual % 10 == 0 {
        score -= 5.0;
    }

    score
}

