pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small for any item (1..10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small awkward gaps (10..25) are partially unusable; penalize softly.
    if post_residual >= 10 && post_residual < 25 {
        score += 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Prefer bins whose residual was already small (tight packing).
    score += (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Last fitting bin: strong reward to use it, else we must open a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling existing.
    score += (open_bins_count as f64) * 2.0;

    // If this is the empty new-bin candidate, penalize unless item is large relative to capacity
    // or no real alternatives exist (fitting_bins_count==1 means only new bin can take it).
    if bin_residual == bin_capacity {
        let big_item = (item_size as f64) > 0.7 * (bin_capacity as f64);
        if fitting_bins_count <= 1 || big_item {
            score -= 25.0;
        } else {
            score += 20.0;
        }
    }

    // Lookahead: if next item fits the post_residual well, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let leftover = post_residual - next_item_size;
        if leftover < 10 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        // next item can't use this tiny gap: dead space confirmed.
        score += 25.0;
    }

    // Mean residual coupling: keep this bin's residual near the mean to balance bins.
    score += ((post_residual as f64 - mean_residual).abs()) * 0.3;

    // Late in stream: be more conservative, prefer tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.5;

    score
}

