}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already favored by starting value).

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // accommodates the next item (perfect 2-item chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // perfect 2-item match
        } else if post_residual >= next_item_size {
            // slack after both items: penalize proportionally to leftover
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.25;
        } else {
            // next item cannot fit here: penalize dead space
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.6;
        }
    }

    // Penalize unusable slivers (post_residual too small for any item, min size 1..10)
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 10.0; // perfect closure of the bin
    }

    // Relative-to-mean coupling: bins tighter than average are better targets
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: keep empty-bin score neutral-high unless
    // no open bin offers a decent fit (post_residual of candidates would be large).
    if bin_residual == bin_capacity {
        score += 5.0 + (open_bins_count as f64) * 0.1;
        // if next item is huge, opening fresh may be wise
        if next_item_size > 70 {
            score -= 15.0;
        }
    }

    // Stream progression: early on, be slightly more willing to open bins
    // (builds a diverse residual portfolio); late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0 * (bin_residual != bin_capacity) as u8 as f64;
    score += (1.0 - progress) * 3.0 * (bin_residual == bin_capacity) as u8 as f64;

    score
}

