pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness reward: strongly favor small post residuals (non-linear).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tight * tight * item_size as f64;

    // Penalize unusable dead space: residual too small for the smallest plausible item (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    } else if post_residual < 20 {
        score += 4.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 0.5 * item_size as f64;
    }

    // Lookahead coupling: reward bins whose post residual can still host the next item,
    // punish bins that would strand it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            score += 3.0 * (next_item_size as f64 - post_residual as f64) / 10.0;
        }
        // Perfect chain: post residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // New-bin candidate handling: empty bin should only win when it's genuinely better.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin only wins over very poor fits.
        score += 25.0;
        // Early in the stream, opening bins is cheap and flexible.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // If many bins are open but none fit well, a fresh bin is attractive.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // If only this new bin fits, it's mandatory anyway.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // Late in the stream, consolidate into existing bins.
        score += 10.0 * progress;
    }

    // Global-state coupling: when mean residual across open bins is high, prefer
    // bins below the mean (balancing), when mean is low, prefer filling tight bins.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    if mean_residual > 40.0 {
        score += 8.0 * dev; // favor below-mean (tighter) bins? no: higher residual = looser
        // Correction: high mean residual -> we want to drain the loosest bins first.
        score -= 16.0 * dev;
    } else {
        score += 6.0 * dev; // low mean residual -> prefer bins with more room (less deviance)
    }

    // Open-bin count pressure: many open bins -> discourage spreading, encourage consolidation.
    if open_bins_count > 8 {
        score += 0.5 * open_bins_count as f64 * 0.1;
        if bin_residual != bin_capacity {
            score -= 2.0;
        }
    }

    // Progress-aware slack: as stream advances, demand tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

