            score -= 3.0 * (1.0 - ((pr - nx) / cap)) * (1.0 - progress);
        } else {
            score += 2.0;
        }
    }
    // new-bin candidate: prefer opening fresh bin only when existing fits are poor
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + 2.0 * (fitting_bins_count as f64);
    }
    score
}

