pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that divide capacity evenly
    // (perfect fits / re-usable classes), penalize awkward leftovers.
    let post = post_residual;
    if post == 0 {
        score -= 1000.0; // perfect fill — best possible outcome
    } else if bin_capacity % post == 0 {
        score -= 60.0; // residual is a divisor class of capacity (e.g. 50, 25, 20)
    } else if post % 10 == 0 {
        score -= 25.0; // decile class — commonly reusable
    } else if post < 10 {
        score += 80.0; // dead space below smallest item size
    } else {
        score += (post % 10) as f64 * 3.0; // fractional-class penalty
    }

    // Coupling with lookahead: if next item fits exactly in the post residual,
    // strongly reward this placement (chained fit).
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 120.0;
        } else if next_item_size <= post {
            score -= (post - next_item_size) as f64 * 0.8;
        } else {
            // next item cannot use this residual; penalize proportionally
            score += (next_item_size - post).min(bin_capacity) as f64 * 0.3;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Prefer tighter bins overall (small residual before placement).
    score += (bin_residual as f64 / cap) * 20.0;

    // Late in the stream, consolidate: favor existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses or many bins open.
        score += 30.0 + 70.0 * progress + (open_bins_count as f64) * 2.0;
    } else {
        score -= 10.0 * progress;
    }

    // Mean-residual coupling: if this bin is far below average residual, it is
    // "tight" — reward using it to balance residual distribution.
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.15;

    score
}

