pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    let dead_zone = 12.0;
    if post_residual > 0 && post_residual <= dead_zone {
        score += (dead_zone - post_residual as f64) * 4.0;
    }

    // Reward tight fits (small post_residual, including perfect fits).
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual <= next_item_size as f64 && next_item_size > 0 {
        score -= 8.0; // residual likely reusable by lookahead item
    }

    // Penalize opening new bins when plenty of bins already fit the item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = open_bins_count as f64 * 0.8;
        score += 10.0 + pressure;
        if fitting_bins_count > 0 && post_residual as f64 > dead_zone {
            score += 15.0; // strongly discourage new bin when decent fits exist
        }
    } else if fitting_bins_count == 1 {
        // Last chance bin: strongly favor using it to avoid opening a bin.
        score -= 12.0;
    }

    // Mild penalty proportional to leftover relative to bin capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 5.0;

    // Encourage balancing residuals toward the mean early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post_residual as f64).abs() * 0.05 * (1.0 - progress);

    score
}

