pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 20.0;

    // Penalize very small dead space that is hard to fill later (<10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use the leftover: penalize creating stranded space.
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin when good fits exist.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin, softened when many bins are open or stream is late.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 30.0 + open_bins_count as f64 * 2.0;
        new_bin_penalty *= (1.0 - 0.5 * progress);
        // If mean residual is large, opening a new bin wastes existing capacity.
        new_bin_penalty += mean_residual * 0.3;
        // If no other bin fits (fitting_bins_count == 1 means only this candidate or one bin), allow it.
        if fitting_bins_count == 1 {
            new_bin_penalty -= 45.0;
        }
        score += new_bin_penalty;
    }

    // Slight preference for filling bins with larger residual when many bins open (consolidation).
    score -= 0.05 * bin_residual as f64 * (open_bins_count as f64).ln().max(0.0);

    score
}

