pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space hurts more, so amplify quadratic waste.
    let waste = post_residual as f64 / bin_capacity as f64;
    let progress_coupling = waste * waste * (0.5 + 2.0 * progress * progress);
    score += 40.0 * progress_coupling;

    // Reward near-perfect fits with a smooth cubic bonus on tightness.
    let tightness = 1.0 - waste;
    score -= 25.0 * tightness * tightness * tightness;

    // Lookahead: reward bins whose post-residual can host the next item,
    // scaled smoothly by how well the next item fills the remaining space.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fill = next_item_size as f64 / post_residual as f64;
        score -= 15.0 * fill * (1.0 + progress);
    } else if next_item_size > 0 {
        // penalize stranding a chunk that the next item can't use
        score += 8.0 * progress;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // Mild penalty when this bin is far above the mean residual (keeps bins balanced),
    // and a mild reward for picking below-mean bins.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev * dev / bin_capacity as f64;

    // New-bin candidate: make it attractive only for large items that would
    // leave open bins with good residuals; otherwise penalize opening bins.
    if bin_residual == bin_capacity {
        let frac_open = if open_bins_count > 0 { 1.0 / open_bins_count as f64 } else { 1.0 };
