pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: tiny leftovers are nearly unusable (items >= 1..=100, but small scraps waste bins)
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    } else if post_residual < 20 {
        score += 6.0;
    }

    // Harmonic class logic: penalize by residue class modulo 10 (fractional capacity alignment)
    let residue_class = (post_residual % 10) as f64;
    score += residue_class * 0.35;

    // Integer-division threshold: post_residual / 10 class
    let class_div = post_residual / 10;
    if class_div == 0 {
        score += 4.0; // very tight bin, likely dead end
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 7.0;
            // extra reward if next item fills it nearly perfectly
            if post_residual - next_item_size < 5 {
                score -= 5.0;
            }
        } else if post_residual < 20 {
            score += 9.0; // would strand this bin
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 14.0;
    }

    // New-bin candidate: penalize mildly, scaled by how much slack open bins already have
    if bin_residual == bin_capacity {
        score += 6.0 + mean_residual * 0.25 + (open_bins_count as f64) * 0.5;
    }

    // Reward large items in tight bins (tight-fill coupling)
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    // Progression: late in the stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

