                    score -= 5.0 + 4.0 * (1.0 - progress) ;
                }
                // NEW: two-step chain where leftover equals next item + small sliver <= 2
                if after_next >= 1 && after_next <= 2 {
                    score -= 10.0 * (1.0 - progress) ;
