        // of capacity is a strong reusable home
        if fresh_left >= bin_capacity / 3 && bin_capacity % fresh_left != 0 && fresh_left % 10 == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        // NEW: never open a fresh bin when some open bin seals exactly with this item
        if post_residual == 0 || (next_item_size > 0 && post_residual == next_item_size) {
            score += 60.0 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // matches the next item size, penalize near-misses that strand space.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as u32 >= next_item_size {
            // Next item can chain into this bin: reward closeness.
            score -= 30.0 * (1.0 - diff / bin_capacity as f64);
            if diff < 1.0 {
                score -= 25.0; // perfect chain
            }
        } else {
            // Next item cannot fit in leftover: dead-space penalty scaled
            // by how much space is stranded.
            score += 0.5 * post_residual as f64;
        }
    }

    // Compare against mean residual: bins below mean residual are already
    // well-used; prefer packing into fuller bins relative to the fleet.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        score += 10.0 * (rel - 1.0).abs().min(3.0) * if rel > 1.0 { 1.0 } else { -0.3 };
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless this is the only
    // fitting option and existing bins are too full for good fits.
    if bin_residual == bin_capacity {
        score += 60.0;
        if next_item_size > 0 && post_residual as u32 >= next_item_size {
            // Opening a fresh bin allows a clean 2-item chain when current
            // bins would fragment; reduce penalty slightly.
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 70.0; // no alternative: must open
        }
    }

    // Late in the stream, consolidation matters more; tighten preference
    // for filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - fit_ratio);

    // Slight preference for bins with many other options (keep scarce
    // flexible bins free).
    if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0).min(5.0);
    }

    score
}

