    let mut score = post_residual as f64;

    // Penalize dead space that is too small to be useful later.
    let tiny = (post_residual > 0 && post_residual < 10) as f64;
    score += tiny * 30.0;

    // Reward tight fits (small post residual).
    score -= (item_size as f64 / bin_capacity as f64) * 8.0;

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + (next_item_size as f64 / 100.0) * 6.0;
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor fits.
    if bin_residual == bin_capacity {
        let poor_fit = (mean_residual - item_size as f64).abs();
        score += 15.0 - poor_fit.min(15.0);
        // Prefer opening new bins early when many bins are already open and fragmented.
        score -= (open_bins_count as f64) * 0.5;
    } else {
        // Penalize bins whose residual deviates badly from what is needed.
        let gap = (bin_residual as f64 - item_size as f64).abs();
        score += gap * 0.2;
    }

    // Time horizon: as the stream progresses, be more conservative (favor filling existing bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Global fragmentation: when mean residual is low, conserve space aggressively.
    if mean_residual < 20.0 {
        score += 8.0;
    }

    score
}

