pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Smooth stream-progress normalization
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with progress:
    // early on, prefer tight fills strongly; later, relax slightly.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let poly = pr_norm * pr_norm * (1.0 - progress) + pr_norm * progress * 0.5;
    score += 40.0 * poly;

    // Dead-space penalty: post_residual too small to hold the smallest items
    let dead = (pr < 10.0) as f64;
    score += 60.0 * dead * (1.0 - progress);

    // Lookahead coupling: reward residual that can still host the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 8.0 * (1.0 - pr / bin_capacity as f64);
        } else {
            score += 6.0 * (1.0 - n / bin_capacity as f64);
        }
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mild pressure against spreading across many open bins
    score += 0.5 * open_bins_count as f64 * pr_norm;

    // New-bin candidate: only attractive when residuals are fragmented
    let is_new = (bin_residual == bin_capacity) as f64;
    let fragmentation = (mean_residual / bin_capacity as f64 - 0.5).abs();
    score += is_new * (20.0 + 40.0 * fragmentation);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
