pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: quantize post_residual into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1 fraction of capacity left

    // Perfect fit -> strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward placements whose leftover belongs to a "useful" harmonic class:
    // leftovers that can host common small items (multiples of 10, 25, 50).
    if post_residual >= 10 && (post_residual % 10 == 0) {
        score -= 15.0;
    }
    if post_residual >= 25 && (post_residual % 25 == 0) {
        score -= 10.0;
    }
    if post_residual >= 50 {
        score -= 8.0;
    }

    // Penalize dead space: leftover smaller than the smallest plausible item (1..~10)
    // but nonzero -> unusable gap.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Coupling with next item: if the leftover exactly (or nearly) fits the next item,
    // reward heavily; if leftover cannot fit next item, penalize proportionally.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual >= next_item_size {
            // leftover can chain: reward proportional to tightness
            score -= 20.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            score += 25.0 * (next_item_size - post_residual) as f64 / cap;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when the
    // item fits poorly everywhere else. Penalize fresh bin unless current bin's
    // leftover would be wasted.
    if bin_residual == bin_capacity {
        // fresh bin: baseline score = capacity - item; make it moderately costly
        score += 30.0;
        // but if next item is huge and current item small, fresh bin helps
        if next_item_size >= 70 && item_size <= 30 {
            score -= 50.0;
        }
        // late in the stream, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Prefer bins below mean residual (tighter bins first) -> keeps loose bins flexible.
    score += 0.5 * (mean_residual - post).max(0.0) - 0.2 * (post - mean_residual).max(0.0);

    // Many open bins: encourage filling existing ones rather than spreading.
    if open_bins_count > 4 {
        score -= 0.3 * open_bins_count as f64 * (1.0 - frac);
    }

    // Integer-division threshold: leftover in [1/3, 2/3] of capacity is versatile.
    if post >= cap / 3.0 && post <= 2.0 * cap / 3.0 {
        score -= 12.0;
    }

    score
}

