pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let match_quality = 1.0 - ((pr - nxt) / bin_capacity as f64).abs();
            score -= 25.0 * match_quality * match_quality;
        } else {
            // next item won't fit here: penalize dead space
            score += 10.0 + 0.5 * (pr / 10.0);
        }
        // exact-ish fit for next item is very attractive
        if pr == nxt {
            score -= 40.0;
        }
    }

    // Perfect fit for current item
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Relative to mean residual: prefer tighter-than-average bins
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid waste
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins fit well, unless residual is tiny
    if bin_residual == bin_capacity {
