pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear (quadratic) penalty on waste
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: later in the stream, penalize loose fits more strongly
    let progress_coupling = 1.0 + 1.5 * progress * (1.0 - progress * 0.5);
    score *= progress_coupling;

    // Dead-space term: residual too small for typical items (below min item size ~1..100 unknown, use smooth sigmoid-like decay)
    let small_gap = (1.0 - norm_pr).exp();
    score += 10.0 * small_gap * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let room_match = 1.0 - ((pr - nxt) / cap).abs().sqrt();
            score -= 5.0 * room_match.max(0.0);
        } else {
            score += 3.0 * (1.0 - pr / nxt.max(1.0));
        }
    }

    // Slight preference for filling bins with larger residual relative to mean (balance avoidance)
    score -= 0.05 * (bin_residual as f64 - mean_residual) * progress;

    // Mild penalty for opening many bins
    score += 0.3 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: keep it neutral-ish but slightly penalized so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + 4.0;
    }

    score
}

