        if next_item_size > 1 && post_residual > next_item_size + 1 && post_residual <= next_item_size + 10 {
            score -= 4.0 * (1.0 - progress) ;
        }
        // NEW: residual that fits next item plus the current item size again
        if next_item_size > 0 && post_residual >= next_item_size + item_size && item_size > 1 {
            score -= 5.0 * (1.0 - progress) ;
        }
    }
    // NEW-BIN CANDIDATE
    if bin_residual == bin_capacity {
        let big_next = next_item_size as f64 / bin_capacity as f64 ;
        score += 180.0 - 60.0 * progress + 0.15 * open_bins_count as f64 - 25.0 * big_next . max (0.0) ;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0 ;
        }
        if open_bins_count <= 4 && progress < 0.3 {
            score += 25.0 ;
        }
        if mean_residual < 15.0 && progress > 0.5 {
            score -= 15.0 ;
        }
        let item_frac = item_size as f64 / bin_capacity as f64 ;
        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3 ;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3 ;
        }
        let fresh_left = bin_capacity - item_size ;
        if next_item_size > 0 && fresh_left == next_item_size {
            score -= 30.0 ;
        }
        if open_bins_count > 6 && mean_residual > 0.4 * bin_capacity as f64 {
            score += 20.0 ;
        }
        // fresh-bin leftover sliver is wasteful
        if next_item_size > 0 && fresh_left < next_item_size && fresh_left < 8 {
            score += 35.0 ;
        }
        // prefer fresh bin when all existing residuals are too small for next item
        if next_item_size > 0 && fitting_bins_count <= 2 && mean_residual < next_item_size as f64 {
            score -= 18.0 * (1.0 - progress) ;
        }
        // discourage opening fresh bins late when many half-empty bins exist
        if open_bins_count > 8 && mean_residual > next_item_size as f64 + 10.0 {
            score += 12.0 ;
        }
        // large items into fresh bins leave big usable leftovers: mild reward
        if item_frac > 0.6 && next_item_size > 0 && fresh_left >= next_item_size {
            score -= 8.0 * (1.0 - progress) ;
        }
        // fresh bin justified when leftover can host next item plus mean slack
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress) ;
        }
        // near-zero tail after next item (perfect closure)
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size ;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress) ;
            }
        }
        // fresh bin leftover below mean residual is likely dead space
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        // chain home: leftover hosts next item twice exactly
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        // near-exact fill wastes nothing and preserves all open residuals
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        // fresh bin leftover matching mean residual — reusable home shape
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        // chain home: leftover hosts next item multiple times exactly
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        // fresh bin leftover that hosts next item plus mean-shaped slack
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        // avoid opening fresh bins when a fitting open bin nearly seals with this item
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        // NEW: fresh bin leftover that hosts next item plus current-size repeat
        if next_item_size > 0 && item_size > 1 && fresh_left >= next_item_size + item_size {
            score -= 7.0 * (1.0 - progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: modulo arithmetic on post_residual.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left

    // Dead-space penalty: residuals that are "harmonically awkward" (small odd-ish leftovers)
    // get punished. Classify post_residual into residue classes mod 10 and mod 25.
    let m10 = post_residual % 10;
    let m25 = post_residual % 25;

    // Perfect fits (post_residual == 0) are heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize tiny leftovers that are hard to fill (below smallest item size 1..10 typical).
        if pr < 10.0 {
            score += 60.0 * (10.0 - pr);
        }
        // Odd residues mod 10 are less likely to be filled by common item sizes.
        if m10 % 2 == 1 {
            score += 8.0;
        }
        // Residuals that are multiples of 25 or 50 are harmonically friendly.
        if m25 == 0 {
            score -= 25.0;
        } else if m10 == 0 {
            score -= 10.0;
        }
        // General dead-space term: quadratic in wasted fraction.
        score += 30.0 * frac * frac;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            if nx == pr {
                score -= 400.0; // chainable perfect fit
            } else {
                score -= 40.0 * (1.0 - nx / pr.max(1.0)); // prefer bins that still fit next item snugly
            }
        } else {
            score += 20.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Prefer tighter bins among many candidates (best-fit core), scaled by stream progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 0.5 * progress * (bin_residual as f64 - item_size as f64);

    // New-bin candidate: only attractive when open bins are crowded or fit is terrible.
    if bin_residual == bin_capacity {
        score = 0.6 * cap - 0.4 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        if next_item_size > 0 && (next_item_size as f64) >= 0.5 * cap {
            score -= 30.0; // big next item: fresh bin is fine
        }
    }

    score
}

