pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 1.0;

    // Perfect fit bonus: post_residual == 0 is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward post_residual that exactly matches next_item_size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post_residual == next_item_size {
            // next item fills this bin perfectly -> huge reward
            score -= 800.0;
        } else if post_residual >= next_item_size {
            // next item can still fit here: reward closeness of match
            let match_quality = 1.0 - (post - nxt) / (bin_capacity as f64);
            score -= 300.0 * match_quality * (nxt / 100.0);
        } else {
            // next item cannot fit here: penalize dead space proportionally
            let dead = nxt - post;
            score += 150.0 * (dead / 100.0);
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are tight;
    // placing here is good if fit is tight, bad if it wastes a scarce big gap.
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (post_f - mean_residual) / mean_residual;
        score += 50.0 * rel;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin (unless post_residual is terrible dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize new-bin candidate unless current fit is poor and lookahead suggests it
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin starts with residual == capacity; only attractive when
        // item is large relative to capacity or all fits are bad.
        let large_item = (item_size as f64) / (bin_capacity as f64);
        let poor_fit = post_f > 40.0;
        if !(large_item > 0.6 || (poor_fit && next_item_size > 0 && post_residual < next_item_size)) {
            score += 400.0;
        } else {
            score += 50.0;
        }
    }

    // Mild stream-progression term: as stream progresses, be more conservative
    // about leaving large residuals (waste compounds over many items).
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 20.0 * progress * (post_f / bin_capacity as f64);
    }

    // Small penalty for many open bins to encourage consolidation
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    if post_residual == 0 {
        score -= 1000.0;
    } else {
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 900.0 - 30.0 * progress;
            } else if next_item_size <= post_residual {
                let two_step_waste = (post_residual - next_item_size) as f64;
                if two_step_waste == 0.0 {
                    score -= 700.0;
                } else if two_step_waste >= 10.0 {
                    score -= 300.0 - 2.0 * two_step_waste;
                } else {
                    score -= 80.0 + 1.5 * (10.0 - two_step_waste);
                }
                // cushion: comfortable slack for the next item
                let after_next = post_residual - next_item_size;
                if after_next >= 3 {
                    score -= (2.0 + 2.0 * progress) * (after_next as f64).min(15.0);
                }
                // leftover after next item stays usable
                if after_next <= 12 && mean_residual >= after_next as f64 {
                    score -= 22.0 - 0.8 * after_next as f64;
                }
                // leftover can host next item again (chain home)
                if next_item_size > 1 && after_next >= next_item_size {
                    score -= 6.0 + 0.2 * (after_next / next_item_size) as f64;
                    if after_next % next_item_size == 0 {
                        score -= 8.0 * (1.0 - progress);
                    }
                }
                // near-seal sliver after next item
                if after_next < next_item_size && after_next <= 3 {
                    score -= 14.0 * (1.0 - progress);
                }
                // leftover just below next item: near-seal, mild late reward
                if after_next < next_item_size && after_next >= 1 && (next_item_size - after_next) <= 5 {
                    score -= 6.0 * (1.0 - progress);
                }
                // leftover matches mean residual shape: reusable home
                if (after_next as f64 - mean_residual).abs() <= 4.0 {
                    score -= 6.0 * (1.0 - progress);
                }
            } else {
                let miss = next_item_size - post_residual;
                score += 2.0 * miss as f64;
                if post_residual < 25 {
                    score += 15.0;
                }
                // near-perfect sealed bins
                if post_residual < 3 {
                    score -= 400.0;
                }
                // near-miss with only one other fitting bin: keep it alive
                if miss <= 6 && fitting_bins_count <= 2 {
                    score -= 5.0;
                }
                // salvage late in the stream with few alternatives
                if miss <= 10 && fitting_bins_count <= 2 && progress > 0.7 {
                    score -= 10.0 * (1.0 - progress);
                }
                // near-miss that seals the bin exactly on a later small item
                if miss <= 2 {
                    score -= 18.0 * (1.0 - progress);
                }
                // strand-space guard just under common small sizes
                if post_residual >= 8 && post_residual <= 16 {
                    score += 10.0 * (1.0 - progress);
                }
                // near-miss whose gap matches mean residual shape — dead space
                if miss > 3 && miss as f64 <= mean_residual * 0.5 {
                    score += 4.0 * (1.0 - progress);
                }
            }
        }
        if post_residual < 10 {
            score += 45.0;
        } else if post_residual < 20 {
            score += 10.0;
        }
        score -= (mean_residual - post_residual as f64) * 0.6;
        // dead-gap penalty with scarcity scaling
        let gap = (post_residual as f64 - item_size as f64).max(0.0);
        let gap_ratio = gap / (item_size as f64).max(1.0);
        if gap > 0.0 {
            let scarcity = if fitting_bins_count <= 2 { 0.6 } else if fitting_bins_count <= 4 { 0.3 } else { 0.2 };
            score += scarcity * gap + 18.0 * gap_ratio.min(2.0);
            if gap < mean_residual {
                let fillable = next_item_size > 0 && gap >= next_item_size as f64;
                let w = if fillable { 0.2 } else { 0.6 };
                score += w * (mean_residual - gap);
            }
            if next_item_size > 0 && (gap as u32) == next_item_size {
                score -= 20.0;
            }
            if next_item_size > 1 && (gap as u32) == 2 * next_item_size {
                score -= 12.0;
            }
        }
        if fitting_bins_count == 1 {
            score -= 12.0;
        }
        let fill = item_size as f64 / (bin_residual as f64).max(1.0);
        score -= 20.0 * fill;
        // dead space: unusable residual relative to next item
        if next_item_size > 0 && post_residual < next_item_size {
            let dead_frac = post_residual as f64 / bin_capacity as f64;
            let unusable_ratio = post_residual as f64 / (next_item_size as f64).max(1.0);
            score += 0.4 * post_residual as f64 + 30.0 * dead_frac + 12.0 * (1.0 - unusable_ratio);
            if next_item_size - post_residual <= 4 {
                score += 20.0 * (1.0 - progress);
            }
        }
        // anti-fragmentation guard
        if fitting_bins_count == 2 && post_residual < bin_capacity / 3 {
            score -= 8.0;
        }
        // tiny unusable slivers when bins are plentiful
        if post_residual <= 5 && open_bins_count > 6 {
            score += 25.0 * (1.0 - progress);
        }
        // mid-sized future homes
        if post_residual >= bin_capacity / 8 && post_residual <= bin_capacity / 2 {
            score -= 6.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= bin_capacity / 2 {
            score -= 4.0 * (1.0 - progress);
        }
        // reward residuals that can absorb two more average items
        if post_residual as f64 >= 2.0 * mean_residual && post_residual > 20 {
            score -= 5.0;
        }
        // compaction sweet spot: headroom matches mean residual
        if next_item_size > 0 && post_residual > next_item_size {
            let headroom = post_residual - next_item_size;
            if (headroom as f64 - mean_residual).abs() <= 3.0 {
                score -= 7.0;
            }
            if (headroom as f64 - mean_residual).abs() <= 1.0 && fitting_bins_count <= 3 {
                score -= 5.0 * (1.0 - progress);
            }
        }
        // three-way closure: residual hosts next item then seals exactly
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0;
        }
        // residual that fits next item plus a small item is doubly useful
        if next_item_size > 1 && post_residual > next_item_size + 1 && post_residual <= next_item_size + 10 {
            score -= 4.0 * (1.0 - progress);
        }
        // MUTATION: exact-fit bonus scaled by bin scarcity — a bin that seals
        // exactly with this item is worth more when alternatives are few
        if post_residual == 0 {
            if fitting_bins_count <= 2 {
                score -= 150.0 * (1.0 - progress);
            }
            if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
                score -= 50.0;
            }
        }
        // MUTATION: penalize leaving residuals in the "dead zone" that no
        // typical item (1..100) can use when the next item overshoots it
        if next_item_size > post_residual && post_residual > 0 && post_residual < 20 {
            score += 0.5 * (20 - post_residual) as f64 * (1.0 - progress);
        }
    }
    // NEW-BIN CANDIDATE
    if bin_residual == bin_capacity {
        let big_next = next_item_size as f64 / bin_capacity as f64;
        score += 180.0 - 60.0 * progress + 0.15 * open_bins_count as f64 - 25.0 * big_next.max(0.0);
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
        if open_bins_count <= 4 && progress < 0.3 {
            score += 25.0;
        }
        if mean_residual < 15.0 && progress > 0.5 {
            score -= 15.0;
        }
        let item_frac = item_size as f64 / bin_capacity as f64;
        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3;
        }
        let fresh_left = bin_capacity - item_size;
        if next_item_size > 0 && fresh_left == next_item_size {
            score -= 30.0;
        }
        if open_bins_count > 6 && mean_residual > 0.4 * bin_capacity as f64 {
            score += 20.0;
        }
        // fresh-bin leftover sliver is wasteful
        if next_item_size > 0 && fresh_left < next_item_size && fresh_left < 8 {
            score += 35.0;
        }
        // prefer fresh bin when all existing residuals are too small for next item
        if next_item_size > 0 && fitting_bins_count <= 2 && mean_residual < next_item_size as f64 {
            score -= 18.0 * (1.0 - progress);
        }
        // discourage opening fresh bins late when many half-empty bins exist
        if open_bins_count > 8 && mean_residual > next_item_size as f64 + 10.0 {
            score += 12.0;
        }
        // large items into fresh bins leave big usable leftovers: mild reward
        if item_frac > 0.6 && next_item_size > 0 && fresh_left >= next_item_size {
            score -= 8.0 * (1.0 - progress);
        }
        // fresh bin justified when leftover can host next item plus mean slack
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress);
        }
        // near-zero tail after next item (perfect closure)
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress);
            }
        }
        // fresh bin leftover below mean residual is likely dead space
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0;
        }
        // chain home: leftover hosts next item twice exactly
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0;
        }
        // near-exact fill wastes nothing and preserves all open residuals
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress);
        }
        // fresh bin leftover matching mean residual — reusable home shape
        if next_item_size > 0 && (fresh_left as f64 - mean_residual).abs() <= 2.0 {
            score -= 8.0;
        }
        // chain home: leftover hosts next item multiple times exactly
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress);
        }
        // fresh bin leftover that hosts next item plus mean-shaped slack
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual).abs() <= 3.0 {
            score -= 9.0 * (1.0 - progress);
        }
        // avoid opening fresh bins when a fitting open bin nearly seals with this item
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0;
        }
        // MUTATION: fresh bin is attractive if its leftover can chain-host the
        // next item several times exactly (divisibility lookahead)
        if next_item_size > 1 && fresh_left >= 3 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 10.0 * (1.0 - progress);
        }
        // MUTATION: late-stream pressure — reject fresh bins unless the item
        // is large enough that open bins would strand big residuals
        if progress > 0.6 && item_frac < 0.25 && mean_residual > 30.0 {
            score += 25.0;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 14.0 * tightness * tightness;

    // Lookahead: if the next item fits into the post residual, reward this bin;
    // otherwise penalize leaving a gap that neither helps nor hurts.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Dead space relative to lookahead item: penalize proportionally to wasted gap.
            let gap = (post_residual as f64).min(next_item_size as f64);
            score += 0.35 * gap;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
        if post_residual < 10 {
            score -= 6.0; // near-perfect fill in the only option
        }
    }

    // Penalize opening a new bin when decent open bins exist and the fit is mediocre.
    if bin_residual == bin_capacity {
        let avg_fit_pressure = (mean_residual - item_size as f64).max(0.0);
        score += 8.0 + 0.15 * open_bins_count as f64 - 0.05 * avg_fit_pressure;
        // Early in the stream, opening new bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 6.0 * (1.0 - progress);
        // If next item is large and this fresh bin could host both, soften the penalty.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0;
        }
    }

    // Mild preference for bins below the mean residual (consolidate fuller bins).
    if bin_residual < bin_capacity {
        score += 0.08 * (mean_residual - bin_residual as f64);
    }

    // Slight global pressure: with many open bins, favor packing into existing ones.
    score += 0.02 * open_bins_count as f64;

    score
}

