pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with non-linear polynomial shaping in normalized residual
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling of post_residual with stream progress:
    // late in the stream, tight fits (small post_residual) are rewarded more strongly
    let tightness = 1.0 - norm_pr;
    score -= 6.0 * progress * tightness * tightness * pr / cap * 10.0;

    // Penalize large dead space more as stream progresses (wasted capacity matters later)
    score += 4.0 * progress * norm_pr * norm_pr * cap;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 10.0 * progress;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        let next_fits = (next_item_size as f64) <= pr;
        if next_fits {
            score -= 8.0 * (1.0 - (pr - next_item_size as f64).abs() / cap);
        } else {
            // penalize leaving residual that next item almost fits
            let gap = next_item_size as f64 - pr;
            if gap < 10.0 {
                score += 3.0 * (1.0 - gap / 10.0);
            }
        }
    }

    // Deviation from mean residual: prefer bins whose residual is close to mean
    // (keeps open bins balanced), scaled smoothly by open bin count
    let n = open_bins_count.max(1) as f64;
    score += 0.5 * (pr - mean_residual).abs() * (1.0 / (1.0 + (n - 1.0) * 0.1));

    // New-bin candidate: mildly penalize early, allow late when open bins are poor fits
    if bin_residual == bin_capacity {
        let openness = 1.0 / (1.0 + n);
        score += 5.0 * openness * (1.0 - progress) + 2.0;
    }

    score
}

