pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into capacity-fraction bands.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let band = (post_residual / (bin_capacity / 8).max(1)) as i32; // 0..8 class
    let band_penalty: [f64; 9] = [0.0, -14.0, -8.0, -3.0, 4.0, 9.0, 14.0, 18.0, 20.0];
    let b = band.min(8) as usize;
    score += band_penalty[b];

    // Modulo-style coupling: post_residual compatible with next item is valuable.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            // next item fits exactly-ish into leftover: reward harmonic match
            let diff = (post_residual - next_item_size) as f64;
            score -= 10.0 + 6.0 * (1.0 - diff / c);
            // exact modulo class match (next divides post_residual class)
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            // next item cannot use the leftover: penalize dead space
            score += 5.0 + 4.0 * (nxt / c);
        }
    }

    // Tight fits strongly rewarded (small post_residual relative to item).
    let tight = pr / (item_size as f64).max(1.0);
    score -= 12.0 * (1.0 / (1.0 + tight));

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate: keep it mildly unattractive unless current bins are very full.
    if bin_residual == bin_capacity {
        let pressure = if open_bins_count > 0 { mean_residual / c } else { 1.0 };
        score += 6.0 + 18.0 * (1.0 - pressure);
        // late in stream, prefer consolidation into open bins
        let prog = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * prog;
    }

    // Reward bins already below mean residual (consolidating emptier bins).
    score -= 3.0 * (mean_residual - pr) / c;

    score
}

