        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            // next item fits: reward proportionally to how well it uses the leftover.
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 150.0 * fill_ratio;
        } else {
            // next item cannot use the leftover: penalize dead space.
            score += 40.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Compare residual against mean residual across open bins.
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Tight fits (small leftover) are generally good: quadratic penalty on waste.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 10.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // New empty bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let early = step_index as f64 / (total_items.max(1) as f64);
        // Base penalty so we prefer existing bins; reduced when fitting bins are scarce.
        score += 120.0 - 200.0 * scarcity - 30.0 * early;
        // If the next item is large, opening a fresh bin is more attractive.
        if next_item_size > 50 {
            score -= 60.0;
        }
    }

    // Slight penalty for very fragmented state (many open bins).
    score += 0.5 * open_bins_count as f64;

    score
}

