    // NEW-BIN CANDIDATE
    if bin_residual == bin_capacity {
        let big_next = next_item_size as f64 / bin_capacity as f64 ;
        score += 180.0 - 60.0 * progress + 0.15 * open_bins_count as f64 - 25.0 * big_next . max (0.0) ;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0 ;
        }
        if open_bins_count <= 4 && progress < 0.3 {
            score += 25.0 ;
        }
        if mean_residual < 15.0 && progress > 0.5 {
            score -= 15.0 ;
        }
        let item_frac = item_size as f64 / bin_capacity as f64 ;
        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3 ;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3 ;
        }
        let fresh_left = bin_capacity - item_size ;
        if next_item_size > 0 && fresh_left == next_item_size {
            score -= 30.0 ;
        }
        if open_bins_count > 6 && mean_residual > 0.4 * bin_capacity as f64 {
            score += 20.0 ;
        }
        // fresh-bin leftover sliver is wasteful
        if next_item_size > 0 && fresh_left < next_item_size && fresh_left < 8 {
            score += 35.0 ;
        }
        // prefer fresh bin when all existing residuals are too small for next item
        if next_item_size > 0 && fitting_bins_count <= 2 && mean_residual < next_item_size as f64 {
            score -= 18.0 * (1.0 - progress) ;
        }
        // discourage opening fresh bins late when many half-empty bins exist
        if open_bins_count > 8 && mean_residual > next_item_size as f64 + 10.0 {
            score += 12.0 ;
        }
        // large items into fresh bins leave big usable leftovers: mild reward
        if item_frac > 0.6 && next_item_size > 0 && fresh_left >= next_item_size {
            score -= 8.0 * (1.0 - progress) ;
        }
        // fresh bin justified when leftover can host next item plus mean slack
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress) ;
        }
        // near-zero tail after next item (perfect closure)
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size ;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress) ;
            }
        }
        // fresh bin leftover below mean residual is likely dead space
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        // chain home: leftover hosts next item twice exactly
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        // near-exact fill wastes nothing and preserves all open residuals
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        // fresh bin leftover matching mean residual — reusable home shape
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        // chain home: leftover hosts next item multiple times exactly
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        // fresh bin leftover that hosts next item plus mean-shaped slack
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        // avoid opening fresh bins when a fitting open bin nearly seals with this item
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on wasted space
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + item_size as f64 * 0.2;
    }

    // Many fitting bins: we can afford to be picky, penalize loose fits more
    if fitting_bins_count > 2 {
        score += post_residual as f64 * 0.3;
    }

    // Lookahead: penalize if this placement leaves a gap that neither fits
    // the next item nor is likely useful (small awkward gap)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // reward leaving room for the next item
            score -= (post_residual - next_item_size) as f64 * 0.15;
            // extra reward for exact two-item packing
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            // gap too small for next item: penalize proportional to wasted potential
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Global state: if mean residual is high, prefer consolidating into bins
    // with above-average residual (reduce fragmentation)
    if bin_residual as f64 > mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Time horizon: early in stream, be conservative (favor new bins for
    // large items to keep flexibility); late in stream, pack tightly everywhere
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.3 && item_size > 50 && bin_residual == bin_capacity {
        score -= 10.0; // early: fresh bins ok for big items
    } else if progress > 0.7 && bin_residual < bin_capacity {
        score -= 8.0; // late: strongly prefer filling open bins
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    // or no good alternative exists
    if bin_residual == bin_capacity {
        score += 20.0 - item_size as f64 * 0.15;
        if open_bins_count == 0 {
            score -= 100.0; // must use a bin
        }
        // open new bin if next item is small (keeps large residual for future)
        if next_item_size > 0 && next_item_size < item_size {
            score -= 6.0;
        }
    }

    // Mild open-bins pressure: many open bins -> prefer consolidating
    score += open_bins_count as f64 * 0.5 * (post_residual as f64 / bin_capacity as f64);

    score
}

