pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Strong reward for tight fits: small post_residual is good.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize dead space that can't fit typical future items (small residual gaps).
    if post_residual > 0 {
        let dead = (post_residual as f64 / 100.0).powi(3);
        score += 30.0 * dead * (0.5 + 0.5 * progress);
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here; penalize leaving a stranded gap.
        score += 10.0 * (post_residual as f64 / 100.0);
    }

    // Last-chance bonus: only fitting bin -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early and when bins exist.
    if bin_residual == bin_capacity {
        score += 55.0 + 20.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
    } else {
        // Mild preference toward fuller bins among open ones.
        score -= 5.0 * (1.0 - (bin_residual as f64 / bin_capacity as f64));
    }

    // Coupling with mean residual: prefer bins below mean residual (fuller than average).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Smooth non-linear stream-progress coupling: tighten packing as stream advances.
    let coupling = (progress * std::f64::consts::PI).sin();
    score -= 8.0 * coupling * (1.0 - fit_ratio);

    score
}

