        if item_frac > 0.6 && next_item_size > 0 && fresh_left >= next_item_size {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress);
        }
        // near-zero tail after next item
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0;
        }
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0;
        }
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress);
        }
        if next_item_size > 0 && (fresh_left as f64 - mean_residual).abs() <= 2.0 {
            score -= 8.0;
        }
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual).abs() <= 3.0 {
            score -= 9.0 * (1.0 - progress);
        }
        // avoid opening fresh bins when an open bin nearly seals with this item
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the residual: quartile classes of capacity
    let post = post_residual;
    let class = match post {
        0 => 0.0,
        1..=25 => 1.0,
        26..=50 => 2.0,
        51..=75 => 3.0,
        _ => 4.0,
    };
    score += class * 3.0;

    // Perfect fit reward
    if post == 0 {
        score -= 50.0;
    }

    // Dead-space penalty: residual too small for typical future items
    if post > 0 && post < 10 {
        score += 20.0;
    }

    // Modulo arithmetic on post_residual: residuals divisible by common item sizes are more usable
    let usable = post >= 10 && post <= 100;
    if usable {
        let mut bonus = 0.0;
        for d in [10u32, 20, 25, 40, 50] {
            if post % d == 0 {
                bonus += 4.0;
            }
        }
        score -= bonus;
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 30.0;
        } else if next_item_size <= post {
            let nxt = next_item_size as f64;
            let fit_frac = nxt / (post as f64);
            // prefer bins where next item fills a large fraction of remaining space
            score -= 10.0 * fit_frac;
            // harmonic class of leftover after next item
            let after = post - next_item_size;
            let after_class = match after {
                0 => 0.0,
                1..=25 => 1.0,
                26..=50 => 2.0,
                51..=75 => 3.0,
                _ => 4.0,
            };
            score += after_class * 2.0;
        } else {
            // next item cannot use this residual: slight penalty for hoarding space
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate logic: only attractive when current open bins fit poorly
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // penalize opening new bins mildly, more so early in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 20.0 * (1.0 - progress);
        // but if open bins have large mean residual and few fit, new bin may be fine
        if mean_residual < 20.0 {
            score -= 10.0;
        }
    }

    // Prefer bins tighter than average (best-fit flavor with mean coupling)
    score += (post as f64 - mean_residual).abs() * 0.2;

    // Congestion: with many open bins, consolidate (favor low post_residual more)
    let congestion = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += congestion * (post as f64) * 0.3;

    // Integer-division threshold: residual in [item..item+9] is a "snug" class
    if post >= 10 && (post / 10) == (item_size / 10) && post >= item_size {
        score -= 6.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
