pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted space, with a smooth non-linear (quadratic-cubic) shaping
    let mut score = pr * (1.0 + 1.5 * norm_pr - 0.8 * norm_pr * norm_pr);

    // Coupling: tight fits matter more as the stream progresses (smooth ramp)
    let tightness = 1.0 - norm_pr; // 0 = perfect fit, 1 = empty
    let progress_weight = 0.5 + 2.0 * progress * (1.0 - progress * 0.5);
    score -= progress_weight * 12.0 * (1.0 - tightness * tightness);

    // Lookahead interaction: reward leaving room for the next item smoothly
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fit_next = if pr >= ns { 1.0 } else { 0.0 };
        let closeness = 1.0 - (pr - ns).abs() / cap;
        score -= fit_next * (6.0 + 10.0 * closeness * closeness) * (0.4 + 0.6 * progress);
        score += (1.0 - fit_next) * 5.0 * (0.3 + 0.7 * progress);
    }

    // Scarcity of fitting bins: smooth bonus for last-chance bins
    if fitting_bins_count <= 1 {
        score -= 8.0 * (0.5 + 0.5 * progress);
    } else {
        let f = fitting_bins_count as f64;
        score += 2.0 * (1.0 - 1.0 / f) * (0.5 + 0.5 * progress);
    }

    // Mean residual coupling: prefer bins deviating from the mean residual smoothly
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev * (1.0 - progress);

    // Mild penalty for spreading across many bins early on
    score += 0.3 * open_bins_count as f64 * (1.0 - progress) * (1.0 - progress);

    // New-bin candidate: penalize gently so it only wins when open bins are truly poor
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * (1.0 - progress) * (1.0 - progress) + 3.0 * open_bins_count as f64;
    }

    score
}

