            score += scarcity * gap + 18.0 * gap_ratio . min (2.0) ;
            if gap < mean_residual {
                let fillable = next_item_size > 0 && gap >= next_item_size as f64 ;
                let w = if fillable { 0.2 } else { 0.6 } ;
                score += w * (mean_residual - gap) ;
            }
            if next_item_size > 0 && (gap as u32) == next_item_size {
                score -= 20.0 ;
            }
            if next_item_size > 1 && (gap as u32) == 2 * next_item_size {
                score -= 12.0 ;
            }
            // NEW: gap that cannot host next item but bins are scarce — heavier penalty
            if next_item_size > 0 && gap < next_item_size as f64 && fitting_bins_count <= 3 {
                score += 8.0 * (1.0 - progress) ;
            }
        }
        if fitting_bins_count == 1 {
            score -= 12.0 ;
        }
        let fill = item_size as f64 / (bin_residual as f64) . max (1.0) ;
        score -= 20.0 * fill ;
        // dead space: unusable residual relative to next item
        if next_item_size > 0 && post_residual < next_item_size {
            let dead_frac = post_residual as f64 / bin_capacity as f64 ;
            let unusable_ratio = post_residual as f64 / (next_item_size as f64) . max (1.0) ;
            score += 0.4 * post_residual as f64 + 30.0 * dead_frac + 12.0 * (1.0 - unusable_ratio) ;
            if next_item_size - post_residual <= 4 {
                score += 20.0 * (1.0 - progress) ;
            }
        }
        // anti-fragmentation guard
        if fitting_bins_count == 2 && post_residual < bin_capacity / 3 {
            score -= 8.0 ;
        }
        // tiny unusable slivers when bins are plentiful
        if post_residual <= 5 && open_bins_count > 6 {
            score += 25.0 * (1.0 - progress) ;
        }
        // mid-sized future homes
        if post_residual >= bin_capacity / 8 && post_residual <= bin_capacity / 2 {
            score -= 6.0 ;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= bin_capacity / 2 {
            score -= 4.0 * (1.0 - progress) ;
        }
        // reward residuals that can absorb two more average items
        if post_residual as f64 >= 2.0 * mean_residual && post_residual > 20 {
            score -= 5.0 ;
        }
        // compaction sweet spot: headroom matches mean residual
        if next_item_size > 0 && post_residual > next_item_size {
            let headroom = post_residual - next_item_size ;
            if (headroom as f64 - mean_residual) . abs () <= 3.0 {
                score -= 7.0 ;
            }
            if (headroom as f64 - mean_residual) . abs () <= 1.0 && fitting_bins_count <= 3 {
                score -= 5.0 * (1.0 - progress) ;
            }
        }
        // three-way closure: residual hosts next item then seals exactly
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0 ;
        }
        // residual that fits next item plus a small item is doubly useful
        if next_item_size > 1 && post_residual > next_item_size + 1 && post_residual <= next_item_size + 10 {
            score -= 4.0 * (1.0 - progress) ;
        }
        // NEW: many open bins with large residuals — prefer compacting into them
        if open_bins_count > 10 && post_residual > bin_capacity / 4 {
            score -= 3.0 ;
        }
    }
    // NEW-BIN CANDIDATE
    if bin_residual == bin_capacity {
        let big_next = next_item_size as f64 / bin_capacity as f64 ;
        score += 180.0 - 60.0 * progress + 0.15 * open_bins_count as f64 - 25.0 * big_next . max (0.0) ;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0 ;
        }
        if open_bins_count <= 4 && progress < 0.3 {
            score += 25.0 ;
        }
        if mean_residual < 15.0 && progress > 0.5 {
            score -= 15.0 ;
        }
        let item_frac = item_size as f64 / bin_capacity as f64 ;
        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3 ;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3 ;
        }
        let fresh_left = bin_capacity - item_size ;
        if next_item_size > 0 && fresh_left == next_item_size {
            score -= 30.0 ;
        }
        if open_bins_count > 6 && mean_residual > 0.4 * bin_capacity as f64 {
            score += 20.0 ;
        }
        // fresh-bin leftover sliver is wasteful
        if next_item_size > 0 && fresh_left < next_item_size && fresh_left < 8 {
            score += 35.0 ;
        }
        // prefer fresh bin when all existing residuals are too small for next item
        if next_item_size > 0 && fitting_bins_count <= 2 && mean_residual < next_item_size as f64 {
            score -= 18.0 * (1.0 - progress) ;
        }
        // discourage opening fresh bins late when many half-empty bins exist
        if open_bins_count > 8 && mean_residual > next_item_size as f64 + 10.0 {
            score += 12.0 ;
        }
        // large items into fresh bins leave big usable leftovers: mild reward
        if item_frac > 0.6 && next_item_size > 0 && fresh_left >= next_item_size {
            score -= 8.0 * (1.0 - progress) ;
        }
        // fresh bin justified when leftover can host next item plus mean slack
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress) ;
        }
        // near-zero tail after next item (perfect closure)
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size ;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress) ;
            }
        }
        // fresh bin leftover below mean residual is likely dead space
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        // chain home: leftover hosts next item twice exactly
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        // near-exact fill wastes nothing and preserves all open residuals
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        // fresh bin leftover matching mean residual — reusable home shape
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        // chain home: leftover hosts next item multiple times exactly
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        // fresh bin leftover that hosts next item plus mean-shaped slack
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        // avoid opening fresh bins when a fitting open bin nearly seals with this item
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        // NEW: fresh bin leftover should ideally tile into mean-sized chunks
        if mean_residual >= 3.0 && fresh_left as f64 >= mean_residual
            && (fresh_left as f64 % mean_residual) < 1.5 {
            score -= 6.0 * (1.0 - progress) ;
        }
        // NEW: don't open fresh bins late when any open bin fits next item comfortably
        if progress > 0.6 && fitting_bins_count > 3 && mean_residual > next_item_size as f64 {
            score += 10.0 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the leftover space: leftovers in low classes
    // (small residual) are hard to reuse; penalize dead space.
    let leftover_class = post_residual / 10; // 0..=10 integer division classes
    score += (leftover_class as f64) * 3.0;

    // Reward leaving room for the lookahead item (harmonic pairing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // leftover can host next item: reward closeness of the match
            let slack = post_residual - next_item_size;
            score -= 40.0 - (slack as f64).min(40.0);
            // exact harmonic match: post_residual == next_item_size
            if slack == 0 {
                score -= 200.0;
            }
        } else {
            // next item cannot use this leftover: penalize proportionally
            score += ((next_item_size - post_residual) as f64) * 0.5;
        }
    }

    // Last-chance bin (only fitting bin): strong bonus to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    } else if fitting_bins_count > 1 {
        // prefer filling more fragmented bins when alternatives exist:
        // penalize bins whose residual is much larger than mean (wasteful pick)
        let diff = bin_residual as f64 - mean_residual;
        if diff > 0.0 {
            score += diff * 0.3;
        }
    }

    // Modulo logic on capacity fractions: bins whose residual lies in a
    // "useless" band (residual % 50 < 10, i.e. awkward slivers) get penalized
    // when we would leave such a sliver behind.
    if post_residual > 0 && (post_residual % 50) < 10 {
        score += 15.0;
    }
    // Reward post_residuals that are multiples of common item harmonics (10/20/25)
    if post_residual > 0 && (post_residual % 25 == 0 || post_residual % 20 == 0) {
        score -= 10.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin
    // fits well (post_residual large relative to capacity) and stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let threshold = 60.0 * (1.0 - 0.5 * progress);
        if post_residual as f64 > threshold && fitting_bins_count == 0 {
            score -= 80.0; // fresh bin is attractive when nothing fits well
        } else {
            score += 120.0; // otherwise strongly discourage opening new bins
        }
    }

    score
}

