pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64);
    } else if post_residual > 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Prefer bins whose residual was already small (tight packing pressure).
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score += 15.0 * tightness;

    // Open-bin pressure: discourage spreading across many open bins.
    score += 0.6 * open_bins_count as f64;

    // Last chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post-residual exactly, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after <= 10 {
            score -= 25.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        // Next item cannot use the gap: penalize leaving it.
        score += 10.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 80.0;
        } else if mean_residual < item_size as f64 * 0.5 {
            score -= 10.0;
        } else {
            score += 25.0 + 0.8 * open_bins_count as f64;
        }
    }

    // Slight late-stream conservatism: keep gaps usable as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

