    // 2-step lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) == nxt {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item fits: moderate reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving a gap smaller than next item.
            score += 40.0 * (nxt - post_residual as f64) / nxt.max(1.0);
        }
    }

    // Relative to mean residual: bins with less residual than average are tighter fits.
    score += 2.0 * (bin_residual as f64 - mean_residual);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize unless current item is large relative to capacity
    // or very few bins fit the item (avoid wasting fresh bins on small items).
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        score += 250.0 * (1.0 - frac);
        if fitting_bins_count <= 1 {
            score -= 120.0;
        }
    }

    // Late in the stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 50.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    if post_residual == 0 {
        score -= 1000.0 ;
    } else {
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 900.0 - 30.0 * progress ;
            } else if next_item_size <= post_residual {
                let two_step_waste = (post_residual - next_item_size) as f64 ;
                if two_step_waste == 0.0 {
                    score -= 700.0 ;
                } else if two_step_waste >= 10.0 {
                    score -= 300.0 - 2.0 * two_step_waste ;
                } else {
                    score -= 80.0 + 1.5 * (10.0 - two_step_waste) ;
                }
                // cushion: comfortable slack for the next item
                let after_next = post_residual - next_item_size ;
                if after_next >= 3 {
                    score -= (2.0 + 2.0 * progress) * (after_next as f64) . min (15.0) ;
                }
                // leftover after next item stays usable
                if after_next <= 12 && mean_residual >= after_next as f64 {
                    score -= 22.0 - 0.8 * after_next as f64 ;
                }
                // leftover can host next item again (chain home)
                if next_item_size > 1 && after_next >= next_item_size {
                    score -= 6.0 + 0.2 * (after_next / next_item_size) as f64 ;
                    if after_next % next_item_size == 0 {
                        score -= 8.0 * (1.0 - progress) ;
                    }
                }
                // near-seal sliver after next item
                if after_next < next_item_size && after_next <= 3 {
                    score -= 14.0 * (1.0 - progress) ;
                }
                // leftover just below next item: near-seal, mild late reward
                if after_next < next_item_size && after_next >= 1 && (next_item_size - after_next) <= 5 {
                    score -= 6.0 * (1.0 - progress) ;
                }
                // leftover matches mean residual shape: reusable home
                if (after_next as f64 - mean_residual) . abs () <= 4.0 {
                    score -= 6.0 * (1.0 - progress) ;
                }
                // NEW: leftover after next item can also host the item after that
                // (two-step lookahead chain) — keeps the home alive longer
                if next_item_size > 1 && after_next >= 2 * next_item_size {
                    score -= 5.0 * (1.0 - progress) ;
                }
            } else {
                let miss = next_item_size - post_residual ;
                score += 2.0 * miss as f64 ;
                if post_residual < 25 {
                    score += 15.0 ;
                }
                // near-perfect sealed bins
                if post_residual < 3 {
                    score -= 400.0 ;
                }
                // near-miss with only one other fitting bin: keep it alive
                if miss <= 6 && fitting_bins_count <= 2 {
                    score -= 5.0 ;
                }
                // salvage late in the stream with few alternatives
                if miss <= 10 && fitting_bins_count <= 2 && progress > 0.7 {
                    score -= 10.0 * (1.0 - progress) ;
                }
                // near-miss that seals the bin exactly on a later small item
                if miss <= 2 {
                    score -= 18.0 * (1.0 - progress) ;
                }
                // strand-space guard just under common small sizes
                if post_residual >= 8 && post_residual <= 16 {
                    score += 10.0 * (1.0 - progress) ;
                }
                // near-miss whose gap matches mean residual shape — dead space
                if miss > 3 && miss as f64 <= mean_residual * 0.5 {
                    score += 4.0 * (1.0 - progress) ;
                }
            }
        }
        if post_residual < 10 {
            score += 45.0 ;
        } else if post_residual < 20 {
            score += 10.0 ;
        }
        score -= (mean_residual - post_residual as f64) * 0.6 ;
        // dead-gap penalty with scarcity scaling
        let gap = (post_residual as f64 - item_size as f64) . max (0.0) ;
        let gap_ratio = gap / (item_size as f64) . max (1.0) ;
        if gap > 0.0 {
            let scarcity = if fitting_bins_count <= 2 { 0.6 } else if fitting_bins_count <= 4 { 0.3 } else { 0.2 } ;
            score += scarcity * gap + 18.0 * gap_ratio . min (2.0) ;
            if gap < mean_residual {
                let fillable = next_item_size > 0 && gap >= next_item_size as f64 ;
                let w = if fillable { 0.2 } else { 0.6 } ;
                score += w * (mean_residual - gap) ;
            }
            if next_item_size > 0 && (gap as u32) == next_item_size {
                score -= 20.0 ;
            }
            if next_item_size > 1 && (gap as u32) == 2 * next_item_size {
                score -= 12.0 ;
            }
        }
        if fitting_bins_count == 1 {
            score -= 12.0 ;
        }
        let fill = item_size as f64 / (bin_residual as f64) . max (1.0) ;
        score -= 20.0 * fill ;
        // dead space: unusable residual relative to next item
        if next_item_size > 0 && post_residual < next_item_size {
            let dead_frac = post_residual as f64 / bin_capacity as f64 ;
            let unusable_ratio = post_residual as f64 / (next_item_size as f64) . max (1.0) ;
            score += 0.4 * post_residual as f64 + 30.0 * dead_frac + 12.0 * (1.0 - unusable_ratio) ;
            if next_item_size - post_residual <= 4 {
                score += 20.0 * (1.0 - progress) ;
            }
        }
        // anti-fragmentation guard
        if fitting_bins_count == 2 && post_residual < bin_capacity / 3 {
            score -= 8.0 ;
        }
        // tiny unusable slivers when bins are plentiful
        if post_residual <= 5 && open_bins_count > 6 {
            score += 25.0 * (1.0 - progress) ;
        }
        // mid-sized future homes
        if post_residual >= bin_capacity / 8 && post_residual <= bin_capacity / 2 {
            score -= 6.0 ;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= bin_capacity / 2 {
            score -= 4.0 * (1.0 - progress) ;
        }
        // reward residuals that can absorb two more average items
        if post_residual as f64 >= 2.0 * mean_residual && post_residual > 20 {
            score -= 5.0 ;
        }
        // compaction sweet spot: headroom matches mean residual
        if next_item_size > 0 && post_residual > next_item_size {
            let headroom = post_residual - next_item_size ;
            if (headroom as f64 - mean_residual) . abs () <= 3.0 {
                score -= 7.0 ;
            }
            if (headroom as f64 - mean_residual) . abs () <= 1.0 && fitting_bins_count <= 3 {
                score -= 5.0 * (1.0 - progress) ;
            }
        }
        // three-way closure: residual hosts next item then seals exactly
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0 ;
        }
        // residual that fits next item plus a small item is doubly useful
        if next_item_size > 1 && post_residual > next_item_size + 1 && post_residual <= next_item_size + 10 {
            score -= 4.0 * (1.0 - progress) ;
        }
        // NEW: residual can host next item AND still fit the mean-sized follow-up
        // — a stronger version of the compaction sweet spot
        if next_item_size > 0 && post_residual > next_item_size + 1 {
            let tail = post_residual - next_item_size ;
            if tail as f64 >= mean_residual * 0.8 && tail <= 2.0 * mean_residual.max(4.0) {
                score -= 6.0 * (1.0 - progress) ;
            }
        }
    }
    // NEW-BIN CANDIDATE
    if bin_residual == bin_capacity {
        let big_next = next_item_size as f64 / bin_capacity as f64 ;
        score += 180.0 - 60.0 * progress + 0.15 * open_bins_count as f64 - 25.0 * big_next . max (0.0) ;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0 ;
        }
        if open_bins_count <= 4 && progress < 0.3 {
            score += 25.0 ;
        }
        if mean_residual < 15.0 && progress > 0.5 {
            score -= 15.0 ;
        }
        let item_frac = item_size as f64 / bin_capacity as f64 ;
        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3 ;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3 ;
        }
        let fresh_left = bin_capacity - item_size ;
        if next_item_size > 0 && fresh_left == next_item_size {
            score -= 30.0 ;
        }
        if open_bins_count > 6 && mean_residual > 0.4 * bin_capacity as f64 {
            score += 20.0 ;
        }
        // fresh-bin leftover sliver is wasteful
        if next_item_size > 0 && fresh_left < next_item_size && fresh_left < 8 {
            score += 35.0 ;
        }
        // prefer fresh bin when all existing residuals are too small for next item
        if next_item_size > 0 && fitting_bins_count <= 2 && mean_residual < next_item_size as f64 {
            score -= 18.0 * (1.0 - progress) ;
        }
        // discourage opening fresh bins late when many half-empty bins exist
        if open_bins_count > 8 && mean_residual > next_item_size as f64 + 10.0 {
            score += 12.0 ;
        }
        // large items into fresh bins leave big usable leftovers: mild reward
        if item_frac > 0.6 && next_item_size > 0 && fresh_left >= next_item_size {
            score -= 8.0 * (1.0 - progress) ;
        }
        // fresh bin justified when leftover can host next item plus mean slack
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress) ;
        }
        // near-zero tail after next item (perfect closure)
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size ;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress) ;
            }
        }
        // fresh bin leftover below mean residual is likely dead space
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        // chain home: leftover hosts next item twice exactly
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        // near-exact fill wastes nothing and preserves all open residuals
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        // fresh bin leftover matching mean residual — reusable home shape
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        // chain home: leftover hosts next item multiple times exactly
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        // fresh bin leftover that hosts next item plus mean-shaped slack
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        // avoid opening fresh bins when a fitting open bin nearly seals with this item
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        // NEW: fresh bin is only worth it early if the leftover will actually be
        // consumed — penalize leftovers far above mean residual mid-stream
        if progress > 0.35 && next_item_size > 0 && fresh_left > next_item_size
            && (fresh_left - next_item_size) as f64 > mean_residual * 1.5 {
            score += 8.0 * progress ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early in the stream, keep bins flexible; late, pack tight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Penalize large post-residual more as the stream advances (less time to fill leftovers).
    score += 0.35 * (post_residual as f64) * (0.5 + progress);

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.45 * next_item_size as f64 * (1.0 - 0.5 * progress);
    } else if next_item_size > 0 {
        // Post-residual too small for next item: dead-space penalty grows with tightness of fit.
        score += 0.25 * (post_residual as f64).max(0.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0 * (1.0 + progress);
    }

    // Discourage opening new bins when many open bins with slack exist.
    if bin_residual == bin_capacity {
        let mean_r = if mean_residual.is_finite() { mean_residual } else { 0.0 };
        score += 8.0 + 0.10 * open_bins_count as f64 + 0.05 * mean_r;
    }

    // Prefer bins tighter than average (best-fit flavor).
    let dev = bin_residual as f64 - if mean_residual.is_finite() { mean_residual } else { bin_residual as f64 };
    score += 0.08 * dev;

    // Small exact-fit bonus.
    if post_residual == 0 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Perfect seal: overwhelmingly attractive.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Tightness reward.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0 - 30.0 * progress;
        } else if post_residual >= next_item_size {
            let after_next = post_residual - next_item_size;
            score -= 80.0;
            // Cushion: comfortable slack for the next item.
            if after_next >= 3 {
                score -= (2.0 + 2.0 * progress) * (after_next as f64).min(15.0);
            }
            // Leftover stays usable / chain home.
            if next_item_size > 1 && after_next >= next_item_size {
                score -= 6.0 + 0.2 * (after_next / next_item_size) as f64;
                if after_next % next_item_size == 0 {
                    score -= 8.0 * (1.0 - progress);
                }
            }
            // Headroom matches mean residual shape: reusable home.
            if (after_next as f64 - mean_residual).abs() <= 4.0 {
                score -= 6.0 * (1.0 - progress);
            }
            // Near-seal sliver after next item.
            if after_next < next_item_size && after_next <= 3 {
                score -= 14.0 * (1.0 - progress);
            }
            if post_residual == 2 * next_item_size {
                score -= 10.0;
            }
        } else {
            // Cannot host next item: penalize dead space.
            let miss = next_item_size - post_residual;
            score += 2.0 * miss as f64;
            if post_residual < 3 {
                score -= 400.0; // near-sealed, still great
            }
            if post_residual < 25 {
                score += 15.0;
            }
            if miss <= 2 {
                score -= 18.0 * (1.0 - progress);
            }
            if miss <= 6 && fitting_bins_count <= 2 {
                score -= 5.0;
            }
            if post_residual >= 8 && post_residual <= 16 {
                score += 10.0 * (1.0 - progress); // strand guard
            }
        }
    }

    // Small unusable residuals are bad.
    if post_residual < 10 {
        score += 45.0;
    } else if post_residual < 20 {
        score += 10.0;
    }

    score -= (mean_residual - post_residual as f64) * 0.6;

    // Dead-gap penalty with scarcity scaling.
    let gap = (post_residual as f64 - item_size as f64).max(0.0);
    if gap > 0.0 {
        let gap_ratio = gap / (item_size as f64).max(1.0);
        let scarcity = if fitting_bins_count <= 2 { 0.6 } else if fitting_bins_count <= 4 { 0.3 } else { 0.2 };
        score += scarcity * gap + 18.0 * gap_ratio.min(2.0);
        if next_item_size > 0 && (gap as u32) == next_item_size {
            score -= 20.0;
        }
        if next_item_size > 1 && (gap as u32) == 2 * next_item_size {
            score -= 12.0;
        }
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Fill ratio reward.
    let fill = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 20.0 * fill;

    // Unusable residual relative to next item.
    if next_item_size > 0 && post_residual < next_item_size {
        let dead_frac = post_residual as f64 / bin_capacity as f64;
        score += 0.4 * post_residual as f64 + 30.0 * dead_frac;
        if next_item_size - post_residual <= 4 {
            score += 20.0 * (1.0 - progress);
        }
    }

    // Anti-fragmentation guard.
    if fitting_bins_count == 2 && post_residual < bin_capacity / 3 {
        score -= 8.0;
    }
    // Tiny slivers when bins are plentiful.
    if post_residual <= 5 && open_bins_count > 6 {
        score += 25.0 * (1.0 - progress);
    }
    // Mid-sized future homes.
    if post_residual >= bin_capacity / 8 && post_residual <= bin_capacity / 2 {
        score -= 6.0;
    }
    // Residual absorbs two more average items.
    if post_residual as f64 >= 2.0 * mean_residual && post_residual > 20 {
        score -= 5.0;
    }

    // Late-stream consolidation.
    score -= 6.0 * progress * tightness;
    score -= 0.02 * (open_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64);

    // NEW-BIN CANDIDATE.
    if bin_residual == bin_capacity {
        let fresh_left = bin_capacity - item_size;
        let item_frac = item_size as f64 / bin_capacity as f64;
        score += 180.0 - 60.0 * progress + 0.15 * open_bins_count as f64;
        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3;
        }
        if next_item_size > 0 && fresh_left == next_item_size {
            score -= 30.0;
        }
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress);
            }
        }
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress);
        }
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress);
        }
        if (fresh_left as f64 - mean_residual).abs() <= 2.0 {
            score -= 8.0;
        }
        // Avoid opening fresh bins when an open bin nearly seals.
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0;
        }
        if fresh_left < next_item_size && fresh_left < 8 {
            score += 35.0;
        }
        if open_bins_count <= 4 && progress < 0.3 {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post / cap;
    // smooth non-linear coupling of post_residual with stream progress
    let w = post / cap;
    score += 0.6 * w * w * (1.0 + progress);
    score += 0.4 * w * progress * (1.0 - progress);
    // reward tight fits more strongly as stream progresses
    score -= (1.0 - w) * (1.0 - w) * (0.5 + 0.5 * progress);
    // penalize opening new bins early; allow late stream to prefer new bins for bad fits
    let new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if new_bin {
        score += 0.3 * (1.0 - progress) - 0.1 * progress;
    }
    // last chance bin: strong reward
    if fitting_bins_count == 1 && !new_bin {
        score -= 0.5 + 0.5 * progress;
    }
    // lookahead: reward leaving room for next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 0.2 * (post - nxt) / cap;
        } else {
            score += 0.3 * (nxt - post) / cap;
        }
    }
    // mean residual coupling
    score += 0.1 * (mean_residual - post) / cap;
    score
}

