pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify leftover into residue classes mod 10
    let pr = post_residual;
    let class = pr % 10;
    // Dead-space penalty grows when leftover cannot plausibly host future items (sizes 1..100)
    if pr > 0 {
        // leftovers that are small primes-of-waste classes are bad
        if pr < 10 {
            score += 60.0; // tiny unusable sliver
        } else if class == 0 {
            score -= 25.0; // round leftover, easy to refill
        } else if class <= 3 {
            score += 20.0;
        } else if class >= 7 {
            score += 10.0;
        } else {
            score -= 8.0;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 400.0;
        } else if next_item_size < pr && (pr - next_item_size) % 10 == 0 {
            score -= 90.0; // leaves round residual again
        } else if next_item_size < pr {
            score -= 20.0;
        } else {
            score += 35.0; // next item cannot use this bin's leftover
        }
        // integer-division threshold: half-capacity boundary
        if pr >= bin_capacity / 2 && next_item_size <= pr {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate logic: only attractive when current bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / cap;
        // penalize new bins when open bins are roomy; reward when fragmented or early
        score += 120.0 * (1.0 - fragmentation) - 80.0 * progress;
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 40.0; // big next item favors a fresh bin
        }
    }

    // Mild preference for tighter existing bins (waste-proportional penalty)
    score += (post_residual as f64 / cap) * 15.0;

    // Prefer bins whose residual is below mean residual (better fill density)
    if (bin_residual as f64) < mean_residual {
        score -= 12.0;
    }

    score
}

