pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is best).
    score += (post_residual as f64) * 0.5;

    // Penalize leaving dead space relative to the smallest plausible next item.
    let dead = post_residual as f64;
    score += dead * dead / (bin_capacity as f64);

    // Lookahead: if the next item fits exactly in the post-residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        score -= 20.0 - gap as f64 * 0.3;
    }
    // If next item is bigger than post-residual, this bin's remaining space is likely dead.
    if next_item_size > post_residual {
        score += dead * 0.6;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when it yields a very tight long-term fit
    // or when all open bins are poor fits (high mean residual waste).
    if bin_residual == bin_capacity {
        let waste_of_open = (mean_residual - item_size as f64).max(0.0);
        let t = step_index as f64 / (total_items.max(1) as f64).max(1.0);
        // Later in the stream, be more reluctant to open new bins.
        let new_bin_penalty = 25.0 + 40.0 * t;
        score += new_bin_penalty - waste_of_open * 0.2;
        // Perfect fit of a large item in a fresh bin is fine.
        if post_residual == 0 {
            score -= 15.0;
        }
    }

    // Mild preference for filling bins that are already mostly full.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 10.0;

    // Global pressure: many open bins -> prefer consolidating into existing ones.
    if open_bins_count > 4 {
        score += 2.0 * ((open_bins_count as f64).ln());
    }

    // Prefer bins whose residual is above mean (keep low-residual bins for small future items).
    if (bin_residual as f64) < mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    if post_residual == 0 {
        score -= 1000.0 ;
    } else {
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 900.0 - 30.0 * progress ;
            } else if next_item_size <= post_residual {
                let two_step_waste = (post_residual - next_item_size) as f64 ;
                if two_step_waste == 0.0 {
                    score -= 700.0 ;
                } else if two_step_waste >= 10.0 {
                    score -= 300.0 - 2.0 * two_step_waste ;
                } else {
                    score -= 80.0 + 1.5 * (10.0 - two_step_waste) ;
                }
                let after_next = post_residual - next_item_size ;
                if after_next >= 3 {
                    score -= (2.0 + 2.0 * progress) * (after_next as f64) . min (15.0) ;
                }
                if after_next <= 12 && mean_residual >= after_next as f64 {
                    score -= 22.0 - 0.8 * after_next as f64 ;
                }
                if next_item_size > 1 && after_next >= next_item_size {
                    score -= 6.0 + 0.2 * (after_next / next_item_size) as f64 ;
                    if after_next % next_item_size == 0 {
                        score -= 8.0 * (1.0 - progress) ;
                    }
                }
                if after_next < next_item_size && after_next <= 3 {
                    score -= 14.0 * (1.0 - progress) ;
                }
                if after_next < next_item_size && after_next >= 1 && (next_item_size - after_next) <= 5 {
                    score -= 6.0 * (1.0 - progress) ;
                }
                if (after_next as f64 - mean_residual) . abs () <= 4.0 {
                    score -= 6.0 * (1.0 - progress) ;
                }
            } else {
                let miss = next_item_size - post_residual ;
                score += 2.0 * miss as f64 ;
                if post_residual < 25 {
                    score += 15.0 ;
                }
                if post_residual < 3 {
                    score -= 400.0 ;
                }
                if miss <= 6 && fitting_bins_count <= 2 {
                    score -= 5.0 ;
                }
                if miss <= 10 && fitting_bins_count <= 2 && progress > 0.7 {
                    score -= 10.0 * (1.0 - progress) ;
                }
                if miss <= 2 {
                    score -= 18.0 * (1.0 - progress) ;
                }
                if post_residual >= 8 && post_residual <= 16 {
                    score += 10.0 * (1.0 - progress) ;
                }
                if miss > 3 && miss as f64 <= mean_residual * 0.5 {
                    score += 4.0 * (1.0 - progress) ;
                }
            }
        }
        if post_residual < 10 {
            score += 45.0 ;
        } else if post_residual < 20 {
            score += 10.0 ;
        }
        score -= (mean_residual - post_residual as f64) * 0.6 ;
        let gap = (post_residual as f64 - item_size as f64) . max (0.0) ;
        let gap_ratio = gap / (item_size as f64) . max (1.0) ;
        if gap > 0.0 {
            let scarcity = if fitting_bins_count <= 2 { 0.6 } else if fitting_bins_count <= 4 { 0.3 } else { 0.2 } ;
            score += scarcity * gap + 18.0 * gap_ratio . min (2.0) ;
            if gap < mean_residual {
                let fillable = next_item_size > 0 && gap >= next_item_size as f64 ;
                let w = if fillable { 0.2 } else { 0.6 } ;
                score += w * (mean_residual - gap) ;
            }
            if next_item_size > 0 && (gap as u32) == next_item_size {
                score -= 20.0 ;
            }
            if next_item_size > 1 && (gap as u32) == 2 * next_item_size {
                score -= 12.0 ;
            }
        }
        if fitting_bins_count == 1 {
            score -= 12.0 ;
        }
        let fill = item_size as f64 / (bin_residual as f64) . max (1.0) ;
        score -= 20.0 * fill ;
        if next_item_size > 0 && post_residual < next_item_size {
            let dead_frac = post_residual as f64 / bin_capacity as f64 ;
            let unusable_ratio = post_residual as f64 / (next_item_size as f64) . max (1.0) ;
            score += 0.4 * post_residual as f64 + 30.0 * dead_frac + 12.0 * (1.0 - unusable_ratio) ;
            if next_item_size - post_residual <= 4 {
                score += 20.0 * (1.0 - progress) ;
            }
        }
