        0 => 60.0,
        1..=5 => 35.0,
        6..=10 => 18.0,
        11..=20 => 8.0,
        _ => 0.0,
    };
    score -= tight_bonus;

    // Penalize dead space that no realistic item (>= 1, typically >= 10) can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Modulo-class coupling: does post_residual land in a "good" residue class
    // for the next item? Reward if next item fits nearly exactly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let post_fit = post_residual - next_item_size;
            score -= 20.0 - (post_fit.min(20) as f64); // lookahead leaves small remainder
        } else {
            score += (next_item_size - post_residual).min(30) as f64 * 0.5;
        }
        // Harmonic pairing: item and next item of same class prefer shared bins
        let next_class = if next_item_size <= quarter { 0 } else if next_item_size <= half { 1 } else if next_item_size <= 3 * quarter { 2 } else { 3 };
        if next_class == item_class && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Integer-division threshold on post_residual: blocks of quarter capacity
    let blocks = post_residual / quarter;
    score += blocks as f64 * 6.0; // more whole quarter-blocks left = less urgent to fill

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: mildly penalize so we prefer existing bins,
    // unless current bin fit is poor (large post_residual) or stream is early
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = post_residual as f64 > cap * 0.35;
        if poor_fit && progress > 0.05 {
            score -= 15.0; // open fresh bin rather than waste space
        } else {
            score += 12.0 + open_bins_count as f64 * 0.5;
        }
    }

    // Slight preference for bins below mean residual (consolidate emptier bins)
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.05;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
