    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Aggressive 2-step lookahead: perfect chain (post_residual == next_item_size)
    // is the ideal placement — strongly reward.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        let gap_frac = gap as f64 / bin_capacity as f64;
        if gap == 0 {
            score -= 25.0;
        } else {
            score += 20.0 * gap_frac;
        }
        // If next item cannot fit anywhere else and this chain works, extra reward.
        if gap == 0 && fitting_bins_count <= 2 {
            score -= 10.0;
        }
    } else {
        // Last item: pure best-fit, nothing to preserve.
        score -= 8.0;
    }

    // Penalize creating dead space that no plausible item (10..80) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate logic: opening a fresh bin is only attractive when the
    // item is large (would leave big waste elsewhere) or existing residuals are bad.
    if bin_residual == bin_capacity {
        // Base penalty to prefer existing bins with decent fits.
        score += 12.0;
        // Large item with poor existing fit -> new bin more attractive.
        let waste_elsewhere = (bin_capacity - item_size) as f64;
        if item_size > 60 && mean_residual < item_size as f64 + 10.0 {
            score -= 20.0;
        }
        // Late in stream, avoid proliferating bins unless necessary.
        if total_items > 0 && step_index as f64 / total_items as f64 > 0.8 {
            score += 10.0;
        }
        // Lookahead: a fresh bin perfectly chains with next item.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity
            && (bin_capacity - item_size - next_item_size) <= 10 {
            score -= 15.0;
        }
        let _ = waste_elsewhere;
    }

    // Mild preference for consolidating into bins below mean residual
    // (fills emptier bins first, keeping tight bins for tight items).
    if bin_residual < bin_capacity && (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Prefer bins with fewer alternatives when fits are scarce overall.
    if open_bins_count > 0 && fitting_bins_count as f64 <= open_bins_count as f64 * 0.25 {
        score -= 5.0;
    }

    score
}

