    // Polynomial coupling with stream progress: early on tolerate slack, later penalize it harder
    score += pr * (0.5 + 1.5 * progress * progress) * 0.5;

    // Smooth interaction: reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= item_size as f64 * tightness * (0.3 + 0.7 * progress);

