            score -= 6.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 && progress > 0.6 {
            score += 10.0 * progress ;
        }
        if item_frac > 0.5 && progress < 0.4 {
            score -= 6.0 * (0.4 - progress) / 0.4 ;
        }
        // mutation: fresh-bin dead-space guard — reject a new bin whose leftover would strand
        // a small awkward remainder relative to the current mean residual
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = (fresh_left - next_item_size) as f64 ;
            if tail > 4.0 && tail < mean_residual * 0.5 {
                score += 12.0 * (1.0 - progress) ;
            }
        }
        // mutation: avoid opening fresh bins while open-bin mean residual can still absorb
        // the next two items on average (reduce fragmentation source)
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && open_bins_count > 2 {
            score += 4.0 + 6.0 * (1.0 - progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // capacity-fraction bands. Smaller classes (tighter fits) get rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let class = (post / cap * 8.0).floor() as i32; // 0..=7 harmonic octave

    // Reward tight fits (small post_residual classes) super-linearly.
    match class {
        0 => score -= 30.0,                    // near-perfect fit
        1 => score -= 18.0,
        2 => score -= 10.0,
        3 => score -= 4.0,
        5 => score += 6.0,                     // half-full leftovers are awkward
        6 => score += 10.0,
        _ => {}
    }

    // Dead-space penalty: residuals that few future item sizes can use.
    // Items are 1..=100; a residual r is "usable" by any item <= r.
    // Penalize residuals in the awkward band (r < 20 => nearly unusable).
    if post_residual > 0 && post_residual < 15 {
        score += 25.0;
    }

    // Modulo arithmetic: residuals that are multiples of common item sizes
    // (10, 20, 25, 50) are more likely to be filled exactly later.
    let r = post_residual;
    if r % 10 == 0 && r > 0 { score -= 5.0; }
    if r % 25 == 0 && r > 0 { score -= 3.0; }
    if r == 50 { score -= 4.0; }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but how tightly?
            let next_left = post_residual - next_item_size;
            score -= 12.0 - (next_left as f64) * 0.3;
        } else {
            // Next item won't fit here; penalize wasting this bin's potential.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bonus: this is the only open bin that fits the item.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate logic: an empty bin should only win when existing
    // fits are poor. Give the fresh bin a mild baseline penalty that grows
    // with stream progress (late in the stream, prefer consolidation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 + 20.0 * progress;
        // But if existing bins are very fragmented (high mean residual spread
        // vs item size), opening fresh is fine.
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
    }

    // Prefer filling bins with below-average residual (consolidate fragments).
    score += (bin_residual as f64 - mean_residual) * 0.1;

    // Slight preference for bins that will be left with "nice" totals.
    if post_residual >= bin_capacity as u32 / 2 {
        score += 3.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
