        score += 60.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Reward tight fits (exact or near-exact fills).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Dead space is worse if the next item is large and cannot use the leftover gap.
    if next_item_size > 0 {
        if (post_residual as u32) < next_item_size && post_residual > 0 {
            score += 15.0 + 0.2 * next_item_size as f64;
        } else if post_residual >= next_item_size {
            // leftover gap can host the lookahead item: reward
            score -= 10.0;
        }
