    // existing bins rather than opening new ones.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize increasingly with open bins and stream progress.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 + 6.0 * open_pressure + 40.0 * progress;
        // Opening a new bin is only attractive if nothing fits well anywhere.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    } else {
        // Existing bin: slight reward when bin pressure is high, especially
        // if this is the last fitting bin.
        if fitting_bins_count == 1 {
            score -= 35.0;
