    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item size well (chained placement).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        // Perfect chain: next item fills bin completely afterwards.
        if gap == 0.0 {
            score -= 900.0;
        } else {
            score -= 400.0 * (1.0 - gap / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // Next item will NOT fit here after placement: penalize dead space.
        let wasted = (post_residual as f64).min(next_item_size as f64);
        score += 60.0 + 0.5 * wasted;
    }

    // Penalize bins far from the mean residual (avoid fragmenting good bins).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when current bin fit is very poor.
    if bin_residual == bin_capacity {
