    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 20.0 + 5.0 * fitting_bins_count as f64;
        } else {
            score -= 10.0;
        }
    }

    // Time horizon: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global state: if mean residual is high, prefer filling fuller bins.
    score += 0.3 * (mean_residual - post_residual as f64);

