pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual (tight fit), non-linearly
    let mut score = norm_pr * norm_pr * 40.0 + norm_pr * 20.0;

    // Smooth non-linear coupling of post-residual with stream progress:
    // early on, waste matters less; later, squeeze bins harder.
    let progress_coupling = norm_pr * (0.5 + progress * (1.0 - progress) * 4.0);
    score += progress_coupling * 30.0;

    // Perfect/near-perfect fits get strong smooth reward
    let fit_quality = 1.0 - (pr / cap);
    score -= item_size as f64 * fit_quality * 0.15;

    // Penalize bins with residuals far from the mean (fragmentation signal)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev.abs() * dev.abs() * 10.0;

    // Last-chance bin: smooth bonus scaled by progress
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward if next item fits the post-residual (chaining)
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= (1.0 - gap / cap) * 12.0;
        } else {
            score += (-gap / cap) * 6.0;
        }
    }

    // New-bin candidate: mildly discouraged early, more acceptable when
    // open bins are crowded (mean residual low) late in the stream.
    if bin_residual == bin_capacity {
        let crowding = 1.0 - (mean_residual / cap).min(1.0);
        score = 25.0 + 30.0 * progress - 20.0 * crowding * progress;
    }

    // Mild penalty for too many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

