pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let q4 = post_residual / (bin_capacity / 4);
    let q8 = post_residual / (bin_capacity / 8);
    let r8 = (post_residual % (bin_capacity / 8)) as f64;

    // Reward post-residuals that are "harmonically clean" (near multiples of
    // capacity/8): dead space is reusable by common item sizes.
    let harmonic_bonus = (r8 / 4.0).min(1.0) * 6.0;
    score -= harmonic_bonus;

    // Penalize tiny dead-space classes that nothing fits into.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Quarter-class logic: full quarter residual is excellent, three-quarters
    // residual is a good slot for mid-size items.
    match q4 {
        0 => score += 25.0,                 // near-perfect fit
        1 => score -= 8.0,                  // quarter left: useful
        2 => score -= 4.0,                  // half left
        3 => score -= 10.0,                 // three quarters: big slot
        _ => {}
    }

    // Integer-division threshold on next_item_size vs post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains into this bin: strong reward, scaled by fit tightness.
            let chain_tight = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 15.0 + 20.0 * chain_tight;
        } else {
            // Next item cannot use this residual; penalize proportionally to waste.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
        // Harmonic pairing: post_residual divisible by next_item_size class.
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: mildly penalize so it's chosen only for hopeless fits.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.05 * open_bins_count as f64;
    }

    // Late-stream consolidation: prefer tighter bins as the stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * mean_residual * 0.05;

    // Tie-break: prefer bins with residual far from the awkward mid-range.
    let mid_dist = (pr - cap * 0.5).abs() / cap;
    score -= mid_dist * 5.0;

    score
}

