        // Slight penalty when many bins compete, encouraging consolidation.
        score += 0.3 * (fitting_bins_count as f64).min(6.0);
    }

    // Prefer filling bins that are already relatively empty compared to the mean,
    // balancing residual distribution across open bins.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Late in the stream, favor closing out bins: reward high fill ratio.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
