    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate: keep it moderately attractive only when existing bins waste space
    if bin_residual == bin_capacity {
        score = 20.0 + 10.0 * (mean_residual / cap) - 6.0 * progress;
    }

    score
