        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size ;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress) ;
            }
        }
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        // mutation: discourage fresh bins late when any open bin can host next item comfortably
        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 && progress > 0.6 {
            score += 10.0 * progress ;
        }
        // mutation: fresh bin attractive early with big items (large usable leftover)
        if item_frac > 0.5 && progress < 0.4 {
            score -= 6.0 * (0.4 - progress) / 0.4 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into a
    // "reusable" class (divisible by common item sizes) are more valuable.
    let classes = [10u32, 20, 25, 50];
    let mut class_bonus = 0.0;
    for c in classes.iter() {
        if post_residual % c == 0 && post_residual > 0 {
            class_bonus += 6.0 * (post_residual as f64 / *c as f64).ln().max(0.0);
        }
    }
    score -= class_bonus;

    // Penalize dead space: leftover that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match between next item and post residual
            if post_residual % next_item_size == 0 {
                score -= 20.0;
            } else {
                score -= 8.0;
            }
        } else {
            // Next item won't fit here; penalize proportionally to waste
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln().max(1.0);
        let poor_fit = if post_residual < 10 { 1.0 } else { 0.0 };
        score += 18.0 * pressure - 15.0 * poor_fit
            + (mean_residual / bin_capacity as f64) * 10.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Slight preference for tighter bins (small residual before placement).
    score += bin_residual as f64 * 0.05;

    // Mean residual coupling: when open bins are generally full, avoid
    // fragmenting; when they are loose, consolidation is cheaper.
    score -= (mean_residual - post_residual as f64).abs() * 0.02;

    score
}

