            }
        }
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0;
        }
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0;
        }
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress);
        }
        if next_item_size > 0 && (fresh_left as f64 - mean_residual).abs() <= 2.0 {
            score -= 8.0;
        }
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual).abs() <= 3.0 {
            score -= 9.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0;
        }
        // Discourage fresh bins late when an open bin can host the next item comfortably.
        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 && progress > 0.6 {
            score += 10.0 * progress;
        }
        // Fresh bin attractive early with big items (large usable leftover).
        if item_frac > 0.5 && progress < 0.4 {
            score -= 6.0 * (0.4 - progress) / 0.4;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item fits the post residual exactly or well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
            if post_residual == next_item_size {
                score -= 200.0;
            }
        } else {
            // Dead space for the next item: penalize small unusable leftovers.
            score += 15.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Penalize leaving very small unusable residue (dead space) in general.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Relative to mean residual: prefer bins that are already tight (below-mean residual)
    // so large empty bins stay available for big items.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New empty bin candidate: penalize unless it is the only option,
    // so we prefer filling existing bins; but if this bin is empty and
    // the item fits poorly nowhere else, the base residual dominates.
    if bin_residual == bin_capacity {
        score += 60.0;
        // If no other bin fits, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Late in the stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

