pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize wasted space relative to capacity non-linearly.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * tightness * tightness;

    // Penalize large post-residual dead space, especially small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead sliver
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits well into the post-residual,
    // reward this placement; otherwise penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_fit = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 15.0 * next_fit;
        } else {
            // next item won't fit here; slight penalty proportional to gap
            score += 5.0;
        }
    }

    // New-bin candidate handling: an empty bin is a fresh resource. Prefer it
    // only when open bins have large mean residuals (fragmented state) or
    // the item is huge and would leave a big hole elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // base cost of opening a new bin, discounted over time and by need
        score += 20.0 + 30.0 * (1.0 - progress) - fragmentation.min(30.0);
        if item_size >= 60 && post_residual < 20 {
            score -= 15.0; // huge item, fresh bin keeps flexibility
        }
    }

    // Global pressure: many open bins with low mean residual -> encourage
    // consolidating into existing bins.
    if open_bins_count > 2 {
        let pressure = mean_residual / bin_capacity as f64;
        score += 10.0 * pressure;
    }

    // Mild time-horizon scaling: early in the stream, be more conservative
    // (prefer new bins); late, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * (1.0 - progress);

    score
}

