pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth interaction: tight fits become more valuable as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Penalize residuals that cannot fit the next item (smooth quadratic gate)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        let fit_next = (next_item_size as f64 <= pr) as f64;
        score += 12.0 * gap / cap * (1.0 - fit_next);
        score -= 8.0 * fit_next * (1.0 - progress);
    }

    // Last-chance bonus: only fitting bin, stronger early (preserve open-bin pool)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty when bin is far below mean residual (wasteful choice)
    score += 0.3 * (mean_residual - pr).abs();

    // New-bin candidate: slight early preference, grows late
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) - 5.0 * progress;
    }

    // Crowd factor: many open bins -> favor consolidation
    score += 0.05 * open_bins_count as f64 * norm_pr;

    score
}

