pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            // smooth reward decaying with gap
            score -= 120.0 * (-gap / 25.0).exp();
        } else {
            // next item won't fit here: penalize small post_residuals that become dead space
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += 0.6 * dead * (1.0 - dead / next_item_size as f64);
            }
        }
    } else {
        // last item: strongly prefer tightest fit
        score -= 300.0 / (1.0 + post_residual as f64);
    }

    // Penalize residual far above mean residual (wasteful use of a roomy bin)
    let diff = post_residual as f64 - mean_residual;
    if diff > 0.0 {
        score += 0.15 * diff;
    } else {
        score += 0.05 * diff;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: prefer opening a new bin only when no tight fit exists elsewhere
    if bin_residual == bin_capacity {
        score += 250.0;
        // but if next item is large and current fit is poor, new bin is attractive
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            score -= 100.0;
        }
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 80.0 * (1.0 - progress);
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.5 * open_bins_count as f64;

    // Slight tie-break by bin fullness
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

