        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        // mutation: discourage fresh bins late when any open bin can host next item comfortably
        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 && progress > 0.6 {
            score += 10.0 * progress ;
        }
        // mutation: fresh bin attractive early with big items (large usable leftover)
        if item_frac > 0.5 && progress < 0.4 {
            score -= 6.0 * (0.4 - progress) / 0.4 ;
        }
        // mutation: fresh bin leftover that hosts next item then mean-sized follow-up
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size ;
            if tail as f64 >= mean_residual * 0.8 && tail as f64 <= mean_residual * 1.4 {
                score -= 7.0 * (1.0 - progress) ;
            }
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual already does this); amplify nonlinearity.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * tightness * 15.0;

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here; mild penalty for leaving awkward residual.
        let waste = post_residual as f64;
        score += 0.05 * waste;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer bins with residuals below mean (consolidate small residuals).
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Time horizon: early in stream, be conservative about fragmenting bins;
    // later, accept larger residuals more freely.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.08 * post_residual as f64;

    // Many open bins: encourage filling existing bins rather than spreading.
    score += 0.3 * open_bins_count as f64;

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    // and the item nearly fills a fresh bin.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
