pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear coupling: reward small post_residual quadratically, stronger late in stream
    let pr = post_residual as f64;
    let tightness = (pr / bin_capacity as f64).powi(2);
    score += (1.0 - progress) * tightness * 8.0 - progress * tightness * 14.0;

    // Perfect fit bonus (smooth via cubic decay)
    if post_residual == 0 {
        score -= 20.0 + 10.0 * progress;
    }

    // Lookahead: penalize leaving residual just under next item (non-linear in gap)
    if next_item_size > 0 && post_residual > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap < 0.0 && gap > -next_item_size as f64 {
            score += (gap.abs() / bin_capacity as f64).powi(3) * 12.0;
        } else if gap >= 0.0 {
            score -= (gap / bin_capacity as f64).powi(2) * 6.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Penalize opening new bins when open bins have slack (smooth sigmoid on mean residual)
    if bin_residual == bin_capacity {
        let slack = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 25.0 + 30.0 * (slack * std::f64::consts::PI).sin().abs() * (1.0 - progress);
    }

    // Mild penalty for waste far above item size, scaled by stream maturity
    score += (post_residual as f64 / bin_capacity as f64).powi(4) * 5.0 * (0.5 + progress);

    score
}

