    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 buckets.
    // Residuals that are multiples of 10 are "harmonic" — more reusable
    // by future items drawn from wide integer distributions.
    let rmod = post_residual % 10;
    if rmod == 0 {
        score -= 6.0; // perfect harmonic class reward
    } else if rmod <= 3 {
        score += 4.0 + 1.5 * rmod as f64; // tiny slivers are dead space
    } else if rmod >= 7 {
        score -= 2.0; // near-harmonic, still quite reusable
    }

    // Integer-division thresholds on post_residual: classify residual size.
    if post_residual == 0 {
        score -= 20.0; // perfect fit, always best
    } else if post_residual <= 10 {
        score += 5.0; // very small residual, hard to reuse
    } else if post_residual <= 30 {
        score -= 1.0; // mid residual fits small items
    } else if post_residual > 70 {
        score -= 3.0; // large residual, very flexible
    }

    // Coupling with next_item_size: reward if next item fits post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 4.0 + 0.05 * next_item_size as f64;
        } else {
            // penalize if next item would be stranded: gap too small
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 3.0;
            }
        }
        // Harmonic match: next_item_size divides into post_residual cleanly
        if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
            score -= 5.0;
        }
    }

    // Last-chance bin logic: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // give bad fits. Penalize the fresh bin mildly, more when many bins open.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.3 * open_bins_count as f64;
    }

    // Waste-avoidance: penalize leaving residual far below mean residual
    // (creates fragmented low-residual bins).
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += 0.08 * dev;
    }

    // Stream progression: later in stream, tighten up (avoid opening bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    // Harmonic fraction of capacity used by this placement.
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 5.0 * fill_frac;

    score
}

