        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 4.0 && open_bins_count > 3 {
            score -= 6.0 * (1.0 - progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (below the minimum item size of 1, but
    // practically below a "useful threshold") are heavily penalized.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Perfect-fit reward: exact fill is maximally desirable.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Tightness reward: fraction of the bin consumed by this placement.
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 20.0 * tightness;
    }

    // Penalize creating a gap that is just barely unusable for the
    // lookahead item (near-miss dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + 0.1 * (next_item_size - post_residual) as f64;
    }
    // Reward leaving exactly enough room for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins when
    // residuals are already plentiful, encourage closing out bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).powf(1.3) * 0.5 * (0.5 + progress);

    // Attraction to bins with low mean residual (consolidation).
    score += 0.15 * mean_residual;

    // Last-chance bin: strongly prefer using it rather than opening new.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin offers a good
    // fit (residual of existing bins is small relative to item).
    if bin_residual == bin_capacity {
        let spread = mean_residual - item_size as f64;
        if spread > 0.0 {
            score -= spread * 1.5;
        } else {
            score += 30.0;
        }
        // Early in stream, new bins are cheap; late, avoid them.
        score += 40.0 * progress;
    }

    score
}

