pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // 2-step lookahead: if the next item exactly fills the post residual,
    // heavily favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how snugly.
            let slack_after_next = post_residual - next_item_size;
            score -= 150.0 * (1.0 - slack_after_next as f64 / post_residual as f64);
        } else {
            // Next item will not fit in the leftover: penalize dead space
            // unless post_residual is large enough to be useful generally.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.4 * waste;
        }
    }

    // Compare post_residual relative to mean residual of open bins.
    if mean_residual > 0.0 {
        let ratio = post_residual as f64 / mean_residual;
        if ratio < 0.5 {
            // Creates much smaller residual than average: good consolidation.
            score -= 80.0 * (0.5 - ratio);
        } else if ratio > 1.5 {
            // Leaves a larger-than-average residual: mild penalty.
            score += 30.0 * (ratio - 1.5);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when current residuals are mostly unusable
    // (e.g., mean residual barely above item size) or late in stream with many bins.
    if bin_residual == bin_capacity {
        let tight = mean_residual - item_size as f64;
        let pressure = if tight > 0.0 && tight < 10.0 { 150.0 } else { 0.0 };
        score = bin_capacity as f64 - pressure - 0.5 * (open_bins_count as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Slight preference for bins with less residual overall (tighter packing),
    // scaled by stream progression.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.3 * progress * post_residual as f64;

    score
}

