        if open_bins_count > 8 && mean_residual > next_item_size as f64 + 10.0 {
            score += 12.0 ;
        }
        if item_frac > 0.6 && next_item_size > 0 && fresh_left >= next_item_size {
            score -= 8.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size ;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress) ;
            }
        }
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        // mutation: discourage fresh bins late when any open bin can host next item comfortably
        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 && progress > 0.6 {
            score += 10.0 * progress ;
        }
        // mutation: fresh bin attractive early with big items (large usable leftover)
        if item_frac > 0.5 && progress < 0.4 {
            score -= 6.0 * (0.4 - progress) / 0.4 ;
        }
        // mutation: strongly penalize opening fresh bins when many open bins still fit the item
        if fitting_bins_count >= 3 {
            score += 18.0 + 4.0 * (fitting_bins_count as f64).min (10.0) ;
        } else if fitting_bins_count == 2 {
            score += 6.0 * (1.0 - progress) ;
        }
        // mutation: fresh bin is attractive if leftover perfectly matches mean residual scale
        if next_item_size > 0 && fresh_left >= next_item_size {
            let chain = ((fresh_left - next_item_size) as f64 / mean_residual.max (1.0)) . fract () ;
            if chain < 0.15 || chain > 0.85 {
                score -= 5.0 * (1.0 - progress) ;
            }
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    if post_residual > 0 {
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 900.0 - 30.0 * progress;
            } else if post_residual >= next_item_size {
                let two_step_waste = (post_residual - next_item_size) as f64;
                if two_step_waste == 0.0 {
                    score -= 700.0;
                } else if two_step_waste >= 10.0 {
                    score -= 300.0 - 2.0 * two_step_waste;
                } else {
                    score -= 80.0 + 1.5 * (10.0 - two_step_waste);
                }
                let after_next = post_residual - next_item_size;
                if after_next >= 3 {
                    score -= (2.0 + 2.0 * progress) * (after_next as f64).min(15.0);
                }
                if after_next <= 12 && mean_residual >= after_next as f64 {
                    score -= 22.0 - 0.8 * after_next as f64;
                }
                if next_item_size > 1 && after_next >= next_item_size {
                    score -= 6.0 + 0.2 * (after_next / next_item_size) as f64;
                    if after_next % next_item_size == 0 {
                        score -= 8.0 * (1.0 - progress);
                    }
                }
                if after_next < next_item_size && after_next <= 3 {
                    score -= 14.0 * (1.0 - progress);
                }
                // near-seal sliver after next item: next-next item may close it
                if after_next < next_item_size && after_next >= 1 && (next_item_size - after_next) <= 5 {
                    score -= 6.0 * (1.0 - progress);
                }
                if (after_next as f64 - mean_residual).abs() <= 4.0 {
                    score -= 6.0 * (1.0 - progress);
                }
            } else {
                let miss = (next_item_size - post_residual) as f64;
                score += 2.0 * miss;
                if post_residual < 25 {
                    score += 15.0;
                }
                // tiny residual that nothing fits: nearly dead
                if post_residual < 3 {
                    score -= 400.0;
                }
                if miss <= 6.0 && fitting_bins_count <= 2 {
                    score -= 5.0;
                }
                if miss <= 10.0 && fitting_bins_count <= 2 && progress > 0.7 {
                    score -= 10.0 * (1.0 - progress);
                }
                if miss <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
                if post_residual >= 8 && post_residual <= 16 {
                    score += 10.0 * (1.0 - progress);
                }
                if miss > 3.0 && miss <= mean_residual * 0.5 {
                    score += 4.0 * (1.0 - progress);
                }
            }
        }

        // small post residuals are generally wasteful (borrowed from best)
        if post_residual < 10 {
            score += 45.0;
        } else if post_residual < 20 {
            score += 10.0;
        }

        score -= 0.6 * (mean_residual - post_residual as f64);

        let gap = (post_residual as f64 - item_size as f64).max(0.0);
        let gap_ratio = gap / (item_size as f64).max(1.0);
        if gap > 0.0 {
            let scarcity = if fitting_bins_count <= 2 { 0.6 } else if fitting_bins_count <= 4 { 0.3 } else { 0.2 };
            score += scarcity * gap + 18.0 * gap_ratio.min(2.0);
            if gap < mean_residual {
                let fillable = next_item_size > 0 && gap >= next_item_size as f64;
                let w = if fillable { 0.2 } else { 0.6 };
                score += w * (mean_residual - gap);
            }
            if next_item_size > 0 && (gap as u32) == next_item_size {
                score -= 20.0;
            }
            if next_item_size > 1 && (gap as u32) == 2 * next_item_size {
                score -= 12.0;
            }
        }

        // sole fitting bin: keep it alive
        if fitting_bins_count == 1 {
            score -= 12.0;
        }

        let fill = item_size as f64 / (bin_residual as f64).max(1.0);
        score -= 20.0 * fill;

        if next_item_size > 0 && post_residual < next_item_size {
            let dead_frac = post_residual as f64 / bin_capacity as f64;
            let unusable_ratio = post_residual as f64 / (next_item_size as f64).max(1.0);
            score += 0.4 * post_residual as f64 + 30.0 * dead_frac + 12.0 * (1.0 - unusable_ratio);
            if next_item_size - post_residual <= 4 {
                score += 20.0 * (1.0 - progress);
            }
        }

        if fitting_bins_count == 2 && post_residual < bin_capacity / 3 {
            score -= 8.0;
        }

        if post_residual <= 5 && open_bins_count > 6 {
            score += 25.0 * (1.0 - progress);
        }

        if post_residual >= bin_capacity / 8 && post_residual <= bin_capacity / 2 {
            score -= 6.0;
        }
        // residual that can host next item comfortably in a mid-size bin
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= bin_capacity / 2 {
            score -= 4.0 * (1.0 - progress);
        }

        if post_residual as f64 >= 2.0 * mean_residual && post_residual > 20 {
            score -= 5.0;
        }

        if next_item_size > 0 && post_residual > next_item_size {
            let headroom = post_residual - next_item_size;
            if (headroom as f64 - mean_residual).abs() <= 3.0 {
                score -= 7.0;
            }
            if (headroom as f64 - mean_residual).abs() <= 1.0 && fitting_bins_count <= 3 {
                score -= 5.0 * (1.0 - progress);
            }
        }

        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0;
        }

        if next_item_size > 1 && post_residual > next_item_size + 1 && post_residual <= next_item_size + 10 {
            score -= 4.0 * (1.0 - progress);
        }
        // chainable residual: multiple of next item
        if next_item_size > 1 && post_residual % next_item_size == 0 && post_residual >= 2 * next_item_size && post_residual <= 3 * next_item_size {
            score -= 5.0 * (1.0 - progress);
        }
        // penalize residual just under a common small size late (dead space)
        if post_residual >= 5 && post_residual <= 9 && progress > 0.5 && next_item_size > post_residual {
            score += 8.0 * progress;
        }
    }

    // Last-chance bin: only bin that fits, strongly prefer over new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // NEW-BIN CANDIDATE
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let big_next = next_item_size as f64 / bin_capacity as f64;
        score += 180.0 - 60.0 * progress + 0.15 * open_bins_count as f64 - 25.0 * big_next.max(0.0);
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
        if open_bins_count <= 4 && progress < 0.3 {
            score += 25.0;
        }
        if mean_residual < 15.0 && progress > 0.5 {
            score -= 15.0;
        }
        let item_frac = item_size as f64 / bin_capacity as f64;
        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3;
        }
        let fresh_left = bin_capacity - item_size;
        if next_item_size > 0 && fresh_left == next_item_size {
            score -= 30.0;
        }
        if open_bins_count > 6 && mean_residual > 0.4 * bin_capacity as f64 {
            score += 20.0;
        }
        if next_item_size > 0 && fresh_left < next_item_size && fresh_left < 8 {
            score += 35.0;
        }
        if next_item_size > 0 && fitting_bins_count <= 2 && mean_residual < next_item_size as f64 {
            score -= 18.0 * (1.0 - progress);
        }
        if open_bins_count > 8 && mean_residual > next_item_size as f64 + 10.0 {
            score += 12.0;
        }
        if item_frac > 0.6 && next_item_size > 0 && fresh_left >= next_item_size {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0;
        }
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0;
        }
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress);
        }
        if next_item_size > 0 && (fresh_left as f64 - mean_residual).abs() <= 2.0 {
            score -= 8.0;
        }
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual).abs() <= 3.0 {
            score -= 9.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0;
        }
        // discourage fresh bins late when an open bin can host next item comfortably
        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 && progress > 0.6 {
            score += 10.0 * progress;
        }
        // fresh bin attractive early with big items (large usable leftover)
        if item_frac > 0.5 && progress < 0.4 {
            score -= 6.0 * (0.4 - progress) / 0.4;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 40.0;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += (20.0 - post_residual as f64) * 2.0;
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + next_item_size as f64 * 0.2;
    } else if next_item_size > 0 && post_residual > 0 {
        // leftover wasted relative to next item
        score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.5;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's genuinely needed.
    if bin_residual == bin_capacity {
        let base_penalty = 80.0;
        // More open bins => more willing to open another (spread load).
        let openness = (open_bins_count as f64).ln().max(0.0) * 5.0;
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += base_penalty - openness + progress * 40.0;
        // If many bins fit the item, opening new bin is wasteful.
        score += fitting_bins_count as f64 * 10.0;
        // If next item is large, fresh bin may be useful.
        if next_item_size >= item_size {
            score -= 10.0;
        }
    }

    // Global residual pressure: if mean residual is high, prefer bins above mean
    // (consolidate), else prefer below-mean bins.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.15;

    // Mild exploration noise-free coupling with time horizon.
    let horizon = 1.0 - step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * horizon;

    score
}

