    let post_norm = post / cap;
    score += 40.0 * post_norm * post_norm * (0.5 + progress);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - post_norm;
    score -= 25.0 * tightness * tightness * tightness * (0.5 + progress);

    // Dead space penalty: post residual that can't fit next item smoothly penalized
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 12.0 * (nxt - post) / cap * (1.0 + progress);
        } else {
            // smooth reward when next item fits into the future residual
            score -= 8.0 * (1.0 - (nxt / post).min(1.0)) * (1.0 - progress);
        }
