    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        score += 20.0 - 25.0 * frac;
        if open_bins_count > 8 {
            score -= 5.0;
        }
    }

    // Slight preference for bins with below-average residual (tighter bins
