pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=10)
    // are pure waste — penalize them hard, super-linearly.
    if post_residual >= 1 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64);
    }
    // Near-dead zone (11..=19): only fits the smallest items; mild penalty.
    else if post_residual > 10 && post_residual < 20 {
        score += 0.8 * (20.0 - post_residual as f64);
    }

    // Reward tight fits (small but usable residual).
    if post_residual > 0 && post_residual <= 30 {
        score -= 12.0 * (1.0 - post_residual as f64 / 30.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 1.5 * open_bins_count as f64;

    // Lookahead: if the next item fits exactly in the post-residual,
    // this placement chains nicely — reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 10.0 {
            score -= 25.0;
        } else {
            score -= 8.0 * (1.0 - slack / 80.0);
        }
    }
    // If next item would be stranded by this placement, mild penalty.
    else if next_item_size > 0 && next_item_size <= bin_residual && next_item_size > post_residual {
        score += 10.0;
    }

    // New-bin candidate: baseline score so it wins only when all open bins
    // would create dead space or the stream is early and bins are few.
    if bin_residual == bin_capacity {
        let dead_pressure = if post_residual >= 1 && post_residual <= 10 { 60.0 * (11.0 - post_residual as f64) } else { 0.0 };
