pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-perfect fits strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // 2-step lookahead: if the next item fits the post-residual exactly,
    // this bin becomes a perfect chain placement — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 180.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 90.0;
        }
        // Penalize leaving a residual just below the next item (dead space trap).
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post-residual against mean residual across open bins:
    // prefer bins whose residual stays close to the mean (balanced packing),
    // penalize creating outliers far below the mean (wasted large gaps elsewhere).
    let post_f = post_residual as f64;
    let dev = post_f - mean_residual;
    score += 0.25 * dev.abs();

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize mildly so we prefer reusing open bins with
    // good fits; but if all fits would leave large residuals, new bin wins.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Late in the stream, opening new bins is less costly (fewer future
        // chances to consolidate), reduce the penalty.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * progress;
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= 60 {
            score -= 15.0;
        }
    }

    // Slight preference for tighter bins overall (best-fit baseline bonus).
    score += 0.1 * (bin_capacity - bin_residual) as f64 * -1.0;

    score
}

