pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer minimal post_residual (tight fit).
    let mut score = post_residual as f64;

    // Fractional waste relative to capacity: dead space is worse when small.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac; // quadratic penalty on waste

    // Lookahead reward: if the next item fits into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chain fit bonus, scaled by how snugly the next item lands.
            let chain_tightness = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 25.0 + 30.0 * (1.0 - chain_tightness);
        } else {
            // Next item cannot follow here; mildly penalize, more so if post_residual is tiny (unusable).
            if post_residual < 10 {
                score += 15.0;
            } else {
                score += 5.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0));
            }
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline: new bin wastes nothing now but defers compaction.
        score = 60.0 + (post_residual as f64);
        // Early in the stream, prefer filling existing bins (many items still coming).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * progress;
        // If many bins are open with high mean residual, encourage consolidation instead.
        score += 0.5 * open_bins_count as f64;
        score += 0.3 * (mean_residual - (bin_capacity as f64) * 0.5).max(0.0);
        // If the next item is large, a fresh bin is more flexible.
        score -= 0.2 * next_item_size as f64;
        // If this bin is the last chance, opening a new bin is bad.
        if fitting_bins_count == 1 {
            score += 50.0;
        }
    } else {
        // Prefer bins whose residual is close to the item (best-fit flavor with a twist).
        let fit_gap = (bin_residual - item_size) as f64;
        score += 0.1 * fit_gap;
        // Slight preference for bins below mean residual (consolidate low-space bins first).
        score += 0.05 * ((bin_capacity as f64) * 0.5 - bin_residual as f64).max(0.0);
