pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill is ideal: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of the residual: residuals that are multiples of common
    // item sizes (10, 20, 25, 50) remain reusable; treat them as "harmonic".
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut harmonic_bonus = 0.0;
    if post_residual % 50 == 0 { harmonic_bonus += 30.0; }
    else if post_residual % 25 == 0 { harmonic_bonus += 20.0; }
    else if post_residual % 20 == 0 { harmonic_bonus += 15.0; }
    else if post_residual % 10 == 0 { harmonic_bonus += 8.0; }
    score -= harmonic_bonus;

    // Lookahead coupling: reward if next item fits in the post residual,
    // with extra reward for near-exact packing of the pair.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack * 0.3;
            if post_residual == next_item_size { score -= 60.0; }
        } else {
            // Next item won't fit here: penalize large unusable leftovers.
            score += (next_item_size as f64 - pr).min(60.0) * 0.4;
        }
    }

    // Dead-space penalty: residuals too small for the smallest plausible item
    // (but nonzero) are waste; penalize the "just barely unusable" band hardest.
    if post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over
    // opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it attractive only when few open bins exist
    // or mean residual across open bins is already low (poor reuse potential).
    if bin_residual == bin_capacity {
        let reuse_potential = mean_residual / cap;
        let phase = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_score = 55.0
            - reuse_potential * 45.0
            - phase * 10.0
            + (open_bins_count as f64).sqrt() * 4.0;
        score = score.min(new_bin_score);
    }

    // Mild penalty for wasting space in a nearly-full bin vs. tighter fits:
    // prefer bins whose fill fraction relative to residual is high.
    let fill_efficiency = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_efficiency * 15.0;

    // Progression bias: late in the stream, closing bins cleanly matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (cap - pr) * 0.05;

    score
}

