            // mutation: mild quadratic dead-space penalty for large unusable gaps
            if next_item_size > 0 && gap < next_item_size as f64 {
                score += 0.8 * gap ;
            }
        }
        if fitting_bins_count == 1 {
            score -= 12.0 ;
        }
        let fill = item_size as f64 / (bin_residual as f64) . max (1.0) ;
        score -= 20.0 * fill ;
