    let mut score = post_residual as f64;

    // Reward tight fits: perfect fill strongly favored.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize small unusable dead space (gap too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 250.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 80.0;
    } else if post_residual >= 20 && post_residual < 35 {
        score += 20.0;
    }

    // Dead space is worse if the lookahead item cannot use it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 3.0;
    }

    // If this bin is the only fitting bin, strongly prefer using it over new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Open-bin pressure: discourage opening extra bins when many are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (open_bins_count as f64 * 6.0 + progress * 40.0);

