    let mut score = post_residual as f64;

    // Base: prefer minimal post residual (best-fit core).
    score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if nxt <= post {
            // Perfect chain match: next item exactly consumes the leftover.
            let gap = (post - nxt).abs();
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
            // Extra strong bonus for exact match (post == next).
            if gap < 0.5 {
                score -= 25.0;
            }
            // Mild bonus if next item fits at all in the leftover.
            score -= 5.0;
        } else {
            // Next item cannot use the leftover: leftover is likely dead space.
            score += 0.25 * (post - nxt);
        }
    }

    // Compare post residual against mean residual across open bins:
    // leaving much more than average wastes capacity.
    if post_residual as f64 > mean_residual {
        score += 0.15 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.05 * (mean_residual - post_residual as f64);
    }

