    // Should be chosen only when all open bins score worse (poor fits / dead space).
    if bin_residual == bin_capacity {
        score = 55.0;
        // Late in the stream, slightly discourage opening new bins to consolidate.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
