                // mutation: smooth continuous reward for leaving exactly a reusable after-space
                let after_frac = after_next as f64 / (mean_residual . max (1.0)) ;
                if after_frac <= 1.0 {
                    score -= 4.0 * after_frac * (1.0 - progress) ;
