                if post_residual >= 8 && post_residual <= 16 {
                    score += 10.0 * (1.0 - progress) ;
                }
                if miss > 3 && miss as f64 <= mean_residual * 0.5 {
                    score += 4.0 * (1.0 - progress) ;
                }
                // mutation: scaled dead-space penalty proportional to unusable fraction
                let unusable = post_residual as f64 / (next_item_size as f64) ;
                score += 10.0 * (1.0 - unusable . min (1.0)) * progress ;
            }
        }
        if post_residual < 10 {
            score += 45.0 ;
        } else if post_residual < 20 {
