        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 && progress > 0.6 {
            score += 10.0 * progress ;
        }
        if item_frac > 0.5 && progress < 0.4 {
            score -= 6.0 * (0.4 - progress) / 0.4 ;
        }
        // mutation: penalize fresh bins whose leftover is dead space for the next item, scaled by progress
        if next_item_size > 0 && fresh_left < next_item_size {
            score += 12.0 * progress * (1.0 - fresh_left as f64 / (next_item_size as f64) . max (1.0)) ;
        }
        // mutation: fresh bin more attractive when many open bins have tiny residuals (consolidation pressure)
        if mean_residual < 8.0 && open_bins_count > 5 {
            score -= 10.0 * (1.0 - progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: small post_residual is good, but dead space that
    // can never fit even the smallest item is pure waste.
    if post_residual < 10 {
        score -= 12.0; // near-perfect fill bonus
    } else {
        // penalize unusable slivers (post_residual < next item or < min size 1)
        let unusable = if next_item_size > 0 {
            (post_residual < next_item_size) as f64
        } else {
            0.0
        };
        score += 6.0 * unusable;
    }

    // Lookahead: reward bins whose post_residual can host the next item,
    // scaled by how large that next item is.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_quality = (next_item_size as f64 / cap).max(0.2);
        score -= 8.0 * fit_quality;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin should only win when existing
    // bins are fragmented (high mean residual spread vs. item size).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post).abs();
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let penalty = 18.0
            + 10.0 * (1.0 - progress)
            + 4.0 * (open_bins_count as f64).ln().max(0.0);
        score += penalty;
        // if the item barely fits anywhere anyway, opening a bin is fine
        if item_size as f64 > mean_residual * 0.85 {
            score -= 20.0;
        }
        let _ = fragmentation;
    }

    // Mild preference for bins with larger residuals among open bins
    // (use big holes first), coupled with stream progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * (bin_residual as f64 / cap) * (0.5 + 0.5 * progress);

    // Tie-break toward fewer open bins to encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    score
}

