pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual (0..1)
    let t = progress;
    let poly = prn * prn * (0.5 + 0.5 * t) + prn * (1.0 - t) * (1.0 - t);
    score += poly * cap * 0.35;

    // Penalize large dead space more as stream progresses (waste compounds later)
    score += (prn * prn * prn) * cap * (0.2 + 0.6 * t);

    // Reward tight fits: small post residual gets a smooth bonus
    let tight = (1.0 - prn).powi(6);
    score -= tight * cap * 0.45;

    // Lookahead coupling: reward leaving space for the next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = (pr - nx).max(0.0) / cap;
        let exact = 1.0 - ((pr - nx).abs() / cap).min(1.0);
        score -= exact * cap * 0.25 * (0.5 + 0.5 * t);
        score += fit_next * cap * 0.10 * (1.0 - t);
    }

    // Last-chance bin: strongly favor using it (smooth sigmoid-like weighting)
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= cap * 0.8 * (0.5 + 0.5 * t);
    }

    // Many open bins: prefer filling existing ones (smooth pressure term)
    let pressure = (open_bins_count as f64).ln().max(0.0) / 4.0;
    score += (1.0 - tight) * cap * 0.05 * pressure;

    // Mean residual coupling: bins far from mean residual get mild penalty
