pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let fit_ratio = post_residual as f64 / cap; // fraction of capacity wasted
    score += 40.0 * fit_ratio * fit_ratio;

    // Harmonic classes: post_residual bucketed by capacity fractions
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let pr = post_residual;
