        score -= 100.0; // perfect fill
    } else if pr < eighth {
        score -= 25.0; // nearly full, excellent
    } else if pr < quarter {
        score -= 5.0; // decent
    } else if pr < 2 * quarter {
        score += 10.0; // half-ish leftover, mediocre
    } else {
        score += 20.0; // large leftover
    }

