            // next item won't fit; penalize proportionally to mismatch
            let overflow = (next_item_size - pr) as f64;
            score += 8.0 * (overflow / cap);
        }
    }

    // Last-chance bonus: only this bin can fit the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: brand-new empty bin
    if bin_residual == bin_capacity {
        // Opening a new bin is costly when existing bins fit well
        let best_possible = if next_item_size > 0 { next_item_size as f64 } else { 0.0 };
