    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item are unusable -> heavy penalty.
    let min_useful = 20u32; // smallest item size bound
    if post_residual > 0 && post_residual < min_useful {
        score += 60.0 + (min_useful - post_residual) as f64;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual >= min_useful {
        // Reward leaving a gap that could still fit typical items.
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack.min(25.0);
    }
    // Penalize if next item would be blocked by this placement's dead space.
    if next_item_size > post_residual && post_residual > 0 {
        score += 15.0;
    }

    // Open-bin pressure: discourage spreading when many bins are open,
    // encourage consolidation when few bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += pressure * 3.0;

    // Mean residual coupling: prefer bins deviating below mean residual
    // (tighter bins) to keep a pool of large gaps open.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: opening a new bin is expensive unless the item is huge
    // or all fits are terrible.
    if bin_residual == bin_capacity {
        score += 35.0 + progress * 20.0;
        // If item is large, opening fresh is more attractive.
        if item_size > 60 {
            score -= 20.0;
        }
    }

    score
}

