pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Exact-fit / zero-waste dominance.
    if post_residual == 0 {
        return -1000.0;
    }

    let mut score = post_residual as f64;

    // Reward tight fits exponentially.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: bins whose post_residual hosts the next item are strongly preferred.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0 - 30.0 * progress;
        } else if post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next >= 10 {
                score -= 300.0 - 2.0 * after_next as f64;
            } else {
