    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // Next item won't fit here; penalize leaving awkward gaps.
            score += 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // New-bin candidate handling: only prefer opening a new bin when existing
    // residuals are small relative to the item (poor fits everywhere) or the
    // stream is early and we can afford slack.
    if bin_residual == bin_capacity {
        let avg_slack = mean_residual / bin_capacity as f64;
        // Penalize new bins generally, less so when open bins are nearly full.
        score += 30.0;
        score -= 25.0 * (1.0 - avg_slack);
        score -= 10.0 * (1.0 - progress);
        // If many bins already open, discourage spreading further.
        score += 0.5 * (open_bins_count as f64).ln().max(0.0);
        // If the item is huge, a fresh bin is a natural home.
        if item_size >= 70 {
            score -= 20.0;
        }
    }

