    // encourage consolidating into existing bins.
    let pressure = open_bins_count as f64 / (step_index as f64 + 1.0).max(1.0);
    score += 5.0 * pressure;

    // Mild preference for bins whose residual deviates favorably from mean
    // (below-mean residual bins are "fuller", prefer filling them).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

