            if tail <= 3 {
                score -= 14.0 * (1.0 - progress) ;
            }
        }
        // fresh bin leftover below mean residual is likely dead space
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        // chain home: leftover hosts next item twice exactly
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        // near-exact fill wastes nothing and preserves all open residuals
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        // fresh bin leftover matching mean residual — reusable home shape
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        // chain home: leftover hosts next item multiple times exactly
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        // fresh bin leftover that hosts next item plus mean-shaped slack
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        // avoid opening fresh bins when a fitting open bin nearly seals with this item
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        // mutation: discourage fresh bins late when an open bin can host next item comfortably
        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 && progress > 0.6 {
            score += 10.0 * progress ;
        }
        // mutation: fresh bin attractive early with big items (large usable leftover)
        if item_frac > 0.5 && progress < 0.4 {
            score -= 6.0 * (0.4 - progress) / 0.4 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Base: penalize wasted residual, with progress-dependent curvature
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Non-linear coupling: quadratic dead-space term growing over the stream
    score += 18.0 * norm_post * norm_post * (0.4 + 0.6 * progress);

    // Reward tight fits (small post_residual) more strongly late in stream
    score -= 12.0 * (1.0 - norm_post).powi(3) * (0.5 + progress);

    // Lookahead: reward residual that can host the next item, penalize near-miss
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 10.0 * (1.0 - slack * slack) * (0.6 + 0.4 * progress);
        } else {
            let miss = (nx - pr) / cap;
            score += 8.0 * miss * (1.0 - 0.5 * miss) * (0.5 + progress);
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 10.0 * progress;
    }

    // Prefer filling bins whose residual deviates from the mean (diversity control)
    score += 0.15 * (pr - mean_residual).abs();

    // Mild penalty for opening new bins when many are already open
    let new_bin_bonus = if bin_residual == bin_capacity {
        6.0 + 8.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress)
    } else {
        0.0
    };
    score += new_bin_bonus;

    // Smooth cubic progress coupling on overall residual scale
    score *= 1.0 + 0.1 * progress.powi(3);

    score
}

