    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: treat capacity as 4 quarters; residual in the lowest
    // quarter is "dead space" — penalize leaving tiny unusable fragments.
    let quarter = bin_capacity / 4;
    let r = post_residual;
    if r > 0 && r < quarter / 2 {
        score += 60.0; // dead-space penalty for very small leftover
    }

    // Modulo-class bonus: residual divisible by common item sizes (10/20/25)
    // is reusable; subtract to favor such bins.
    if r % 10 == 0 && r > 0 {
        score -= 15.0;
    }
    if r % 25 == 0 && r > 0 {
        score -= 10.0;
    }

    // Lookahead coupling: reward residual that exactly fits the next item,
    // penalize residuals that strand the next item.
    if next_item_size > 0 {
        if r == next_item_size {
            score -= 200.0;
        } else if r > next_item_size && (r - next_item_size) % 10 == 0 {
            score -= 40.0;
        } else if r > 0 && r < next_item_size {
            score += 25.0; // next item can't use this leftover
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Prefer fuller bins relative to mean residual.
    if (post_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Slight preference for keeping open_bins_count small (consolidation),
    // weighted more early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (2.0 - progress);

    // New-bin candidate: only attractive when current residual would be wasted
    // dead space; make empty bin mildly unattractive otherwise.
    if bin_residual == bin_capacity {
        if item_size >= 3 * quarter {
            score -= 30.0; // big item into fresh bin is fine
        } else {
            score += 20.0;
        }
    }

    score
}

