                    score -= 14.0 * (1.0 - progress) ;
                }
                if after_next < next_item_size && after_next >= 1 && (next_item_size - after_next) <= 5 {
                    score -= 6.0 * (1.0 - progress) ;
                }
                if (after_next as f64 - mean_residual) . abs () <= 4.0 {
                    score -= 6.0 * (1.0 - progress) ;
                }
                // mutation: after_next exactly hosts next item again (perfect chain)
                if after_next == next_item_size && next_item_size > 1 {
                    score -= 15.0 * (1.0 - progress) ;
                }
            } else {
                let miss = next_item_size - post_residual ;
                score += 2.0 * miss as f64 ;
                if post_residual < 25 {
                    score += 15.0 ;
                }
                if post_residual < 3 {
                    score -= 400.0 ;
                }
                if miss <= 6 && fitting_bins_count <= 2 {
                    score -= 5.0 ;
                }
                if miss <= 10 && fitting_bins_count <= 2 && progress > 0.7 {
                    score -= 10.0 * (1.0 - progress) ;
                }
                if miss <= 2 {
                    score -= 18.0 * (1.0 - progress) ;
                }
                if post_residual >= 8 && post_residual <= 16 {
                    score += 10.0 * (1.0 - progress) ;
                }
                if miss > 3 && miss as f64 <= mean_residual * 0.5 {
                    score += 4.0 * (1.0 - progress) ;
                }
            }
        }
        if post_residual < 10 {
            score += 45.0 ;
        } else if post_residual < 20 {
            score += 10.0 ;
        }
        score -= (mean_residual - post_residual as f64) * 0.6 ;
        let gap = (post_residual as f64 - item_size as f64) . max (0.0) ;
        let gap_ratio = gap / (item_size as f64) . max (1.0) ;
        if gap > 0.0 {
            let scarcity = if fitting_bins_count <= 2 { 0.6 } else if fitting_bins_count <= 4 { 0.3 } else { 0.2 } ;
            score += scarcity * gap + 18.0 * gap_ratio . min (2.0) ;
            if gap < mean_residual {
                let fillable = next_item_size > 0 && gap >= next_item_size as f64 ;
                let w = if fillable { 0.2 } else { 0.6 } ;
                score += w * (mean_residual - gap) ;
            }
            if next_item_size > 0 && (gap as u32) == next_item_size {
                score -= 20.0 ;
            }
            if next_item_size > 1 && (gap as u32) == 2 * next_item_size {
                score -= 12.0 ;
            }
            // mutation: dead-gap penalty scaled by scarcity of fitting alternatives
            if next_item_size > 0 && gap < next_item_size as f64 && gap < mean_residual * 0.5 {
                score += 12.0 * (1.0 - progress) ;
            }
        }
        if fitting_bins_count == 1 {
            score -= 12.0 ;
        }
        let fill = item_size as f64 / (bin_residual as f64) . max (1.0) ;
        score -= 20.0 * fill ;
        if next_item_size > 0 && post_residual < next_item_size {
            let dead_frac = post_residual as f64 / bin_capacity as f64 ;
            let unusable_ratio = post_residual as f64 / (next_item_size as f64) . max (1.0) ;
            score += 0.4 * post_residual as f64 + 30.0 * dead_frac + 12.0 * (1.0 - unusable_ratio) ;
            if next_item_size - post_residual <= 4 {
                score += 20.0 * (1.0 - progress) ;
            }
        }
        if fitting_bins_count == 2 && post_residual < bin_capacity / 3 {
            score -= 8.0 ;
        }
        if post_residual <= 5 && open_bins_count > 6 {
            score += 25.0 * (1.0 - progress) ;
        }
        if post_residual >= bin_capacity / 8 && post_residual <= bin_capacity / 2 {
            score -= 6.0 ;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= bin_capacity / 2 {
            score -= 4.0 * (1.0 - progress) ;
        }
        if post_residual as f64 >= 2.0 * mean_residual && post_residual > 20 {
            score -= 5.0 ;
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let headroom = post_residual - next_item_size ;
            if (headroom as f64 - mean_residual) . abs () <= 3.0 {
                score -= 7.0 ;
            }
            if (headroom as f64 - mean_residual) . abs () <= 1.0 && fitting_bins_count <= 3 {
                score -= 5.0 * (1.0 - progress) ;
            }
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0 ;
        }
        if next_item_size > 1 && post_residual > next_item_size + 1 && post_residual <= next_item_size + 10 {
            score -= 4.0 * (1.0 - progress) ;
        }
        // mutation: prefer bins whose post-fit residual is a multiple of next item (chainable)
        if next_item_size > 1 && post_residual % next_item_size == 0 && post_residual >= 2 * next_item_size && post_residual <= 3 * next_item_size {
            score -= 5.0 * (1.0 - progress) ;
        }
        // mutation: penalize residual just below a common small size late (dead space)
        if post_residual >= 5 && post_residual <= 9 && progress > 0.5 && next_item_size > post_residual {
            score += 8.0 * progress ;
        }
        // mutation: lookahead — bin that fits next item AND has post_residual >= mean_residual is a strong home
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) as f64 >= mean_residual {
            score -= 6.0 + 4.0 * (1.0 - progress) ;
        }
    }
    // NEW-BIN CANDIDATE
    if bin_residual == bin_capacity {
        let big_next = next_item_size as f64 / bin_capacity as f64 ;
        score += 180.0 - 60.0 * progress + 0.15 * open_bins_count as f64 - 25.0 * big_next . max (0.0) ;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0 ;
        }
        if open_bins_count <= 4 && progress < 0.3 {
            score += 25.0 ;
        }
        if mean_residual < 15.0 && progress > 0.5 {
            score -= 15.0 ;
        }
        let item_frac = item_size as f64 / bin_capacity as f64 ;
        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3 ;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3 ;
        }
        let fresh_left = bin_capacity - item_size ;
        if next_item_size > 0 && fresh_left == next_item_size {
            score -= 30.0 ;
        }
        if open_bins_count > 6 && mean_residual > 0.4 * bin_capacity as f64 {
            score += 20.0 ;
        }
        if next_item_size > 0 && fresh_left < next_item_size && fresh_left < 8 {
            score += 35.0 ;
        }
        if next_item_size > 0 && fitting_bins_count <= 2 && mean_residual < next_item_size as f64 {
            score -= 18.0 * (1.0 - progress) ;
        }
        if open_bins_count > 8 && mean_residual > next_item_size as f64 + 10.0 {
            score += 12.0 ;
        }
        if item_frac > 0.6 && next_item_size > 0 && fresh_left >= next_item_size {
            score -= 8.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size ;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress) ;
            }
        }
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        // mutation: discourage fresh bins late when any open bin can host next item comfortably
        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 && progress > 0.6 {
            score += 10.0 * progress ;
        }
        // mutation: fresh bin attractive early with big items (large usable leftover)
        if item_frac > 0.5 && progress < 0.4 {
            score -= 6.0 * (0.4 - progress) / 0.4 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0, 10) are unusable for any item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Post-residuals just above the minimum item size are fragile: penalize the
    // "awkward gap" band where only tiny items could fit.
    if post_residual >= 10 && post_residual < 25 {
        score += 25.0 * (1.0 - (post_residual as f64 - 10.0) / 15.0);
    }

    // Reward very tight fits (post_residual near zero) strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
        score -= 20.0 * tightness * tightness;
    }

    // Perfect-fill coupling with lookahead: if the next item exactly consumes
    // the post-residual, this placement is ideal.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits after this placement: mildly favorable.
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover: penalize proportionally to gap size.
        score += 5.0 + 0.15 * (post_residual as f64 - next_item_size as f64).max(0.0);
    }

    // Last-chance bonus: this is the only bin that fits the item; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer reusing open bins unless this bin is a terrible fit
    // or the fleet is already saturated with dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by open-bin pressure.
        score = bin_capacity as f64 + 12.0 + 2.5 * open_bins_count as f64;
        // If many open bins have plenty of room, opening a new bin is wasteful.
        if mean_residual > 40.0 {
            score += 25.0;
        }
        // If the stream is nearly done and few bins are open, reuse is cheap anyway.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress > 0.9 && open_bins_count > 0 {
            score += 15.0;
        }
    }

    // Open-bins pressure: mildly discourage spreading across many bins when
    // alternatives exist (encourages consolidating into tighter bins).
    score += 0.3 * open_bins_count as f64;

    // Slight preference to fill bins that are already relatively full
    // (low residual before placement) to close them out.
    let pre_fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 6.0 * pre_fill;

    // Mean-residual coupling: when average residual is small (bins nearly full),
    // reward using this bin even more to finish bins off.
    if mean_residual < 20.0 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    score
}

