pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Next item fits here later; residual is "usable", scale by how much would remain.
            score -= 120.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use this residual -> dead space risk, penalize proportionally.
            score += 60.0 * (post_residual as f64 / bin_capacity as f64)
                   + 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize residuals far from mean (fragmentation indicator).
    score += 0.8 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when open bins are badly fragmented
    // (high mean residual relative to capacity) or stream is early.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        score = 150.0 - 100.0 * fragmentation;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 20.0; // fresh bin can host next item too
        }
    }

    // Slight preference for tighter fits overall.
