    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is ideal.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead waste).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as u32) < next_item_size {
            // wasted residual relative to next item need
            let waste = nxt - post_residual as f64;
            score += 0.9 * waste;
        } else {
            // residual can host next item: reward proportionally
            score -= 0.5 * (post_residual as f64 / nxt).min(2.0);
        }
        // Exact match of post_residual to next item: strong bonus
        if post_residual == next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // existing bins are crowded or fit is poor.
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity - item_size;
    if is_new_bin {
        // Penalize new bins mildly; the tight-fit bonus gives it residual=cap-item
        // which is decent only if item is large.
        let load = item_size as f64 / cap;
        score += 10.0 - 8.0 * load;
        // In late stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * progress;
        // Many open bins with slack: discourage opening another.
        score += 0.3 * open_bins_count as f64;
    }

    // Prefer bins below mean residual (more filled) slightly.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Early stream: encourage moderate spreading to build useful residual pool.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 {
        score -= 2.0 * (1.0 - progress * 5.0) * tightness;
    }

    // Small non-linear coupling: residual fragmentation penalty.
    let frag = (post_residual as f64 / cap).powf(3.0);
    score += 4.0 * frag * (1.0 - tightness);

    score
}

