            score -= 6.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 && progress > 0.6 {
            score += 10.0 * progress ;
        }
        if item_frac > 0.5 && progress < 0.4 {
            score -= 6.0 * (0.4 - progress) / 0.4 ;
        }
        // mutation: fresh-bin leftover should track mean residual closely — if it does,
        // the new bin blends into the residual distribution instead of creating outliers
        let left_band = ((fresh_left as f64) - mean_residual) . abs () ;
        if left_band <= 4.0 {
            score -= 6.0 * (1.0 - left_band / 4.0) * progress ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling of post_residual with stream progress:
    // late in stream, prefer tight fills more aggressively
    let late = progress * progress;
    score += 12.0 * late * (norm_pr * norm_pr * norm_pr) * cap * 0.1;

    // Penalize large post residual relative to mean residual (fragmentation)
    score += 0.35 * (pr - mean_residual).abs();

    // Reward nearly-full placements (dead-space avoidance), smoothly
    score -= 8.0 * (-norm_pr * 4.0).exp() * (1.0 + late);

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 {
        score -= 6.0 + 10.0 * late;
    }

    // Lookahead: if next item fits into post residual, reward this placement
    if next_item_size > 0 {
        let fits_next = if (post_residual as u32) >= next_item_size { 1.0 } else { 0.0 };
        // smooth version via sigmoid of slack
        let slack = (post_residual as f64 - next_item_size as f64) / cap;
        let sig = 1.0 / (1.0 + (-slack * 12.0).exp());
        score -= 5.0 * sig * (1.0 - 0.5 * late);
        let _ = fits_next;
    }

    // Mild penalty for spreading across many open bins early
    score += 0.05 * open_bins_count as f64 * (1.0 - late);

    // New-bin candidate: penalize slightly unless residuals are tight
    if bin_residual == bin_capacity {
        score += 3.0 + 15.0 * (1.0 - late) - 10.0 * late * norm_pr;
    }

    score
}

