pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by large
    // powers/fractions of capacity are more reusable.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -40.0 // perfect fit, best outcome
    } else if pr % 50 == 0 {
        -18.0
    } else if pr % 25 == 0 {
        -12.0
    } else if pr % 10 == 0 {
        -8.0
    } else if pr % 5 == 0 {
        -4.0
    } else {
        0.0
    };
    score += class_bonus;

    // Penalize tiny dead space that nothing (>=1) can use
    if pr > 0 && pr < 4 {
        score += 25.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // reward proportionally to how snugly next item fits
            let snug = 1.0 - (pr - next_item_size) as f64 / cap;
            score -= 10.0 + 15.0 * snug;
        } else {
            score += 6.0; // next item won't reuse this bin
        }
    }

