    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Fraction-of-capacity coupling on current residual
    let frac = bin_residual as f64 / cap;
    if (frac * 4.0).fract() < 0.01 {
        score -= 3.0; // quarter-aligned residuals are harmonic
    }

    // Prefer filling bins more densely as the stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (item_size as f64 / cap) * 10.0;

    // Slight preference to keep the number of open bins small
    score += open_bins_count as f64 * 0.3;

    // Prefer bins whose residual is below the mean (compact them)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 && next_item_size > mean_residual {
            1.0
        } else {
            0.0
        };
        score = cap * 0.9 - pressure * 15.0 + (fitting_bins_count as f64) * 4.0;
    }

    score
}

