    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize medium dead space that is unlikely to fit typical items.
    if post_residual > 0 && post_residual < 30 {
        score += (30.0 - post_residual as f64) * 0.6;
    }

    // Reward tight fits (small post_residual) proportionally.
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * 15.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading; with few bins,
    // opening a new one is cheaper so slightly favor filling existing bins less.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 5.0);
    score += pressure * 0.4;

    // Lookahead: if the next item fits the post residual, reward creating that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item cannot use the gap, penalize leaving a gap just above it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Prefer bins whose residual is already below average (consolidating waste).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: make it attractive only when existing fits are poor
    // (large post_residual) or when bin pressure is low.
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual;
        if avg_waste > 35.0 || open_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 15.0;
        }
    }

    score
}

