pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- 2-step lookahead matching ----
    if next_item_size > 0 {
        // Perfect chain: post_residual exactly fits next item -> strong reward
        if post_residual == next_item_size {
            score -= 60.0 + 20.0 * progress;
        } else if post_residual > next_item_size {
            // Next item fits with slack left: reward proportionally to tightness
            let slack = (post_residual - next_item_size) as f64;
            let tightness = 1.0 - slack / bin_capacity as f64;
            score -= 35.0 * tightness * tightness;
        } else {
            // Next item does NOT fit here: penalize dead space that likely becomes waste
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    } else {
        // Last item: minimize leftover directly (already in score)
        score -= 10.0;
    }

    // ---- Mean residual coupling: prefer bins whose residual deviates from mean ----
    let deviation = post_residual as f64 - mean_residual;
    // Favor bins tighter than average (below-mean post residual) to keep large slots alive
    if deviation < 0.0 {
        score -= 0.25 * (-deviation);
    } else {
        score += 0.15 * deviation;
    }

    // ---- Last chance bin: if this is the only fitting bin, strongly favor using it ----
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive only if no open bin fits well,
        // or when many bins are open and the item fits poorly everywhere.
        // Penalize new bins mildly so they are chosen only for poor fits elsewhere.
        let poor_fit_threshold = 20.0;
        if post_residual as f64 > bin_capacity as f64 - item_size as f64 {
            // empty bin: post_residual == capacity; check if item is small enough
            // that open bins would waste little space
            if fitting_bins_count > 0 && item_size as f64 <= poor_fit_threshold {
                score += 30.0; // discourage opening for tiny items
            } else {
                score -= 5.0 * progress; // late in stream, consolidation matters
            }
        }
    }

    // Small tie-breaker: prefer bins with fewer open competitors
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
