pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (item fills a large fraction of the bin's residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize unusable slivers of dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // Lookahead (k=2): reward bins whose post-residual can host the next item,
    // especially when the next item is a good relative fit for it.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let nxt_fit = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 8.0 + 14.0 * nxt_fit;
        } else {
            // This bin would be sealed off for the next item: mild penalty.
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, prefer using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is attractive when the
    // open bins are fragmented (low mean residual) or none exist yet.
    if bin_residual == bin_capacity {
        score -= 10.0 + 6.0 * (mean_residual / cap);
        if open_bins_count == 0 {
            score -= 25.0;
        }
        // Late in the stream, opening new bins is wasteful; damp the bonus.
        let t = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 * t;
    }

    // Dynamic time horizon: early on, be picky (amplify fit discrimination);
    // late in the stream, pack greedily and compress score differences.
    let t = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * t;

    // Mild pressure toward bins whose residual is above the fleet mean
    // (drains roomier bins, keeps tight bins coherent).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

