    let coupling = norm_pr * norm_pr * (0.5 + 1.5 * progress) + norm_pr * (1.0 - progress) * 3.0;
    score += 6.0 * coupling;

    // Penalize dead space that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
