        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 && progress > 0.6 {
            score += 10.0 * progress ;
        }
        // mutation: fresh bin attractive early with big items (large usable leftover)
        if item_frac > 0.5 && progress < 0.4 {
            score -= 6.0 * (0.4 - progress) / 0.4 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear in post_residual).
    score -= 40.0 * (1.0 - (post_residual as f64 / cap)).powi(3);

    // Harmonic class logic: dead space below the smallest item (<=10 here, but
    // keep general via modulo classes) is nearly unusable; penalize residuals
    // that fall into "hard-to-fill" integer-division classes.
    let pr = post_residual;
    let small_chunk = (bin_capacity / 10).max(1); // granularity class
    let class = pr / small_chunk;
    if class == 0 {
        score += 25.0; // near-zero residual: dead space
    } else if class == 1 {
        score += 8.0; // very tight leftover, risky
    } else if class <= 3 {
        score -= 5.0; // sweet spot: fits small/medium items well
    }

    // Modulo-10 harmonic classes: residuals that are multiples of 10 align
    // with typical item size classes -> easier future packing.
    if pr % 10 == 0 && pr > 0 {
        score -= 4.0;
    } else if pr % 10 != 0 && pr < 20 {
        score += 3.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            score -= 10.0 * (next_item_size as f64 / pr.max(1) as f64);
        } else {
            // next item cannot use this leftover: penalize small leftovers more
            let waste = pr as f64;
            score += 6.0 * (1.0 - waste / cap);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: opening a new bin is only attractive when the item is
    // large relative to capacity or no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size as f64 / cap;
        // penalize opening new bins mildly; relax when item is huge or many bins open
        score += 12.0 - 10.0 * large_item - 3.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));
        // late in stream, prefer consolidation into existing bins
        score += 5.0 * progress;
    }

    // Prefer bins with below-average residual (keep a spread of fill levels).
    score -= 0.05 * (mean_residual - bin_residual as f64);

    score
}

