        if post_residual as f64 >= 2.0 * mean_residual && post_residual > 20 {
            score -= 5.0 ;
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let headroom = post_residual - next_item_size ;
            if (headroom as f64 - mean_residual) . abs () <= 3.0 {
                score -= 7.0 ;
            }
            if (headroom as f64 - mean_residual) . abs () <= 1.0 && fitting_bins_count <= 3 {
                score -= 5.0 * (1.0 - progress) ;
            }
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0 ;
        }
        if next_item_size > 1 && post_residual > next_item_size + 1 && post_residual <= next_item_size + 10 {
            score -= 4.0 * (1.0 - progress) ;
        }
        if next_item_size > 1 && post_residual % next_item_size == 0 && post_residual >= 2 * next_item_size && post_residual <= 3 * next_item_size {
            score -= 5.0 * (1.0 - progress) ;
        }
        if post_residual >= 5 && post_residual <= 9 && progress > 0.5 && next_item_size > post_residual {
            score += 8.0 * progress ;
        }
        // mutation: dead-space ratio term — penalize bins whose post-fit residual is a small
        // fraction of what other bins offer, unless it is exactly consumed by next item
        if next_item_size > 0 && mean_residual > 0.0 {
            let ratio = post_residual as f64 / mean_residual ;
            if ratio < 0.25 && post_residual != next_item_size {
                score += 5.0 * (0.25 - ratio) ;
            }
        }
    }
    // NEW-BIN CANDIDATE
    if bin_residual == bin_capacity {
        let big_next = next_item_size as f64 / bin_capacity as f64 ;
        score += 180.0 - 60.0 * progress + 0.15 * open_bins_count as f64 - 25.0 * big_next . max (0.0) ;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0 ;
        }
        if open_bins_count <= 4 && progress < 0.3 {
            score += 25.0 ;
        }
        if mean_residual < 15.0 && progress > 0.5 {
            score -= 15.0 ;
        }
        let item_frac = item_size as f64 / bin_capacity as f64 ;
        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3 ;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3 ;
        }
        let fresh_left = bin_capacity - item_size ;
        if next_item_size > 0 && fresh_left == next_item_size {
            score -= 30.0 ;
        }
        if open_bins_count > 6 && mean_residual > 0.4 * bin_capacity as f64 {
            score += 20.0 ;
        }
        if next_item_size > 0 && fresh_left < next_item_size && fresh_left < 8 {
            score += 35.0 ;
        }
        if next_item_size > 0 && fitting_bins_count <= 2 && mean_residual < next_item_size as f64 {
            score -= 18.0 * (1.0 - progress) ;
        }
        if open_bins_count > 8 && mean_residual > next_item_size as f64 + 10.0 {
            score += 12.0 ;
        }
        if item_frac > 0.6 && next_item_size > 0 && fresh_left >= next_item_size {
            score -= 8.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size ;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress) ;
            }
        }
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 && progress > 0.6 {
            score += 10.0 * progress ;
        }
        if item_frac > 0.5 && progress < 0.4 {
            score -= 6.0 * (0.4 - progress) / 0.4 ;
        }
        // mutation: fresh-bin value scales with how chainable its leftover is —
        // a fresh bin whose leftover can host the next item exactly is much stronger
        if next_item_size > 1 && fresh_left % next_item_size == 0 && fresh_left >= next_item_size {
            score -= 10.0 * (1.0 - progress) ;
        }
        // mutation: discourage fresh bins when open bins still have large usable pools
        if next_item_size > 0 && mean_residual > fresh_left as f64 + 5.0 && fitting_bins_count >= 2 {
            score += 14.0 * (0.5 + 0.5 * progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // next item fits but leaves slack; mild reward proportional to tightness
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // next item won't fit here; penalize leaving a small unusable gap
        if post_residual < 10 {
            score += 25.0;
        } else {
            score += 4.0;
        }
    }

    // Prefer bins tighter than the mean residual (best-fit style)
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize new-bin opening unless current bin fit is bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 - 5.0 * progress;
        if post_residual < 20 {
            score += 30.0; // opening a bin for a near-full fit is fine
            score -= 20.0;
        }
    }

    // Dead-space penalty: very small residuals are wasteful
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Slight preference for consolidating into fewer bins when many are open
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // 2-step lookahead: exact closure on next item.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 900.0 - 30.0 * progress;
            } else if post_residual >= next_item_size {
                let after_next = post_residual - next_item_size;
                // Reward by how small the leftover after next item is.
                if after_next == 0 {
                    score -= 700.0;
                } else if after_next <= 5 {
                    score -= 250.0 + 20.0 * (5 - after_next) as f64;
                } else if after_next <= 12 {
                    score -= 120.0 + 8.0 * (12 - after_next) as f64;
                } else {
                    score -= 300.0 - 2.0 * (after_next as f64).min(30.0);
                }
                // leftover after next item can host next_item again (chain home)
                if next_item_size > 1 && after_next >= next_item_size {
                    score -= 6.0 + 0.2 * (after_next / next_item_size) as f64;
                    if after_next % next_item_size == 0 {
                        score -= 8.0 * (1.0 - progress);
                    }
                }
                // small tail after next item: near-seal bonus
                if after_next < next_item_size && after_next <= 3 {
                    score -= 14.0 * (1.0 - progress);
                }
                if after_next < next_item_size && after_next >= 1 && (next_item_size - after_next) <= 5 {
                    score -= 6.0 * (1.0 - progress);
                }
                // headroom matches mean residual: reusable home shape
                if ((after_next as f64) - mean_residual).abs() <= 4.0 {
                    score -= 6.0 * (1.0 - progress);
                }
                // chainable multiple of next item
                if next_item_size > 1 && post_residual % next_item_size == 0 && post_residual >= 2 * next_item_size && post_residual <= 3 * next_item_size {
                    score -= 5.0 * (1.0 - progress);
                }
            } else {
                // Next item will NOT fit: dead space risk, scaled by gap.
                let miss = next_item_size - post_residual;
                score += 2.0 * miss as f64;
                if post_residual < 25 {
                    score += 15.0;
                }
                if post_residual < 3 {
                    score -= 400.0;
                }
                // near-miss with few alternatives: keep it alive
                if miss <= 6 && fitting_bins_count <= 2 {
                    score -= 5.0;
                }
                if miss <= 10 && fitting_bins_count <= 2 && progress > 0.7 {
                    score -= 10.0 * (1.0 - progress);
                }
                if miss <= 2 {
                    score -= 18.0 * (1.0 - progress);
                }
                // residual in awkward mid-range: mildly discourage late
                if post_residual >= 8 && post_residual <= 16 {
                    score += 10.0 * (1.0 - progress);
                }
                if miss > 3 && miss as f64 <= mean_residual * 0.5 {
                    score += 4.0 * (1.0 - progress);
                }
            }
        }

        // Compare post residual to mean residual: efficient consumption.
        score -= 0.6 * (mean_residual - post_residual as f64);

        // small residual bands: prioritize sealing
        if post_residual < 10 {
            score += 45.0;
        } else if post_residual < 20 {
            score += 10.0;
        }

        // dead-gap penalty with scarcity scaling
        let gap = (post_residual as f64 - item_size as f64).max(0.0);
        if gap > 0.0 {
            let scarcity = if fitting_bins_count <= 2 { 0.6 } else if fitting_bins_count <= 4 { 0.3 } else { 0.2 };
            let gap_ratio = gap / (item_size as f64).max(1.0);
            score += scarcity * gap + 18.0 * gap_ratio.min(2.0);
            if gap < mean_residual {
                let fillable = next_item_size > 0 && gap >= next_item_size as f64;
                let w = if fillable { 0.2 } else { 0.6 };
                score += w * (mean_residual - gap);
            }
            if next_item_size > 0 && (gap as u32) == next_item_size {
                score -= 20.0;
            }
            if next_item_size > 1 && (gap as u32) == 2 * next_item_size {
                score -= 12.0;
            }
        }

        // fill ratio reward
        let fill = item_size as f64 / bin_residual.max(1) as f64;
        score -= 20.0 * fill;

        // last-chance bin: only bin that fits — prefer over new bin
        if fitting_bins_count == 1 {
            score -= 12.0;
        }

        // unusable residual relative to next item
        if next_item_size > 0 && post_residual < next_item_size {
            let unusable_ratio = post_residual as f64 / (next_item_size as f64).max(1.0);
            score += 0.4 * post_residual as f64 + 30.0 * (post_residual as f64 / bin_capacity as f64)
                + 12.0 * (1.0 - unusable_ratio);
            if next_item_size - post_residual <= 4 {
                score += 20.0 * (1.0 - progress);
            }
        }

        // anti-fragmentation guard
        if fitting_bins_count == 2 && post_residual < bin_capacity / 3 {
            score -= 8.0;
        }

        // tiny unusable slivers when bins are plentiful
        if post_residual <= 5 && open_bins_count > 6 {
            score += 25.0 * (1.0 - progress);
        }

        // mid-range residual that can absorb more items
        if post_residual >= bin_capacity / 8 && post_residual <= bin_capacity / 2 {
            score -= 6.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= bin_capacity / 2 {
            score -= 4.0 * (1.0 - progress);
        }

        // residual that can absorb two more average items
        if post_residual as f64 >= 2.0 * mean_residual && post_residual > 20 {
            score -= 5.0;
        }

        // headroom matching mean residual, tight when few alternatives
        if next_item_size > 0 && post_residual > next_item_size {
            let headroom = post_residual - next_item_size;
            if (headroom as f64 - mean_residual).abs() <= 3.0 {
                score -= 7.0;
            }
            if (headroom as f64 - mean_residual).abs() <= 1.0 && fitting_bins_count <= 3 {
                score -= 5.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0;
        }
        if next_item_size > 1 && post_residual > next_item_size + 1 && post_residual <= next_item_size + 10 {
            score -= 4.0 * (1.0 - progress);
        }
        // penalize residual just below a common small size late (dead space)
        if post_residual >= 5 && post_residual <= 9 && progress > 0.5 && next_item_size > post_residual {
            score += 8.0 * progress;
        }
    }

    // NEW-BIN CANDIDATE
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let fresh_left = bin_capacity - item_size;
        let big_next = next_item_size as f64 / bin_capacity as f64;
        score += 180.0 - 60.0 * progress + 0.15 * open_bins_count as f64 - 25.0 * big_next.max(0.0);

        // small items into a fresh bin waste space; large items pack well
        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3;
        }

        if next_item_size > 0 {
            if fresh_left == next_item_size {
                score -= 30.0;
            }
            if fresh_left == 2 * next_item_size {
                score -= 12.0;
            }
            // fresh leftover below next item and small: dead sliver
            if fresh_left < next_item_size && fresh_left < 8 {
                score += 35.0;
            }
            if fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
                score += 10.0;
            }
            // fresh leftover can host next item plus mean-shaped slack
            if fresh_left > next_item_size {
                let tail = fresh_left - next_item_size;
                if ((tail as f64) - mean_residual).abs() <= 3.0 {
                    score -= 9.0 * (1.0 - progress);
                }
                if tail <= 3 {
                    score -= 14.0 * (1.0 - progress);
                }
                if (tail as f64) <= mean_residual {
                    score -= 10.0 * (1.0 - progress);
                }
            }
            // prefer fresh bin when existing residuals too small for next item
            if fitting_bins_count <= 2 && mean_residual < next_item_size as f64 {
                score -= 18.0 * (1.0 - progress);
            }
            // discourage fresh bins when many half-empty bins exist
            if open_bins_count > 8 && mean_residual > next_item_size as f64 + 10.0 {
                score += 12.0;
            }
            if open_bins_count > 6 && mean_residual > 0.4 * bin_capacity as f64 {
                score += 20.0;
            }
            if next_item_size >= bin_capacity / 2 {
                score -= 10.0;
            }
            if item_frac > 0.6 && fresh_left >= next_item_size {
                score -= 8.0 * (1.0 - progress);
            }
            if (fresh_left as f64 - mean_residual).abs() <= 2.0 {
                score -= 8.0;
            }
            if fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
                score -= 6.0 * (1.0 - progress);
            }
        }
        // near-exact fill
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress);
        }
        // avoid opening fresh bins when an open bin nearly seals with this item
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0;
        }
        // early stream with few bins: fresh bin is fine
        if open_bins_count <= 4 && progress < 0.3 {
            score += 25.0;
        }
        // large item into fresh bin attractive early
        if item_frac > 0.5 && progress < 0.4 {
            score -= 6.0 * (0.4 - progress) / 0.4;
        }
        // discourage fresh bins late when open bins can host next item comfortably
        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 && progress > 0.6 {
            score += 10.0 * progress;
        }
        // discourage fresh bins late when residuals are tight overall
        if mean_residual < 15.0 && progress > 0.5 {
            score -= 15.0;
        }
    }

    // Late in the stream, consolidate: prefer tightest fits even more.
    score -= progress * 0.3 * post_residual as f64;

    score
}

