        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 && progress > 0.6 {
            score += 10.0 * progress ;
        }
        // mutation: fresh bin attractive early with big items (large usable leftover)
        if item_frac > 0.5 && progress < 0.4 {
            score -= 6.0 * (0.4 - progress) / 0.4 ;
        }
        // mutation: fresh bin should be strongly discouraged when mean residual can still fit next item (avoid premature opening)
        if next_item_size > 0 && mean_residual >= next_item_size as f64 + 2.0 && open_bins_count > 2 {
            score += 8.0 + 6.0 * progress ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize tiny dead space that nothing small could reuse later
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly or well
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
        } else {
            score += 4.0;
        }
    }

    // Time horizon: early in stream, be more exploratory (favor new bins less);
    // late in stream, consolidate to avoid opening bins we won't fill
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses unless item is large
        let large_item_bonus = if item_size > bin_capacity / 2 { 10.0 } else { 0.0 };
        score += 8.0 + 20.0 * progress - large_item_bonus;
    } else {
        // Existing bin: reward more as stream progresses (consolidation)
        score -= 5.0 * progress;
    }

    // Global state coupling: many open bins with high mean residual -> prefer filling existing bins
    if open_bins_count > 3 && mean_residual > 30.0 && bin_residual < bin_capacity {
        score -= 0.05 * mean_residual;
    }

    // Prefer bins below mean residual (more filled than average)
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= 0.08 * diff;
    }

    score
}

