pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 + progress) - norm_post * progress * progress;
    score += 20.0 * poly;

    // Penalize waste relative to mean residual across open bins
    let waste = (post - mean_residual) / cap;
    score += 10.0 * waste * waste * cap;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_post;
    score -= tightness * tightness * (10.0 + 20.0 * progress);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 25.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let gap = (post - nxt) / cap;
            score -= 12.0 * (1.0 - gap) * (1.0 - gap);
        } else {
            score += 5.0 * (nxt - post) / cap;
        }
    }

    // Mild penalty for many open bins to encourage consolidation
    score += open_bins_count as f64 * 0.5 * (0.5 + 0.5 * progress);

    // Slight preference for opening new bins early vs late
    if bin_residual == bin_capacity {
        score += 8.0 * progress;
    }

    score
}

