pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // minimum item (or the lookahead item) are wasted capacity. Penalize heavily
    // once post_residual falls into the "unusable gap" regime.
    let min_gap = if next_item_size > 0 { next_item_size.min(10) } else { 10 };
    if post_residual > 0 && post_residual < min_gap {
        score += 40.0 + (min_gap - post_residual) as f64 * 3.0;
    }

    // Non-linear dead-space curve: moderate residuals are fine, but residuals
    // just above a typical item size waste little; residuals slightly below
    // common sizes are dead. Penalize residual that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // Reward near-perfect fits (post_residual small but item fully placed).
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Tight-fit coupling: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 15.0;

    // Last-chance pressure: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into a new
    // bin; with few bins, consolidation is cheaper anyway.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open,
        // and when the item would leave a large residual anyway.
        score += 20.0 + open_bins_count as f64 * 2.0 + fill * 10.0;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 8.0; // fresh bin can serve the lookahead too
        }
    } else {
        // Slight reward for consolidating into existing bins when open count is high.
        score -= open_bins_count as f64 * 0.3;
    }

    // Mean-residual alignment: prefer bins whose residual is close to the mean
    // (keeps residuals balanced), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // Stream progression: late in the stream, avoid creating tiny unusable gaps
    // even more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 15 {
        score += progress * 10.0;
    }

    score
}

