        if next_item_size > 0 && (next_item_size as f64) > 2.0 * mean_residual {
            score -= 8.0 * (1.0 - progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        score -= 30.0 / (1.0 + diff as f64);
        // Exact match bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving residual too small for the next item (dead space)
        if post_residual < next_item_size && post_residual > 0 {
            let waste = next_item_size - post_residual;
            score += 0.5 * waste as f64;
        }
    } else {
        // Last item: prefer tightest fit
        score -= 10.0;
    }

    // Reward residuals below mean (tight bins), penalize above-mean waste
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless it's a genuinely better option
    if bin_residual == bin_capacity {
        let mut penalty = 40.0;
        // More open bins => new bin less costly
        penalty -= 2.0 * open_bins_count as f64;
        // Late in stream, prefer reusing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        penalty += 20.0 * progress;
        // If next item fits into fresh bin with item, soften penalty
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            penalty -= 10.0;
        }
        score += penalty.max(0.0);
    }

    score
}

