pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: square the post residual to strongly prefer snug placements.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead (k=2): penalize if the next item no longer fits after this placement,
    // reward if it still fits (chaining compatible items).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.35;
            // Extra reward when next item exactly consumes the future residual.
            if post_residual == next_item_size {
                score -= 12.0;
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // New-bin candidate: penalize opening a new bin unless it is genuinely needed
    // (no other fitting bins, or current bin residual is poor for item sizes seen).
    if bin_residual == bin_capacity {
        let escape_penalty = if fitting_bins_count <= 1 { 0.0 } else { 40.0 };
        // Slightly cheaper to open new bin early in the stream (more future structure).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 + escape_penalty + progress * 20.0 - (mean_residual * 0.1);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Waste-avoidance: penalize leaving large unusable gaps relative to the
    // smallest plausible item (1..100 range => gap < 1 is perfect).
    if post_residual > 0 {
        score += 8.0 / post_residual as f64;
    }

    // Mild preference for balancing residual mass across open bins.
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // Late-stream pressure: as the stream ends, consolidating into fewer bins matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
