pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual (tight fit), with non-linear emphasis
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling of post-residual with stream progress:
    // early on tolerate slack, later penalize it more (waste compounds)
    let prog_coupling = pr * (0.5 + 1.5 * progress * progress);
    score += prog_coupling;

    // Interaction: post_residual vs mean residual — avoid bins that deviate
    // from the fleet's average slack (keeps residual distribution balanced)
    score += 0.3 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // Lookahead: reward leaving space close to the next item's size
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score += 0.4 * diff;
        // bonus if next item fits exactly-ish
        let fit_quality = 1.0 - (diff / cap).min(1.0);
        score -= 0.6 * fit_quality * fit_quality * pr;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // More open bins -> mild preference for consolidating into existing bins
    score -= 0.5 * (open_bins_count as f64).ln() * (cap - pr);

    // Slight penalty for opening a new bin (empty-bin candidate gets pr = cap)
    let new_bin_indicator = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    score += new_bin_indicator * (10.0 + 30.0 * progress);

    score
}

