    let progress = step_index as f64 / total_items . max (1) as f64 ;
    if post_residual == 0 {
        score -= 1000.0 ;
    } else {
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 900.0 - 30.0 * progress ;
            } else if next_item_size <= post_residual {
                let two_step_waste = (post_residual - next_item_size) as f64 ;
                if two_step_waste == 0.0 {
                    score -= 700.0 ;
                } else if two_step_waste >= 10.0 {
                    score -= 300.0 - 2.0 * two_step_waste ;
                } else {
                    score -= 80.0 + 1.5 * (10.0 - two_step_waste) ;
                }
                let after_next = post_residual - next_item_size ;
                if after_next >= 3 {
                    score -= (2.0 + 2.0 * progress) * (after_next as f64) . min (15.0) ;
                }
                if after_next <= 12 && mean_residual >= after_next as f64 {
                    score -= 22.0 - 0.8 * after_next as f64 ;
                }
                if next_item_size > 1 && after_next >= next_item_size {
                    score -= 6.0 + 0.2 * (after_next / next_item_size) as f64 ;
                    if after_next % next_item_size == 0 {
                        score -= 8.0 * (1.0 - progress) ;
                    }
                }
                if after_next < next_item_size && after_next <= 3 {
                    score -= 14.0 * (1.0 - progress) ;
                }
                if after_next < next_item_size && after_next >= 1 && (next_item_size - after_next) <= 5 {
                    score -= 6.0 * (1.0 - progress) ;
                }
                if (after_next as f64 - mean_residual) . abs () <= 4.0 {
                    score -= 6.0 * (1.0 - progress) ;
                }
                // mutation: reward leaving exactly the mean residual after next item (predictable reuse)
                if after_next > 0 && (after_next as f64 - mean_residual) . abs () <= 1.5 {
                    score -= 9.0 * (1.0 - progress) ;
                }
            } else {
                let miss = next_item_size - post_residual ;
                score += 2.0 * miss as f64 ;
                if post_residual < 25 {
                    score += 15.0 ;
                }
                if post_residual < 3 {
                    score -= 400.0 ;
                }
                if miss <= 6 && fitting_bins_count <= 2 {
                    score -= 5.0 ;
                }
                if miss <= 10 && fitting_bins_count <= 2 && progress > 0.7 {
                    score -= 10.0 * (1.0 - progress) ;
                }
                if miss <= 2 {
                    score -= 18.0 * (1.0 - progress) ;
                }
                if post_residual >= 8 && post_residual <= 16 {
                    score += 10.0 * (1.0 - progress) ;
                }
                if miss > 3 && miss as f64 <= mean_residual * 0.5 {
                    score += 4.0 * (1.0 - progress) ;
                }
            }
        }
        if post_residual < 10 {
            score += 45.0 ;
        } else if post_residual < 20 {
            score += 10.0 ;
        }
        score -= (mean_residual - post_residual as f64) * 0.6 ;
        let gap = (post_residual as f64 - item_size as f64) . max (0.0) ;
        let gap_ratio = gap / (item_size as f64) . max (1.0) ;
        if gap > 0.0 {
            let scarcity = if fitting_bins_count <= 2 { 0.6 } else if fitting_bins_count <= 4 { 0.3 } else { 0.2 } ;
            score += scarcity * gap + 18.0 * gap_ratio . min (2.0) ;
            if gap < mean_residual {
                let fillable = next_item_size > 0 && gap >= next_item_size as f64 ;
                let w = if fillable { 0.2 } else { 0.6 } ;
                score += w * (mean_residual - gap) ;
            }
            if next_item_size > 0 && (gap as u32) == next_item_size {
                score -= 20.0 ;
            }
            if next_item_size > 1 && (gap as u32) == 2 * next_item_size {
                score -= 12.0 ;
            }
        }
        if fitting_bins_count == 1 {
            score -= 12.0 ;
        }
        let fill = item_size as f64 / (bin_residual as f64) . max (1.0) ;
        score -= 20.0 * fill ;
        if next_item_size > 0 && post_residual < next_item_size {
            let dead_frac = post_residual as f64 / bin_capacity as f64 ;
            let unusable_ratio = post_residual as f64 / (next_item_size as f64) . max (1.0) ;
            score += 0.4 * post_residual as f64 + 30.0 * dead_frac + 12.0 * (1.0 - unusable_ratio) ;
            if next_item_size - post_residual <= 4 {
                score += 20.0 * (1.0 - progress) ;
            }
            // mutation: dead space late in the stream is costlier (no time to amortize)
            if post_residual > 4 && progress > 0.6 {
                score += 6.0 * progress * dead_frac * 100.0 . min (post_residual as f64) / 10.0 ;
            }
        }
        if fitting_bins_count == 2 && post_residual < bin_capacity / 3 {
            score -= 8.0 ;
        }
        if post_residual <= 5 && open_bins_count > 6 {
            score += 25.0 * (1.0 - progress) ;
        }
        if post_residual >= bin_capacity / 8 && post_residual <= bin_capacity / 2 {
            score -= 6.0 ;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= bin_capacity / 2 {
            score -= 4.0 * (1.0 - progress) ;
        }
        if post_residual as f64 >= 2.0 * mean_residual && post_residual > 20 {
            score -= 5.0 ;
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let headroom = post_residual - next_item_size ;
            if (headroom as f64 - mean_residual) . abs () <= 3.0 {
                score -= 7.0 ;
            }
            if (headroom as f64 - mean_residual) . abs () <= 1.0 && fitting_bins_count <= 3 {
                score -= 5.0 * (1.0 - progress) ;
            }
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0 ;
        }
        if next_item_size > 1 && post_residual > next_item_size + 1 && post_residual <= next_item_size + 10 {
            score -= 4.0 * (1.0 - progress) ;
        }
        if next_item_size > 1 && post_residual % next_item_size == 0 && post_residual >= 2 * next_item_size && post_residual <= 3 * next_item_size {
            score -= 5.0 * (1.0 - progress) ;
        }
        if post_residual >= 5 && post_residual <= 9 && progress > 0.5 && next_item_size > post_residual {
            score += 8.0 * progress ;
        }
        // mutation: prefer bins whose post residual stays above the smallest plausible item (1..=5 window)
        if next_item_size > 0 && post_residual < next_item_size && post_residual >= 1 && next_item_size <= 20 {
            score += 3.0 * (next_item_size - post_residual) as f64 * progress ;
        }
    }
    // NEW-BIN CANDIDATE
    if bin_residual == bin_capacity {
        let big_next = next_item_size as f64 / bin_capacity as f64 ;
        score += 180.0 - 60.0 * progress + 0.15 * open_bins_count as f64 - 25.0 * big_next . max (0.0) ;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0 ;
        }
        if open_bins_count <= 4 && progress < 0.3 {
            score += 25.0 ;
        }
        if mean_residual < 15.0 && progress > 0.5 {
            score -= 15.0 ;
        }
        let item_frac = item_size as f64 / bin_capacity as f64 ;
        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3 ;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3 ;
        }
        let fresh_left = bin_capacity - item_size ;
        if next_item_size > 0 && fresh_left == next_item_size {
            score -= 30.0 ;
        }
        if open_bins_count > 6 && mean_residual > 0.4 * bin_capacity as f64 {
            score += 20.0 ;
        }
        if next_item_size > 0 && fresh_left < next_item_size && fresh_left < 8 {
            score += 35.0 ;
        }
        if next_item_size > 0 && fitting_bins_count <= 2 && mean_residual < next_item_size as f64 {
            score -= 18.0 * (1.0 - progress) ;
        }
        if open_bins_count > 8 && mean_residual > next_item_size as f64 + 10.0 {
            score += 12.0 ;
        }
        if item_frac > 0.6 && next_item_size > 0 && fresh_left >= next_item_size {
            score -= 8.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size ;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress) ;
            }
        }
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 && progress > 0.6 {
            score += 10.0 * progress ;
        }
        if item_frac > 0.5 && progress < 0.4 {
            score -= 6.0 * (0.4 - progress) / 0.4 ;
        }
        // mutation: fresh bin is more attractive when its leftover is close to mean residual (likely reusable)
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 4.0 {
            score -= 7.0 * (1.0 - progress) ;
        }
        // mutation: avoid opening a fresh bin when many open bins already have near-mean residuals
        if open_bins_count > 5 && mean_residual > 8.0 && progress > 0.4 {
            score += 6.0 * progress ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lies in
    // "small" residue classes are more reusable for typical items.
    let pr = post_residual as i64;
    let cap = bin_capacity as i64;

    // Modulo-10 harmonic class penalty: residues 1..9 are dead space,
    // residue 0 (multiple of 10) is highly reusable.
    let m10 = pr % 10;
    if pr > 0 {
        score += match m10 {
            0 => -12.0,
            1 | 9 => 6.0,
            2 | 8 => 3.0,
            3 | 7 => 1.5,
            _ => 0.0,
        };
    }

    // Perfect fit reward: post_residual exactly zero or a small harmonic
    // multiple (e.g. 10, 20, 25, 50) is gold.
    if pr == 0 {
        score -= 40.0;
    } else if pr % 25 == 0 || pr % 20 == 0 {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits the post residual exactly
    // (harmonic chain), strongly favor this bin.
    if next_item_size > 0 {
        let n = next_item_size as i64;
        if n == pr {
            score -= 30.0;
        } else if pr >= n && (pr - n) % 10 == 0 {
            score -= 10.0;
        } else if pr < n {
            // dead-end residual: cannot host the lookahead at all
            score += 8.0 * (n as f64 - pr as f64).ln().max(0.0);
        }
        // Integer-division threshold: leftover after hosting next item
        let after_next = pr - n;
        if after_next >= 0 && after_next < 10 && after_next > 0 {
            score += 4.0; // creates sub-10 sliver
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Penalize wasting a large residual on a small item (ratio mismatch).
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    if fill_frac < 0.4 {
        score += 10.0 * (0.4 - fill_frac);
    } else if fill_frac > 0.9 {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (post_residual of empty bin = cap - item, a fresh harmonic start).
    if bin_residual == bin_capacity {
        score += 25.0;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // early in stream, opening bins is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Mild pressure toward consolidating into fewer bins when many are open.
    score += 0.5 * open_bins_count as f64;

    // Mean-residual anchoring: prefer bins whose resulting residual is
    // below the mean (tighter packing).
    score += 0.3 * (post_residual as f64 - mean_residual);

    score
}

