pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // (1) are pure waste; penalize the more the tighter the gap is.
    let dead_threshold = 1u32;
    if post_residual < dead_threshold && post_residual > 0 {
        score += 40.0 * (dead_threshold - post_residual) as f64;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item cannot fit in the post residual,
    // this placement creates dead space for the known future item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.35 * (next_item_size - post_residual) as f64;
    }
    // Conversely reward leaving room that still fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score -= 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, mild encouragement to fill existing bins.
    score += 0.8 * open_bins_count as f64;

    // Prefer bins whose residual is close to the item (tight fit).
    score += 0.15 * (bin_residual - item_size) as f64;

    // Mean-residual coupling: placing into a bin below the mean residual
    // (smaller residual = tighter bin) is preferred.
    score += 0.5 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
