        // the item (if many fit, opening new is wasteful).
        score = 30.0 + 6.0 * fitting_bins_count as f64;
        // Early in the stream, opening bins is cheaper (builds flexibility).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
        // If the item is large relative to capacity, a fresh bin is attractive.
        score -= 0.1 * item_size as f64;
    }

    score
