pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain fit (next item exactly fills the bin)
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize remaining gap proportional to how far the next item is from fitting
        score += 0.8 * gap;
        // If next item cannot fit at all, penalize dead space more
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer tightest fill
        score += 0.3 * post_residual as f64;
    }

    // Tight fit reward: small post_residual relative to capacity is good
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * tightness * tightness;

    // Compare against mean residual: placing in a below-average-residual bin
    // (best-fit behavior) is preferred.
    score -= 0.4 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Base penalty so we prefer existing bins with decent fits
        score += 12.0;
        // But if the new bin gives a perfect lookahead chain, allow it
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 70.0;
        }
        // Late in the stream, opening fresh bins is riskier (wasted capacity)
        let progress = step_index as f64 / total_items as f64;
        score += 8.0 * progress;
    }

    // Slight preference for consolidating into fewer bins when many are open
    score += 0.05 * open_bins_count as f64;

    score
}

