        if next_item_size > 1 && post_residual % next_item_size == 0 && post_residual >= 2 * next_item_size && post_residual <= 3 * next_item_size {
            score -= 5.0 * (1.0 - progress);
        }
        if post_residual >= 5 && post_residual <= 9 && progress > 0.5 && next_item_size > post_residual {
            score += 8.0 * progress;
        }
    }

    // NEW-BIN CANDIDATE
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let fresh_left = bin_capacity - item_size;
        let big_next = next_item_size as f64 / bin_capacity as f64;
        score += 180.0 - 60.0 * progress + 0.15 * open_bins_count as f64 - 25.0 * big_next.max(0.0);

        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
        if open_bins_count <= 4 && progress < 0.3 {
            score += 25.0;
        }
        if mean_residual < 15.0 && progress > 0.5 {
            score -= 15.0;
        }

        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3;
        }

        if next_item_size > 0 {
            if fresh_left == next_item_size {
                score -= 30.0;
            }
            if fresh_left == 2 * next_item_size {
                score -= 12.0;
            }
            if fresh_left < next_item_size && fresh_left < 8 {
                score += 35.0;
            }
            if fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual).abs() <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
            if fresh_left > next_item_size {
                let tail = fresh_left - next_item_size;
                if tail <= 3 {
                    score -= 14.0 * (1.0 - progress);
                }
            }
            if fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
                score += 10.0;
            }
            if fitting_bins_count <= 2 && mean_residual < next_item_size as f64 {
                score -= 18.0 * (1.0 - progress);
            }
            if fresh_left >= next_item_size && (fresh_left as f64 - mean_residual).abs() <= 2.0 {
                score -= 8.0;
            }
            if fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
                score -= 6.0 * (1.0 - progress);
            }
        }
        if open_bins_count > 6 && mean_residual > 0.4 * bin_capacity as f64 {
            score += 20.0;
        }
        if open_bins_count > 8 && next_item_size > 0 && mean_residual > next_item_size as f64 + 10.0 {
            score += 12.0;
        }
        if item_frac > 0.6 && next_item_size > 0 && fresh_left >= next_item_size {
            score -= 8.0 * (1.0 - progress);
        }
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 && progress > 0.6 {
            score += 10.0 * progress;
        }
        if item_frac > 0.5 && progress < 0.4 {
            score -= 6.0 * (0.4 - progress) / 0.4;
        }
    }

    score -= progress * 0.3 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, moderate residuals are fine; late, we push hard toward tight fits.
    let poly = pr * pr / cap;                       // quadratic penalty on large dead space
    let coupling = poly * (0.35 + 0.65 * progress); // grows stronger as stream progresses
    score += 0.9 * coupling;

    // Reward tight fits (small post_residual) with a smooth saturating bonus.
    let tightness = 1.0 - (pr / cap);
    score -= 18.0 * tightness * tightness * tightness;

    // Lookahead: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = pr - nxt;
            let fit_quality = 1.0 - gap / cap;
            score -= 10.0 * fit_quality * fit_quality;
        } else {
            // Next item won't fit here; mildly penalize near-full residuals that strand space.
            let stranded = (pr / cap).powi(3);
            score += 6.0 * stranded;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 14.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist
    // and as the stream progresses (amortization improves late).
    if bin_residual == bin_capacity {
        let mut penalty = 22.0 + 16.0 * progress;
        if fitting_bins_count > 0 {
            penalty += 10.0 * (fitting_bins_count as f64).ln();
        }
        // If mean residual across open bins is large, new bin is less wasteful.
        penalty -= 4.0 * (mean_residual / cap);
        score += penalty.max(0.0);
    }

    // Mild preference for balancing residual mass across open bins.
    let dev = (pr - mean_residual).abs() / cap;
    score += 2.5 * dev * dev;

    score
}

