pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: classify post_residual into residual classes.
    // Small dead space (< 10, minimum item size) is nearly unusable -> penalize mildly less
    // than medium dead space which could have fit items but likely won't be filled.
    let dead = post_residual as f64;
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable sliver: dead weight, but small absolute waste.
            score += 5.0;
        } else {
            // Usable space: reward keeping it, scaled by fraction of capacity.
            let frac = post_residual as f64 / bin_capacity as f64;
            score -= 12.0 * frac;
            // Harmonic class buckets: quarters of capacity.
            let quarter = (bin_capacity / 4).max(1);
            let class = post_residual / quarter;
            match class {
                0 => score -= 3.0,   // 0..25 residual
                1 => score -= 1.0,   // 25..50
                2 => score += 2.0,   // 50..75 : half-full-ish bin, mediocre
                _ => score += 6.0,   // 75..100 : nearly empty bin used for this item
            }
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 400.0;
        } else if gap < 10 {
            score -= 150.0;
        } else {
            score -= 40.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    }
    // If next item cannot fit in this residual, the residual is likely dead -> penalize.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin is expensive unless current bin
    // would be left with large awkward residual.
    if bin_residual == bin_capacity {
        // Fresh bin: baseline moderate score; prefer it only when alternatives are bad.
        score = 60.0 - (mean_residual / bin_capacity as f64) * 30.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0;
        }
        // Early in stream, opening bins is fine; late in stream, prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    }

    // Prefer bins whose residual is close to mean (balance), slight tie-breaker.
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    // Tightness reward: reward filling a large fraction of the current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Many open bins: encourage closing them out (using bins with small residual).
    if open_bins_count > 4 {
        score += 0.5 * post_residual as f64 * 0.1;
    }

    score
}

