pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1..10)
    // are wasted; penalize the "unusable gap" zone harshly.
    if post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual <= 20 {
        // Semi-dead zone: only next_item_size can potentially use it.
        if next_item_size == 0 || next_item_size > post_residual {
            score += 12.0;
        } else {
            // Gap exactly matches the lookahead item: strong reward.
            score -= 15.0;
        }
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Reward leaving a residual that the lookahead item can still use.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 10.0 * snug;
    } else if next_item_size > 0 {
        // Lookahead cannot use this bin afterward; mild penalty scaled by stream position.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 6.0 + 6.0 * progress;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // filling existing bins is cheap.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (keeps residuals homogeneous and mergeable).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate handling: only attractive when current bin fits are poor
    // or this bin is already nearly full.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let poor_fits = (post_residual as f64) > 60.0;
        if desperation > 0.5 || (poor_fits && open_bins_count == 0) {
