        // plausible future item — scale penalty by how far below next_item it falls
        if next_item_size > 0 && post_residual < next_item_size {
            let shortfall = (next_item_size - post_residual) as f64 ;
            if shortfall <= 10.0 {
                score += shortfall * (1.5 + 2.5 * progress) * (post_residual as f64 / bin_capacity as f64) . max (0.01) * 10.0 ;
            }
        }
        // mutation: reward near-perfect fills harder when few bins remain open
        if post_residual <= 2 && fitting_bins_count <= 3 {
            score -= 10.0 + 8.0 * (1.0 - progress) ;
        }
    }
    // NEW-BIN CANDIDATE
    if bin_residual == bin_capacity {
        let big_next = next_item_size as f64 / bin_capacity as f64 ;
        score += 180.0 - 60.0 * progress + 0.15 * open_bins_count as f64 - 25.0 * big_next . max (0.0) ;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0 ;
        }
        if open_bins_count <= 4 && progress < 0.3 {
            score += 25.0 ;
        }
        if mean_residual < 15.0 && progress > 0.5 {
            score -= 15.0 ;
        }
        let item_frac = item_size as f64 / bin_capacity as f64 ;
        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3 ;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3 ;
        }
        let fresh_left = bin_capacity - item_size ;
        if next_item_size > 0 && fresh_left == next_item_size {
            score -= 30.0 ;
        }
        if open_bins_count > 6 && mean_residual > 0.4 * bin_capacity as f64 {
            score += 20.0 ;
        }
        if next_item_size > 0 && fresh_left < next_item_size && fresh_left < 8 {
            score += 35.0 ;
        }
        if next_item_size > 0 && fitting_bins_count <= 2 && mean_residual < next_item_size as f64 {
            score -= 18.0 * (1.0 - progress) ;
        }
        if open_bins_count > 8 && mean_residual > next_item_size as f64 + 10.0 {
            score += 12.0 ;
        }
        if item_frac > 0.6 && next_item_size > 0 && fresh_left >= next_item_size {
            score -= 8.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size ;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress) ;
            }
        }
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 && progress > 0.6 {
            score += 10.0 * progress ;
        }
        if item_frac > 0.5 && progress < 0.4 {
            score -= 6.0 * (0.4 - progress) / 0.4 ;
        }
        // mutation: gate fresh bins by aggregate slack — if open bins collectively
        // hold enough residual for the next few items, opening a new one wastes space
        if next_item_size > 0 {
            let slack_est = mean_residual * (open_bins_count as f64) ;
            if slack_est >= 3.0 * next_item_size as f64 {
                score += (slack_est - 3.0 * next_item_size as f64) . min (40.0) * (0.3 + 0.5 * progress) ;
            } else if slack_est < next_item_size as f64 {
                score -= 12.0 * (1.0 - progress) ;
            }
        }
        // mutation: a fresh bin is only attractive if its leftover beats the mean
        // open-bin residual by a healthy margin
        if (fresh_left as f64) < mean_residual + 5.0 && progress > 0.35 {
            score += 14.0 * progress ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward when post_residual exactly fits the next item (perfect 2-step match)
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize dead space: post_residual too small to fit the next item
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Penalize creating unusable dead space relative to mean residual
    if (post_residual as f64) < mean_residual {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Late in the stream, prefer tighter packing (smaller post_residual)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.5;

    // Slight preference for filling existing bins over opening new ones
    if bin_residual < bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Exact-fit / zero-waste handling.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: reward bins whose post_residual hosts the next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0 - 30.0 * progress; // perfect two-item fill
        } else if next_item_size <= post_residual {
            let after_next = post_residual - next_item_size;
            let two_step_waste = after_next as f64;
            if two_step_waste >= 10.0 {
                score -= 300.0 - 2.0 * two_step_waste;
            } else {
                score -= 80.0 + 1.5 * (10.0 - two_step_waste);
            }
            if after_next >= 3 {
                score -= (2.0 + 2.0 * progress) * (after_next as f64).min(15.0);
            }
            if after_next <= 12 && mean_residual >= after_next as f64 {
                score -= 22.0 - 0.8 * after_next as f64;
            }
            if next_item_size > 1 && after_next >= next_item_size {
                score -= 6.0 + 0.2 * (after_next / next_item_size) as f64;
                if after_next % next_item_size == 0 {
                    score -= 8.0 * (1.0 - progress);
                }
            }
            if after_next < next_item_size && after_next <= 3 {
                score -= 14.0 * (1.0 - progress);
            }
            if (after_next as f64 - mean_residual).abs() <= 4.0 {
                score -= 6.0 * (1.0 - progress);
            }
        } else {
            let miss = next_item_size - post_residual;
            score += 2.0 * miss as f64;
            if post_residual < 25 {
                score += 15.0;
            }
            if post_residual < 3 {
                score -= 400.0; // near-dead residual: burn it now
            }
            if miss <= 6 && fitting_bins_count <= 2 {
                score -= 5.0;
            }
            if miss <= 2 {
                score -= 18.0 * (1.0 - progress);
            }
            if post_residual >= 8 && post_residual <= 16 {
                score += 10.0 * (1.0 - progress);
            }
