    // Penalize bins whose residual barely exceeds the item (awkward fit),
    // but reward near-perfect packing.
    let exact = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    if exact < 0.05 {
        score -= 8.0;
    } else if exact < 0.20 {
        score += 4.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Post-residual too small for next item: penalize dead space more
            // if the dead space is large.
            score += (post_residual as f64 / bin_capacity as f64) * 10.0;
        }
    } else {
        // Last item: just minimize post-residual.
        score -= 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 0.05 * open_bins_count as f64;
    }

    // New-bin candidate handling: opening a new bin is expensive when many
    // bins are open; make empty-bin score less attractive as stream progresses.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 15.0 * progress + 2.0 * open_bins_count as f64;
        // But if the mean residual across open bins is small (all bins tight),
        // opening a new bin is reasonable.
        score -= mean_residual * 0.15;
    }

    // Global balance: prefer bins whose residual is below the mean residual
    // (pack into fuller bins first).
    score += (bin_residual as f64 - mean_residual) * 0.08;

    // Early stream: be slightly greedy toward filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
