    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // base: post residual, scaled by stream progress (late items value tight fits more)
    let mut score = pr * (0.6 + 0.8 * progress);

    // non-linear polynomial coupling of post_residual with progress
    score += 40.0 * norm_pr * norm_pr * (1.0 - progress);
    score += 60.0 * norm_pr * norm_pr * norm_pr * progress;

    // penalize residual close to but below next item size (dead space)
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 && gap < 20.0 {
            score += (20.0 - gap) * 1.5;
        }
        // reward residual that exactly accommodates next item
        if (gap.abs() < 1.0) {
            score -= 15.0;
        }
    }

    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // favor bins with residual below mean (tighter bins first)
    score += (mean_residual - pr) * 0.3;

    // mild penalty when many bins open and post residual large
    score += 0.05 * (open_bins_count as f64) * norm_pr;

    score
}

