}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into capacity-fraction classes.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post_class = post_residual / quarter; // 0..4 harmonic class
    let next_class = next_item_size / quarter;

    // Perfect fit / near-perfect fit reward: post_residual is a small divisor class.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= eighth {
        score -= 60.0;
    } else if post_residual < quarter {
        score -= 20.0;
    } else {
        // Large leftover (>= quarter capacity) is dead space: penalize super-linearly.
        score += (post_residual as f64 - quarter as f64) * 0.9;
    }

    // Modulo arithmetic: reward when post_residual is a multiple of small units (10/20),
    // since future items often tile such residuals exactly.
    if post_residual % 10 == 0 {
        score -= 12.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: strongly reward if next item fits the post residual exactly
    // or within a tight class.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap <= eighth {
                score -= 40.0;
            } else if gap < quarter {
                score -= 10.0;
            }
        } else {
            // Next item cannot use this bin's leftover: leftover is likelier dead space.
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
        // Harmonic class match: next item class equals post class => good chaining.
        if next_class == post_class && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 45.0;
        if post_residual <= quarter {
            score -= 25.0;
        }
    }

    // New-bin candidate handling: an empty bin has huge residual; make it attractive
    // only when current fit is bad (post_residual large) or many bins are open.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 0.55 * cap + open_bins_count as f64 * 3.0;
        // Later in the stream, prefer consolidating into open bins more strongly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
        // If mean residual across open bins is large, opening a new bin is wasteful.
        score += mean_residual.max(0.0) * 0.5;
        // But if the item is large and fits would leave big dead space elsewhere,
        // a fresh bin is fine: soften when item is big.
        score -= (item_size as f64 / cap) * 30.0;
    }

    // Mild tie-break toward fuller bins (smaller post_residual already dominates,
    // add slight preference for bins tighter than the mean).
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

