        }
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        // mutation: discourage fresh bins late when an open bin can host next item comfortably
        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 && progress > 0.6 {
            score += 10.0 * progress ;
        }
        // mutation: fresh bin attractive early with big items (large usable leftover)
        if item_frac > 0.5 && progress < 0.4 {
            score -= 6.0 * (0.4 - progress) / 0.4 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    let dead_threshold = 20u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 * (1.0 - post_residual as f64 / dead_threshold as f64);
    }

    // Reward tight fits (small waste relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness * tightness;

    // If post-residual exactly matches next item, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.3 + 0.7 * progress) * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // New-bin candidate: only attractive when current bin fit would leave bad dead space
    // or no bin fits well; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        if waste < dead_threshold as f64 {
            score += 50.0; // would create dead space immediately -> avoid new bin
        } else {
            score += 12.0 + open_bins_count as f64 * 2.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    score
}

