pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong lookahead: perfect match of post_residual with next item is gold.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if diff == 0.0 {
            score -= 1000.0; // exact 2-step chain
        } else if post_residual >= next_item_size {
            // next item fits here: reward closeness of leftover after both items
            let two_step = (post_residual as f64 - next).abs();
            score -= (100.0 - two_step) * 0.6;
        } else {
            // next item won't fit: penalize wasted residual proportional to gap
            score += (next - post_residual as f64) * 1.5;
        }
        // bonus if residual after chain is small (tight packing)
        if post_residual as f64 >= next {
            score -= (post_residual as f64 - next) * 0.2;
        }
    }

    // Tightness reward: small post_residual is good, but zero-ish waste extra bonus
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score -= 50.0;
    }

    // Compare against mean residual across open bins: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: avoid opening a new bin if this is the only fit
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when open bins are fragmented
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 1000.0;
        } else {
            // penalize new bin unless mean residual is badly fragmented
            score += mean_residual * 1.2 + open_bins_count as f64 * 5.0;
        }
    }

    // Late in stream: consolidate, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

