pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: waste ratio penalty
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 8.0;

    // Penalize leaving awkward small residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable slivers are bad unless bin nearly done
    }
    if post_residual == 0 {
        score -= 25.0; // perfect closure
    }

    // Lookahead: if next item fits exactly in the post-residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how snugly
            let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual as f64;
            score -= 10.0 * snug;
        } else {
            // next item won't fit here: mild penalty for blocking
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: discourage opening new bins when decent fits exist,
    // but allow it when open bins' residuals are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        // if mean residual is small (bins nearly full), opening a new bin is fine
        score += 15.0 * (1.0 - fragmentation);
        // early stream: slightly prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 6.0;
        // many open bins: new bin less costly
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Prefer bins with residual close to item size (best-fit flavor)
    let gap = (bin_residual - item_size) as f64;
    score += gap * 0.05;

    // Global balance: pull toward bins below mean residual (spread usage evenly
    // keeps medium residuals available for medium items)
    score += (bin_residual as f64 - mean_residual) * 0.03;

    // Late-stream: prioritize closing bins out
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 && post_residual < 20 {
        score -= 8.0 * progress;
    }

    score
}

