pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual (dead space fraction)
    let pr = post_residual as f64 / bin_capacity as f64;

    // Smooth polynomial coupling: dead space is penalized more as stream progresses
    let coupling = pr * pr * (1.0 + 3.0 * progress) + pr * progress * 2.0;
    score += coupling * bin_capacity as f64;

    // Reward tight fits (post_residual near zero), stronger late in the stream
    let tight = (1.0 - pr).powi(6);
    score -= tight * (12.0 + 18.0 * progress);

    // Lookahead: reward leaving room for the next item (smooth kernel)
    if next_item_size > 0 {
        let diff = post_residual as f64 - next_item_size as f64;
        let k = (diff / bin_capacity as f64).abs();
        let kernel = (-k * k * 8.0).exp();
        score -= kernel * (10.0 + 10.0 * progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Many fitting bins: slight preference for bins with smaller residual (best fit)
    if fitting_bins_count > 1 {
        score += pr * 4.0;
    }

    // New empty bin candidate: penalize mildly so it wins only when fits are bad,
    // with a smooth decay as the stream progresses (consolidate late).
    if bin_residual == bin_capacity {
        score += 20.0 + 25.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    // Mild preference to spread across bins when mean residual is high
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

