        }
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size ;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress) ;
            }
        }
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 && progress > 0.6 {
            score += 10.0 * progress ;
        }
        if item_frac > 0.5 && progress < 0.4 {
            score -= 6.0 * (0.4 - progress) / 0.4 ;
        }
        // mutation: fresh-bin leftover dead-space check — penalize fresh bins whose leftover will strand small space
        let fresh_frac = fresh_left as f64 / bin_capacity as f64 ;
        if next_item_size > 0 && fresh_left > next_item_size && fresh_frac < 0.12 {
            score += 18.0 * (0.12 - fresh_frac) / 0.12 ;
        }
        // mutation: allow fresh bin when open bins' residuals are all just below next item (collective miss)
        if next_item_size > 0 && mean_residual < next_item_size as f64 && open_bins_count >= 3 {
            score -= 12.0 * (1.0 - progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual modulo small divisors.
    // Residuals that are "nice" (small, or exactly matching common item sizes)
    // are more valuable than awkward mid-range dead space.
    let pr = post_residual;
    let nice = |r: u32| -> bool {
        r == 0 || r >= 40 || (r <= 10)
    };
    if nice(pr) {
        score -= 6.0;
    } else if pr % 10 == 0 {
        score -= 3.0;
    } else if pr % 5 == 0 {
        score -= 1.5;
    } else {
        // awkward residual: penalize non-multiples of 5 more strongly
        score += 2.0 + ((pr % 5) as f64);
    }

    // Integer-division threshold: can the NEXT item also fit in the leftover?
    if next_item_size > 0 && next_item_size <= pr {
        // lookahead fit: reward, scaled by how tight the pair packing is
        let pair_waste = (pr - next_item_size) as f64;
        score -= 8.0 - 0.1 * pair_waste;
        if (next_item_size + item_size) % 10 == 0 {
            score -= 2.0; // exact decade pairing
        }
    } else if next_item_size > pr {
        // leftover can't take next item: dead-space risk grows with progress
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 3.0 + 4.0 * progress;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // current fit is terrible (large post_residual means item barely dented it,
    // or no open bin fits well). Penalize new bin by mean_residual slack.
    if bin_residual == bin_capacity {
        let mean_r = if mean_residual.is_finite() { mean_residual } else { 0.0 };
        let mut nb = 25.0 + 0.3 * open_bins_count as f64;
        // reward new bin if existing fit leaves a very awkward residual
        if !nice(pr) && pr % 5 != 0 {
            nb -= 8.0;
        }
        // if mean residual is small, open bins are nearly full anyway
        if mean_r < 15.0 {
            nb -= 5.0;
        }
        score += nb;
    }

    // Prefer tighter fits overall (waste-based quadratic penalty).
    score += 0.02 * (pr as f64) * (pr as f64) / 100.0;

    // Slight preference for balancing bin fullness across the fleet.
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * diff;

    score
}

