    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item + 20 {
        // gap too small for likely future items -> dead space penalty
        score += (1.0 + 20.0 - post_residual as f64) * 4.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0; // near-perfect fit, gap still usable for small items
    }

    // Reward using bins that are the only fitting option (avoid opening new bins needlessly)
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing ones;
    // penalize opening a new bin (empty-bin candidate has bin_residual == bin_capacity).
    let pressure = (open_bins_count as f64) / (1.0 + (total_items as f64).max(1.0) / 50.0);
    if bin_residual == bin_capacity {
        score += 25.0 + 10.0 * pressure;
    } else {
        score -= 5.0 + 3.0 * pressure.min(5.0);
    }

    // Lookahead coupling: if next item fits exactly in the post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 5.0 {
            score -= 20.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // next item won't fit here anyway; slight penalty for leaving gap
        score += 3.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates below mean (tighter bins)
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res).min(30.0) * 0.3;
    } else {
        score += (res - mean_residual).min(30.0) * 0.15;
    }

    // Progress coupling: later in the stream, be slightly more conservative with new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

