        if post_residual > 0 && next_item_size > post_residual && post_residual < 20 {
            score += 12.0;
        }
    } else {
        // Last item: strongly prefer tightest fit
        score -= 30.0;
    }

    // Prefer bins with residual below mean residual (denser bins first)
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0 * (res_f - mean_residual) / bin_capacity as f64;
    }

    // Time horizon: early in stream, encourage opening new bins for large items
    let progress = step_index as f64 / (total_items.max(1) as f64);
