        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual).abs() <= 3.0 {
            score -= 9.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 && progress > 0.6 {
            score += 10.0 * progress;
        }
        if item_frac > 0.5 && progress < 0.4 {
            score -= 6.0 * (0.4 - progress) / 0.4;
        }
    }

    // Late in the stream, consolidate: prefer tightest fits even more.
    score -= progress * 0.3 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling: reward small post_residual, more strongly as stream progresses
    let tight = 1.0 - pr / cap;
    score -= 40.0 * tight * tight * (0.5 + progress);

    // Penalize large dead space quadratically
    let waste = pr / cap;
    score += 30.0 * waste * waste * waste;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 15.0 * (1.0 - slack * slack);
        } else {
            score += 10.0;
        }
    }

    // Prefer filling bins when many bins are open (consolidation)
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - waste);

    // Mild alignment with mean residual: avoid bins far from mean
    let dev = (pr - mean_residual).abs() / cap;
    score += 8.0 * dev * dev;

    // Slight preference for opening new bins early (cheap), costly later
    score += 5.0 * progress * (1.0 - tight);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) exponentially.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fill: extremely attractive.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Penalize dead space too small for the next item (waste).
    if post_residual > 0 && next_item_size > 0 {
        let waste = post_residual as f64;
        let usable = next_item_size as f64;
        if waste < usable {
            score += 6.0 * (usable - waste);
            // Extra penalty when waste is small and hard to ever use.
            if waste < 10.0 {
                score += 10.0 * (1.0 - waste / 10.0);
            }
        }
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            let gap = (post_residual - next_item_size) as f64;
            score -= 5.0 * (1.0 - gap / (bin_capacity as f64));
            // Chainable: post residual exactly matches next item (perfect two-step).
            if gap == 0.0 {
                score -= 40.0;
            }
            // Post residual can host next item twice (chainable further).
            if next_item_size > 1 && post_residual >= 2 * next_item_size {
                score -= 6.0;
                if post_residual % next_item_size == 0 {
                    score -= 6.0;
                }
            }
            // Headroom close to mean residual => likely reusable later.
            if (gap - mean_residual).abs() <= 3.0 {
                score -= 7.0;
            }
        } else {
            score += 3.0;
            let miss = next_item_size - post_residual;
            if miss <= 2 {
                score -= 12.0 * (1.0 - progress(step_index, total_items));
            }
            if post_residual < 3 {
                score -= 200.0; // near-perfect fill even though next item misses
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Time horizon: late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Global state coupling: many open bins with high mean residual => prefer
    // filling existing bins rather than spreading.
    if open_bins_count > 0 {
        let spread = (mean_residual - bin_residual as f64).abs();
        score += 0.05 * spread;
        score -= 0.02 * (open_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64);
    }

    // Small residual band: slightly discourage leaving awkward mid-size gaps
    // that few item sizes can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 * (1.0 - progress);
    } else if post_residual >= 10 && post_residual < 20 {
        score += 4.0;
    }

    // New-bin candidate logic.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // Default: new bin is worse than a decent existing fit.
        score += 20.0 - 25.0 * pressure;
        // Late stream: opening a fresh bin is even less attractive.
        score += 10.0 * progress;

        let fresh_left = bin_capacity.saturating_sub(item_size);
        let item_frac = item_size as f64 / bin_capacity as f64;

        // Fresh bin attractive when leftover exactly matches next item.
        if next_item_size > 0 && fresh_left == next_item_size {
            score -= 45.0;
        }
        // Fresh bin attractive with big items leaving large usable leftover.
        if item_frac > 0.5 && progress < 0.4 {
            score -= 8.0 * (0.4 - progress) / 0.4;
        }
        if item_frac > 0.7 {
            score -= 10.0 * (item_frac - 0.7) / 0.3;
        }
        // Fresh bin unattractive when leftover is tiny dead space.
        if next_item_size > 0 && fresh_left < next_item_size && fresh_left < 8 {
            score += 35.0;
        }
        if fresh_left <= 2 {
            score -= 20.0 * (1.0 - progress);
        }
        // When open bins are numerous with small residuals, fresh bin is bad.
        if open_bins_count > 6 && mean_residual < 15.0 && progress > 0.5 {
            score += 15.0;
        }
        // When many open bins can still host next item, avoid fresh bin.
        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 && progress > 0.6 {
            score += 12.0 * progress;
        }
        // Fresh bin with leftover matching mean residual is reusable.
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size;
            if (tail as f64 - mean_residual).abs() <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
            if tail <= 3 {
                score -= 12.0 * (1.0 - progress);
            }
        }
        // Fresh bin with chainable leftover (multiple of next item).
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
