        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 && progress > 0.6 {
            score += 10.0 * progress ;
        }
        // mutation: fresh bin attractive early with big items (large usable leftover)
        if item_frac > 0.5 && progress < 0.4 {
            score -= 6.0 * (0.4 - progress) / 0.4 ;
        }
        // mutation: fresh bin more attractive when mean residual is dead-space heavy (unusable)
        if next_item_size > 0 && mean_residual > 0.0 && mean_residual < next_item_size as f64 * 0.5 && open_bins_count > 3 {
            score -= 8.0 * (1.0 - progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo buckets on capacity
    let pr = post_residual;
    let class = (pr % 10) as f64;
    score += class * 0.35; // prefer residuals that align to decile classes

    // Reward tight fits: post_residual small relative to capacity
    let tightness = 1.0 - (pr as f64) / cap;
    score -= tightness * tightness * 25.0;

    // Penalize dead space that nothing (min size 1, typical 10+) can use
    if pr > 0 && pr < 10 {
        score += 60.0; // unusable sliver
    }

    // Coupling with lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 80.0;
        } else if next_item_size <= pr {
            let leftover = pr - next_item_size;
            score -= 30.0 - (leftover as f64) * 0.4;
        } else {
            // next item won't fit here; slight penalty for hoarding space
            score += 8.0;
        }
        // harmonic class match between next item and post residual (mod 10)
        if pr >= next_item_size && ((pr - next_item_size) % 10) == 0 {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize mildly so we prefer reusing bins unless fit is bad
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64) * 2.0;
        // but if current bin would leave terrible residual, opening fresh is fine
        if post_residual > 0 && post_residual < 15 {
            score -= 55.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below mean (compact packing)
    let dev = mean_residual - (bin_residual as f64);
    score += dev * 0.25;

    // Stream progression: late in stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= tightness * 15.0 * progress;

    // Integer division threshold: residual / item ratio
    if item_size > 0 {
        let ratio = pr / item_size;
        score += (ratio as f64) * 3.0;
    }

    score
}

