pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: prefer tight fits (low post_residual already does this), but add
    // aggressive 2-step lookahead coupling.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward when the NEXT item exactly fills or nearly fills the post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect 2-item completion: strongly favor this bin.
            score -= 40.0 + 30.0 * (1.0 - progress);
        } else if next_item_size <= post_residual {
            // Next item still fits: moderate reward, scaled by how snugly.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 5.0 + 25.0 * snug;
        } else {
            // Next item cannot use this bin's remainder: penalize dead space,
            // worse when the leftover is small-but-unusable.
            let waste = (next_item_size - post_residual) as f64;
            score += 3.0 + waste * 0.15;
        }
    }

    // Compare post_residual against mean residual: leaving a residual far below
    // the mean means we are consuming scarce space; slightly penalize.
    score += 0.10 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using
    // it over opening a new bin (unless post_residual is large and a fresh bin
    // would be better for future big items).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is attractive when the item
    // would leave a large awkward residual in an existing bin, or when many bins
    // are open and mean residual is already high.
    if bin_residual == bin_capacity {
        // Base cost of a new bin, discounted late in the stream.
        score = (bin_capacity - item_size) as f64 + 8.0 - 6.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 4.0; // fresh bin also serves the next item
        }
    }

    // Mild pressure against hoarding many open bins with large residuals.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
