            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 2.0 * miss;
            if post_residual < 3 {
                score -= 400.0;
            }
            if miss <= 2 {
                score -= 18.0 * (1.0 - progress);
            }
            if miss <= 6 && fitting_bins_count <= 2 {
                score -= 5.0;
            }
            if post_residual < 25 {
                score += 15.0;
            }
