    }

    // Dead space too small to be useful later.
    if post_residual > 0 {
        let usable = if next_item_size > 0 { next_item_size as f64 } else { 1.0 };
        if (post_residual as f64) < usable {
            score += 6.0 * (usable - post_residual as f64);
        }
        if post_residual < 10 {
            score += 45.0;
        } else if post_residual < 20 {
            score += 10.0;
        }
    }

    // Fill ratio reward: prefer bins where the item fills a large share of the residual.
    let fill = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 20.0 * fill;

    // Gap-based scarcity coupling.
    let gap = (post_residual as f64 - item_size as f64).max(0.0);
    if gap > 0.0 {
        let scarcity = if fitting_bins_count <= 2 { 0.6 } else if fitting_bins_count <= 4 { 0.3 } else { 0.2 };
        let gap_ratio = gap / (item_size as f64).max(1.0);
        score += scarcity * gap + 18.0 * gap_ratio.min(2.0);
        if gap < mean_residual {
            let fillable = next_item_size > 0 && gap >= next_item_size as f64;
            let w = if fillable { 0.2 } else { 0.6 };
            score += w * (mean_residual - gap);
        }
        if next_item_size > 0 && (gap as u32) == next_item_size {
            score -= 20.0;
        }
    }

    score -= (mean_residual - post_residual as f64) * 0.6;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }
    if fitting_bins_count == 2 && post_residual < bin_capacity / 3 {
        score -= 8.0;
    }

    // Time horizon: late in the stream, prefer consolidation.
    score -= 6.0 * progress * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Global state coupling.
    if open_bins_count > 0 {
        let spread = (mean_residual - bin_residual as f64).abs();
        score += 0.05 * spread;
        score -= 0.02 * (open_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64);
    }
    if post_residual <= 5 && open_bins_count > 6 {
        score += 25.0 * (1.0 - progress);
    }

    // NEW-BIN CANDIDATE: default unattractive, but open when no open bin fits well
    // or when a fresh bin leaves a perfectly chainable leftover.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 180.0 - 60.0 * progress + 0.15 * open_bins_count as f64 - 25.0 * pressure;
