        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3;
        }
        let fresh_left = bin_capacity - item_size;
        if next_item_size > 0 {
            if fresh_left == next_item_size {
                score -= 30.0;
            }
            if fresh_left >= next_item_size {
                let tail = fresh_left - next_item_size;
                if tail <= 3 {
                    score -= 14.0 * (1.0 - progress);
                }
                if (tail as f64 - mean_residual).abs() <= 3.0 {
                    score -= 9.0 * (1.0 - progress);
                }
                if next_item_size > 1 && tail >= 2 * next_item_size && tail % next_item_size == 0 {
                    score -= 6.0 * (1.0 - progress);
                }
            } else if fresh_left < 8 {
                score += 35.0;
            }
        }
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress);
        }
        if open_bins_count <= 4 && progress < 0.3 {
            score += 25.0;
        }
        if mean_residual < 15.0 && progress > 0.5 {
            score -= 15.0;
        }
        if next_item_size > 0 && fitting_bins_count <= 2 && mean_residual < next_item_size as f64 {
            score -= 18.0 * (1.0 - progress);
        }
        if item_frac > 0.5 && progress < 0.4 {
            score -= 6.0 * (0.4 - progress) / 0.4;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 && progress > 0.6 {
            score += 10.0 * progress;
        }
    }

    score
}

