pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * bin_capacity as f64;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // hard-to-fill zone
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly or well,
    // strongly favor this bin (chaining placements).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score -= 20.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty for wasting the chain potential
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // When many bins can fit the item, prefer bins with smaller residuals (best-fit bias).
    if fitting_bins_count > 1 {
        score += 0.5 * (bin_residual as f64 - mean_residual).max(-20.0).min(20.0);
    }

    // Global state: penalize creating new bins when many open bins have large mean residual.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Opening a new bin is penalized more when open bins have plenty of room.
        let room_pressure = mean_residual / bin_capacity as f64;
        score += 35.0 + 40.0 * room_pressure - 10.0 * progress;
        // But if this bin is the only fitting option handled above, the last-chance bonus
        // already favors open bins; ensure new bin isn't chosen on tight fits alone.
        if post_residual == 0 {
            score += 55.0; // never open a fresh bin for a perfect fit elsewhere
        }
    } else {
        // Slight reward for using open bins as they accumulate (consolidation).
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Time horizon: early in the stream, be slightly more willing to spread items
    // (keeps flexibility); late in the stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 3.0 * (bin_residual as f64 / bin_capacity as f64);

    score
}

