            score -= 10.0 ;
        }
        if next_item_size > 1 && post_residual > next_item_size + 1 && post_residual <= next_item_size + 10 {
            score -= 4.0 * (1.0 - progress) ;
        }
        // mutation: prefer bins whose post-fit residual is a multiple of next item (chainable)
        if next_item_size > 1 && post_residual % next_item_size == 0 && post_residual >= 2 * next_item_size && post_residual <= 3 * next_item_size {
            score -= 5.0 * (1.0 - progress) ;
        }
        // mutation: penalize residual just below a common small size late (dead space)
        if post_residual >= 5 && post_residual <= 9 && progress > 0.5 && next_item_size > post_residual {
            score += 8.0 * progress ;
        }
        // mutation: dead-space ratio term — residual that can never host the mean-sized item
        if next_item_size > 0 && post_residual < next_item_size {
            let dead_ratio = post_residual as f64 / (next_item_size as f64) . max (1.0) ;
            score += 10.0 * (1.0 - dead_ratio) * progress ;
        }
        // mutation: reward near-perfect fills more strongly when few bins remain open
        if post_residual <= 2 && fitting_bins_count <= 3 {
            score -= 6.0 + 8.0 * (1.0 - progress) ;
        }
        // mutation: mildly discourage leaving residuals that match no plausible future size band
        if post_residual > 12 && post_residual < 20 && next_item_size > post_residual + 4 {
            score += 6.0 * progress ;
        }
    }
    // NEW-BIN CANDIDATE
    if bin_residual == bin_capacity {
        let big_next = next_item_size as f64 / bin_capacity as f64 ;
        score += 180.0 - 60.0 * progress + 0.15 * open_bins_count as f64 - 25.0 * big_next . max (0.0) ;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0 ;
        }
        if open_bins_count <= 4 && progress < 0.3 {
            score += 25.0 ;
        }
        if mean_residual < 15.0 && progress > 0.5 {
            score -= 15.0 ;
        }
        let item_frac = item_size as f64 / bin_capacity as f64 ;
        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3 ;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3 ;
        }
        let fresh_left = bin_capacity - item_size ;
        if next_item_size > 0 && fresh_left == next_item_size {
            score -= 30.0 ;
        }
        if open_bins_count > 6 && mean_residual > 0.4 * bin_capacity as f64 {
            score += 20.0 ;
        }
        if next_item_size > 0 && fresh_left < next_item_size && fresh_left < 8 {
            score += 35.0 ;
        }
        if next_item_size > 0 && fitting_bins_count <= 2 && mean_residual < next_item_size as f64 {
            score -= 18.0 * (1.0 - progress) ;
        }
        if open_bins_count > 8 && mean_residual > next_item_size as f64 + 10.0 {
            score += 12.0 ;
        }
        if item_frac > 0.6 && next_item_size > 0 && fresh_left >= next_item_size {
            score -= 8.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size ;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress) ;
            }
        }
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        // mutation: discourage fresh bins late when any open bin can host next item comfortably
        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 && progress > 0.6 {
            score += 10.0 * progress ;
        }
        // mutation: fresh bin attractive early with big items (large usable leftover)
        if item_frac > 0.5 && progress < 0.4 {
            score -= 6.0 * (0.4 - progress) / 0.4 ;
        }
        // mutation: fresh bin must earn its keep — penalize when leftover would be dead space
        if next_item_size > 0 && fresh_left < next_item_size {
            score += 0.5 * (fresh_left as f64) + 8.0 ;
        }
        // mutation: favor fresh bins whose leftover equals a multiple of the mean residual (chainable)
        if mean_residual > 1.0 && (fresh_left as f64) % mean_residual . max (1.0) < 2.0 && fresh_left > 10 {
            score -= 7.0 * (1.0 - progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;

    // Smooth non-linear coupling: quadratic penalty on post_residual, modulated by progress.
    let pr_norm = pr / cap;
    score += 6.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    score -= 4.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * progress;

    // Coupling with mean residual: prefer bins whose residual differs from mean
    // (place into bins that are either very full or leave balanced space).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev * dev - 1.5 * dev * (0.5 + progress);

    // Lookahead: if next item fits exactly in the post residual, reward strongly (smoothly).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs() / cap;
        score -= 5.0 * (1.0 - gap) * (1.0 - gap);
    }

    // Last-chance bin: strong smooth reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening a new bin, softly decreasing with progress
    // and with how many bins are open (consolidation pressure).
    if bin_residual == bin_capacity {
        score += 25.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
        // Allow opening when many bins are nearly full (mean residual small).
        score -= 20.0 * (1.0 - mean_residual / cap).max(0.0);
    }

    score
}

