pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post_residual: classify dead space into buckets.
    let cap = bin_capacity as f64;
    let pr = post_residual as u32;
    // class width via integer division: 0..10, 10..25, 25..50, 50..100
    let class = if pr == 0 { 0u32 }
        else if pr < 10 { 1 }
        else if pr < 25 { 2 }
        else if pr < 50 { 3 }
        else { 4 };

    // Reward tight fits strongly (small post_residual classes).
    score -= match class {
        0 => 60.0,
        1 => 35.0,
        2 => 15.0,
        3 => 5.0,
        _ => 0.0,
    };

    // Penalize dead space that the next item cannot use: harmonic compatibility.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (nx as u32) <= pr {
            // Next item fits into the leftover: reward proportional to how well it nests.
            let waste_after = (pr as f64) - nx;
            score -= (1.0 - waste_after / cap) * 25.0;
        } else {
            // Dead space unusable by next item: penalize by size of the gap.
            score += ((pr as f64) / cap) * 20.0;
        }
        // Perfect pairing: next item exactly fills the bin.
        if next_item_size == pr {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But allow new bin when few fitting bins and mean residual is small.
        score -= (fitting_bins_count as f64) * 6.0;
        score += (mean_residual / cap) * 30.0;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight preference for fuller bins overall (compactness pressure).
    score -= (1.0 - (bin_residual as f64) / cap) * 10.0;

    // Progress-based tie-break: later in stream, prefer consolidating.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64).abs() * 0.1;

    score
}

