pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual >= 10 && post_residual <= 15 {
        score += 18.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Reward tight fits relative to bin capacity.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * tightness;

    // Pressure from number of open bins: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // Mean residual coupling: placing into a bin far below mean residual is less attractive
    // (keeps large residuals available for large future items).
    if (bin_residual as f64) < mean_residual {
        score += 6.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    }
    // Penalize if next item cannot fit into post residual but this bin could have held both.
    if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual - item_size {
        // same condition trivially; instead check next fits better elsewhere
    }
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate: penalize moderately so we only open new bins when open bins give bad fits.
    if bin_residual == bin_capacity {
        score += 45.0 + 3.0 * open_bins_count as f64;
        // But if no open bin fits well (many fitting bins means competition, keep new bin costly)
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
    }

    // Stream progression: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

