        if post_residual as f64 >= 2.0 * mean_residual && post_residual > 20 {
            score -= 5.0 ;
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let headroom = post_residual - next_item_size ;
            if (headroom as f64 - mean_residual) . abs () <= 3.0 {
                score -= 7.0 ;
            }
            if (headroom as f64 - mean_residual) . abs () <= 1.0 && fitting_bins_count <= 3 {
                score -= 5.0 * (1.0 - progress) ;
            }
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0 ;
        }
        if next_item_size > 1 && post_residual > next_item_size + 1 && post_residual <= next_item_size + 10 {
            score -= 4.0 * (1.0 - progress) ;
        }
        if next_item_size > 1 && post_residual % next_item_size == 0 && post_residual >= 2 * next_item_size && post_residual <= 3 * next_item_size {
            score -= 5.0 * (1.0 - progress) ;
        }
        if post_residual >= 5 && post_residual <= 9 && progress > 0.5 && next_item_size > post_residual {
            score += 8.0 * progress ;
        }
        // mutation: dead-space ratio guard — penalize bins whose post-fit residual is a small dead fraction
        if next_item_size > 0 && post_residual > next_item_size {
            let dead_ratio = (post_residual - next_item_size) as f64 / bin_capacity as f64 ;
            if dead_ratio < 0.05 {
                score -= 9.0 * (1.0 - dead_ratio * 20.0) * (1.0 - progress) ;
            }
        }
    }
    if bin_residual == bin_capacity {
        let big_next = next_item_size as f64 / bin_capacity as f64 ;
        score += 180.0 - 60.0 * progress + 0.15 * open_bins_count as f64 - 25.0 * big_next . max (0.0) ;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0 ;
        }
        if open_bins_count <= 4 && progress < 0.3 {
            score += 25.0 ;
        }
        if mean_residual < 15.0 && progress > 0.5 {
            score -= 15.0 ;
        }
        let item_frac = item_size as f64 / bin_capacity as f64 ;
        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3 ;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3 ;
        }
        let fresh_left = bin_capacity - item_size ;
        if next_item_size > 0 && fresh_left == next_item_size {
            score -= 30.0 ;
        }
        if open_bins_count > 6 && mean_residual > 0.4 * bin_capacity as f64 {
            score += 20.0 ;
        }
        if next_item_size > 0 && fresh_left < next_item_size && fresh_left < 8 {
            score += 35.0 ;
        }
        if next_item_size > 0 && fitting_bins_count <= 2 && mean_residual < next_item_size as f64 {
            score -= 18.0 * (1.0 - progress) ;
        }
        if open_bins_count > 8 && mean_residual > next_item_size as f64 + 10.0 {
            score += 12.0 ;
        }
        if item_frac > 0.6 && next_item_size > 0 && fresh_left >= next_item_size {
            score -= 8.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size ;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress) ;
            }
        }
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 && progress > 0.6 {
            score += 10.0 * progress ;
        }
        if item_frac > 0.5 && progress < 0.4 {
            score -= 6.0 * (0.4 - progress) / 0.4 ;
        }
        // mutation: fresh-bin leftover dead-space ratio — reject fresh bins whose leftover is a tiny unusable sliver
        if next_item_size > 0 && fresh_left < next_item_size {
            let sliver = fresh_left as f64 / bin_capacity as f64 ;
            if sliver < 0.04 {
                score += 30.0 * (1.0 - sliver * 25.0) ;
            }
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect/near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.8 * gap;
        if post_residual == next_item_size {
            score -= 300.0;
        }
        // Penalize leaving residual too small for next item (dead space).
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Compare against mean residual across open bins.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Penalize opening a new bin when decent fits exist, unless item is huge
    // relative to all residuals (poor fit everywhere).
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count > 0 {
            score += 60.0 * (1.0 - tightness);
        }
        // New bin is attractive when the item is large and residuals are small.
        score -= 40.0 * tightness * tightness;
    }

    // Slight preference to fill older bins (reduce open bin count pressure).
    if open_bins_count > 4 {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    // Early-stream: be a bit greedy toward tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    if post_residual == 0 {
        score -= 1000.0 ;
