        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size ;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress) ;
            }
        }
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 && progress > 0.6 {
            score += 10.0 * progress ;
        }
        if item_frac > 0.5 && progress < 0.4 {
            score -= 6.0 * (0.4 - progress) / 0.4 ;
        }
        // mutation: penalize fresh bins when a single open bin can host both this item and the next
        if next_item_size > 0 && fitting_bins_count >= 1 && bin_capacity >= item_size + next_item_size && progress > 0.4 {
            score += 14.0 * progress ;
        }
        // mutation: extra penalty for small fresh-bin leftovers that likely become dead space
        if fresh_left < 12 && fresh_left > 2 {
            score += 6.0 + 0.5 * fresh_left as f64 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squash post_residual toward zero non-linearly.
    let post = post_residual as f64;
    let tight = 1.0 - (post / bin_capacity as f64).powi(3);
    score -= tight * 30.0;

    // Penalize dead space that is too small for the smallest possible item (1..100 now).
    if post > 0 && post < 5.0 {
        score += 60.0;
    }

    // Lookahead: penalize if the next item cannot fit the post-residual.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 8.0 + (next_item_size as f64 - post) * 0.25;
        } else {
            // Bonus when next item exactly exploits leftover space.
            let slack = post - next_item_size as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        }
    }

    // Last chance: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Global pressure: many open bins with high mean residual -> discourage spreading.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
    score += pressure * 0.15;

    // Time horizon: early in stream, be conservative about creating tiny residuals;
    // late in stream, exploit remaining space aggressively.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - t) * post * 0.3;
    score -= t * 10.0;

    // New-bin candidate: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let avg_waste = mean_residual - post;
        score = 95.0 + avg_waste * 0.4 - (fitting_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Perfect fill: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score + 60.0 * progress; // new-bin candidate must never beat this
    }

    // Tightness reward (exponential).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: exact match with next item is gold.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0 - 30.0 * progress;
        } else if next_item_size <= post_residual {
            let after_next = post_residual - next_item_size;
            let two_step_waste = after_next as f64;
            if two_step_waste >= 10.0 {
                score -= 300.0 - 2.0 * two_step_waste;
            } else {
                score -= 80.0 + 1.5 * (10.0 - two_step_waste);
            }
            if after_next >= 3 {
                score -= (2.0 + 2.0 * progress) * (after_next as f64).min(15.0);
            }
            // Chainable: residual can host next item twice.
            if next_item_size > 1 && after_next >= next_item_size {
                score -= 6.0 + 0.2 * ((after_next / next_item_size) as f64);
                if after_next % next_item_size == 0 {
                    score -= 8.0 * (1.0 - progress);
                }
            }
            // Residual close to mean residual of other bins => keeps pool usable.
            if (after_next as f64 - mean_residual).abs() <= 4.0 {
                score -= 6.0 * (1.0 - progress);
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 2.0 * miss;
            if post_residual < 3 {
                score -= 400.0; // tiny dead residual: great to bury here
            }
            if miss <= 2 {
                score -= 18.0 * (1.0 - progress);
            }
            if miss <= 6 && fitting_bins_count <= 2 {
                score -= 5.0;
            }
            if post_residual >= 8 && post_residual <= 16 {
                score += 10.0 * (1.0 - progress); // mid residual without next fit: mild dead space
            }
        }
    }

    // Penalize residual too small to be useful.
    if next_item_size > 0 && post_residual < next_item_size {
        let unusable_ratio = post_residual as f64 / (next_item_size as f64).max(1.0);
        score += 0.4 * post_residual as f64 + 12.0 * (1.0 - unusable_ratio);
        if next_item_size - post_residual <= 4 {
            score += 20.0 * (1.0 - progress);
        }
    }

    // Small residuals late are dead space unless burying tiny items.
    if post_residual <= 5 && open_bins_count > 6 {
        score += 25.0 * (1.0 - progress);
    }
    if post_residual < 10 {
        score += 45.0;
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Gap-based scarcity: penalize leaving a gap larger than item but unusable.
    let gap = (post_residual as f64 - item_size as f64).max(0.0);
    if gap > 0.0 {
        let gap_ratio = gap / (item_size as f64).max(1.0);
        let scarcity = if fitting_bins_count <= 2 { 0.6 } else if fitting_bins_count <= 4 { 0.3 } else { 0.2 };
        score += scarcity * gap + 18.0 * gap_ratio.min(2.0);
        if next_item_size > 0 && (gap as u32) == next_item_size {
            score -= 20.0;
        }
        if next_item_size > 1 && (gap as u32) == 2 * next_item_size {
            score -= 12.0;
        }
    }

    // Fill ratio reward.
    let fill = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 20.0 * fill;

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }
    if fitting_bins_count == 2 && post_residual < bin_capacity / 3 {
        score -= 8.0;
    }

    // Mean-residual coupling: keep pool homogeneous.
    score -= (mean_residual - post_residual as f64) * 0.6;
    if open_bins_count > 0 {
        let spread = (mean_residual - bin_residual as f64).abs();
        score += 0.05 * spread;
    }

    // Consolidation late.
    score -= 6.0 * progress * tightness;

    // NEW-BIN CANDIDATE.
    if bin_residual == bin_capacity {
        let fresh_left = bin_capacity - item_size;
        let item_frac = item_size as f64 / bin_capacity as f64;
