    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: waste left behind, with non-linear penalty on awkward residuals
    let mut score = pr * (1.0 + 0.8 * prn * prn);

    // Smooth stream-progress coupling: later in the stream, waste is more costly
    score += 30.0 * t * prn * prn;

    // Penalize residuals that neither fit the next item nor are near zero
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 15.0 * gap * (1.0 + t);
        let reward = if pr >= next_item_size as f64 { (pr - next_item_size as f64).min(20.0) } else { 0.0 };
        score -= 0.5 * reward;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - prn);
    }

    // Encourage consolidation when many bins are open
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - prn);

    // Favor bins tighter than the mean residual
    score += 5.0 * (mean_residual - pr) / cap;

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (fitting_bins_count as f64);
    }

    score
}

