}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: prefer residuals in "useful" classes.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is best
    } else {
        // Modulo classes on post_residual (capacity 100 => classes of 10)
        let class = pr % 10;
        // Residuals that are multiples of 10 pair well with common item sizes
        let class_bonus = if class == 0 { 18.0 } else if class <= 2 || class >= 8 { 6.0 } else { 0.0 };
        score -= class_bonus;

        // Dead-space penalty: residual too small for any plausible item (1..=100)
        if pr < 10 {
            score += 35.0; // nearly unusable sliver
        } else if pr < 25 {
            score += 12.0;
        }

        // Integer-division threshold: can post_residual fit the lookahead item?
        if next_item_size > 0 {
            if next_item_size <= pr {
                score -= 22.0 + (pr - next_item_size) as f64 * 0.15;
            } else {
                score += 10.0; // lookahead won't fit here
            }
            // Harmonic coupling: next item shares a divisor/modulo relation with pr
            if pr % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            // Last item: prefer zero waste strongly
            score += pr as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer filling bins when many bins are open (consolidation pressure)
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score -= pressure * (bin_capacity - post_residual) as f64 * 0.02;

    // Progress-scaled tightness: later in stream, waste matters more
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += post_residual as f64 * (0.3 + 0.5 * progress);

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
