    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold any item
    // (min item size 1, but "practically unusable" gaps are tiny) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 25.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Reward tight fits (perfect fill gets a big discount).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual {
            // residual too small for next item -> dead space for lookahead
            score += 15.0 * (post_residual as f64 / 100.0);
        } else {
            score -= 8.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when the fit here is bad (large dead space).
    if bin_residual == bin_capacity {
        let dead = (bin_capacity - item_size) as f64;
        score = 20.0 + dead * 0.9;
        if fitting_bins_count == 0 {
            score -= 80.0; // must open a new bin anyway
        }
        if next_item_size > 0 && next_item_size <= dead as u32 {
            score -= 10.0;
        }
    }

    // Mild stream-progression adaptation: later in stream, conserve bins more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    // Mean-residual coupling: prefer bins whose residual deviates favorably from mean.
    score += 0.15 * (post_residual as f64 - mean_residual);

    score
}

