pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fits (small post_residual) are good.
    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Aggressive 2-step lookahead: if next item fits exactly into post_residual,
    // this placement creates a perfect two-item packing.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score -= 20.0;
        } else if post_residual < next_item_size && post_residual >= 1 {
            // Dead space that the next item cannot use: penalize proportionally,
            // especially when the leftover is small and hard to reuse.
            let dead = post_residual as f64;
            score += dead * 0.5;
        }
        // If next item cannot fit in ANY reasonable residual, prefer leaving
        // large usable residuals rather than fragmenting.
        if post_residual < next_item_size && post_residual > 0 && post_residual < 20 {
            score += 15.0;
        }
    } else {
        // Last item: pure tight-fit preference.
        score -= 10.0;
    }

    // Relative-to-mean coupling: bins with residual far below the mean are
    // already fragmented; placing here if it fits well is fine, but avoid
    // dumping items into bins whose residual is much larger than needed
    // when other bins could take the item.
    let mean_diff = bin_residual as f64 - mean_residual;
    if mean_diff > 30.0 {
        // This bin is unusually empty; using it wastes its flexibility.
        score += 5.0;
    } else if mean_diff < -30.0 {
        // This bin is nearly full already; finishing it off is good.
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 30.0;
        if post_residual > 40 {
            // Poor fit in the only bin; new bin may still be better.
            score += 25.0;
        }
    }

    // New-bin candidate handling: an empty bin should only win when the fit
    // into open bins is bad. Give the empty bin a moderate baseline so that
    // any decent existing fit beats it.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.6 + 30.0; // ~90 baseline
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 10.0;
        }
        // Early in the stream, opening bins is cheap; late, prefer filling.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
        // If many bins are open, discourage opening more.
        score += open_bins_count as f64 * 1.5;
    }

    // Mild penalty for leaving residuals in the awkward 20-40 zone that few
    // items (sizes 10..80) can use efficiently.
    if post_residual >= 20 && post_residual <= 40 {
        score += 6.0;
    }

    score
}

