    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space relative to capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_frac * waste_frac;

    // Penalize consuming large-residual bins (keep big bins for big future items).
    score -= 0.15 * bin_residual as f64;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin for a mediocre fit.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly (or well) into the post residual,
    // reward this placement strongly (chained packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain = post_residual - next_item_size;
            score -= 25.0 * (1.0 - chain as f64 / bin_capacity as f64);
        } else {
            // Next item cannot follow: penalize dead-space creation.
            score += 10.0 * waste_frac;
        }
    }

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing fits are poor. Make the empty-bin score moderate by default.
    if bin_residual == bin_capacity {
        score = 60.0 + 0.5 * mean_residual - 20.0 * waste_frac;
        // Late in the stream, prefer consolidation into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * progress;
        // Many open bins already: discourage opening more.
        score += 2.0 * open_bins_count as f64;
        // If the item is large, a fresh bin is more reasonable.
        score -= 0.2 * item_size as f64;
    }

    // Global residual pressure: when mean residual is high, encourage using
    // up existing space (penalize placements that leave bins underused).
    score -= 0.05 * mean_residual;

    score
}

