pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear coupling: reward small post_residual quadratically (tight fits).
    let tightness = 1.0 - post / cap;
    score -= 20.0 * tightness * tightness * tightness;

    // Penalize residual that is too small to be useful for future items (dead space),
    // with a smooth bell-shaped penalty around unusable residuals.
    let dead = (1.0 - (post / 20.0).exp()) * (post / cap);
    score += 15.0 * dead;

    // Stream-progress coupling: later in the stream, prefer consolidating into
    // existing bins more aggressively (smooth polynomial ramp).
    let ramp = progress * progress * (3.0 - 2.0 * progress);
    score += 10.0 * ramp * (post / cap);

    // New-bin candidate: penalize opening a new bin, more when other bins fit
    // and when many bins are already open.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        let fit_pressure = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 0.0 };
        score += 25.0 + 8.0 * fit_pressure + 2.0 * open_bins_count as f64;
        // Allow new bin late in stream only if it would hold future items well.
        if next_item_size > 0 && post >= next_item_size as f64 {
            score -= 12.0 * (post / cap);
        }
    } else {
        // Reward choosing bins whose residual matches the mean residual (balance).
        score -= 3.0 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / cap));
    }

    // Lookahead: if the next item fits exactly into the resulting residual, reward strongly.
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score -= 10.0 * (1.0 - gap / cap).max(0.0);
    } else {
        // Last item: minimize wasted space absolutely.
        score += 5.0 * (post / cap);
    }

    score
}

