pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual (modulo arithmetic on capacity fractions) ---
    let cap = bin_capacity as f64;
    let pr = post_residual as i64;
    let post_class = pr % 12; // harmonic residue classes of remaining space
    match post_class {
        0 => score -= 30.0,               // perfect fill / exact multiple class
        1..=5 => score += 18.0,           // dead-space band: tiny unusable slivers
        6..=10 => score += 8.0,           // marginal band
        _ => {}                            // 11: usable small pocket, neutral
    }

    // Integer-division thresholds on post_residual relative to capacity quarters
    let quarter = (bin_capacity / 4).max(1);
    if post_residual >= 3 * quarter {
        score -= 12.0; // bin still roomy: good to concentrate load here
    } else if post_residual >= quarter {
        score -= 4.0;
    } else if post_residual > 0 {
        score += 10.0; // bin nearly full but not sealed: mediocre
    } else {
        score -= 40.0; // bin sealed exactly: ideal
    }

    // --- Lookahead coupling: does next_item_size harmonically fit post_residual? ---
    if next_item_size > 0 {
        let nxt = next_item_size as i64;
        if nxt == pr {
            score -= 45.0; // exact pairing: extremely desirable
        } else if nxt < pr {
            let slack = pr - nxt;
            // harmonic check: does leftover slack fall in a good residue class?
            if slack % 12 == 0 {
                score -= 25.0;
            } else if slack <= 5 {
                score += 12.0; // would create dead sliver after next item
            } else {
                score -= 6.0;
            }
        } else {
            // next item cannot fit here; post_residual becomes a waiting pocket.
            // Reward only if pocket is a "harmonic" size likely to be matched later.
            if pr >= 20 && pr % 10 == 0 {
                score -= 8.0;
            } else if pr < 10 {
                score += 14.0; // stranded dead space
            }
        }
    }

    // --- Last-chance bin pressure ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0; // only viable bin: strongly prefer using it over opening new
    } else if fitting_bins_count > 3 {
        score += 3.0 * (fitting_bins_count as f64 - 3.0); // plenty of options, mild de-prioritization of cluttered bins
    }

    // --- Progression-aware load balancing ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev * (1.0 - progress); // early: spread residuals toward mean; late: free-for-all
    score -= 0.05 * open_bins_count as f64 * (post_residual as f64 / cap);

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // base waste of the new bin plus a switch penalty; making it low only
        // when using existing bins would be clearly worse is handled by the
        // last-chance bonus above. Add a modest opening cost.
        score += 25.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && (next_item_size as i64 + item_size as i64) <= bin_capacity as i64 {
            score -= 15.0; // fresh bin can host a clean pair: attractive
        }
    }

    score
}

