pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item are "dead space" — penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Coupling: dead space relative to mean residual across open bins.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.25 * (pr - mean_residual) * (pr / (pr + 20.0));
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit
    // is excellent; encourage closing out nearly-full bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (1.0 - pr / 100.0);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let bad_fit = if bin_residual >= item_size { (bin_residual - item_size) as f64 } else { 100.0 };
        score += 30.0 + 2.0 * open_bins_count as f64 - 0.3 * bad_fit;
        // Late in the stream, reusing bins is cheaper than opening new ones.
        score += 20.0 * progress;
    }

    // Lookahead: favor bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    score
