pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, reward strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fits the post residual
    // (chain packing), or penalize if post residual is awkwardly small
    // relative to the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // next item fills this bin exactly
        } else if post_residual >= next_item_size {
            // next item also fits: good chaining, small residual preferred
            score -= 2.0 * (post_residual as f64 - next_item_size as f64).sqrt();
        } else {
            // post residual too small for next item: dead space penalty
            let waste = post_residual as f64;
            score += 3.0 * (waste / bin_capacity as f64) * (1.0 - waste / next_item_size as f64).max(0.0) * 10.0;
        }
    }

    // Prefer bins whose residual is tight relative to the item (good fit).
    let fit_tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 5.0 * fit_tightness;

    // Relative to mean residual: prefer bins with below-average residual
    // (consolidate space), penalize placing into above-average residual bins.
    score += 0.5 * ((bin_residual as f64) - mean_residual);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        score += 60.0;
        // If lookahead chains well into an existing bin, discourage new bin more.
        if next_item_size > 0 && post_residual == next_item_size {
            score += 500.0;
        }
        // Early in stream, opening bins is cheap; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
