pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio for dynamic horizon effects
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: post_residual near 0 is good, already in base score.
    // Penalize large dead space quadratically beyond a threshold.
    let dead = post_residual as f64;
    if dead > 20.0 {
        score += 0.05 * (dead - 20.0) * (dead - 20.0);
