            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Crowding: many open bins with high mean residual -> prefer reusing
    // existing bins rather than spreading out.
    if open_bins_count > 2 && mean_residual > 30.0 {
        score -= 0.1 * mean_residual.min(60.0);
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless the
