        // future reuse potential of a fresh bin is lower.
        let time_relief = 10.0 * progress;
        // If next item is large, a fresh bin is more useful.
        let lookahead_bonus = if next_item_size > item_size { 5.0 } else { 0.0 };
        score += base_penalty - time_relief - lookahead_bonus;
    }

    // Mild bonus for bins whose residual is close to item size (good fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 4.0 * fill_ratio;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
