            score += 15.0 ;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 && progress > 0.6 {
            score += 10.0 * progress ;
        }
        if item_frac > 0.5 && progress < 0.4 {
            score -= 6.0 * (0.4 - progress) / 0.4 ;
        }
        // mutation: fresh bin more attractive when its leftover is a clean multiple of next item
        if next_item_size > 1 && fresh_left % next_item_size == 0 && fresh_left >= 2 * next_item_size {
            score -= 7.0 * (1.0 - progress) ;
        }
        // mutation: discourage fresh bins when the resulting leftover is unusable dead space
        if next_item_size > 0 && fresh_left < next_item_size && fresh_left > 8 {
            score += 12.0 * progress ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress and residual ratios
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64 / bin_capacity as f64;
    let ir = item_size as f64 / bin_capacity as f64;
    let mean_r = mean_residual / bin_capacity as f64;

    // Smooth polynomial coupling: waste grows super-linearly with post_residual
    let waste_poly = pr * pr * (1.0 + 2.0 * pr) * bin_capacity as f64;
    score += 0.8 * waste_poly;

    // Reward tight fits via smooth interaction of item ratio and post-residual
    score -= 12.0 * ir * (1.0 - pr) * (1.0 - pr);

    // As stream progresses, penalize leaving large residuals more (less time to reuse them)
    let time_pressure = progress * progress;
    score += 6.0 * time_pressure * pr * bin_capacity as f64;

    // Penalize bins far from mean residual unless it's a good fit (smooth coupling)
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 2.0 * dev * dev * (1.0 - ir);

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 5.0 * pr;
    }

    // Lookahead: reward post_residual that still fits the next item, penalize near-misses
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64) >= nr {
            score -= 4.0 * (nr / bin_capacity as f64);
        } else {
            score += 3.0 * (nr - post_residual as f64) / bin_capacity as f64;
        }
    }

    // New-bin candidate: prefer it only when existing bins would waste heavily
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * (0.55 + 0.5 * progress) - 10.0 * ir;
        // Discourage new bins when many are already open and mean residual is large
        score += 0.3 * open_bins_count as f64 + 8.0 * mean_r;
    }

    score
}

