    }
    // Penalize dead space in the awkward middle band (31..49): hard to fill.
    if post_residual > 30 && post_residual < 50 {
        score += 6.0;
    }

    // Tight fit reward: small post_residual relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 10.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 - slack * 0.1;
    } else if next_item_size > post_residual {
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current fit is terrible.
    if bin_residual == bin_capacity {
        let bad_fit = if post_residual > 50 { 1.0 } else { 0.0 };
        score = 30.0 + bad_fit * 20.0 - (open_bins_count as f64) * 0.5;
    }

    // Late in stream, consolidate: penalize spreading across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Tightness reward (kept from parent, sharpened).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Dead-space penalty: residual too small for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead_frac = post_residual as f64 / bin_capacity as f64;
        score += 0.4 * post_residual as f64 + 30.0 * dead_frac + 12.0 * (1.0 - post_residual as f64 / (next_item_size as f64).max(1.0));
        if next_item_size - post_residual <= 4 {
            score += 20.0 * (1.0 - progress);
        }
    }
    // Tiny residuals are dead weight.
    if post_residual > 0 && post_residual < 3 {
        score += 40.0;
    }

    // Lookahead: reward bins whose post_residual hosts the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0 - 30.0 * progress;
        } else if post_residual >= next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next >= 10 {
                score -= 300.0 - 2.0 * after_next as f64;
            } else {
                score -= 80.0 + 1.5 * (10.0 - after_next) as f64;
            }
            // Chainable residual: after_next can host another next item.
            if next_item_size > 1 && after_next >= next_item_size {
                score -= 6.0 + 0.2 * (after_next / next_item_size) as f64;
                if after_next % next_item_size == 0 {
                    score -= 8.0 * (1.0 - progress);
                }
            }
            if after_next < next_item_size && after_next <= 3 {
                score -= 14.0 * (1.0 - progress);
            }
            if (after_next as f64 - mean_residual).abs() <= 4.0 {
                score -= 6.0 * (1.0 - progress);
            }
        } else {
            let miss = next_item_size - post_residual;
            score += 2.0 * miss as f64;
            if miss <= 2 {
                score -= 18.0 * (1.0 - progress);
            }
        }
    }

    // Penalize medium dead zones that nothing typical fills.
    if post_residual >= 5 && post_residual <= 9 && progress > 0.5 && next_item_size > post_residual {
        score += 8.0 * progress;
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Fill ratio reward.
    score -= 20.0 * (item_size as f64) / (bin_residual as f64).max(1.0);

    // Time horizon consolidation.
    score -= 6.0 * progress * tightness;

    // Global state coupling.
    if open_bins_count > 0 {
        let spread = (mean_residual - bin_residual as f64).abs();
        score += 0.05 * spread;
        score -= 0.02 * (open_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64);
    }

    // NEW-BIN CANDIDATE handling.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 180.0 - 60.0 * progress + 0.15 * open_bins_count as f64 - 25.0 * pressure;
        let fresh_left = bin_capacity - item_size;
        let item_frac = item_size as f64 / bin_capacity as f64;
        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3;
        }
        if next_item_size > 0 {
            if fresh_left == next_item_size {
                score -= 30.0;
            }
            if fresh_left > next_item_size {
                let tail = fresh_left - next_item_size;
                if tail <= 3 {
                    score -= 14.0 * (1.0 - progress);
                }
                if ((tail as f64) - mean_residual).abs() <= 3.0 {
                    score -= 9.0 * (1.0 - progress);
                }
            }
            if fresh_left < next_item_size && fresh_left < 8 {
                score += 35.0;
            }
        }
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress);
        }
        // Discourage fresh bins late when open bins can host next item.
        if fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 && progress > 0.6 {
            score += 10.0 * progress;
        }
        // Fresh bin attractive early with big items.
        if item_frac > 0.5 && progress < 0.4 {
            score -= 6.0 * (0.4 - progress) / 0.4;
        }
    }

    score
}

