pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- 2-step lookahead coupling ----
    if next_item_size > 0 {
        // Perfect chain: next item exactly fills post_residual -> strong reward
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item can also land here: reward proportionally to how well it fills the remainder
            let fill_after_next = (post_residual - next_item_size) as f64;
            let chain_fill = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * chain_fill;
            // Bonus if the two items together leave near-zero waste
            if fill_after_next <= 5.0 {
                score -= 15.0;
            }
            // Extra reward if next item exactly fills the bin (post_residual - next == 0 handled above)
        } else {
            // Next item cannot follow here: penalize wasted residual that nothing can use
            score += 12.0 * (1.0 - progress.min(1.0));
        }
    } else {
        // Last item: prefer tightest fit (post_residual already does that)
        score -= 5.0;
    }

    // ---- Relative-to-mean-residual shaping ----
    // Prefer bins whose residual is already small (dense bins); penalize sprawling bins
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 1.0 {
            score -= 8.0 * (1.0 - rel);
        } else {
            score += 6.0 * (rel - 1.0).min(3.0);
        }
    }

    // ---- Last-chance bin before opening a new one ----
    if fitting_bins_count == 1 {
        // This is the only open bin that fits: strongly favor using it
        score -= 30.0;
        // Especially if the fit is decent
        if post_residual <= 20 {
            score -= 20.0;
        }
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline cost plus escalation as the stream matures
        // (late in the stream, consolidating into existing bins matters more)
        score = 100.0 + 40.0 * progress;
        // If no other bin fits well, opening is more acceptable
        if fitting_bins_count == 0 {
            score -= 80.0;
        } else if fitting_bins_count == 1 {
            // Only one fitting bin: only open a new bin if that fit is terrible
            if post_residual > 40 {
                score -= 60.0;
            }
        }
        // Early stream: opening fresh bins is cheap and often good
        if progress < 0.2 {
            score -= 25.0;
        }
        // If next item is large, a fresh bin gives flexibility
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // ---- Dead-space penalty: residuals too small for typical future items ----
    if post_residual > 0 && post_residual < 10 {
        score += 10.0; // tiny unusable sliver
    }

    score
}

