        // mutation: fine-tuned dead-space penalty — residual that no plausible item can use
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            let ratio = post_residual as f64 / next_item_size as f64 ;
            if ratio < 0.5 {
