        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 && progress > 0.6 {
            score += 10.0 * progress ;
        }
        if item_frac > 0.5 && progress < 0.4 {
            score -= 6.0 * (0.4 - progress) / 0.4 ;
        }
        // mutation: fresh-bin leftover that matches the mean residual is highly reusable
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 4.0 {
            score -= 7.0 * (1.0 - progress) ;
        }
        // mutation: discourage opening a new bin when its leftover would be near-dead (just under next item)
        if next_item_size > 1 && fresh_left > 0 && fresh_left < next_item_size && (next_item_size - fresh_left) <= 3 {
            score += 16.0 * (0.5 + 0.5 * progress) ;
        }
        // mutation: fresh bin with leftover that can host next item AND a small tail is attractive
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) <= 2 {
            score -= 12.0 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let norm_item = item / cap;

    // Base: prefer small post residual, with non-linear (quadratic) penalty growth.
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Smooth polynomial coupling of tightness with stream progress:
    // late in the stream, waste matters more; early, flexibility matters.
    let tightness = 1.0 - norm_pr;
    score -= (1.0 + 2.0 * progress * progress) * 30.0 * tightness * tightness;

    // Penalize post_residual close to the "dead zone" (too small for typical items)
    // using a smooth bump around small residuals.
    let dead = norm_pr * (1.0 - norm_pr) * 4.0; // peaks at 0.5
    score += 10.0 * dead * (1.0 - progress);

    // Lookahead: reward leaving room for the next item (smooth coupling).
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let diff = norm_pr - nxt;
        let fit_quality = 1.0 - diff.abs().min(1.0);
        score -= 12.0 * fit_quality * fit_quality;
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Mild penalty when many bins are already open (encourage consolidation).
    score += open_bins_count as f64 * 0.5 * (1.0 - progress);

    // Deviation from mean residual: prefer bins whose residual differs
    // from the mean in a smooth way (fill the emptiest-fitting first).
    score += 0.3 * (mean_residual - bin_residual as f64).abs();

    // New-bin candidate: keep it neutral-to-slightly-high so it only wins
    // when no open bin offers a genuinely tight fit.
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * progress;
    }

    score
}

