pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    score -= 30.0 * (1.0 - pr / cap).powi(3);

    // Dead-space penalty: leftover too small to ever be useful.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // Lookahead coupling: does this bin stay usable for the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0 * (1.0 - pr / next_item_size as f64);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Harmonic class logic: leftovers aligned to multiples of 10 are more
    // reusable (integer-division-friendly); ragged remainders penalized.
    let r = post_residual % 10;
    if post_residual > 0 && r != 0 {
        score += 2.0 + r as f64 * 0.3;
    }
    // Bonus for post_residual exactly divisible into harmonic classes.
    if post_residual > 0 && r == 0 && post_residual >= 20 {
        score -= 4.0;
    }

    // New-bin candidate: mildly penalized, more so late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * progress;
    }

    // Many open bins with slack: prefer consolidating into existing bins.
    if open_bins_count > 4 && mean_residual > item_size as f64 {
        score -= 6.0;
    }

    score
}

