        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual > 0.0 && (mean_residual - next_item_size as f64) . abs () <= 2.0 {
            score += 14.0 * (1.0 - progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps (< 10).
    // A tiny leftover is pure waste; strongly punish it, but reward a
    // perfect or near-perfect fill.
    if post_residual == 0 {
        score -= 60.0; // perfect fit: best possible outcome
    } else if post_residual < 10 {
        score += 40.0; // dead space below minimum item size
    } else {
        // Smooth penalty that grows as residual approaches unusable range
        let r = post_residual as f64;
        score += 6.0 * (10.0 / r).powi(2);
    }

    // Bonus if this placement leaves room for the lookahead item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // residual wasted relative to lookahead: mild penalty
        let waste = (next_item_size - post_residual) as f64;
        score += 0.15 * waste;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += 0.05 * pressure;

    // Tightness reward: bins whose residual is already small are closer
    // to being "closed out"; finishing them is good.
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness;

    // Prefer bins below mean residual (tighter bins) slightly
    score += 0.05 * (mean_residual - bin_residual as f64);

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
    }

    score
}

