        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.5 && open_bins_count > 3 {
            score -= 14.0 * (1.0 - progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: reward if the NEXT item fits into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        // Reward a chained fit; tighter chains are better.
        score -= 25.0 + 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize dead space that the next item cannot use.
        let dead = (post_residual as f64 - (post_residual as f64).min(next_item_size as f64)).max(0.0);
        score += 8.0 * dead / bin_capacity as f64;
    }

    // Compare post_residual against mean residual: avoid making a bin worse than average.
    let mean_pr = mean_residual - item_size as f64;
    if (post_residual as f64) > mean_pr {
        score += 3.0 * (post_residual as f64 - mean_pr);
    } else {
        score -= 1.5 * (mean_pr - post_residual as f64).min(20.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and few bins are open (avoid wasting residual capacity elsewhere).
    if bin_residual == bin_capacity {
        score += 55.0;
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 40.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, opening a fresh bin is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Mild penalty for very small leftovers that are hard to reuse.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

