pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good (best-fit core).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that the lookahead item cannot use:
    // if the next item could exactly fill the leftover, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (post_residual as f64 / next_item_size.max(1) as f64).min(3.0);
        } else {
            // leftover too small for next item -> potential dead space
            score += 8.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // More competing fitting bins -> mild penalty for wasting a scarce residual elsewhere.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate handling: penalize opening a new bin, but less when the item
    // is large or the mean residual across open bins is too small to matter.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is more attractive for large items and when open bins
        // are nearly full on average (mean_residual small).
        let mean_pressure = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let new_bin_penalty = 18.0 - 14.0 * item_frac - 10.0 * mean_pressure - 4.0 * progress;
        score += new_bin_penalty.max(2.0);
