    let norm_post = pr / cap;
    score += 12.0 * norm_post * norm_post;

    // Lookahead: reward if next item fits exactly into post_residual (perfect chain).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 6.0 * (1.0 - slack * slack);
        } else {
            // dead space relative to next item
            score += 4.0 * (1.0 - nxt / cap);
        }
    }

