pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: reward bins whose leftover can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 4.0;
        }
    }

    // Open-bin pressure: discourage scattering across many bins unless fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.35 * (0.5 + progress);

    // Last-chance bonus: if this is the only bin that fits, prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Mean residual coupling: prefer bins near (below) the mean residual to keep balance.
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    // New-bin candidate: only attractive when current bin would leave a nasty gap.
    if bin_residual == bin_capacity {
        let waste_if_placed_elsewhere = (bin_residual - item_size) as f64;
        score = 55.0 + waste_if_placed_elsewhere * 0.2 - (open_bins_count as f64) * 0.5;
    }

    score
}

