pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            // Next item fits; reward proportionally to how well it fills the remainder.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 150.0 * fill;
            let chain_residual = post_residual as f64 - next_item_size as f64;
            if chain_residual <= 5.0 {
                score -= 100.0;
            }
        } else {
            // Next item does NOT fit here: penalize leaving residual just below next item.
            let gap = next_item_size as f64 - post_residual as f64;
            if gap <= 10.0 {
                score += 60.0 + 5.0 * gap; // dead-space trap
            }
        }
    } else {
        // Last item: any fit is fine, prefer tightest.
        score -= 50.0;
    }

    // Compare residual against mean residual: prefer bins that are already full-ish.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin before opening a new bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize opening a new bin when open bins could still fit reasonably.
    if bin_residual == bin_capacity {
        score += 120.0;
        // If next item is huge, a fresh bin may be attractive anyway.
        if next_item_size >= 60 && item_size <= 20 {
            score -= 100.0;
        }
        // Early in stream, more willing to open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * (1.0 - progress);
    }

    // Slight penalty for spreading across too many open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

