                    score -= 300.0 - 2.0 * two_step_waste;
                } else {
                    score -= 80.0 + 1.5 * (10.0 - two_step_waste);
                }
                let after_next = post_residual - next_item_size;
                if after_next >= 3 {
                    score -= (2.0 + 2.0 * progress) * (after_next as f64).min(15.0);
                }
                if after_next <= 12 && mean_residual >= after_next as f64 {
                    score -= 22.0 - 0.8 * after_next as f64;
                }
                if next_item_size > 1 && after_next >= next_item_size {
                    score -= 6.0 + 0.2 * (after_next / next_item_size) as f64;
                    if after_next % next_item_size == 0 {
                        score -= 8.0 * (1.0 - progress);
                    }
                }
                if after_next < next_item_size && after_next <= 3 {
                    score -= 14.0 * (1.0 - progress);
                }
                if after_next < next_item_size && after_next >= 1 && (next_item_size - after_next) <= 5 {
                    score -= 6.0 * (1.0 - progress);
                }
                if (after_next as f64 - mean_residual).abs() <= 4.0 {
                    score -= 6.0 * (1.0 - progress);
                }
            } else {
                let miss = next_item_size - post_residual;
                score += 2.0 * miss as f64;
                if post_residual < 25 {
                    score += 15.0;
                }
                if post_residual < 3 {
                    score -= 400.0;
                }
                if miss <= 6 && fitting_bins_count <= 2 {
                    score -= 5.0;
                }
                if miss <= 10 && fitting_bins_count <= 2 && progress > 0.7 {
                    score -= 10.0 * (1.0 - progress);
                }
                if miss <= 2 {
                    score -= 18.0 * (1.0 - progress);
                }
                if post_residual >= 8 && post_residual <= 16 {
                    score += 10.0 * (1.0 - progress);
                }
                if miss > 3 && miss as f64 <= mean_residual * 0.5 {
                    score += 4.0 * (1.0 - progress);
                }
            }
        }
        if post_residual < 10 {
            score += 45.0;
        } else if post_residual < 20 {
            score += 10.0;
        }
        score -= (mean_residual - post_residual as f64) * 0.6;
        let gap = (post_residual as f64 - item_size as f64).max(0.0);
        let gap_ratio = gap / (item_size as f64).max(1.0);
        if gap > 0.0 {
            let scarcity = if fitting_bins_count <= 2 { 0.6 } else if fitting_bins_count <= 4 { 0.3 } else { 0.2 };
            score += scarcity * gap + 18.0 * gap_ratio.min(2.0);
            if gap < mean_residual {
                let fillable = next_item_size > 0 && gap >= next_item_size as f64;
                let w = if fillable { 0.2 } else { 0.6 };
                score += w * (mean_residual - gap);
            }
            if next_item_size > 0 && (gap as u32) == next_item_size {
                score -= 20.0;
            }
            if next_item_size > 1 && (gap as u32) == 2 * next_item_size {
                score -= 12.0;
            }
        }
        if fitting_bins_count == 1 {
            score -= 12.0;
        }
        let fill = item_size as f64 / (bin_residual as f64).max(1.0);
        score -= 20.0 * fill;
        if next_item_size > 0 && post_residual < next_item_size {
            let dead_frac = post_residual as f64 / bin_capacity as f64;
            let unusable_ratio = post_residual as f64 / (next_item_size as f64).max(1.0);
            score += 0.4 * post_residual as f64 + 30.0 * dead_frac + 12.0 * (1.0 - unusable_ratio);
            if next_item_size - post_residual <= 4 {
                score += 20.0 * (1.0 - progress);
            }
        }
        if fitting_bins_count == 2 && post_residual < bin_capacity / 3 {
            score -= 8.0;
        }
        if post_residual <= 5 && open_bins_count > 6 {
            score += 25.0 * (1.0 - progress);
        }
        if post_residual >= bin_capacity / 8 && post_residual <= bin_capacity / 2 {
            score -= 6.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= bin_capacity / 2 {
            score -= 4.0 * (1.0 - progress);
        }
        if post_residual as f64 >= 2.0 * mean_residual && post_residual > 20 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let headroom = post_residual - next_item_size;
            if (headroom as f64 - mean_residual).abs() <= 3.0 {
                score -= 7.0;
            }
            if (headroom as f64 - mean_residual).abs() <= 1.0 && fitting_bins_count <= 3 {
                score -= 5.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0;
        }
        if next_item_size > 1 && post_residual > next_item_size + 1 && post_residual <= next_item_size + 10 {
            score -= 4.0 * (1.0 - progress);
        }
        if next_item_size > 1 && post_residual % next_item_size == 0 && post_residual >= 2 * next_item_size && post_residual <= 3 * next_item_size {
            score -= 5.0 * (1.0 - progress);
        }
        if post_residual >= 5 && post_residual <= 9 && progress > 0.5 && next_item_size > post_residual {
            score += 8.0 * progress;
        }
    }

    // NEW-BIN CANDIDATE
    if bin_residual == bin_capacity {
        let big_next = next_item_size as f64 / bin_capacity as f64;
        score += 180.0 - 60.0 * progress + 0.15 * open_bins_count as f64 - 25.0 * big_next.max(0.0);
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
        if open_bins_count <= 4 && progress < 0.3 {
            score += 25.0;
        }
        if mean_residual < 15.0 && progress > 0.5 {
            score -= 15.0;
        }
        let item_frac = item_size as f64 / bin_capacity as f64;
        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3;
        }
        let fresh_left = bin_capacity - item_size;
        if next_item_size > 0 && fresh_left == next_item_size {
            score -= 30.0;
        }
        if open_bins_count > 6 && mean_residual > 0.4 * bin_capacity as f64 {
            score += 20.0;
        }
        if next_item_size > 0 && fresh_left < next_item_size && fresh_left < 8 {
            score += 35.0;
        }
        if next_item_size > 0 && fitting_bins_count <= 2 && mean_residual < next_item_size as f64 {
            score -= 18.0 * (1.0 - progress);
        }
        if open_bins_count > 8 && mean_residual > next_item_size as f64 + 10.0 {
            score += 12.0;
        }
        if item_frac > 0.6 && next_item_size > 0 && fresh_left >= next_item_size {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0;
        }
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0;
        }
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress);
        }
        if next_item_size > 0 && (fresh_left as f64 - mean_residual).abs() <= 2.0 {
            score -= 8.0;
        }
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual).abs() <= 3.0 {
            score -= 9.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 && progress > 0.6 {
            score += 10.0 * progress;
        }
        if item_frac > 0.5 && progress < 0.4 {
            score -= 6.0 * (0.4 - progress) / 0.4;
        }
    }

    // Late consolidation: prefer tightest fits even more.
    score -= progress * 0.3 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post-residual preferred).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * 40.0;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // Penalize dead space that likely can't fit future items.
    // Dead space = post_residual; if it's below the minimum plausible item size,
    // it's wasted. Item sizes 1..100, so anything >0 could theoretically fit,
    // but small slivers are statistically hard to use.
    let sliver = post_residual as f64;
    score += (sliver * sliver) / (bin_capacity as f64) * 0.5;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it fills remainder.
            let leftover2 = post_residual - next_item_size;
            score -= 20.0 - (leftover2 as f64) * 0.2;
        } else {
            // next item does NOT fit after placing here: slight penalty,
            // since it may need a new bin anyway.
            score += 5.0;
        }
    }

    // Last-chance logic: if this is the only bin that can fit the item,
    // avoid opening a new bin — reward heavily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets baseline attractiveness so
    // it's chosen only when fits into open bins are poor.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline: slightly worse than a good tight fit,
        // better than a bad loose fit.
        score += 45.0;
        // Early in the stream, opening bins is cheap/flexible.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 15.0;
        // If many open bins already, discourage proliferation.
        score += (open_bins_count as f64) * 1.5;
        // If lookahead item is large, a fresh bin is more valuable.
        if next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Global state: prefer filling bins whose residual is below mean residual
    // (consolidate space in fuller bins), keep emptier bins for large future items.
    if bin_residual as f64 > mean_residual {
        // This bin is emptier than average: mild penalty for using it with a small item.
        if item_size < 40 {
            score += 6.0;
        }
    } else {
        score -= 4.0;
    }

    // Time-horizon modulation: late in the stream, be aggressive about
    // filling existing bins (avoid leftover fragmentation).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 12.0 * (1.0 - tightness);

    // Small tie-breaker noise-free deterministic jitter based on residual parity
    // to break exact ties toward larger residuals first (keeps big gaps usable).
    score += (bin_residual % 3) as f64 * 0.01;

    score
}

