pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap; // normalized post residual in [0,1)

    let mut score = post;

    // Smooth polynomial coupling: reward tight fits more aggressively as stream progresses.
    let tightness = (1.0 - pr).powi(3);
    score -= 30.0 * tightness * (0.4 + 0.6 * progress);

    // Penalize large dead space quadratically, amplified late in the stream.
    score += 8.0 * pr * pr * (0.3 + 0.9 * progress);

    // Perfect-fit bonus (post_residual == 0) with smooth decay.
    if post_residual == 0 {
        score -= 25.0 * (1.0 - progress * 0.3);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead coupling: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let nx = next_item_size as f64 / cap;
        score -= 12.0 * nx * (1.0 - pr);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space likely: penalize proportionally to unusable gap vs next item.
        let gap = post_residual as f64;
