    if bin_residual == bin_capacity {
        score += 6.0 + 0.5 * open_bins_count as f64 - 4.0 * progress;
    } else {
        // Favor bins with residuals far from mean residual (better packing diversity).
        let dev = (bin_residual as f64 - mean_residual).abs() / cap;
        score -= 3.0 * dev;
    }

    score
}

