pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "usable" classes (multiples of common item sizes) are favored.
    let class = if post_residual == 0 {
        0.0 // perfect fit, best possible
    } else if post_residual % 10 == 0 {
        1.0
    } else if post_residual % 25 == 0 {
        2.0
    } else if post_residual % 5 == 0 {
        3.0
    } else {
        5.0
    };
    score += class * 2.0;

    // Reward tight fits: waste relative to capacity.
    let tightness = (item_size as f64) / (bin_capacity as f64);
    score -= tightness * 12.0;

    // Dead-space penalty: small non-zero post_residual that nothing can use.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 1.5;
    }

    // Last chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
        // Extra reward when next item exactly fills post residual.
        if next_item_size == post_residual {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Penalize leaving a residual the next item cannot use.
        score += (next_item_size - post_residual).min(20) as f64 * 0.4;
    }

    // New-bin candidate handling: prefer new bin only when existing bins
    // would create large unusable residuals and many bins are already open.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.9;
        // Cheaper to open a new bin early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 15.0;
        // Discourage hoarding open bins.
        score += open_bins_count as f64 * 1.2;
        // If existing bins are all poor fits, new bin is attractive.
        score -= mean_residual * 0.05;
        // Large item into fresh bin is good.
        score -= tightness * 20.0;
    }

    score
}

