        }
        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 && progress > 0.6 {
            score += 10.0 * progress ;
        }
        if item_frac > 0.5 && progress < 0.4 {
            score -= 6.0 * (0.4 - progress) / 0.4 ;
        }
        // mutation: fresh-bin leftover dead-space check — if fresh leftover can't hold next item
        // and no open bin has room, opening a new bin wastes less than a bad squeeze
        if next_item_size > 0 && fresh_left < next_item_size && fitting_bins_count <= 1 {
