pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fits (low post_residual).
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 8.0 * tightness;

    // Aggressive 2-step lookahead: if next item fits exactly into the post residual,
    // this placement sets up a perfect follow-up — heavily reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here; residual risks becoming dead space.
            let dead = (next_item_size - post_residual) as f64;
            score += 4.0 * (dead / bin_capacity as f64);
        }
    }

    // Compare post_residual relative to mean residual of open bins.
    // Leaving residual below the mean is good (bin nearly closed out).
    score += 3.0 * (post_residual as f64 - mean_residual) / bin_capacity as f64;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Penalize leaving very small unusable slivers (wasted capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Mild preference for filling existing bins rather than opening new ones
    // as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when no open bin is a decent fit
        // or many bins are already open and mean residual is small.
        score += 20.0 - 25.0 * progress;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
    } else {
        score -= 3.0 * progress;
    }

    score
}

