    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin, more when good alternatives exist
    // or when the stream is early (more future items to co-fill).
    if bin_residual == bin_capacity {
