        // mutation: combine lookahead anticipation — prefer bins whose post residual can host next item AND leave a near-mean residual
        if next_item_size > 0 && post_residual > next_item_size && (post_residual - next_item_size) as f64 >= mean_residual - 2.0 && (post_residual - next_item_size) as f64 <= mean_residual + 2.0 {
            score -= 10.0 * (1.0 - progress) ;
        }
        // mutation: penalize leaving small awkward slivers that no plausible item can fill
        if post_residual >= 1 && post_residual <= 4 && next_item_size > post_residual {
            score += 12.0 * (1.0 - progress) ;
        }
    }
    // NEW-BIN CANDIDATE
    if bin_residual == bin_capacity {
        let big_next = next_item_size as f64 / bin_capacity as f64 ;
        score += 180.0 - 60.0 * progress + 0.15 * open_bins_count as f64 - 25.0 * big_next . max (0.0) ;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0 ;
        }
        if open_bins_count <= 4 && progress < 0.3 {
            score += 25.0 ;
        }
        if mean_residual < 15.0 && progress > 0.5 {
            score -= 15.0 ;
        }
        let item_frac = item_size as f64 / bin_capacity as f64 ;
        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3 ;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3 ;
        }
        let fresh_left = bin_capacity - item_size ;
        if next_item_size > 0 && fresh_left == next_item_size {
            score -= 30.0 ;
        }
        if open_bins_count > 6 && mean_residual > 0.4 * bin_capacity as f64 {
            score += 20.0 ;
        }
        if next_item_size > 0 && fresh_left < next_item_size && fresh_left < 8 {
            score += 35.0 ;
        }
        if next_item_size > 0 && fitting_bins_count <= 2 && mean_residual < next_item_size as f64 {
            score -= 18.0 * (1.0 - progress) ;
        }
        if open_bins_count > 8 && mean_residual > next_item_size as f64 + 10.0 {
            score += 12.0 ;
        }
        if item_frac > 0.6 && next_item_size > 0 && fresh_left >= next_item_size {
            score -= 8.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size ;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress) ;
            }
        }
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 && progress > 0.6 {
            score += 10.0 * progress ;
        }
        if item_frac > 0.5 && progress < 0.4 {
            score -= 6.0 * (0.4 - progress) / 0.4 ;
        }
        // mutation: avoid fresh bins when an open bin leaves a near-perfect post-fit residual
        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual > 0.0 && (mean_residual - next_item_size as f64) . abs () <= 2.0 {
            score += 14.0 * (1.0 - progress) ;
        }
        // mutation: fresh bin only when no open bin can host the next item and mean residual is tight
        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 && progress > 0.4 {
            score += 8.0 * progress ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Best-fit core: reward tight fits, penalize dead space that can't host typical items
    let tightness = 1.0 - (post_residual as f64) / cap_f;
    score -= 12.0 * tightness;

    // Harmonic classes: classify post_residual into modulo classes of common item sizes
    let pr = post_residual;
    if pr == 0 {
        // Perfect closure: strongly reward
        score -= 60.0;
    } else if pr < 10 {
        // Dead space below minimum item size: heavy penalty
        score += 25.0 * (10 - pr) as f64;
    } else {
        // Modulo arithmetic on post_residual: which harmonic classes remain usable?
        let mut usable = 0.0;
        for m in [10u32, 20, 25, 30, 40, 50, 60, 70, 80] {
            if pr >= m {
                usable += 1.0;
            }
        }
        score -= 6.0 * usable;
        // Fractional alignment: post_residual exactly divisible by small divisors -> future items tile well
        for d in [5u32, 10, 20, 25] {
            if pr % d == 0 {
                score -= 4.0;
            }
        }
    }

    // Lookahead coupling: does next_item_size fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 10.0;
            // Chain fit: next item also lands in a harmonic class
            if next_item_size % 10 == 0 {
                score -= 5.0;
            }
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless item is large or no good fit exists
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = (item_size as f64) > 0.7 * cap_f;
        let poor_fit = (post_residual as f64) > 0.5 * cap_f;
        score += 20.0;
        if large_item {
            score -= 15.0;
        }
        if poor_fit && !large_item {
            score += 10.0;
        }
        // Late in stream, prefer consolidating into open bins
        score += 10.0 * progress;
        // Many open bins with slack: discourage another
        if mean_residual > 0.3 * cap_f && open_bins_count > 2 {
            score += 8.0;
        }
    }

    // Mild preference for bins with residual near item's harmonic complement
    let complement = bin_capacity.saturating_sub(item_size);
    let closeness = ((bin_residual as i64 - complement as i64).abs()) as f64;
    score += 0.05 * closeness;

    score
}

