pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are unusable, penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Reward leaving residuals that can host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // residual too small for next item -> dead weight
        score += 15.0;
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += 2.0 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (high mean residual spread / many bins) or item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_alternatives = (mean_residual - item_size as f64).max(0.0);
        score = 55.0 + open_bins_count as f64 * 1.5 - poor_alternatives * 0.4
                 - fill_ratio * 10.0 + progress * 5.0;
        // Large items justify fresh bins more readily.
        score -= item_size as f64 * 0.3;
        // Never open a new bin when a perfect fit exists elsewhere.
        if post_residual == 0 { score -= 100.0; }
    }

    // Mild trend: as stream progresses, prefer consolidating into open bins.
    score += 10.0 * (step_index as f64 / (total_items.max(1) as f64)) * (post_residual as f64 / bin_capacity as f64);

    score
}

