    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 500.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leaving a gap that is too small to be useful.
            let gap = post_residual as f64;
            if gap < 10.0 {
                score += 60.0;
            } else {
                score += 0.3 * (gap - 10.0);
            }
        }
    }

    // Relative to mean residual: prefer bins that are tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let urgency = if next_item_size > 0 && next_item_size >= item_size { 1.2 } else { 1.0 };
        score += 120.0 * urgency;
        if post_residual >= 40 {
            score -= 30.0;
