pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };

    let mut score = pr;

    // Smooth non-linear coupling: residual value depends on stream progress
    let decay = (1.0 - progress) * (1.0 - progress);
    score -= 60.0 * pr_norm * (1.0 - decay * 0.5);

    // Penalize mid-range dead space quadratically
    let dead = pr_norm * (1.0 - pr_norm);
    score += 25.0 * dead * dead * cap * 0.01;

    // Last-chance bonus (smooth via fitting count)
    if fitting_bins_count == 1 && is_new_bin < 0.5 {
        score -= 40.0;
    }

    // Lookahead coupling: reward if next item fits post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = (pr - nxt).max(0.0) / cap;
        score -= 30.0 * fits;
        let near = 1.0 - ((pr - nxt) / cap).abs().min(1.0);
        score += 10.0 * near * near;
    }

    // New-bin candidate: penalize mildly unless residuals are tight
    score += is_new_bin * (8.0 + 20.0 * (1.0 - mean_residual / cap).abs());

    // Crowd penalty for many open bins
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

