pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Perfect fit: strong reward
    if pr == 0 {
        score -= 35.0;
    }
    // Dead-space trap: residual too small for any future item (sizes >= 10 historically)
    else if pr < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item can also fit in this bin afterwards
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
        // Harmonic pairing: post_residual exactly matches next item -> near-perfect chain
        if pr == next_item_size {
            score -= 10.0;
        }
    }

    // Integer-division classes of post_residual (harmonic bins of width 20)
    let cls = pr / 20;
    score += match cls {
        0 => 10.0,  // tiny leftover, mostly dead
        1 => 0.0,
        2 => -5.0,  // sweet spot: ~40-59 residual, fits most mid items
        3 => -3.0,
        _ => -6.0,  // large residual, very reusable
    };

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score = cap - 5.0 + open_bins_count as f64 * 0.6;
        if fitting_bins_count == 0 {
            // No open bin fits: opening is forced/necessary
            score -= 120.0;
        }
        // Late in stream, prefer consolidating into existing bins
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += t * 15.0;
    }

    // Mild pressure toward bins below mean residual (tighter packing)
    score += (mean_residual - pr as f64) * 0.05;

    // Stream progression: tiny bonus for earlier bins as stream advances
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= t * 2.0;

    score
}

