    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving a gap that can host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else if post_residual > 0 {
            score += 15.0; // gap too small for next item: likely dead space
        }
    } else {
        // Last item: prefer emptying bins completely.
        score -= post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; with few, spreading is cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (2.0 + 6.0 * progress);

    // Pull toward mean residual: bins far below mean residual are poor targets.
    score += (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate handling: empty bin is a safe fallback but should lose
    // to decent fits; win only when fits are bad or many bins already open.
    if bin_residual == bin_capacity {
        score = 55.0 + (open_bins_count as f64) * 1.5 - (mean_residual * 0.2);
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // pairing lookahead fits in a fresh bin
        }
        if fitting_bins_count == 1 {
            score += 45.0; // never open a new bin when a last-chance bin exists
        }
    }

    score
}

