pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Tight-fit reward: strongly favor small post_residual (non-linear).
    let tightness = 1.0 - (post / cap);
    score -= 18.0 * tightness * tightness * tightness;

    // Penalize leaving residual that is too small to be useful for future items.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 1.5;
    }

    // Non-linear coupling of post_residual with stream progress:
    // early on, tolerate slack; late, prefer packing tightly.
    let progress_coupling = (progress * std::f64::consts::PI).sin();
    score -= 8.0 * tightness * progress_coupling;

    // Last-chance bin: reward heavily to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits into the resulting residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 10.0 * (1.0 - ((post - nxt) / cap).abs());
        } else {
            score += 4.0 * (nxt - post) / cap;
        }
    }

    // New-bin candidate: penalize opening a bin unless item is large
    // (large items leave proportionally usable residual) or existing
    // fits are very poor (post_residual would be tiny).
    if bin_residual == bin_capacity {
        let ratio = item / cap;
        let poor_existing = if fitting_bins_count > 0 {
            // best achievable post_residual among open bins approximated via mean_residual
            (mean_residual - item).max(0.0)
        } else {
            0.0
        };
        score += 30.0 - 20.0 * ratio * ratio;
        if poor_existing < 8.0 {
            score -= 35.0; // existing bins would waste space; new bin is fine
        }
        // late in the stream, discourage proliferation of open bins
        score += (open_bins_count as f64).ln() * 3.0 * (progress * progress);
    }

    // Mild penalty for bins much emptier than average (keep bins balanced).
    score += ((mean_residual - bin_residual as f64) / cap).abs() * 2.0;

    score
}

