pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits; perfect closure gets a big reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residuals divisible by common item
    // sizes (or capacity fractions) are more "usable" dead space.
    let pr = post_residual as u32;
    let mut usability = 0.0;
    for d in [10u32, 20, 25, 50, 100] {
        if d <= pr && pr % d == 0 {
            usability += 12.0;
        }
    }
    // Small residuals are dead space; large residuals are flexible.
    if pr > 0 && pr < 10 {
        score += 30.0; // tiny sliver penalty
    }
    if pr >= 50 {
        score -= 15.0; // roomy residual is valuable
    }
    score -= usability;

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly reward this bin (chain fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            score -= 20.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            score += 10.0; // next item won't fit here; slight penalty
        }
        // Harmonic check: next item aligns with capacity fractions
        if next_item_size % 10 == 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 25.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if no open bin fits well
        // (i.e., mean residual is small relative to item) or bins are scarce.
        let pressure = item_size as f64 / mean_residual.max(1.0);
        score = 200.0 + 100.0 * (1.0 - pressure.min(1.0)) + open_bins_count as f64;
        if post_residual == 0 {
            score -= 50.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
    }

    // Mild stream-progression term: later in the stream, consolidate more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
