pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize large residual gaps that no future small item (>=1) can use anyway is moot;
    // instead reward leaving gaps >= next_item_size so lookahead fits.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + next_item_size as f64 * 0.2;
    }
    // Penalize if post_residual is a "just barely too small" gap for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer filling existing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (2.0 + 6.0 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score = 100.0 + open_bins_count as f64 * 5.0;
        if fitting_bins_count == 0 {
            score = 5.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // opening fresh bin may help the bigger next item
        }
        return score;
    }

    // Prefer bins whose residual is close to item_size (tight fit).
    score -= (bin_residual as f64 - item_size as f64).abs() * -0.5 * 0.0;
    score += (bin_residual - item_size) as f64 * 0.3;
    // Favor bins below mean residual (fuller bins).
    score += (mean_residual - bin_residual as f64) * 0.4;

    score
}

