    let mut score = post_residual as f64;

    // Perfect lookahead match: next item exactly fills the residual
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item can still fit here: mild reward proportional to tightness
        let tight = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 20.0 * tight;
    } else if next_item_size > 0 {
        // Dead space: post_residual too small for next item
        let waste = (post_residual as f64) / bin_capacity as f64;
        score += 15.0 * waste;
    }

    // Penalize residual far from mean (avoid leaving oddly-large gaps)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Progress-based pressure: late in stream, consolidate tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive if no open bin gives a tight fit
    if bin_residual == bin_capacity {
        score += 45.0;
        if fitting_bins_count <= 1 {
            score -= 50.0; // no good alternative, allow opening
        }
    }

    score
}

