pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize wasted fraction of the bin.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 12.0 * tightness * tightness;

    // Penalize large post-residuals that are unlikely to be usable later.
    if post_residual > 0 {
        if post_residual < 10 {
            score -= 8.0; // small dead space is fine
        } else {
            score += (post_residual as f64 / 20.0).powi(2) * 0.5;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward if the next item fits into the post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + 0.15 * next_item_size as f64;
        } else {
            // Penalize leaving residual just barely too small for next item.
            let gap = next_item_size as f64 - post_residual as f64;
            if gap < 10.0 {
                score += 6.0;
            }
        }
    }

    // Global pressure: when many bins are open, discourage opening new bins.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 * 0.8 + mean_residual * 0.1;
        score += 18.0 + pressure * (1.0 - progress * 0.5);
