    // Prefer bins with residuals close to the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Early stream: be slightly greedy toward filling bins fully.
    if step_index < total_items / 4 {
        score -= 3.0 * tightness;
    }

    score
}

