        if next_item_size > 0 && post_residual > next_item_size {
            let headroom = post_residual - next_item_size ;
            if (headroom as f64 - mean_residual) . abs () <= 3.0 {
                score -= 7.0 ;
            }
            if (headroom as f64 - mean_residual) . abs () <= 1.0 && fitting_bins_count <= 3 {
                score -= 5.0 * (1.0 - progress) ;
            }
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0 ;
        }
        if next_item_size > 1 && post_residual > next_item_size + 1 && post_residual <= next_item_size + 10 {
            score -= 4.0 * (1.0 - progress) ;
        }
        if next_item_size > 1 && post_residual % next_item_size == 0 && post_residual >= 2 * next_item_size && post_residual <= 3 * next_item_size {
            score -= 5.0 * (1.0 - progress) ;
        }
        if post_residual >= 5 && post_residual <= 9 && progress > 0.5 && next_item_size > post_residual {
            score += 8.0 * progress ;
        }
        // mutation: dead-space pressure — residual too small for typical next items is costly, scaled by remaining stream
        if next_item_size > 0 && post_residual < next_item_size {
            let stream_left = 1.0 - progress ;
            score += 6.0 * stream_left * (1.0 - post_residual as f64 / (next_item_size as f64) . max (1.0)) ;
        }
        // mutation: reward residuals that still fit the mean-sized future item
        if mean_residual > 0.0 && post_residual as f64 >= mean_residual {
            score -= 3.0 * (1.0 - progress) ;
        }
    }
    // NEW-BIN CANDIDATE
    if bin_residual == bin_capacity {
        let big_next = next_item_size as f64 / bin_capacity as f64 ;
        score += 180.0 - 60.0 * progress + 0.15 * open_bins_count as f64 - 25.0 * big_next . max (0.0) ;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0 ;
        }
        if open_bins_count <= 4 && progress < 0.3 {
            score += 25.0 ;
        }
        if mean_residual < 15.0 && progress > 0.5 {
            score -= 15.0 ;
        }
        let item_frac = item_size as f64 / bin_capacity as f64 ;
        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3 ;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3 ;
        }
        let fresh_left = bin_capacity - item_size ;
        if next_item_size > 0 && fresh_left == next_item_size {
            score -= 30.0 ;
        }
        if open_bins_count > 6 && mean_residual > 0.4 * bin_capacity as f64 {
            score += 20.0 ;
        }
        if next_item_size > 0 && fresh_left < next_item_size && fresh_left < 8 {
            score += 35.0 ;
        }
        if next_item_size > 0 && fitting_bins_count <= 2 && mean_residual < next_item_size as f64 {
            score -= 18.0 * (1.0 - progress) ;
        }
        if open_bins_count > 8 && mean_residual > next_item_size as f64 + 10.0 {
            score += 12.0 ;
        }
        if item_frac > 0.6 && next_item_size > 0 && fresh_left >= next_item_size {
            score -= 8.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size ;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress) ;
            }
        }
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 && progress > 0.6 {
            score += 10.0 * progress ;
        }
        if item_frac > 0.5 && progress < 0.4 {
            score -= 6.0 * (0.4 - progress) / 0.4 ;
        }
        // mutation: fresh-bin leftover chainability graded by divisibility depth
        if next_item_size > 1 && fresh_left % next_item_size == 0 {
            let depth = (fresh_left / next_item_size) as f64 ;
            score -= 4.0 * depth . min (4.0) * (1.0 - progress) ;
        }
        // mutation: late stream, small leftovers everywhere -> fresh bin with tight tail is better
        if progress > 0.75 && fresh_left <= 10 {
            score -= 12.0 * progress ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit classes are heavily rewarded.
    let pr = post_residual as u32;
    if pr == 0 {
        score -= 1000.0; // perfect fit
    } else if pr <= 10 {
        score -= 60.0; // small dead space, still usable for tiny items
    } else {
        // residue class modulo 10: multiples of 10 are "harmonic" slots
        let class = pr % 10;
        score -= if class == 0 { 40.0 } else { class as f64 * 0.5 };
    }

    // Fractional capacity classes: post_residual / capacity buckets
    let frac = post_residual as f64 / cap;
    if frac < 0.05 {
        score -= 30.0;
    } else if frac > 0.5 {
        score += 15.0; // wasting more than half a bin's remaining space
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 200.0;
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use this residual: mild penalty proportional to gap
            score += (next_item_size - pr).min(50) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: empty bin gets neutral-ish baseline.
    if bin_residual == bin_capacity {
        // Prefer new bin only if existing fits are bad (score stays high via base)
        score += 25.0 + 0.1 * open_bins_count as f64;
    } else {
        // Mild preference for tighter existing bins
        score += (bin_residual as f64 - item_size as f64) * 0.05;
    }

    // Stream progression: early on, keep bins open and flexible; late, pack aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 20.0 * (mean_residual / cap);

    // Mean residual alignment: bins near mean residual are good targets.
    score -= 10.0 - (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold any plausible
    // future item (min item size 1, but practically small gaps < 10) are waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight fit reward: the closer post_residual is to 0, the better.
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Penalize "unusable" gaps: post_residual in (0, 10) is pure dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Penalize medium gaps that can't fit the next item (lookahead coupling).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + 0.1 * next_item_size as f64 * (1.0 - progress);
    }

    // Reward bins whose post_residual still fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; discourage opening new bins.
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced early in the stream.
        score += 12.0 + 10.0 * progress;
        // If no existing bin fits well (post_residual large elsewhere),
        // opening new is less penalized — handled implicitly by comparison.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Prefer bins whose residual is close to the item (best fit flavor).
        score += 0.3 * (bin_residual - item_size) as f64;
        // Slight preference for bins below mean residual (fill emptier bins less).
        if (bin_residual as f64) > mean_residual {
            score += 1.0;
        } else {
            score -= 1.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    if post_residual == 0 {
        // Perfect fit: overwhelming reward.
        score -= 1000.0;
    } else {
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 12.0 * tightness * tightness;

        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 900.0 - 30.0 * progress;
            } else if post_residual >= next_item_size {
                let after_next = post_residual - next_item_size;
                if after_next == 0 {
                    score -= 700.0;
                } else if after_next >= 10 {
                    score -= 300.0 - 2.0 * after_next as f64;
                } else {
                    score -= 80.0 + 1.5 * (10.0 - after_next) as f64;
                }
                // Reward headroom that can host more items (chainable residual).
                if after_next >= 3 {
                    score -= (2.0 + 2.0 * progress) * (after_next as f64).min(15.0);
                }
                if after_next as f64 <= mean_residual && after_next <= 12 {
                    score -= 22.0 - 0.8 * after_next as f64;
                }
                if next_item_size > 1 && after_next >= next_item_size {
                    score -= 6.0 + 0.2 * (after_next / next_item_size) as f64;
                    if after_next % next_item_size == 0 {
                        score -= 8.0 * (1.0 - progress);
                    }
                }
                // Small dead slivers just below next item size are wasteful.
                if after_next < next_item_size && after_next <= 3 {
                    score += 14.0 * (1.0 - progress);
                }
                if after_next < next_item_size && (next_item_size - after_next) <= 5 {
                    score += 6.0 * (1.0 - progress);
                }
                if (after_next as f64 - mean_residual).abs() <= 4.0 {
                    score -= 6.0 * (1.0 - progress);
                }
            } else {
                let miss = (next_item_size - post_residual) as f64;
                score += 2.0 * miss;
                if post_residual < 25 {
                    score += 15.0;
                }
                // Nearly-full bin is excellent even if it can't host next item.
                if post_residual < 3 {
                    score -= 400.0;
                }
                if miss <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
                if miss <= 6.0 && fitting_bins_count <= 2 {
                    score -= 5.0;
                }
                if miss <= 10.0 && fitting_bins_count <= 2 && progress > 0.7 {
                    score -= 10.0 * (1.0 - progress);
                }
                if post_residual >= 8 && post_residual <= 16 {
                    score += 10.0 * (1.0 - progress);
                }
            }
        }

        // Penalize medium-small dead residuals.
        if post_residual < 10 {
            score += 45.0;
        } else if post_residual < 20 {
            score += 10.0;
        }

        score -= (mean_residual - post_residual as f64) * 0.6;

        // Leftover gap relative to item size.
        let gap = (post_residual as f64 - item_size as f64).max(0.0);
        if gap > 0.0 {
            let gap_ratio = gap / (item_size as f64).max(1.0);
            let scarcity = if fitting_bins_count <= 2 { 0.6 } else if fitting_bins_count <= 4 { 0.3 } else { 0.2 };
            score += scarcity * gap + 18.0 * gap_ratio.min(2.0);
            if gap < mean_residual {
                let fillable = next_item_size > 0 && gap >= next_item_size as f64;
                let w = if fillable { 0.2 } else { 0.6 };
                score += w * (mean_residual - gap);
            }
            if next_item_size > 0 && gap as u32 == next_item_size {
                score -= 20.0;
            }
        }

        // Last-chance bin.
        if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
            score -= 15.0;
        }

        // Fill ratio reward.
        let fill = item_size as f64 / (bin_residual as f64).max(1.0);
        score -= 20.0 * fill;

        if next_item_size > 0 && post_residual < next_item_size {
            let dead_frac = post_residual as f64 / bin_capacity as f64;
            let unusable_ratio = post_residual as f64 / (next_item_size as f64).max(1.0);
            score += 0.4 * post_residual as f64 + 30.0 * dead_frac + 12.0 * (1.0 - unusable_ratio);
            if next_item_size - post_residual <= 4 {
                score += 20.0 * (1.0 - progress);
            }
        }

        if fitting_bins_count == 2 && post_residual < bin_capacity / 3 {
            score -= 8.0;
        }
        if post_residual <= 5 && open_bins_count > 6 {
            score += 25.0 * (1.0 - progress);
        }
        if post_residual >= bin_capacity / 8 && post_residual <= bin_capacity / 2 {
            score -= 6.0;
        }
        if post_residual as f64 >= 2.0 * mean_residual && post_residual > 20 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let headroom = (post_residual - next_item_size) as f64;
            if (headroom - mean_residual).abs() <= 3.0 {
