        if post_residual >= 5 && post_residual <= 9 && progress > 0.5 && next_item_size > post_residual {
            score += 8.0 * progress;
        }
    }

    // Time horizon: late in stream prefer consolidation.
    score -= 6.0 * progress * (1.0 - (post_residual as f64) / (bin_capacity as f64));

