        let gap_ratio = gap / (item_size as f64) . max (1.0) ;
        if gap > 0.0 {
            let scarcity = if fitting_bins_count <= 2 { 0.6 } else if fitting_bins_count <= 4 { 0.3 } else { 0.2 } ;
            score += scarcity * gap + 18.0 * gap_ratio . min (2.0) ;
            if gap < mean_residual {
                let fillable = next_item_size > 0 && gap >= next_item_size as f64 ;
                let w = if fillable { 0.2 } else { 0.6 } ;
                score += w * (mean_residual - gap) ;
            }
            if next_item_size > 0 && (gap as u32) == next_item_size {
                score -= 20.0 ;
            }
            if next_item_size > 1 && (gap as u32) == 2 * next_item_size {
                score -= 12.0 ;
            }
        }
        if fitting_bins_count == 1 {
            score -= 12.0 ;
        }
        let fill = item_size as f64 / (bin_residual as f64) . max (1.0) ;
        score -= 20.0 * fill ;
        if next_item_size > 0 && post_residual < next_item_size {
            let dead_frac = post_residual as f64 / bin_capacity as f64 ;
            let unusable_ratio = post_residual as f64 / (next_item_size as f64) . max (1.0) ;
            score += 0.4 * post_residual as f64 + 30.0 * dead_frac + 12.0 * (1.0 - unusable_ratio) ;
            if next_item_size - post_residual <= 4 {
                score += 20.0 * (1.0 - progress) ;
            }
        }
        if fitting_bins_count == 2 && post_residual < bin_capacity / 3 {
            score -= 8.0 ;
        }
        if post_residual <= 5 && open_bins_count > 6 {
            score += 25.0 * (1.0 - progress) ;
        }
        if post_residual >= bin_capacity / 8 && post_residual <= bin_capacity / 2 {
            score -= 6.0 ;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= bin_capacity / 2 {
            score -= 4.0 * (1.0 - progress) ;
        }
        if post_residual as f64 >= 2.0 * mean_residual && post_residual > 20 {
            score -= 5.0 ;
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let headroom = post_residual - next_item_size ;
            if (headroom as f64 - mean_residual) . abs () <= 3.0 {
                score -= 7.0 ;
            }
            if (headroom as f64 - mean_residual) . abs () <= 1.0 && fitting_bins_count <= 3 {
                score -= 5.0 * (1.0 - progress) ;
            }
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0 ;
        }
        if next_item_size > 1 && post_residual > next_item_size + 1 && post_residual <= next_item_size + 10 {
            score -= 4.0 * (1.0 - progress) ;
        }
        if next_item_size > 1 && post_residual % next_item_size == 0 && post_residual >= 2 * next_item_size && post_residual <= 3 * next_item_size {
            score -= 5.0 * (1.0 - progress) ;
        }
        if post_residual >= 5 && post_residual <= 9 && progress > 0.5 && next_item_size > post_residual {
            score += 8.0 * progress ;
        }
        // mutation: reward near-perfect residual utilization (post_residual close to mean but small)
        if post_residual as f64 >= mean_residual * 0.9 && post_residual <= 12 {
            score -= 9.0 * (1.0 - progress) ;
        }
        // mutation: penalize leaving residuals in dead zone (too small for typical next items)
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < mean_residual as u32 / 2 {
            score += 14.0 * progress + 0.3 * post_residual as f64 ;
        }
    }
    // NEW-BIN CANDIDATE
    if bin_residual == bin_capacity {
        let big_next = next_item_size as f64 / bin_capacity as f64 ;
        score += 180.0 - 60.0 * progress + 0.15 * open_bins_count as f64 - 25.0 * big_next . max (0.0) ;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0 ;
        }
        if open_bins_count <= 4 && progress < 0.3 {
            score += 25.0 ;
        }
        if mean_residual < 15.0 && progress > 0.5 {
            score -= 15.0 ;
        }
        let item_frac = item_size as f64 / bin_capacity as f64 ;
        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3 ;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3 ;
        }
        let fresh_left = bin_capacity - item_size ;
        if next_item_size > 0 && fresh_left == next_item_size {
            score -= 30.0 ;
        }
        if open_bins_count > 6 && mean_residual > 0.4 * bin_capacity as f64 {
            score += 20.0 ;
        }
        if next_item_size > 0 && fresh_left < next_item_size && fresh_left < 8 {
            score += 35.0 ;
        }
        if next_item_size > 0 && fitting_bins_count <= 2 && mean_residual < next_item_size as f64 {
            score -= 18.0 * (1.0 - progress) ;
        }
        if open_bins_count > 8 && mean_residual > next_item_size as f64 + 10.0 {
            score += 12.0 ;
        }
        if item_frac > 0.6 && next_item_size > 0 && fresh_left >= next_item_size {
            score -= 8.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size ;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress) ;
            }
        }
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 && progress > 0.6 {
            score += 10.0 * progress ;
        }
        if item_frac > 0.5 && progress < 0.4 {
            score -= 6.0 * (0.4 - progress) / 0.4 ;
        }
        // mutation: fresh bin only attractive if its leftover exceeds mean residual by a margin
        if (fresh_left as f64) < mean_residual + 5.0 && progress > 0.4 {
            score += 22.0 * progress ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness * tightness;

    // Penalize residual that cannot hold the next item (dead space).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Good: next item can still fit here.
            score -= 6.0;
        } else {
            // Dead space for the lookahead item.
            score += 4.0 + 0.15 * (next_item_size - post_residual) as f64;
        }
        // Bonus if post_residual fits next item snugly.
        if post_residual > 0 && post_residual >= next_item_size {
            let snug = next_item_size as f64 / post_residual as f64;
            score -= 8.0 * snug;
        }
    } else {
        // Last item: minimize waste only.
        score -= 10.0 * tightness;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many fitting bins: mild penalty for spreading too thin; prefer fullest.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Compare against mean residual state: placing into a below-average-residual
    // bin (fuller bin) is good, keeps many large-residual bins flexible.
    score -= 0.1 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item fits poorly everywhere (item large relative to residuals) or many
    // bins are already open and stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (bin_capacity - item_size) as f64;
        // Base cost of a fresh bin: its leftover space.
        score = waste + 20.0;
        // If only this new bin "fits" (no open bin fits), it's forced anyway.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Early stream with few bins: opening new bins is cheap (future items
        // may use the space); late stream: consolidate.
        score -= 15.0 * (1.0 - progress) * (1.0 - progress);
        // Penalize opening new bins when open bins already have plenty of room.
        score += 0.2 * mean_residual;
        // Large item in a fresh bin leaves less waste.
        score -= 0.1 * item_size as f64;
    }

    // Mild penalty for accumulating many open bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);

    if bin_residual == bin_capacity {
        // ---- NEW-BIN CANDIDATE ----
        let mut score = (bin_capacity - item_size) as f64;
        let fresh_left = bin_capacity - item_size;
        let item_frac = item_size as f64 / bin_capacity as f64;

        // Base cost: fresh bins are expensive unless nothing fits.
        score += 120.0 - 40.0 * progress + 0.1 * open_bins_count as f64;

        // Big item in fresh bin leaves a large usable leftover.
        if item_frac > 0.6 {
            score -= 15.0 * (item_frac - 0.6) / 0.4;
        }
        if fresh_left == next_item_size {
            score -= 40.0;
        }
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 15.0;
        }
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 12.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fresh_left < next_item_size && fresh_left <= 3 {
            score += 30.0 * (1.0 - progress);
        }
        // Many open bins with large mean residual: don't open another.
        if open_bins_count > 6 && mean_residual > 0.4 * bin_capacity as f64 {
            score += 25.0;
        }
        if fitting_bins_count == 0 {
            score -= 150.0;
        }
        // Late stream: strongly prefer consolidating into existing bins.
        if progress > 0.6 && fitting_bins_count >= 1 {
            score += 25.0 * progress;
        }
        if next_item_size > 0 && fitting_bins_count <= 2 && mean_residual < next_item_size as f64 && progress < 0.5 {
            score -= 15.0 * (1.0 - progress);
        }
        return score;
    }

    // ---- EXISTING BIN ----
    let mut score = post_residual as f64;

    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Exact match with next item is a perfect two-step fill.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 900.0 - 30.0 * progress;
            } else if next_item_size < post_residual {
                let after_next = post_residual - next_item_size;
                score -= 60.0 + 2.0 * (after_next as f64).min(20.0);
                if after_next >= next_item_size {
                    score -= 6.0 + 0.2 * (after_next / next_item_size) as f64;
                    if after_next % next_item_size == 0 {
                        score -= 8.0 * (1.0 - progress);
                    }
                }
                if after_next < next_item_size && after_next <= 3 {
                    score -= 14.0 * (1.0 - progress);
                }
                if (after_next as f64 - mean_residual).abs() <= 4.0 {
                    score -= 6.0 * (1.0 - progress);
                }
            } else {
                // Next item won't fit; penalize dead space.
                let miss = next_item_size - post_residual;
                score += 2.0 * miss as f64;
                if post_residual < 10 {
                    score += 40.0;
                } else if post_residual < 20 {
                    score += 10.0;
                }
                if post_residual < 3 {
                    score -= 300.0;
                }
                if miss <= 2 {
                    score -= 18.0 * (1.0 - progress);
                }
                if miss <= 6 && fitting_bins_count <= 2 {
                    score -= 5.0;
                }
            }
        }

        // Tightness reward.
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 12.0 * tightness * tightness;

        // Fill ratio of this placement.
        let fill = item_size as f64 / (bin_residual as f64).max(1.0);
        score -= 20.0 * fill;

        // Residual near mean_residual is chainable with other bins.
        score -= 0.4 * (mean_residual - post_residual as f64).abs().min(20.0);

        // Last-chance bin.
        if fitting_bins_count == 1 {
            score -= 15.0;
        } else if fitting_bins_count == 2 && post_residual < bin_capacity / 3 {
            score -= 6.0;
        }

        // Mid-range residuals are useful for typical item sizes.
        if post_residual >= bin_capacity / 8 && post_residual <= bin_capacity / 2 {
            score -= 6.0;
        }

        // Tiny dead space late in stream is waste.
        if post_residual >= 5 && post_residual <= 9 && progress > 0.5 && next_item_size > post_residual {
            score += 8.0 * progress;
        }

        // Consolidation pressure late.
        score -= 6.0 * progress * tightness;
        if post_residual <= 5 && open_bins_count > 6 {
            score += 25.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear waste penalty: quadratic coupling of post_residual with capacity
    score += 0.8 * (post / cap) * (post / cap) * cap;

    // Smooth progress coupling: later in stream, waste matters more
    score *= 1.0 + 0.6 * progress * (post / cap);

    // Reward tight fits (small post_residual) with cubic term
    score -= 12.0 * (1.0 - post / cap).powi(3);

    // If this bin is the only one that fits, strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize bins with residual far from mean (fragmentation)
    score += 0.3 * ((bin_residual as f64 - mean_residual) / cap).abs() * cap * 0.1;

    // Lookahead: if next item fits exactly in post_residual, reward heavily
    if next_item_size > 0 && next_item_size <= post_residual as u32 {
        let slack = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 15.0 * (1.0 - slack);
    }

    // New-bin candidate: mild penalty so open bins are preferred unless very poor fit
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
