pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "usable slots"
    // (multiples of common item sizes / small remainders), penalize dead space.
    let pr = post_residual;
    let class = pr % 10;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if class == 0 {
        score -= 25.0; // residual is a round number, reusable
    } else if class <= 2 {
        score += 20.0; // tiny sliver, near-dead space
    } else if class >= 8 {
        score -= 10.0; // close to next round slot
    }

    // Fractional capacity coupling: residual fraction vs item fraction
    let res_frac = post_residual as f64 / cap;
    let item_frac = item_size as f64 / cap;
    score -= 30.0 * (1.0 - (res_frac - item_frac).abs() * 2.0).max(0.0);

    // Lookahead: if next item fits into post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 35.0;
        // harmonic match: next item exactly consumes residual class
        if (post_residual - next_item_size) % 10 == 0 {
            score -= 15.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 12.0; // this bin becomes dead after placement
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when current fits are poor
    if bin_residual == bin_capacity {
        // base penalty so open bins with decent fit win
        score += 40.0;
        if next_item_size > 0 {
            let tight = (next_item_size as f64 / cap) > 0.5;
            if tight {
                score -= 30.0; // big item coming: fresh bin valuable
            }
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        // late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
    }

    // Prefer filling bins whose residual is below item+slack thresholds
    if bin_residual < bin_capacity {
        let half = bin_capacity / 2;
        if bin_residual <= half && post_residual < 20 {
            score -= 18.0; // consolidating a nearly-full bin
        }
    }

    // Mean-residual coupling: if this bin is far below mean residual, it's a
    // good "garbage absorber" for small items
    if (item_size as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

