        if open_bins_count > 5 && mean_residual < 0.15 * bin_capacity as f64 {
            score -= 10.0 * (1.0 - progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item can use are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0; // unusable sliver
    } else if post_residual > 0 && post_residual < 20 {
        score += 60.0;
    } else if post_residual == 0 {
        score -= 120.0; // perfect closure
    }

    // Relative tightness reward: fraction of residual consumed by this item.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill_ratio;

    // Penalize leaving a gap that is just barely below the next item (near-miss dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0; // leaves room for lookahead
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (1.0 - fill_ratio);
    score -= 0.3 * mean_residual * fill_ratio;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        score = 150.0 - 100.0 * desperation - 0.2 * mean_residual + 30.0 * progress;
    }

    score
}

