pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // 2-step lookahead: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_gap = post_residual - next_item_size;
        if next_fit_gap == 0 {
            score -= 30.0; // perfect chain: item + next item fill bin exactly
        } else {
            // prefer bins where next item leaves small leftover too
            let next_tightness = 1.0 - (next_fit_gap as f64) / (bin_capacity as f64);
            score -= 12.0 * next_tightness * next_tightness;
        }
    } else if next_item_size > 0 {
        // next item won't fit in residual: penalize proportionally to wasted capacity
        let wasted = post_residual as f64;
        score += 0.05 * wasted;
    }

    // Penalize creating dead space relative to mean residual of open bins.
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.1 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current fit is very poor
    // (large post_residual waste) or bin pool is fragmented.
    if bin_residual == bin_capacity {
        let waste_penalty = post_residual as f64; // = capacity - item_size for new bin
        score += 5.0; // base cost of opening a new bin
        score += 0.2 * waste_penalty;
        if fitting_bins_count > 2 {
            score += 10.0; // plenty of alternatives; discourage new bin
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // fresh bin can host a perfect pair: reward
            score -= 20.0 * (1.0 - ((bin_capacity - item_size - next_item_size) as f64) / (bin_capacity as f64));
        }
    }

    // Early in stream, be slightly conservative about fragmenting bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0 * (1.0 - progress); // near-perfect fills early are precious
    }

    score
}

