pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot be used by the next item
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else {
            // Residual big enough for the next item: mild bonus
            score -= 4.0;
        }
    }

    // Last-chance bin: heavily favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Many fitting bins: prefer the fullest (smallest residual) via post_residual already,
    // but add extra pressure scaled by choice abundance
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Global state: when open bins have large mean residual, prefer filling them
    // rather than opening new bins (penalize new-bin candidate implicitly).
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty grows with open bins and mean residual
        score += 8.0 + 1.5 * open_bins_count as f64 + 0.4 * mean_residual;
        // But if the item is huge relative to typical residual, opening a fresh
        // bin may be wise: reduce penalty when mean_residual is small
        if mean_residual < (item_size as f64) * 0.5 {
            score -= 6.0;
        }
        // Early stream: opening bins is cheap
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 4.0 * (1.0 - progress);
    } else {
        // Existing bin: mild bonus scaled by how full the stream is
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 3.0 * progress;
    }

    // Discourage leaving residuals in the awkward 1..10 zone
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    // Perfect fit celebration
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

