    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Non-linear base: quadratic in post_residual (waste grows super-linearly),
    // scaled by a smooth progress-dependent coefficient.
    let base = pr * (1.0 + 0.6 * (pr / cap)) * (0.7 + 0.6 * progress);

    // Smooth coupling of post_residual with mean residual: penalize bins whose
    // leftover deviates upward from the fleet mean (fragmentation signal).
    let dev = (pr - mean_residual) / cap;
    let coupling = pr * (0.5 * dev * dev.abs()) + 0.3 * pr * dev;

    // Last-chance bin: strongly reward using it (avoid opening a new bin).
    let last_chance = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -40.0 * (1.0 + progress)
    } else {
        0.0
    };

    // New-bin candidate: opening a bin is cheap early, costly late; also
    // discourage it when several bins already fit the item.
    let new_bin = if bin_residual == bin_capacity {
        25.0 * (0.4 + 0.8 * progress) + 5.0 * (open_bins_count as f64).sqrt()
    } else {
        0.0
    };

    // Lookahead: reward placements whose post_residual can host the next item
    // (smooth hinge rather than hard threshold).
    let lookahead = if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            -8.0 * (1.0 - (gap / cap).min(1.0))
        } else {
            4.0 * ((-gap) / cap)
        }
    } else {
        0.0
    };

    // Mild reward for tight fits (small post_residual) via smooth saturating term.
    let tight = -10.0 * (-pr / (0.25 * cap)).exp();

    base + coupling + last_chance + new_bin + lookahead + tight
}

