pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect / near-perfect fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * (post_residual - next_item_size) as f64;
        } else {
            // Penalize stranding: post-residual too small for the next item.
            let waste = post_residual as f64;
            score += 0.5 * waste * (waste / bin_capacity as f64);
        }
    }

    // Prefer bins whose residual is close to the mean residual (balance).
    score += 0.08 * ((bin_residual as f64 - mean_residual).abs());

    // Time horizon: early in the stream, be conservative (favor tight fits
    // to preserve flexibility); late, favor closing out bins.
