pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post residual (dead space), modulated by progress
    let mut score = norm_pr * (1.0 + 2.0 * progress) + 1.5 * norm_pr * norm_pr;

    // Smooth cubic interaction: late in stream, prefer tighter fits aggressively
    let tight = 1.0 - norm_pr;
    score -= 3.0 * progress * tight * tight * tight;

    // Reward using this bin when few bins can fit (last-chance bonus)
    if fitting_bins_count == 1 {
        score -= 2.0 + 3.0 * progress;
    } else {
        score += 0.05 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead coupling: bonus if next item fits the post residual exactly-ish
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = (pr - nxt) / cap;
            score -= 1.2 * (1.0 - gap * 4.0).max(0.0) * (0.5 + progress);
        } else {
            score += 0.4 * (nxt - pr) / cap;
        }
    }

    // Penalize bins far from mean residual (fragmentation avoidance), smooth
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.6 * dev * dev;

    // New-bin candidate: mild penalty unless residuals across bins are low
    if bin_residual == bin_capacity {
        let mean_norm = mean_residual / cap;
        score = 0.8 + 2.0 * mean_norm * mean_norm - 0.5 * progress;
    }

    score
}

