                    if after_next > 0 && after_next < 4 && progress > 0.4 {
                        score += 10.0 * progress ;
                    }
                } else {
                    let miss = next_item_size - post_residual ;
                    score += 2.0 * miss as f64 ;
                    if post_residual < 25 {
                        score += 15.0 ;
                    }
                    if post_residual < 3 {
                        score -= 400.0 ;
                    }
                    if miss <= 6 && fitting_bins_count <= 2 {
                        score -= 5.0 ;
                    }
                    if miss <= 10 && fitting_bins_count <= 2 && progress > 0.7 {
                        score -= 10.0 * (1.0 - progress) ;
                    }
                    if miss <= 2 {
                        score -= 18.0 * (1.0 - progress) ;
                    }
                    if post_residual >= 8 && post_residual <= 16 {
                        score += 10.0 * (1.0 - progress) ;
                    }
                    if miss > 3 && miss as f64 <= mean_residual * 0.5 {
                        score += 4.0 * (1.0 - progress) ;
                    }
                    // mutation: tiny unusable slivers are pure waste; penalize proportionally to how far below next item
                    if post_residual <= 6 && miss >= 3 {
                        score += 14.0 * (1.0 - progress) * (1.0 - post_residual as f64 / 6.0) ;
                    }
                }
            }
        }
        if post_residual < 10 {
            score += 45.0 ;
        } else if post_residual < 20 {
            score += 10.0 ;
        }
        score -= (mean_residual - post_residual as f64) * 0.6 ;
        let gap = (post_residual as f64 - item_size as f64) . max (0.0) ;
        let gap_ratio = gap / (item_size as f64) . max (1.0) ;
        if gap > 0.0 {
            let scarcity = if fitting_bins_count <= 2 { 0.6 } else if fitting_bins_count <= 4 { 0.3 } else { 0.2 } ;
            score += scarcity * gap + 18.0 * gap_ratio . min (2.0) ;
            if gap < mean_residual {
                let fillable = next_item_size > 0 && gap >= next_item_size as f64 ;
                let w = if fillable { 0.2 } else { 0.6 } ;
                score += w * (mean_residual - gap) ;
            }
            if next_item_size > 0 && (gap as u32) == next_item_size {
                score -= 20.0 ;
            }
            if next_item_size > 1 && (gap as u32) == 2 * next_item_size {
                score -= 12.0 ;
            }
        }
        if fitting_bins_count == 1 {
            score -= 12.0 ;
        }
        let fill = item_size as f64 / (bin_residual as f64) . max (1.0) ;
        score -= 20.0 * fill ;
        if next_item_size > 0 && post_residual < next_item_size {
            let dead_frac = post_residual as f64 / bin_capacity as f64 ;
            let unusable_ratio = post_residual as f64 / (next_item_size as f64) . max (1.0) ;
            score += 0.4 * post_residual as f64 + 30.0 * dead_frac + 12.0 * (1.0 - unusable_ratio) ;
            if next_item_size - post_residual <= 4 {
                score += 20.0 * (1.0 - progress) ;
            }
        }
        if fitting_bins_count == 2 && post_residual < bin_capacity / 3 {
            score -= 8.0 ;
        }
        if post_residual <= 5 && open_bins_count > 6 {
            score += 25.0 * (1.0 - progress) ;
        }
        if post_residual >= bin_capacity / 8 && post_residual <= bin_capacity / 2 {
            score -= 6.0 ;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= bin_capacity / 2 {
            score -= 4.0 * (1.0 - progress) ;
        }
        if post_residual as f64 >= 2.0 * mean_residual && post_residual > 20 {
            score -= 5.0 ;
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let headroom = post_residual - next_item_size ;
            if (headroom as f64 - mean_residual) . abs () <= 3.0 {
                score -= 7.0 ;
            }
            if (headroom as f64 - mean_residual) . abs () <= 1.0 && fitting_bins_count <= 3 {
                score -= 5.0 * (1.0 - progress) ;
            }
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0 ;
        }
        if next_item_size > 1 && post_residual > next_item_size + 1 && post_residual <= next_item_size + 10 {
            score -= 4.0 * (1.0 - progress) ;
        }
        if next_item_size > 1 && post_residual % next_item_size == 0 && post_residual >= 2 * next_item_size && post_residual <= 3 * next_item_size {
            score -= 5.0 * (1.0 - progress) ;
        }
        if post_residual >= 5 && post_residual <= 9 && progress > 0.5 && next_item_size > post_residual {
            score += 8.0 * progress ;
        }
        // mutation: reward exact divisibility of post residual by small sizes (chainable future fits)
        if next_item_size > 1 && post_residual > next_item_size && post_residual % next_item_size == 0 {
            score -= 3.0 * (1.0 - progress) ;
        }
        // mutation: penalize residual slightly below next item when it is near mean residual (wasted reusable space)
        if next_item_size > 0 && post_residual < next_item_size && (next_item_size - post_residual) <= 3 && post_residual as f64 > 0.5 * mean_residual {
            score += 9.0 * (1.0 - progress) ;
        }
    }
    // NEW-BIN CANDIDATE
    if bin_residual == bin_capacity {
        let big_next = next_item_size as f64 / bin_capacity as f64 ;
        score += 180.0 - 60.0 * progress + 0.15 * open_bins_count as f64 - 25.0 * big_next . max (0.0) ;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0 ;
        }
        if open_bins_count <= 4 && progress < 0.3 {
            score += 25.0 ;
        }
        if mean_residual < 15.0 && progress > 0.5 {
            score -= 15.0 ;
        }
        let item_frac = item_size as f64 / bin_capacity as f64 ;
        if item_frac < 0.3 {
            score += 20.0 * (0.3 - item_frac) / 0.3 ;
        } else if item_frac > 0.7 {
            score -= 12.0 * (item_frac - 0.7) / 0.3 ;
        }
        let fresh_left = bin_capacity - item_size ;
        if next_item_size > 0 && fresh_left == next_item_size {
            score -= 30.0 ;
        }
        if open_bins_count > 6 && mean_residual > 0.4 * bin_capacity as f64 {
            score += 20.0 ;
        }
        if next_item_size > 0 && fresh_left < next_item_size && fresh_left < 8 {
            score += 35.0 ;
        }
        if next_item_size > 0 && fitting_bins_count <= 2 && mean_residual < next_item_size as f64 {
            score -= 18.0 * (1.0 - progress) ;
        }
        if open_bins_count > 8 && mean_residual > next_item_size as f64 + 10.0 {
            score += 12.0 ;
        }
        if item_frac > 0.6 && next_item_size > 0 && fresh_left >= next_item_size {
            score -= 8.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left >= next_item_size && (fresh_left - next_item_size) as f64 <= mean_residual {
            score -= 10.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size {
            let tail = fresh_left - next_item_size ;
            if tail <= 3 {
                score -= 14.0 * (1.0 - progress) ;
            }
        }
        if next_item_size > 0 && fresh_left < next_item_size && (fresh_left as f64) < mean_residual * 0.6 {
            score += 10.0 ;
        }
        if next_item_size > 1 && fresh_left == 2 * next_item_size {
            score -= 12.0 ;
        }
        if fresh_left <= 2 {
            score -= 25.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && (fresh_left as f64 - mean_residual) . abs () <= 2.0 {
            score -= 8.0 ;
        }
        if next_item_size > 1 && fresh_left >= 2 * next_item_size && fresh_left % next_item_size == 0 {
            score -= 6.0 * (1.0 - progress) ;
        }
        if next_item_size > 0 && fresh_left > next_item_size && ((fresh_left - next_item_size) as f64 - mean_residual) . abs () <= 3.0 {
            score -= 9.0 * (1.0 - progress) ;
        }
        if post_residual > 0 && post_residual < 4 && open_bins_count > 2 {
            score += 15.0 ;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 && progress > 0.6 {
            score += 10.0 * progress ;
        }
        if item_frac > 0.5 && progress < 0.4 {
            score -= 6.0 * (0.4 - progress) / 0.4 ;
        }
        // mutation: fresh bin is best when its leftover is exactly a multiple of the next item (perfect chain)
        if next_item_size > 1 && fresh_left % next_item_size == 0 && fresh_left >= next_item_size {
            score -= 4.0 ;
        }
        // mutation: avoid opening fresh bins for tiny items when open bins have ample room
        if item_frac < 0.15 && open_bins_count > 3 && mean_residual > 20.0 {
            score += 18.0 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into
    // "usable" classes (multiples of small divisors) are preferred.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward exact or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Harmonic class: post_residual divisible by common item sizes (10/20/25/50)
    // is more reusable; penalize "dead" residuals in awkward ranges.
    if post_residual % 10 == 0 { score -= 15.0; }
    if post_residual % 20 == 0 { score -= 10.0; }
    if post_residual % 25 == 0 { score -= 8.0; }
    if post_residual % 50 == 0 { score -= 12.0; }

    // Dead-space bands: residuals that most items (10..80 range, but 1..100 here)
    // cannot exploit well.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable sliver
    }
    if post_residual >= 51 && post_residual <= 59 {
        score += 10.0; // awkward mid band
    }

    // Lookahead coupling: if next item fits the post residual exactly or in
    // harmonic class, strongly reward.
    if next_item_size > 0 {
        let ni = next_item_size;
        if post_residual == ni {
            score -= 300.0;
        } else if post_residual >= ni {
            if post_residual % ni == 0 { score -= 60.0; }
            let gap = post_residual - ni;
            if gap <= 5 { score -= 80.0; }
            if gap % 10 == 0 { score -= 20.0; }
        } else {
            // next item won't fit here: penalize small residuals more
            score += (ni - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline penalty so open bins with decent fits win.
        score += 60.0;
        // But if current item leaves a terrible fit everywhere, opening fresh
        // is fine: reward when item is large relative to capacity.
        let frac = item_size as f64 / cap;
        if frac > 0.7 {
            score -= 90.0;
        }
        // Early in stream, opening bins is cheaper (more future items to fill).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 40.0;
        // Many open bins with high mean residual => consolidate instead.
        if mean_residual > cap * 0.4 {
            score += 50.0;
        }
    }

    // Mild consolidation pressure: prefer bins with residual below mean
    // (tighter bins) to keep loose bins available for big items.
    score += (pr - mean_residual) * 0.3;

    // Slight preference for filling fuller bins as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0;

    score
}

