pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical future items are heavily penalized.
    if post_residual > 0 {
        let dead_threshold = 12.0_f64.min(bin_capacity as f64 * 0.15);
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 8.0;
        }
    }

    // Reward tight fits (small post_residual relative to item size).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 6.0;

    // Penalize wasting a nearly empty bin's flexibility (large post_residual
    // after placing a small item is fine only if the bin was fresh).
    let was_fresh = bin_residual == bin_capacity;
    if !was_fresh {
        score += (post_residual as f64 / bin_capacity as f64) * 4.0;
    }

    // Open-bins pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.35;

    // Lookahead: if the next item fits the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
        // Extra reward for a near-exact chain fit.
        let gap = post_residual - next_item_size;
        if gap <= 10 {
            score -= 3.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover: penalize proportionally.
        score += (post_residual as f64 / bin_capacity as f64) * 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !was_fresh {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when no good existing fit exists.
    if was_fresh {
        let good_fit_exists = fill_ratio > 0.6 || (next_item_size > 0 && next_item_size <= post_residual);
        if good_fit_exists {
            score += 15.0; // prefer existing bins
        } else {
            score -= 2.0; // opening fresh bin is reasonable
        }
    }

    // Slight time decay: early in the stream, keep bins open for flexibility.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.19;
    score
}
